window.__D("text/zohar-hebrew-translation/c033",{"p":[[9522012435,"<p>אָמַר רַבִּי אַבָּא, דָּבָר זֶה לֹא הִתְיַשֵּׁב, וְצָרִיךְ לְעַיֵּן בּוֹ. אָמַר רַבִּי אֶלְעָזָר, כָּךְ הוּא בְּוַדַּאי, פְּלִשְׁתִּי זֶה קָרוֹב לְיִחוּסוֹ שֶׁל דָּוִד הָיָה, וּבֶן עָרְפָּה הָיָה, וְהַיְנוּ מַה שֶּׁכָּתוּב (שמואל א יז) מִמַּעַרְכוֹת פְּלִשְׁתִּים. אַל תִּקְרֵי מִמַּעַרְכוֹת, אֶלָּא מִמְּעָרוֹת פְּלִשְׁתִּים, שֶׁשָּׂמוּ אֶת אִמּוֹ כַּמְּעָרָה הַזּוֹ. וְכֵיוָן שֶׁכָּתוּב וַיְקַלֵּל הַפְּלִשְׁתִּי אֶת דָּוִד בֵּאלֹהָיו, הִסְתַּכֵּל בּוֹ דָּוִד בְּעַיִן רָעָה. וּבְכָל מָקוֹם שֶׁהָיָה מִסְתַּכֵּל בְּעַיִן רָעָה, כָּל מִינֵי צָרַעַת נִמְשְׁכוּ מֵעֵינֵי דָוִד. וְכָךְ הָיָה בְּיוֹאָב, כֵּיוָן שֶׁהִסְתַּכֵּל בּוֹ בְּדָוִד בְּעַיִן רָעָה, מַה כָּתוּב? (שם ב ג) וְלֹא יִכָּרֵת מִבֵּית יוֹאָב זָב וּמְצֹרָע וְגוֹ'.</p>\n<p>וְכָאן בַּפְּלִשְׁתִּי הַזֶּה, כֵּיוָן שֶׁקִּלֵּל אֶת הַשֵּׁם, הִסְתַּכֵּל בּוֹ בְּעַיִן רָעָה, וְרָאָה שֶׁהִצְטָרַע בְּמִצְחוֹ. מִיָּד - וַתִּטְבַּע הָאֶבֶן בְּמִצְחוֹ, וְדָבְקָה הַצָּרַעַת בְּמִצְחוֹ. וְהַכֹּל הָיָה; הִשְׁתַּקְּעָה עַיִן רָעָה שֶׁל צָרַעַת בְּמִצְחוֹ, וְהִשְׁתַּקְּעָה אֶבֶן מַמָּשׁ בִּמִצְחוֹ, וַדַּאי מְצֹרָע הָיָה.</p>\n<p>בִּלְעָֹם הָרָשָׁע עֵינוֹ הָיְתָה בְּהִפּוּךְ מֵעֵין דָּוִד. עֵין דָּוִד הָיְתָה מְרֻקֶּמֶת מִכָּל מִינֵי גְוָנִים. לֹא הָיְתָה עַיִן בָּעוֹלָם יָפָה לְמַרְאֶה כְּעֵין דָּוִד. כָּל גּוֹנֵי הָעוֹלָם נוֹצְצִים בָּהּ, וְהַכֹּל בְּאַהֲבָה לְמִי שֶׁיְּרֵא חֵטְא, שֶׁכָּתוּב (תהלים קיט) יְרֵאֶיךְ יִרְאוּנִי וְיִשְׂמָחוּ, שְׂמֵחִים כְּשֶׁרוֹאִים אוֹתִי. וְכָל אוֹתָם רְשָׁעִים פּוֹחֲדִים מִפָּנָיו.</p>\n<p>אֲבָל עֵינוֹ שֶׁל בִּלְעָם הָרָשָׁע, עַיִן רָעָה בַּכֹּל. בְּכָל מָקוֹם שֶׁהָיָה מִסְתַּכֵּל, כְּשַׁלְהֶבֶת שׂוֹרֵף אוֹתוֹ. שֶׁהֲרֵי אֵין עַיִן רָעָה בָּעוֹלָם כְּעֵין אוֹתוֹ רָשָׁע, שֶׁהִיא בְּהִפּוּךְ מֵעֵינוּ שֶׁל דָּוִד.</p>\n<p>עֵל גִּלּוּי עֲרָיוֹת - שֶׁכָּתוּב (ישעיה ג) וְשִׂפַּח ה' קָדְקֹד בְּנוֹת צִיּוֹן, וְכָתוּב (ויקרא יד) וְלַשְׂאֵת וְלַסַּפַּחַת. עַל הַגְּנֵבָה - שֶׁכָּתוּב (זכריה ה) הוֹצֵאתִיהָ נְאֻם ה' צְבָאוֹת וּבָאָה אֶל בֵּית הַגַּנָּב וְגוֹ' וְכִלַּתּוּ וְאֶת עֵצָיו וְאֶת אֲבָנָיו. מַהוּ הַדָּבָר שֶׁמְּכַלֶּה עֵצִים וַאֲבָנִים? זוֹ צָרַעַת, שֶׁכָּתוּב (ויקרא יד) וְנָתַץ אֶת הַבַּיִת אֶת אֲבָנָיו וְאֶת עֵצָיו.</p>\n<p>עֵל לָשׁוֹן הָרָע - שֶׁכָּתוּב (במדבר יב) וַתְּדַבֵּר מִרְיָם וְאַהֲרֹן בְּמֹשֶׁה וְגוֹ', וְכָתוּב (שם) וַיִּפֶן אַהֲרֹן אֶל מִרְיָם וְהִנֵּה מְצֹרָעַת. עַל עֵדוּת שֶׁקֶר - מִשּׁוּם שֶׁהֵעִידוּ עֵדוּת שֶׁקֶר וְאָמְרוּ (שמות לב) אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל, בְּקוֹל חָזָק, שֶׁכָּתוּב (שם) קוֹל מִלְחָמָה בַּמַּחֲנֶה. בִּגְלַל זֶה, (במדבר ה) וִישַׁלְּחוּ מִן הַמַּחֲנֶה כָּל צָרוּעַ וְכָל זָב וְגוֹ'.</p>\n<p>עַל דַּיָּן שֶׁמְּקַלְקֵל דִּין - שֶׁכָּתוּב (ישעיה ה) כֶּאֱכֹל קַשׁ לְשׁוֹן אֵשׁ וַחֲשַׁשׁ וְגוֹ', וּפִרְחָם כָּאָבָק יַעֲלֶה וְגוֹ'. מָה הַטַּעַם? כִּי מָאֲסוּ אֵת תּוֹרַת ה' צְבָאוֹת. וְאֵין פִּרְחָם אֶלָּא צָרַעַת, שֶׁכָּתוּב (ויקרא יג) וְאִם פָּרוֹחַ תִּפְרַח הַצָּרַעַת. עַל שֶׁנִּכְנָס בִּתְחוּם חֲבֵרוֹ מִנַּיִן? מֵעֻזִּיָּהוּ, שֶׁנִּכְנַס בִּתְחוּם הַכְּהֻנָּה, שֶׁכָּתוּב וְהַצָּרַעַת זָרְחָה בְמִצְחוֹ. וְעַל הַמְשַׁלֵּחַ מְדָנִים בֵּין אַחִים - שֶׁכָּתוּב (בראשית יב) וַיְנַגַּע ה' אֶת פַּרְעֹה, שֶׁהוּא שָׁלַח מְדָנִים בֵּין אַבְרָהָם וְשָׂרָה. וְעַל עַיִן הָרָע, כְּמוֹ שֶׁנֶּאֱמַר. וְכֻלָּם הָיוּ בְּאוֹתוֹ בִּלְעָם הָרָשָׁע.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, פְּתוֹרָה אֲשֶׁר עַל הַנָּהָר. מַה זֶּה עַל הַנָּהָר? שֶׁנָּתַן עַיִן הָרָע עַל אוֹתוֹ נָהָר שֶׁעוֹמֵד עַל יִשְׂרָאֵל, שֶׁכָּתוּב (ישעיה סו) הִנְנִי נֹטֶה אֵלֶיהָ כְּנָהָר שָׁלוֹם. וְהוּא בָּא בְּאוֹתוֹ שֻׁלְחָן וְהִתְגָּרָה בָהֶם.</p>\n<p>אָמַר רַבִּי אַבָּא, כָּל הַדְּבָרִים הַלָּלוּ הָיוּ בְּוַדַּאי בְּבִלְעָם. אֲבָל גִּלּוּי עֲרָיוֹת מִנַּיִן? שֶׁכָּתוּב (במדבר לא) הֵן הֵנָּה הָיוּ לִבְנֵי יִשְׂרָאֵל בִּדְבַר בִּלְעָם לִמְסָר מַעַל בַּה' וְגוֹ'. הֲרֵי כָּאן עֲבוֹדָה זָרָה וְגִלּוּי עֲרָיוֹת. עֵדוּת שֶׁקֶר - שֶׁכָּתוּב וְיֹדֵעַ דַּעַת עֶלְיוֹן. וְדַעַת בְּהֶמְתּוֹ לֹא הָיָה יוֹדֵעַ. קִלְקֵל אֶת הַדִּין - שֶׁכָּתוּב לְךְ אִיעָצְךְ. שֶׁהֲרֵי בְּדִין עוֹמֵד, וְנָתַן עֵצָה רָעָה לְהַזִּיק, וְסָטָה מֵהַדִּין, וְיָּעַץ רָעוֹת עֲלֵיהֶם.</p>\n<p>נִכְנַס בִּתְחוּם שֶׁלֹּא שֶׁלּוֹ, שֶׁכָּתוּב וָאַעַל פָּר וָאַיִל בַּמִּזְבֵּחַ, וְכָתוּב אֶת שִׁבְעַת הַמִּזְבְּחֹת עָרַכְתִּי. מְשַׁלֵּחַ מְדָנִים בֵּין אַחִים, בֵּין יִשְׂרָאֵל לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם. לָשׁוֹן הָרָע לֹא הָיָה בָּעוֹלָם כְּמוֹתוֹ. קִלְלַל הַשֵּׁם, שֶׁכָּתוּב וְאָנֹכִי אִקָּרֶה כֹּה. וְכֻלָּם הָיוּ בוֹ. עַיִן רָעָה, כְּמוֹ שֶׁנֶּאֱמַר. וְהַכֹּל עַל אוֹתוֹ נָהָר שֶׁל יִשְׂרָאֵל נָתַן עֵינוֹ לְהִתְגָּרוֹת בּוֹ. אֶרֶץ בְּנֵי עַמּוֹ, וְכִי לֹא יָדַעְנוּ שֶׁהִיא אֶרֶץ בְּנֵי עַמּוֹ? אֶלָּא סוֹד זֶה שֶׁכָּל בְּנֵי עַמּוֹ מִתְדַּבְּקִים בּוֹ, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522012436,"<p>וַיַּרְא בָּלָק בֶּן צִפּוֹר וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (משלי כג) אַל תִּלְחַם אֶת לֶחֶם רַע עָיִן וְגוֹ' - זֶה בִּלְעָם שֶׁבֵּרַךְ אֶת יִשְׂרָאֵל. וְאַל תִּתְאָו לְמַטְעַמֹּתָיו - זֶה בָּלָק, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הִתְרַצָּה לְאוֹתָן עוֹלוֹת שֶׁהִתְקִין לְפָנָיו.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁרָאָה בָלָק שֶׁסִּיחוֹן וְעוֹג נֶהֶרְגוּ וְאַרְצָם נִלְקְחָה, רָאָה מַה שֶּׁרָאָה, שֶׁהוּא אָמַר וַיַּרְא. אֶלָּא רָאָה בְחָכְמָתוֹ שֶׁהוּא, וַחֲמִשָּׁה עֶלְיוֹנֵי מִדְיָן וְעַמּוֹ נוֹפְלִים בִּידֵי יִשְׂרָאֵל. רָאָה וְלֹא יָדַע. וְעַל זֶה הִקְדִּים לְבִלְעָם, שֶׁכֹּחוֹ בְּפִיו, כְּמוֹ שֶׁיִּשְׂרָאֵל כֹּחָם בְּפִיהֶם.</p>\n<p>וַאֲפִלּוּ בִּלְעָם הָיָה תָּאֵב יוֹתֵר מִבָּלָק, וְאוֹתָהּ יְדִיעָה שֶׁהוּא יָדַע הָיָה יוֹדֵעַ בַּלַּיְלָה, מִשּׁוּם שֶׁאוֹתָם כְּתָרִים תַּחְתּוֹנִים וַחֲמוֹרִים לֹא נִמְצָאִים אֶלָּא בַּמִּשְׁמָרָה הָרִאשׁוֹנָה שֶׁל הַלַּיְלָה, וְלָכֵן הָיְתָה לוֹ אָתוֹן שֶׁל צַד זֶה, לְהִתְחַבֵּר חֲמוֹרִים אִתָּהּ בְּרֵאשִׁית הַלַּיְלָה.</p>"],[9522012437,"<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם לַיְלָה? כָּךְ זֶה בְּוַדַּאי. וּבֵאַרְנוּ, אוֹתוֹ מְמֻנֶּה שֶׁמְּמֻנֶּה עֲלֵיהֶם, וְהוּא בָּא לְמוּלוֹ. כְּגוֹן זֶה, (בראשית לא) וַיָּבא אֱלֹהִים אֶל לָבָן הָאֲרַמִּי וְגוֹ'. וְהַכֹּל דָּבָר אֶחָד. בִּגְלַל זֶה הוּא אָמַר לִגְדוֹלֵי בָלָק לִינוּ פֹה הַלַּיְלָה.</p>\n<p>כֵּיוָן שֶׁהָיָה בָּא אוֹתוֹ מְמֻנֶּה, בִּלְעָם הָיָה בָּא עַל אֲתּוֹנוֹ, וְעָשָׂה מַעֲשֵׂהוּ וְאָמַר דְּבָרִים, וְאָז הָאָתוֹן הָיְתָה מוֹדִיעָה לוֹ, וְהוּא מַרְאֶה מַעֲשֶׂה לְהַשְׁרוֹת עָלָיו אוֹתָהּ רוּחַ. וּמַה הֶרְאָה? הוּא הָיָה יוֹדֵעַ שֶׁחֲמוֹרִים מְשׁוֹטְטִים וְשׁוֹרִים בִּתְחִלַּת הַלַּיְלָה, וְאָז הֶרְאָה מַעֲשֶׂה וְהֶעֱמִיד אֶת אֲתוֹנוֹ בְּמָקוֹם מְתֻקָּן, וְעָשָׂה מַעֲשֵׂהוּ וְסִדֵּר דְּבָרָיו. וְאָז הָיָה בָּא מִי שֶׁבָּא, וְהוֹדִיעַ לוֹ עַל יְדֵי אוֹתָהּ הָאָתוֹן.</p>\n<p>כֵּיוָן שֶׁלַּיְלָה אֶחָד אָמַר לוֹ לֹא תֵלֵךְ עִמָּהֶם, מַדּוּעַ שָׁב פַּעַם שֵׁנִית לָזֶה? אֶלָּא הֵם בְּרָשׁוּת עֶלְיוֹנָה עוֹמְדִים, וַהֲרֵי שָׁנִינוּ, בְּדֶרֶךְ שֶׁאָדָם רוֹצֶה לָלֶכֶת, בָּהּ מוֹלִיכִין וְכוּ'. בַּהַתְחָלָה כָּתוּב לֹא תֵלֵךְ עִמָּהֶם. כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁרְצוֹנוֹ לָלֶכֶת, אָמַר לוֹ, קוּם לֵךְ אִתָּם וְאַךְ אֶת הַדָּבָר וְגוֹ'. מֶה עָשָׂה בִּלְעָם כָּל אוֹתוֹ הַלַּיְלָה? הָיָה מְהַרְהֵר וְאוֹמֵר: וְאֵיפֹה הוּא הַכָּבוֹד שֶׁלִּי? הַאִם בְּקֶשֶׁר אַחֵר הִתְקַשַּׁרְתִּי? הִשְׁגִּיחַ כָּל אוֹתוֹ הַלַּיְלָה בִּכְשָׁפָיו וְלֹא מָצָא צַד שֶׁיִּהְיֶה הוּא בִּרְשׁוּתוֹ, אֶלָּא מִצַּד אֲתוֹנוֹ.</p>\n<p>וְהַיְנוּ מַה שֶּׁאָמַר רַבִּי יִצְחָק אָמַר רַבִּי יְהוּדָה, בַּכְּתָרִים הַתַּחְתּוֹנִים הַלָּלוּ יֵשׁ יָמִין וְיֵשׁ שְׂמֹאל. מִצַּד יָמִין חֲמוֹרִים, כְּפִי שֶׁבֵּאַרְנוּ, וּמִצַּד שְׂמֹאל אֲתוֹנוֹת. וְשָׁנִינוּ, עֲשָׂרָה הֵם לְיָמִין, וַעֲשָׂרָה לִשְׂמֹאל. וְזֶהוּ שֶׁאָמַר רַבִּי יוֹסֵי, יוֹסֵף כְּשֶׁנִּפְרַד מֵאָבִיו יָדַע בַּחָכְמָה הָעֶלְיוֹנָה בְּסוֹד כְּתָרִים קְדוֹשִׁים עֶלְיוֹנִים. כֵּיוָן שֶׁהָיָה בְּמִצְרַיִם, לָמַד בְּאוֹתָהּ חָכְמָה שֶׁלָּהֶם בְּאוֹתָם כְּתָרִים תַּחְתּוֹנִים, אֵיךְ אֲחוּזִים אֵלֶּה שֶׁל יָמִין וְאֵלֶּה שֶׁל שְׂמֹאל. עֲשָׂרָה שֶׁל יָמִין וַעֲשָׂרָה שֶׁל שְׂמֹאל חֲמוֹרִים וַאֲתוֹנוֹת. וּמִשּׁוּם זֶה רָמַז לְאָבִיו מִמַּה שֶּׁלָּמַד שָׁם, שֶׁכָּתוּב (שם מח) וּלְאָבִיו שָׁלַח כְּזֹּאת עֲשָׂרָה חֲמוֹרִים וְגוֹ'.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אֵלּוּ שֶׁל יָמִין כְּלוּלִים כֻּלָּם בְּאֶחָד שֶׁנִּקְרָא חֲמוֹ\"ר. וְזֶהוּ אוֹתוֹ חֲמוֹר שֶׁכָּתוּב (דברים כב) לֹא תַחֲר!שׁ בְּשׁוֹר וּבַחֲמֹ\"ר יַחְדָּו. וְזֶהוּ חֲמוֹר שֶׁעָתִיד מֶלֶךְ הַמָּשִׁיחַ לִשְׁלֹט עָלָיו, כְּמוֹ שֶׁבֵּאַרְנוּ. וְאוֹתָם שֶׁל שְׂמֹאל כְּלוּלִים כֻּלָּם בְּאֶחָד שֶׁנִּקְרָא אָתוֹן, שֶׁהֲרֵי מִצִּדָּהּ נִקְרָא עִירֹה, מְקַטְרֵג הַתִּינוֹקוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ. וְהַיְנוּ שֶׁכָּתוּב (זכריהט) עָנִי וְרֹכֵב עַל חֲמוֹר וְעַל עַיִר בֶּן אֲתֹנוֹת. אֲתָנַת חָסֵר. עֲשָׂרָה שֶׁכְּלוּלִים בְּאֶחָד.</p>\n<p>וְזְהִוּ שֶׁאָמַר רַבִּי שִׁמְעוֹן, מַהוּ שֶּׁאָמַר (בראשית מט) אֹסְרִי לַגֶּפֶן עִירֹה? אֹסְרִי לַגֶּפֶן, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְקַשֵּׁר מִשּׁוּם שֶׁיִּשְׂרָאֵל נִקְרְאוּ גֶפֶן. עִירֹה, שֶׁהוּא קָטֵגוֹר שֶׁלָּהֶם, וּמִשּׁוּם שֶׁנִּקְרָאִים שׂוֹרֵק, שֶׁכָּתוּב (ירמיה ב) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק. בְּנִי אֲתֹנוֹ, אוֹתוֹ שֶׁיּוֹצֵא מִצַּד הָאָתוֹן הַזֶּה.</p>\n<p>וְאֵלּוּ עֲשָׂרָה מִיָּמִין וַעֲשָׂרָה מִשְּׂמֹאל, וְנִכְלָלִים בַּשְּׁנַיִם הָאֵלֶּה, כֻּלָּם נִמְצָאִים בְּקֶסֶ\"ם. וְיֵשׁ עֲשָׂרָה אֲחֵרִים שֶׁל יָמִין וַעֲשָׂרָה שֶׁל שְׂמֹאל שֶׁנִּמְצָאִים בְּנַחַ\"שׁ. וְלָכֵן כָּתוּב כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל. מָה הַטַּעַם? בִּגְלַל כִּי ה' אֱלֹהָיו עִמּוֹ. מִצַּד הַנַּחַ\"שׁ יָצָא שׁוֹ\"ר, מִצַּד הַקֶּסֶ\"ם יָצָא חֲמוֹ\"ר, וְזֶהוּ שׁוֹר וַחֲמֹר. וְעַל זֶה בִּלְעָם, כֵּיוָן שֶׁיָּדַע שֶׁנִּקְשָׁר בְּרָשׁוּת אַחֶרֶת, וְאָמַר לוֹ אַךְ אֶת הַדָּבָר וְגוֹ' - הִזִּיק לוֹ, וְאָמַר, וְאֵיפֹה כְּבוֹדִי? מִיָּד הִסְתַּכֵּל בִּכְשָׁפָיו וְלֹא מָצָא שֶׁיִּהְיֶה בִרְשׁוּתוֹ, רַק אָתוֹן זוֹ.</p>\n<p>מִיָּד - וַיָּקָם בִּלְעָם בַּבֹּקֶר וַיַּחֲבֹשׁ אֶת אֲתֹנוֹ, לַעֲשׂוֹת אֶת רְצוֹנוֹ בָּהּ וּרְצוֹן בָּלָק. וְעַל זֶה, וַיִּחַר אַף אֱלֹהִים כִּי הוֹלֵךְ הוּא. הוּא דַּוְקָא, שֶׁהוֹצִיא עַצְמוֹ מֵרְשׁוּתוֹ, מִמַּה שֶּׁאָמַר לוֹ וְאַךְ אֶת הַדָּבָר וְגוֹ'. בֹּא תִרְאֶה שֶׁכָּךְ הוּא, שֶׁהֲרֵי בַּהַתְחָלָה נָתַן לוֹ רְשׁוּת, וְאָמַר קוּם לֵךְ אִתָּם. עַכְשָׁו שֶׁהָיָה הוֹלֵךְ, לָמָּה וַיִּחַר אַף אֱלֹהִים? אֶלָּא מִשּׁוּם שֶׁהוֹלֵךְ הוּא, הוּא בִּרְשׁוּתוֹ, לְהוֹצִיא מֵאוֹתוֹ שֶׁאָמַר לוֹ וְאַךְ אֶת הַדָּבָר.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, רָשָׁע, אַתָּה מְתַקֵּן וּמְזָרֵז כְּלֵי זֵינְךְ לָצֵאת מֵרְשׁוּתִי - חַיֶּיךְ, אַתָּה וַאֲתוֹנְךְ תִּהְיוּ בִרְשׁוּתִי. מִיָּד - וַיִּתְיַצֵּב מַלְאַךְ ה'. מַה זֶּה וַיִּתְיַצֵּב? אָמַר רַבִּי אַבָּא, יָצָא וְעָמַד בְּאֻמָּנוּת אַחֶרֶת מֵאֻמָּנוּתוֹ, שֶׁמַּלְאָךְ זֶה הָיָה שֶׁל רַחֲמִים. וְהַיְנוּ מַה שֶּׁאָמַר רַבִּי שִׁמְעוֹן, רְשָׁעִים מְהַפְּכִים רַחֲמִים לְדִין. לְשָׂטָן לוֹ, שֶׁהֲרֵי לֹא הָיְתָה אֻמָּנוּתוֹ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, לֹא שִׁנָּה הַמַּלְאָךְ וְלֹא יָצָא מֵאֻמָּנוּתוֹ, אֶלָּא מִשּׁוּם שֶׁמַּלְאָךְ זֶה הָיָה מִצַּד רַחֲמִים וְעָמַד מִמּוּלוֹ, סָתַר אֶת חָכְמָתוֹ וְקִלְקֵל רְצוֹנוֹ. זֶהוּ שֶׁכָּתוּב לְשָׂטָן לוֹ. לוֹ הָיָה לְשָׂטָן, וְנִמְצָא שָׂטָן, אֲבָל לְאַחֵר לֹא הָיָה שָׂטָן.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן, כַּמָּה חָכָם הָיָה בִּלְעָם בִּכְשָׁפָיו עַל כָּל בְּנֵי הָעוֹלָם, שֶׁהֲרֵי בְּשָׁעָה שֶׁהִשְׁגִּיחַ לִמְצֹא עֵצָה לָצֵאת מֵרְשׁוּת הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתוֹ דָּבָר, שֶׁכָּתוּב וְאַךְ אֶת הַדָּבָר, הִסְתַּכֵּל בִּכְשָׁפָיו וְלֹא מָצָא, פְּרָט לְאוֹתָהּ אָתוֹן, מַה כָּתוּב? וַיַּחֲבֹשׁ אֶת אֲתֹנוֹ. הִטְעִין אוֹתָהּ בְּכָל הַכְּשָׁפִים וּבְכָל הַקְּסָמִים שֶׁיָּדַע, וְהִכְנִיס בָּהּ וְהִכְלִילָהּ מִכֻּלָּם כְּדֵי לְקַלֵּל אֶת יִשְׂרָאֵל. מִיָּד - וַיִּחַר אַף אֱלֹהִים כִּי הוֹלֵךְ הוּא. דַּוְקָא הוּא, כְּמוֹ שֶׁנִּתְבָּאֵר. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? הִקְדִּים מַלְאָךְ שֶׁל רַחֲמִים לַעֲמֹד מִמּוּלוֹ, וְיִסְתֹּר כְּשָׁפָיו וּקְסָמָיו.</p>\n<p>וּבֹא וּרְאֵה, שֶׁעַד עַכְשָׁו לֹא כָתוּב ה', וְלֹא נִרְאָה בִקְסָמָיו וּבִכְשָׁפָיו, וַהֲרֵי פֵּרְשׁוּהָ. וְעַכְשָׁו, כֵּיוָן שֶׁהִתְקִין אֶת אֲתוֹנוֹ וְזֵרְזָהּ בְּתִקּוּנֵי כְשָׁפָיו בְּצַד הַדִּין לְקַלֵּל אֶת יִשְׂרָאֵל, הִקְדִּים הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת מַלְאָךְ הָרַחֲמִים לְמוּלוֹ, וּבְשֵׁם הָרַחֲמִים, כְּדֵי לִסְתֹּר חָכְמָתוֹ וּלְהַטּוֹת אֶת אֲתוֹנוֹ מֵאוֹתוֹ הַדֶּרֶךְ, כְּמוֹ שֶׁכָּתוּב וַתֵּט הָאָתוֹן מִן הַדֶּרֶךְ. דַּוְקָא מִן הַדֶּרֶךְ. וְעַל זֶה לֹא כָתוּב וַיִּתְיַצֵּב מַלְאַךְ הָאֱלֹהִים, וַיַּעֲמֹד מַלְאַךְ הָאֱלֹהִים, אֶלָּא מַלְאַךְ ה', שֶׁל רַחֲמִים.</p>\n<p>אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, רָשָׁע, אַתָּה הִטְעַנְתָּ אֶת אֲתוֹנְךְ בִּכְשָׁפֶיךְ בְּכַמָּה צִדְדֵי דִין מוּל בָּנַי - אֲנִי אַעֲבִיר אֶת הַמִּטְעָן שֶׁלָּךְ וְיֵהָפֵךְ מִדֶּרֶךְ זֶה. מִיָּד הִקְדִּים מַלְאָךְ רַחֲמִים לְשָׂטָן לוֹ. דַּוְקָא לוֹ, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>"],[9522012438,"<p>וַתֵּרֶא הָאָתוֹן אֶת מַלְאַךְ ה' וְגוֹ'. אָמַר רַבִּי יִצְחָק, וְכִי לָמָּה רָאֲתָה הִיא, וּבִלְעָם שֶׁהָיָה חָכָם כָּל כָּךְ לֹא רָאָה? אָמַר רַבִּי יוֹסֵי, חַס וְשָׁלוֹם שֶׁאוֹתוֹ רָשָׁע יִסְתַּכֵּל בְּמַרְאֵה קֹדֶשׁ. אָמַר לוֹ, אִם כָּךְ, הֲרֵי כָּתוּב נֹפֵל וּגְלוּי עֵינָיִם! אָמַר לוֹ, לֹא שָׁמַעְתִּי בָזֶה דָּבָר, וְלֹא אֹמַר. אָמַר לוֹ, אֲנִי שָׁמַעְתִּי. כְּשֶׁהָיָה צָרִיךְ לְהִסְתַּכֵּל, הָיָה נוֹפֵל וְרוֹאֶה, וְכָעֵת לֹא הִצְטָרֵךְ לְהִסְתַּכֵּל.</p>\n<p>אָמַר לוֹ, אִם כָּךְ, בְּדַרְגָּה עֶלְיוֹנָה יוֹתֵר הָיָה עַל כָּל נְבִיאֵי הָאֱמוּנָה, שֶׁהוּא גְּלוּי עֵינָיִם, רוֹאֶה וּמִסְתַּכֵּל בִּכְבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא. וַהֲרֵי רַבִּי שִׁמְעוֹן אָמַר, בִּלְעָם הָיָה יוֹדֵעַ בִּכְשָׁפָיו בְּאוֹתָם כְּתָרִים תַּחְתּוֹנִים שֶׁלְּמַטָּה, כְּמוֹ שֶׁכָּתוּב (יהושע יג) וְאֶת בִּלְעָם בֶּן בְּעוֹר הַקּוֹסֵם. קְרָאוֹ הַכָּתוּב קוֹסֵם, שֶׁל טִנֹּפֶת הַטִּנּוֹפוֹת, אֵיךְ יִסְתַּכֵּל בִּכְבוֹד רִבּוֹנוֹ? וְעוֹד, הֲרֵי אָמַר רַבִּי שִׁמְעוֹן, בְּמַרְאֶה אֶחָד שֶׁרָאָה לְפִי שָׁעָה, שֶׁכָּתוּב וַיְגַל ה' אֶת עֵינֵי בִלְעָם, הִתְעַקְּמוּ עֵינָיו, וְאַתָּה אוֹמֵר שֶׁהֲרֵי רוֹאֶה בְגִלּוּי עֵינַיִם וּמִסְתַּכֵּל בִּכְבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא?</p>\n<p>אָמַר לוֹ, אֲנִי אֶחֱזֹר לְמוּלְךְ, שֶׁלִּי וְשֶׁלְּךְ צָרִיךְ צַחוּת. וַדַּאי סוֹדוֹת תּוֹרָה עֶלְיוֹנִים, וְלֹא יְכוֹלִים בְּנֵי אָדָם לַעֲמֹד עֲלֵיהֶם. לָכֵן אָסוּר לְהַקְדִּים בִּדְבַר תּוֹרָה עַד שֶׁיִּשְׁמַע דָּבָר וְיֵדַע אוֹתוֹ עַל בֻּרְיוֹ. בָּאוּ לִפְנֵי רַבִּי שִׁמְעוֹן וְאָמְרוּ דָבָר לְפָנָיו.</p>"],[9522012439,"<p>פָּתַח וְאָמַר, (תהלים ח) מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ שֶׁמְּמֻנֵּי הָעוֹלָם אָמְרוּ אוֹתוֹ בְּשָׁעָה שֶׁעָלָה בִרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אָדָם. קָרָא לְכִתּוֹת כִּתּוֹת שֶׁל מַלְאֲכֵי עֶלְיוֹן וְהוֹשִׁיבָם לְפָנָיו. אָמַר לָהֶם, אֲנִי רוֹצֶה לִבְרֹא אָדָם. אָמְרוּ לְפָנָיו, (שם מט) וְאָדָם בִּיקָר בַּל יָלִין וְגוֹ'. הוֹשִׁיט הַקָּדוֹשׁ בָּרוּךְ הוּא אֶצְבָּעוֹ וְשָׂרַף אוֹתָם. הוֹשִׁיב כִּתּוֹת אֲחֵרוֹת לְפָנָיו. אָמַר לָהֶם, אֲנִי רוֹצֶה לִבְרֹא אָדָם. אָמְרוּ לְפָנָיו, מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ? מַה טִּיבוֹ שֶׁל אָדָם זֶה? אָמַר לָהֶם, בֶּן אָדָם שֶׁיִּהְיֶה בַצֶּלֶם שֶׁלָּנוּ, שֶׁתִּהְיֶה חָכְמָתוֹ עֶלְיוֹנָה מֵחָכְמַתְכֶם.</p>\n<p>כֵּיוָן שֶׁבָּרָא אָדָם, וְחָטָא, וְיָצָא זַכַּאי לְפָנָיו, בָּאוּ עֲזָ\"א וַעֲזָאֵ\"ל, אָמְרוּ לְפָנָיו: פִּתְחוֹן פֶּה יֵשׁ לָנוּ אֵלֶיךְ, הֲרֵי בֶּן אָדָם שֶׁעָשִׂיתָ חָטָא לְפָנֶיךְ! אָמַר לָהֶם: אִלְמָלֵא תִּהְיוּ מְצוּיִים אֶצְלָם וְכוּ'. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? הִפִּילָם מִדַּרְגָּתָם הַקְּדוֹשָׁה מֵהַשָּׁמַיִם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כָּעֵת הֵשַׁבְתִּי לִשְׁאֵלַתְכֶם, שֶׁבִּלְעָם אָמַר נֹפֵל וּגְלוּי עֵינָיִם. אִם נֹאמַר שֶׁלֹּא הָיָה כָּךְ, וּשְׁבָחִים הָיָה מְשַׁבֵּחַ אֶת עַצְמוֹ - אֵיךְ יִכְתֹּב הַקָּדוֹשׁ בָּרוּךְ הוּא דָּבָר כּוֹזֵב בַּתּוֹרָה?! וְאִם דְּבַר אֱמֶת הוּא, אֵיךְ יִשְׁתַּבַּח אוֹתוֹ רָשָׁע בְּדַרְגָּה עֶלְיוֹנָה עַל כָּל נְבִיאֵי הָאֱמֶת?! וְעוֹד, שֶׁהֲרֵי אֵין שׁוֹרָה קְדֻשָּׁה הָעֶלְיוֹנָה, רַק בְּמָקוֹם הָרָאוּי לָהּ.</p>\n<p>כָּעֵת חָזַרְנוּ לַדָּבָר הָרִאשׁוֹן. אַחֲרֵי שֶׁהִפִּילָם הַקָּדוֹשׁ בָּרוּךְ הוּא מִמְּקוֹמָם הַקָּדוֹשׁ, טָעוּ אַחַר נְשׁוֹת הָעוֹלָם וְהִטְעוּ אֶת הָעוֹלָם. כָּאן יֵשׁ לְהִסְתַּכֵּל, וַהֲרֵי כָּתוּב (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת וְגוֹ'. וַהֲרֵי מַלְאָכִים אֵלּוּ הָיוּ, אֵיךְ יָכְלוּ לְהִתְקַיֵּם בָּאָרֶץ? אֶלָּא בּא וּרְאֵה, כָּל אוֹתָם (מלכים) שֶׁלְּמַעְלָה לֹא עוֹמְדִים וְלֹא יְכוֹלִים לַעֲמֹד, רַק בְּאוֹר עֶלְיוֹן שֶׁמֵּאִיר לָהֶם וּמְקַיֵּם אוֹתָם. וְאִם פּוֹסֵק מֵהֶם אוֹתוֹ הָאוֹר, לֹא יְכוֹלִים לַעֲמֹד. כָּל שֶׁכֵּן אוֹתָם שֶׁהִפִּילָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִפְסִיק מֵהֶם אוֹתוֹ הָאוֹר שֶׁלְּמַעְלָה שֶׁהִשְׁתַּנָּה זִיוָם. וּכְשֶׁיָּרְדוּ וְשָׁלַט בָּהֶם אֲוִיר הָעוֹלָם, הִשְׁתַּנּוּ בְדַרְגָּה אַחֶרֶת.</p>\n<p>בֹּא וּרְאֵה, הַמָּן שֶׁהָיָה יוֹרֵד לְיִשְׂרָאֵל בַּמִּדְבָּר, אוֹתוֹ מָן הָיָה מִטַּל שֶׁלְּמַעְלָה, שֶׁהָיָה יוֹרֵד מֵהָעַתִּיק הַנִּסְתָּר שֶׁל כָּל הַנִּסְתָּרִים. וּכְשֶׁהָיָה נוֹחֵת, הָיָה אוֹרוֹ מֵאִיר בְּכָל הָעוֹלָמוֹת, וּמִמֶּנּוּ נִזּוֹן שְׂדֵה הַתַּפּוּחִים וּמַלְאָכִים עֶלְיוֹנִים. וּכְשֶׁהָיָה יוֹרֵד לְמַטָּה וְשׁוֹלֵט בּוֹ אֲוִיר הָעוֹלָם, הָיָה מַגְלִיד נִקְפָּא, וּמִשְׁתַּנֶּה זִיווֹ, וְלֹא הָיָה זִיווֹ אֶלָּא כְּמוֹ שֶׁכָּתוּב (במדבר יא) וְהַמָּן כִּזְרַע גַּד הוּא וְגוֹ', וְלֹא יוֹתֵר. וְכָל שֶׁכֵּן הַמַּלְאָכִים, כֵּיוָן שֶׁיָּרְדוּ וְשָׁלַט בָּהֶם אֲוִיר, הִשְׁתַּנּוּ מֵאוֹתָהּ דַּרְגָּה רִאשׁוֹנָה שֶׁהָיוּ בָהּ.</p>\n<p>מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? רָאָה שֶׁהִטְעוּ אֶת הָעוֹלָם, קְשָׁרָם בְּשַׁלְשְׁלָאוֹת בַּרְזֶל בְּהַר הַחֹשֶׁךְ. בְּאֵיזֶה מָקוֹם יוֹשְׁבִים? בְּעֹמֶק הָהָר. הוֹשִׁיב אֶת עֲזָ\"א, וְזָרַק חֹשֶׁךְ הַפָּנִים. מִשּׁוּם שֶׁבְּאוֹתָהּ שָׁעָה שֶׁקְּשָׁרָם הַקָּדוֹשׁ בָּרוּךְ הוּא, הִתְחַזֵּק וְהִרְגִּיז כְּלַפֵּי מַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִפִּילוֹ בְעֹמֶק עַד צַוָּארוֹ, וְזָרַק חֹשֶׁךְ בְּפָנָיו. עֲזָאֵ\"ל שֶׁלֹּא הִתְחַזֵּק, הוֹשִׁיבוֹ לְפָנָיו, וְהֵאִיר לוֹ הַחֹשֶׁךְ.</p>\n<p>וּבְנֵי הָעוֹלָם שֶׁיּוֹדְעִים מְקוֹמָם, בָּאִים אֲלֵיהֶם וּמְלַמְּדִים אֶת בְּנֵי הָאָדָם כְּשָׁפִים וּנְחָשִׁים וּקְסָמִים. וְאוֹתָם הָרֵי הַחֹשֶׁךְ נִקְרָאִים הַרֲרֵי קֶדֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁהַחֹשֶׁךְ מַקְדִּים לָאוֹר, וּמִשּׁוּם זֶה הָרֵי הַחֹשֶׁךְ נִקְרָאִים הַרֲרֵי קֶדֶם. לָבָן וּבִלְעָם לָמְדוּ מֵהֶם כְּשָׁפִים, וְהַיְנוּ מַה שֶּׁאָמַר בִּלְעָם, מִן אֲרָם יַנְחֵנִי בָלָק מֶלֶךְ מוֹאָב מֵהַרֲרֵי קֶדֶם וְגוֹ'.</p>\n<p>בֹּא וּרְאֵה, בִּלְעָם הָיָה מְשַׁבֵּחַ אֶת עַצְמוֹ מִמָּקוֹם זֶה, וְאָמַר, נְאֻם שֹׁמֵעַ אִמְרֵי אֵל וְגוֹ'. מִשּׁוּם שֶׁעֲזָ\"א וַעֲזָאֵ\"ל אוֹמְרִים לְאוֹתָם בְּנֵי הָעוֹלָם מֵאוֹתָם דְּבָרִים עֶלְיוֹנִים שֶׁיָּדְעוּ בַתְּחִלָּה לְמַעְלָה, וּמְדַבְּרִים מֵעוֹלָם הַקָּדוֹשׁ שֶׁהָיוּ בוֹ. זֶהוּ שֶׁכָּתוּבּ שֹׁמֵעַ אִמְרֵי אֵל. לֹא כָתוּב שׁוֹמֵעַ קוֹל אֵל, אֶלָּא אִמְרֵי אֵל, אוֹתָן אֲמִירוֹת שֶׁאוֹמְרִים מִמֶּנּוּ. מִי שֶׁבָּא מֵהַשִּׁעוּר וְשׁוֹאֲלִים אוֹתוֹ מֵאֵיפֹה אַתָּה בָּא - אוֹמֵר: מִלִּשְׁמֹעַ דִּבְרֵי הַמֶּלֶךְ הַקָּדוֹשׁ. כָּךְ נְאֻם שּמֵעַ אִמְרֵי אֵל. וְיֹדֵעַ דַּעַת עֶלְיוֹן, שֶׁהָיָה יוֹדֵעַ בְּשָׁעָה שֶׁהַדִּין תָּלוּי בָּעוֹלָם, וּמְכַוֵּן הַשָּׁעָה בִכְשָׁפָיו.</p>\n<p>אֲשֶׁר מַחֲזֵה שַׁדַּי יֶחֱזֶה. מַה זֶּה מַחֲזֵה שַׁדַּי? אֶלָּא הֵם נֹפֵל וּגְלוּי עֵינָיִם. וְאֵלּוּ הֵם עֲזָ\"א וַעֲזָאֵ\"ל. נֹפֵל - זֶה עֲזָ\"א, שֶׁהֶעֱמִיקוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעֹמֶק הַחֹשֶׁךְ, וְיוֹשֵׁב בְּעֹמֶק עַד צַוָּארוֹ כְּמוֹ שֶׁאָמַרְנוּ, וְחֹשֶׁךְ נִזְרַק בְּפָנָיו, וְלָכֵן נִקְרָא נֹפֵל. נָפַל פַּעַם אַחַת מֵהַשָּׁמַיִם, וְנָפַל פַּעַם אַחֶרֶת אַחַר כָּךְ בְּעֹמֶק הַחֹשֶׁךְ. עֲזָאֵ\"ל - הוּא גְּלוּי עֵינָיִם, שֶׁהֲרֵי לֹא נִזְרַק חֹשֶׁךְ עָלָיו, שֶׁלֹּא הִתְחַזֵּק וְלֹא הִרְגִּיז לְמַעְלָה כְּמוֹ אוֹתוֹ שֶׁלְּמַעְלָה. וּבִלְעָם קָרָא לָהֶם מַחֲזֵה שַׁדַּי, שֶׁהֵם נֹפֵל וּגְלוּי עֵינָיִם.</p>\n<p>וּבְאוֹתוֹ זְמַן לֹא נִשְׁאַר בָּעוֹלָם מִי שֶׁיִּמָּצֵא לִפְנֵיהֶם, פְּרָט לוֹ. וּבְכָל יוֹם הָיָה נִסְתָּר בְּאוֹתָם הָרִים עִמָּהֶם. זֶהוּ שֶׁכָּתוּב יַנְחֵנִי בָלָק מֶלֶךְ מוֹאָב מֵהַרֲרֵי קֶדֶם. מֵהַרֲרֵי קֶדֶם בְּוַדַּאי, וְלֹא מֵאֶרֶץ בְּנֵי קֶדֶם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כַּמָּה פְעָמִים אָמַרְתִּי לְךְ דָּבָר זֶה, וְלֹא מִסְתַּכְּלִים הַחֲבֵרִים, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מַשְׁרֶה שְׁכִינָתוֹ, רַק בְּמָקוֹם קָדוֹשׁ, בְּמָקוֹם שֶׁרָאוּי לְהַשְׁרוֹת עָלָיו. וְכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְרִיז וְאוֹמֵר, (דברים יח) לֹא יִמָּצֵא בְךְ מַעֲבִיר בְּנוֹ וְגוֹ', וְהוּא שֶׁבָּא (בא) לְהִתְעָרֵב אִתָּם. אֶלָּא אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קִדְּשָׁם לִשְׁרוֹת בֵּינֵיהֶם. וְהַיְנוּ מַה שֶּׁכָּתוּב, (שם כג) כִּי ה' אֱלֹהֶיךְ מִתְהַלֵּךְ בְּקֶרֶב מַחֲנֶךְ וְגוֹ'. וּמִשּׁוּם שֶׁהוּא מִתְהַלֵּךְ בְּקֶרֶב מַחֲנֶךְ, כָּתוּב וְהָיָה מַחֲנֶיךְ קָדוֹשׁ וְגוֹ'. וְכָתוּב (ויקרא כ) וִהְיִיתֶם קְדשִׁים וְגוֹ'. וְכָתוּב (שם יח) אַל תִּטַּמְּאוּ בְּכָל אֵלֶּה וְגוֹ'. וְכָתוּב (שם כ) וָאָקֻץ בָּם וְגוֹ'. שֶׁלֹּא יָכֹלְתִּי לִקְרַב אֲלֵיהֶם, וְהִשְׁרוּ אוֹתִי בַּחוּץ. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, וְאַשְׁרֵי חֵלֶק הַנְּבִיאִים הַנֶּאֱמָנִים הַקְּדוֹשִׁים, שֶׁהֵם קְדוֹשִׁים, וְיֵשׁ לָהֶם חֵלֶק לְהִשְׁתַּמֵּשׁ בַּקְּדֻשָּׁה הָעֶלְיוֹנָה.</p>"],[9522012440,"<p>וַתֵּרֶא הָאָתוֹן אֶת מַלְאַךְ ה' נִצָּב בַּדֶּרֶךְ וְחַרְבּוֹ שְׁלוּפָה בְּיָדוֹ. (בדרך,) בְּאוֹתוֹ דֶּרֶךְ שֶׁהָיָה שׁוֹקֵעַ (נמצא) בְּתוֹכָהּ. וְחַרְבּוֹ שְׁלוּפָה בְּיָדוֹ, וְכִי אִם הוּא יָצָא מוּל הָאָתוֹן הַזּוֹ, לְשֵׁם מָה צָרִיךְ חֶרֶב? וְאִם הוּא יוֹצֵא מוּל בִּלְעָם, לָמָּה רָאֲתָה הָאָתוֹן שֶׁלּוֹ, וְהוּא לֹא רָאָה? אֶלָּא הַכֹּל הִזְדַּמֵּן. אוֹתוֹ מַלְאָךְ מִזְדַּמֵּן מוּל הָאָתוֹן לְהוֹצִיאָהּ מֵאוֹתוֹ הַדֶּרֶךְ שֶׁנִּטְעָן בָּהּ. וּבַמֶּה? בְּרַחֲמִים. וְהִזְדַּמֵּן מוּל בִּלְעָם, לְהַעֲנִישׁוֹ עַל שֶׁרָצָה לָלֶכֶת בִּרְשׁוּתוֹ וְלֹא בְּרָשׁוּת אַחֶרֶת (שלמעלה).</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּעֵת יֵשׁ לִשְׁאֹל: אִם דְּבָרָיו הָיוּ בָאִים מִצַּד כְּתָרִים הַתַּחְתּוֹנִים וְלֹא מִמָּקוֹם אַחֵר, לָמָּה כָּתוּב וַיָּבֹא הָאֱלֹהִים אֶל בִּלְעָם וְגוֹ', וְאַךְ אֶת הַדָּבָר וְגוֹ'? אָמַר רַבִּי יִצְחָק, (בשביל ישראל חזר המלאך לדבר אתו. שאם תאמר שהקדוש ברוך הוא דבר אתו, והוא אמר אך את הדבר וגו' חס ושלום, שהרי אותו מלאך אמר לו, ואפס את הדבר וגו'. שאם תאמר, ויאמר אלהים אלבלעם וגו') כָּךְ לָמַדְתִּי, שֶׁהֲרֵי אֱלֹהִים שֶׁל כָּאן, כֻּלָּם מַלְאָךְ הָיָה. וְאוֹתוֹ הוּא מָקוֹם שֶׁבָּא מִצַּד דִּין הַקָּשֶׁה שֶׁבּוֹ אֲחוּזִים כֹּחַ וְתֹקֶף אוֹתָם כְּתָרִים תַּחְתּוֹנִים שֶׁבִּלְעָם הָיָה מִשְׁתַּמֵּשׁ בָּהֶם. וּמִשּׁוּם כָּךְ, וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם. וַיֹּאמֶר אֱלֹהִים אֶל בִּלְעָם. שֶׁלִּפְעָמִים נִקְרָא מַלְאָךְ בְּשֵׁם עֶלְיוֹן.</p>\n<p>וַתֵּט הָאָתוֹן מִן הַדֶּרֶךְ, סָטְתָה מֵאוֹתוֹ הַדֶּרֶךְ, שֶׁהָיְתָה טְעוּנָה מִצַּד דִּין הַקָּשֶׁה כְּנֶגֶד יִשְׂרָאֵל. וּבַמָּה רָאָה בִלְעָם שֶׁהִיא סָטְתָה מֵאוֹתוֹ הַדֶּרֶךְ? אֶלָּא כָּךְ אָמַר רַבִּי שִׁמְעוֹן, שֶׁאֲפִלּוּ בַּדֶּרֶךְ רָצָה לְהַזִּיק לְיִשְׂרָאֵל בְּכֹחַ אֲתוֹנוֹ. וְכֵיוָן שֶׁלֹּא עָלְתָה בְיָדוֹ, מַה כָּתוּב? וַיַּךְ אֶת הָאָתוֹן בַּמַּקֵּל. הִטְעִין אוֹתָהּ וְהִלְבִּישׁ אוֹתָהּ בְּזֵרוּזֵי דִין קָשֶׁה וְחָזָק. זֶהוּ שֶׁכָּתוּב בַּמַּקֵּל, בַּמַּקֵּל דַּוְקָא, שֶׁהוּא דִּין קָשֶׁה תַּקִּיף. בְּמַקְלוֹ לֹא כָתוּב, אֶלָּא בַּמַּקֵּל.</p>\n<p>צֵא וּרְאֵה כַּמָּה תַּקִּיפָה חָכְמַת אוֹתוֹ רָשָׁע וְתַאֲוָתוֹ לְהַזִּיק לָהֶם לְיִשְׂרָאֵל, שֶׁהוּא הִשְׁגִּיחַ לָצֵאת מֵרָשׁוּת שֶׁלְּמַעְלָה בִּגְלַל תַּאֲוָתוֹ לְהִתְכַּבֵּד וּלְהַזִּיק לָהֶם לְיִשְׂרָאֵל.</p>\n<p>וַיַּעָמֹד מַלְאַךְ ה' בְּמִשְׁעוֹל הַכְּרָמִים וְגוֹ'. מַה כָּתוּב לְמַעְלָה? בַּהַתְחָלָה כָּתוּב וַתֵּט הָאָתוֹן מִן הַדֶּרֶךְ וַתֵּלֵךְ בַּשָּׂדֶה. וַתֵּלֶךְ בְּדֶרֶךְ יָשָׁר, מִצַּד הַשָּׂדֶה, (התעוררה) וְנָטְתָה מִמַּה שֶּׁהָיָה בָּהּ. וַיַּךְ בִּלְעָם אֶת הָאָתוֹן לְהַטֹּתָהּ הַדָּרֶךְ, לְהַסְטוֹתָהּ מֵאוֹתוֹ דֶּרֶךְ שֶׁל הַשָּׂדֶה. אָמַר רַבִּי יוֹסֵי, בֵּין הַמַּלְאָךְ וּבֵין בִּלְעָם הָיְתָה הָאָתוֹן בִּמְצוּקָה. אַחַר כָּךְ רָאָה בִּלְעָם שֶׁלֹּא הָיָה יָכוֹל, אָז וַיַּךְ אֶת הָאָתוֹן בַּמַּקֵּל, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וַיַּעָמֹד מַלְאַךְ ה' וְגוֹ'. אָמַר רַבִּי אַבָּא, כַּמָּה יֵשׁ לָנוּ לְהִסְתַּכֵּל בְּדִבְרֵי הַתּוֹרָה. פְּסוּקִים אֵלּוּ רְמוּזִים בְּחָכְמָה עֶלְיוֹנָה. וְכִי לְחִנָּם יָצָא מַלְאָךְ זֶה לְהֵרָאוֹת לְאָתוֹן אַחַת, אוֹ לַעֲמֹד מוּלָהּ בֵּין הַכְּרָמִים פַּעַם כָּאן וּפַעַם כָּאן? אֶלָּא הַכֹּל סוֹד עֶלְיוֹן הוּא, וְהַכֹּל רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי לְהָגֵן עַל יִשְׂרָאֵל וְלֹא יִשְׁלְטוּ בָהֶם מִינִים רָעִים, מִשּׁוּם שֶׁהֵם חֶלְקוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וַיַּעָמֹד מַלְאַךְ ה' וְגוֹ'. לָמַדְנוּ, מִצַּד הָאִמָּא, כְּשֶׁהִיא מִתְעַטֶּרֶת, יוֹצְאִים בְּעַטְרוֹתֶיהָ אֶלֶף וַחֲמֵשׁ מֵאוֹת צְדָדִים חֲקוּקִים בְּתַכְשִׁיטֶיהָ. וּכְשֶׁרוֹצָה לְהִזְדַּוֵּג בַּמֶּלֶךְ, מִתְעַטֶּרֶת בַּעֲטָרָה אַחַת שֶׁל אַרְבָּעָה גְוָנִים. אוֹתָם גְּוָנִים לוֹהֲטִים בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם, כָּל גָּוֶן וְגָוֶן לוֹהֵט שָׁלֹשׁ פְּעָמִים בְּאוֹתוֹ צַד, שֶׁהֵם שְׁנֵים עָשָׂר תְּחוּמִים חֲקוּקִים, וְנִכְנָסִים וְנִכְלָלִים בִּשְׁנֵים עָשָׂר אֲחֵרִים.</p>\n<p>בְּרֹאשׁ הָעֲטָרָה יֵשׁ אַרְבַּע חוֹמוֹת לְאַרְבָּעָה צְדָדִים, וְהֵם מִגְדָּלוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ה) מִגְדְּלוֹת מֶרְקָחִים. מַה זֶּה מֶרְקָחִים? כְּמוֹ שֶׁנֶּאֱמַר (שם ג) מִכֹּל אַבְקַת רוֹכֵל. וְעַל כָּל מִגְדָּל וּמִגְדָּל שְׁלֹשָׁה פְתָחִים קְבוּעִים בַּאֲבָנִים טוֹבוֹת מִכָּל צַד וְצַד. עֲטָרָה זוֹ מְאִירָה (טהורה) (טמירה) בְּדִלּוּגִים שֶׁל אוֹפִיר בִּשְׁבִיל כְּבוֹד הַמֶּלֶךְ, כְּמוֹ שֶׁכָּתוּב (ישעיה יג) אוֹקִיר אֱנוֹשׁ מִפָּז וְגוֹ'.</p>\n<p>תַּחַת הָעֲטָרָה תְּלוּיִים זַגֵּי זָהָב סְבִיבוֹתֶיהָ, זַג זָהָב מִצַּד זֶה, וְזַג זָהָב מִצַּד זֶה, וְרִמּוֹן אֶחָד. (בתוך) כְּגוֹן אוֹתוֹ רִמּוֹן יֵשׁ אֶלֶף זַגִּים, וְכָל זַג מֵהֶם לוֹהֵט בְּאָדם וְלָבָן. אוֹתוֹ רִמּוֹן נֶחֱלָק לְאַרְבָּעָה חֲלָקִים, וְיֵשׁ פֶּתַח לִרְאוֹת זַגָּיו. שְׁלֹשׁ מֵאוֹת וְעֶשְׂרִים וַחֲמִשָּׁה זַגִּים לְצַד זֶה, וְכֵן לְכָל צַד וְצַד, עַד שֶׁלּוֹהֲטִים אַרְבָּעָה צִדְדֵי הָעוֹלָם מִמַּרְאֵה כָּל פֶּלַח וּפֶלַח, וְהֵם נִקְרָאִים פֶּלַח הָרִמּוֹן, כְּמוֹ שֶׁכָּתוּב (שיר השירים ד) כְּפֶלַח הָרִמּוֹן רַקָּתֵךְ מִבַּעַד לְצַמָּתֵךְ.</p>\n<p>אַרְבָּעָה גַלְגַּלִּים בְּפִלְחֵי אַרְבַּע הַזָּוִיּוֹת לוֹקְחִים בְּגִלְגּוּל אֶת אוֹתָהּ עֲטָרָה, וּכְשֶׁלּוֹקְחִים אוֹתָהּ, מִזְדַּקְּפִים לְמַעְלָה. עַד שֶׁמַּגִּיעִים לְגִלְגּוּל פֶּלַח הָעֶלְיוֹן, שֶׁנּוֹהֵם יוֹמָם וָלַיְלָה, מִתְחַבְּרִים כָּל אוֹתָם פְּלָחִים, וְלוֹקְחִים הָעֲטָרָה וְזוֹקְפִים אוֹתָהּ. וְקוֹל אוֹתָם הַגַּלְגַּלִּים נִשְׁמָע בְּכָל הָרְקִיעִים. לְקוֹל נְעִימוּתָם רוֹעֲשִׁים כָּל כֹּחוֹת הַשָּׁמַיִם, וְכֻלָּם שׁוֹאֲלִים זֶה לָזֶה, עַד שֶׁכֻּלָּם אוֹמְרִים: (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ.</p>\n<p>כְּשֶׁמִּזְדַּוֵּג הַמֶּלֶךְ בַּמַּלְכָּה, עוֹלָה עֲטָרָה זוֹ וּמִתְיַשֶּׁבֶת בְּרֹאשׁ הַמַּלְכָּה, וְאָז יוֹרֶדֶת עֲטָרָה אַחַת עֶלְיוֹנָה קְבוּעָה שֶׁל כָּל אֶבֶן טוֹבָה, וְכַפְתּוֹר וָפֶרַח סְבִיבָהּ. בְּשִׁשָּׁה גַלְגַּלִּים בָּאָה לְשִׁשָּׁה צִדְדֵי הָעוֹלָם, שֵׁשׁ כַּנְפֵי נֶשֶׁר לוֹקְחִים אוֹתָהּ. בִּפְלָחֶיהָ חֲמִשִּׁים (פלחי) עֲנָבִים סְבִיבָהּ שֶׁחָקְקָה בָּהּ הָאֵם הָעֶלְיוֹנָה, קְבוּעִים בְּאֶבֶן טוֹבָה, לָבָן וְאָדם, יָרֹק וְשָׁחֹר, תְּכֵלֶת וְאַרְגָּמָן. שֵׁשׁ מֵאוֹת וּשְׁלֹשׁ עֶשְׂרֵה זָוִיּוֹת לְכָל צַד וְצַד.</p>\n<p>אֶלֶף וְשֵׁשׁ מֵאוֹת מִגְדָּלִים לְכָל צַד וְצַד, וְכָל מִגְדָּל וּמִגְדָּל הָרִים קְבוּעִים. פּוֹרְחִים לְמַעְלָה, נִשְׁאָבִים בִּכְתֹנֶת (בשלחן) הָאֵם הָעֶלְיוֹנָה בְּשֶׁמֶן מִשְׁחָה שֶׁלָּהּ. אָז הָאִמָּא בְּלַחַשׁ מַשְׁפִּיעָה מַתָּנוֹת עֶלְיוֹנוֹת, וְשׁוֹלַחַת וְקוֹבַעַת אוֹתָם בְּאוֹתָהּ הָעֲטָרָה. אַחַר כָּךְ מַשְׁפִּיעָה נַחֲלֵי שֶׁמֶן מִשְׁחַת קֹדֶשׁ עַל רֹאשׁ הַמֶּלֶךְ, וּמֵהָרֹאשׁ יוֹרֵד אוֹתוֹ שֶׁמֶן טוֹב עֶלְיוֹן עַל זְקָנוֹ הַמְכֻבָּד, וּמִשָּׁם שׁוֹפֵעַ עַל אוֹתָם לְבוּשֵׁי הַמֶּלֶךְ. זֶהוּ שֶׁכָּתוּב (תהלים קלג) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ יֹרֵד עַל הַזָּקָן וְגוֹ'.</p>\n<p>אַחַר כָּךְ חוֹזֶרֶת הָעֲטָרָה, וּמְעַטֶּרֶת אוֹתָהּ הָאֵם הָעֶלְיוֹנָה בְּאוֹתָהּ עֲטָרָה, וּפוֹרֶשֶׂת אוֹתָהּ עָלָיו וְעַל הַמַּלְכָּה, לְבוּשֵׁי כָבוֹד בְּאוֹתָהּ עֲטָרָה. וְאָז נִשְׁמָע קוֹל בְּכָל הָעוֹלָמוֹת, (שיר השירים ג) צְאֶינָה וּרְאֶינָה וְגוֹ'. אָז חֶדְוָה הִיא בְּכָל בְּנֵי הַמֶּלֶךְ. וּמִי הֵם? כָּל אוֹתָם שֶׁבָּאוּ מִצַּד יִשְׂרָאֵל, שֶׁהֲרֵי לֹא מִזְדַּוְּגִים בָּהֶם וְלֹא עוֹמְדִים עִמָּהֶם, פְּרָט לְאוֹתָם יִשְׂרָאֵל שֶׁהֵם בְּנֵי הַבַּיִת וּמְשַׁמְּשִׁים אוֹתָם. וְאָז בְּרָכוֹת שֶׁיּוֹצְאוֹת מֵהֶם, שֶׁל יִשְׂרָאֵל הֵן.</p>\n<p>וְיִשְׂרָאֵל לוֹקְחִים הַכֹּל, וְשׁוֹלְחִים חֵלֶק מִמֶּנּוּ לִשְׁאָר הָעַמִּים, וּמֵאוֹתוֹ חֵלֶק נִזּוֹנִים כָּל אוֹתָם הָעַמִּים. וְלָמַדְנוּ, מִבֵּין צִדְדֵי חֶלְקָם שֶׁל הַמְמֻנִּים עַל שְׁאָר הָעַמִּים יוֹצֵא שְׁבִיל דַּקִּיק אֶחָד שֶׁמִּשָּׁם נִשְׁפָּע חֵלֶק לְאוֹתָם תַּחְתּוֹנִים, וּמִשָּׁם נִפְרָד לְכַמָּה צְדָדִים. וְלָזֶה קוֹרְאִים תַּמְצִית, שֶׁיּוֹצֵאת מִצַּד הָאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>וְעַל זֶה כָּל הָעוֹלָם שׁוֹתֶה מִתַּמְצִית אֶרֶץ יִשְׂרָאֵל. מִי זוֹ אֶרֶץ יִשְׂרָאֵל? הֲרֵי בֵּאַרְנוּ. וּבֵין לְמַעְלָה וּבֵין לְמַטָּה, כָּל אוֹתָם שְׁאָר עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת לֹא נִזּוֹנִים אֶלָּא מֵאוֹתָהּ תַּמְצִית. וְאַל תֹּאמַר שֶׁהֵם בִּלְבַדָּם, אֶלָּא אֲפִלּוּ אוֹתָם כְּתָרִים תַּחְתּוֹנִים שׁוֹתִים מֵאוֹתָהּ תַּמְצִית. וְזֶהוּ בְּמִשְׁעוֹל הַכְּרָמִים, שְׁבִיל מִגְּדוֹלֵי שְׁאָר הָעַמִּים שֶׁמִּתְבָּרְכִים מִמֶּנּוּ.</p>\n<p>כְּשֶׁרָאָה אוֹתוֹ מַלְאָךְ שֶׁבִּלְעָם מַסְטֶה אֶת הָאָתוֹן לְאוֹתוֹ שְׁבִיל, שֶׁכָּתוּב לְהַ תָהּ הַדָּרֶךְ, מִיָּד - וַיַּעֲמֹד מַלְאַךְ ה' בְּמִשְׁעוֹל הַכְּרָמִים, לְהַסְתִּיר הַשְּׁבִיל, שֶׁלֹּא יִסְתַּיְּעוּ בוֹ שְׁאָר עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת וְאוֹתָם כְּתָרִים תַּחְתּוֹנִים. וְהָלְכָה זוֹ, כְּזוֹ שֶׁאָמַר רַבִּי יִצְחָק. כָּתוּב (שיר השירים א) שָׂמֻנִי נֹטֵרָה וְגוֹ', לִשְׁמֹר וּלְבָרֵךְ אֶת שְׁאָר הָעַמִּים בַּגָּלוּת. וְיִשְׂרָאֵל שֶׁהֵם כַּרְמִי שֶׁלִּי - לֹא נָטָרְתִּי, מִשּׁוּם שֶׁהֵם בַּגָּלוּת וְלֹא מִתְבָּרְכִים כָּרָאוּי.</p>\n<p>גָּדֵר מִזֶּה וְגָדֵר מִזֶּה. אָמַר רַבִּי אַבָּא, אֵיךְ יָכוֹל אוֹתוֹ מַלְאָךְ לְהַסְתִּיר אוֹתוֹ הַשְּׁבִיל? אֶלָּא מִשּׁוּם שֶׁסִּיּוּעַ אַחֵר הָיָה לוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל. רַבִּי יְהוּדָה אָמַר, הַתּוֹרָה סִיְּעָה לוֹ, שֶׁכָּתוּב (שמות לב) מִזֶּה וּמִזֶּה הֵם כְּתֻבִים.</p>\n<p>בְּאוֹתָהּ שָׁעָה מַה כָּתוּב? וַתֵּרֶא הָאָתוֹן וְגוֹ', וַתִּלָּחֵץ אֶל הַקִּיר. מַה זֶּה וַתִּלָּחֵץ אֶל הַקִּיר? כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כב) מְקַרְקַר קִר וְגוֹ'. קִיר - פַּטְרוֹן, אוֹתוֹ שֶׁשּׁוֹלֵט עֲלֵיהֶם. וַתִּלְחַץ אֶת רֶגֶל בִּלְעָם אֶל הַקִּיר, הִיא לֹא נָתְנָה לוֹ כְּלָל סִיּוּעַ. וּבַמְּצוּקָה (זרקה) הִנִּיחָה (שלחה) אוֹתוֹ לְאוֹתוֹ קִיר וְרָמְזָה לוֹ זֶה. אָז וַיּסֶף לְהַכֹּתָהּ, בַּצַּד הַזֶּה.</p>\n<p>וַיּוֹסֶף מַלְאַךְ ה' עֲבוֹר וַיַּעֲמֹד בְּמָקוֹם צָר וְגוֹ'. בְּאוֹתָהּ שָׁעָה הִסְתִּיר לָהּ כָּל הַדְּרָכִים וְכָל הַסִּיּוּעִים, שֶׁלֹּא נִמְצָא בָּהּ סִיּוּעַ מִכָּל צַד שֶׁבָּעוֹלָם. אָז וַתִּרְבַּץ תַּחַת בִּלְעָם. כְּשֶׁרָאָה בִלְעָם שֶׁלֹּא הָיָה יָכוֹל, מַה כָּתוּב? וַיִּחַר אַף בִּלְעָם וַיַּךְ אֶת הָאָתוֹן בַּמַּקֵּל, כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁהִתְקִינָהּ וְהִלְבִּישָׁהּ בְּזֵרוּזֵי דִין קָשֶׁה וְתַקִּיף.</p>\n<p>וַיִּפְתַּח ה' אֶת פִּי הָאָתוֹן וְגוֹ'. זֶה אֶחָד מֵאוֹתָם דְּבָרִים שֶׁנִּבְרְאוּ עֶרֶב שַׁבָּת בֵּין הַשְּׁמָשׁוֹת. אָמַר רַבִּי יִצְחָק, מָה הַגְּדֻלָּה הַזּוֹ לְבִלְעָם אוֹ לָאָתוֹן אוֹ לְיִשְׂרָאֵל בַּדְּבָרִים הַלָּלוּ? אָמַר רַבִּי יוֹסֵי, שֶׁצָּחֲקוּ עָלָיו אוֹתָם גְּדוֹלִים שֶׁהָיוּ עִמּוֹ, וּכְשֶׁהִגִּיעוּ לְבָלָק, אָמְרוּ לוֹ: וְכִי לַשּׁוֹטֶה הַזֶּה שָׁלַחְתָּ לְכַבֵּד?! לֹא תִמְצָא בּוֹ מַמָּשׁ וְלֹא בִדְבָרָיו. וּבְאוֹתוֹ דִּבּוּר שֶׁל הָאָתוֹן הִתְבַּזָּה מִכְּבוֹדוֹ. רַבִּי חִיָּיא אָמַר, אִלְמָלֵא לֹא אָמְרָה הָאָתוֹן אֶת זֶה, לֹא הִשְׁאִיר בִּלְעָם אוֹתוֹ שֶׁלּוֹ, וּבְדִבְרֵי הָאָתוֹן יָדַע שֶׁנִּשְׁבָּר כֹּחוֹ.</p>\n<p>רַבִּי אַבָּא שָׁאַל, כָּתוּב (במדבר טז) וַתִּפְתַּח הָאָרֶץ וְגוֹ', וְכָתוּב וַיִּפְתַּח ה' אֶת פִּי וְגוֹ'. מַה שּׁוֹנֶה אֶרֶץ מֵאָתוֹן שֶׁלֹּא כָתוּב בָּהּ וַיִּפְתַּח ה' אֶת פִּי הָאָרֶץ? אֶלָּא שָׁם מֹשֶׁה גָּזַר עַל הַפֶּה, וּפָתְחָה וְעָשְׂתָה הָאָרֶץ אֶת מִצְוַת מֹשֶׁה, וְלֹא נָאֶה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַעֲבֹר מִצְוָתוֹ, שֶׁהֲרֵי מֹשֶׁה גָּזַר וְצִוָּה, וּפָצְתָה הָאֲדָמָה אֶת פִּיהָ. וְלָכֵן הִיא עָשְׂתָה מִצְוָתוֹ, שֶׁכָּתוּב וַתִּפְתַּח הָאָרֶץ אֶת פִּיהָ. אֲבָל כָּאן לֹא נִמְצָא מִי שֶׁגָּזַר, אֶלָּא רְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה, וְהוֹאִיל וּרְצוֹנוֹ הָיָה בְּכָךְ, כָּתוּב וַיִּפְתַּח ה' אֶת פִּי הָאָתוֹן. מִמֶּנּוּ בָּא הַדָּבָר, וּמִמֶּנּוּ נִמְצָא.</p>\n<p>רַבִּי יְהוּדָה אָמַר, הִסְתַּכַּלְתִּי בְּפָרָשָׁה זוֹ וּבַדְּבָרִים הַלָּלוּ, וְנִרְאֶה שֶׁאֵלּוּ דְּבָרִים שֶׁלֹּא צְרִיכִים. וְכִי מֵאַחַר שֶׁכָּתוּב וַיִּפְתַּח ה' אֶת פִּי הָאָתוֹן, צָרִיךְ לִהְיוֹת דְּבָרִים הַלָּלוּ דְּבָרִים מְעֻלִּים, דִּבְרֵי חָכְמָה?! וְאִם כְּמוֹ שֶׁהִתְעוֹרְרוּ חֲבֵרֵינוּ, שֶׁהוּא מִשְׁתַּבֵּחַ שֶׁסּוּסָתוֹ רוֹעָה בָּאָחוּ, וְהִיא שָׁבָה וְאוֹמֶרֶת: הֲלוֹא אָנֹכִי אֲתֹנְךְ - מִכָּאן הָיָה לָהּ לִפְתֹּחַ! וְהִיא לֹא פָתְחָה, אֶלָּא - מֶה עָשִׂיתִי לְךְ. וְאִם כָּךְ, לָמָּה טָרַח הַקָּדוֹשׁ בָּרוּךְ הוּא לִפְתֹּחַ אֶת פִּיהָ בַּדְּבָרִים הַלָּלוּ?</p>\n<p>אָמַר רַבִּי אַבָּא, וַדַּאי בַּדְּבָרִים הַלָּלוּ לָמַדְנוּ עַל דַּעַת בִּלְעָם שֶׁאֵינוֹ כְדַאי לִשְׁרוֹת עָלָיו רוּחַ הַקֹּדֶשׁ. וְלָמַדְנוּ שֶׁהֲרֵי אֵין בַּאֲתוֹנוֹ יְכֹלֶת לְהַזִּיק אוֹ לְהֵיטִיב. וְלָמַדְנוּ מֵאָתוֹן זוֹ שֶׁהֲרֵי אֵין כֹּחַ בַּבְּהֵמוֹת לְהַשְׁרוֹת עֲלֵיהֶן דַּעַת שְׁלֵמָה. בֹּא תִרְאֶה, בִּלְעָם, בְּאוֹתוֹ דִּבּוּר שֶׁל אֲתוֹנוֹ וּבְאוֹתָהּ דַּעַת טִפְּשָׁה לֹא יָכוֹל לַעֲמֹד. בְּדַעַת עֶלְיוֹנָה עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>וַתֹּאמֶר לְבִלְעָם מֶה עָשִׂיתִי לְךְ. וְכִי בִרְשׁוּתִי הָיָה לַעֲשׂוֹת טוֹב וָרָע? לֹא. שֶׁהֲרֵי בְּהֵמוֹת לֹא מִתְנַהֲגוֹת אֶלָּא בְּמַה שֶּׁמַּנְהִיגִים אוֹתָן. וְאַף עַל גַּב שֶׁאוֹתָהּ אָתוֹן בְּעֹמֶק (במצוקה) יוֹתֵר, זֶה לֹא בִרְשׁוּתָהּ, שֶׁהֲרֵי הוּא הִטְעִינָהּ בִּכְשָׁפָיו, וְעוֹמֶדֶת בִּרְשׁוּתוֹ.</p>\n<p>וַיֹּאמֶר בִּלְעָם לָאָתוֹן כִּי הִתְעַלַּלְתְּ בִּי. הָיָה לוֹ לִצְחֹק מִמֶּנָּה, וְהוּא הֵשִׁיב כְּטִפְּשׁוּת דְּבָרֶיהָ לְעֻמָּתָהּ. אָז צָחֲקוּ מִמֶּנּוּ, וְנִהְיָה קַל בְּעֵינֵיהֶם, וְיָדְעוּ שֶׁהוּא שׁוֹטֶה. וּמָה אָמַר? כִּי הִתְעַלַּלְתְּ בִּי לוּ יֶשׁ חֶרֶב בְּיָדִי. אָמְרוּ: שׁוֹטֶה זֶה יָכוֹל לְהַשְׁמִיד עַמִּים בְּפִיו, אֵיךְ לֹא יָכוֹל לְהַשְׁמִיד אֶת אֲתוֹנוֹ וְהוּא צָרִיךְ חֶרֶב?! וְלָמַדְנוּ שֶׁאֵין כֹּחַ בַּבְּהֵמוֹת לְהַשְׁרוֹת עֲלֵיהֶן רוּחַ אַחֶרֶת. שֶׁאִם יֹאמְרוּ בְּנֵי אָדָם, אִם יְדַבְּרוּ הַבְּהֵמוֹת כַּמָּה דַעַת שָׁלֵם יוֹצִיאוּ לָעוֹלָם - צֵא וּלְמַד מֵאָתוֹן זוֹ, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא פָּתַח פִּיהָ, רְאֵה דְבָרֶיהָ.</p>"],[9522012441,"<p>וַיְהִי בַבֹּקֶר וַיִּקַּח בָּלָק אֶת בִּלְעָם וְגוֹ'. רַבִּי יִצְחָק אָמַר, בָּלָק הָיָה חָכָם בִּכְשָׁפִים יוֹתֵר מִבִּלְעָם, פְּרָט שֶׁלֹּא הָיָה מְכַוֵּן הַשָּׁעָה לְקַלֵּל. מָשָׁל וְכוּ'. מִשּׁוּם כָּךְ, וַיִּקַּח בָּלָק אֶת בִּלְעָם וְגוֹ'. הוּא הָיָה מַתְקִין אוֹתוֹ וְאוֹחֲזוֹ לַכֹּל.</p>\n<p>וַיַּעָלֵהוּ בָּמוֹת בָּעַל. מַה זֶּה וַיַּעֲלֵהוּ בָּמוֹת בָּעַל? אֶלָּא הִשְׁגִּיחַ בִּכְשָׁפָיו בְּאֵיזֶה צַד יֶאֱחֹז בָּהֶם, וּמָצָא שֶׁעֲתִידִים יִשְׂרָאֵל לַעֲשׂוֹת בָּמוֹת וְלַעֲבֹד לַבַּעַל, כְּמוֹ שֶׁכָּתוּב, וַיֵּלְכוּ אַחֲרֵי הַבַּעַל. וַיַּרְא מִשָּׁם קְצֵה הָעָם, רָאָה אֶת גְּדוֹלֵי הָעָם וּמַלְכָּם שֶׁעוֹבְדִים לוֹ, כְּמוֹ שֶׁכָּתוּב (מלכים א יח) וַיִּקְרְאוּ בְשֵׁם הַבַּעַל, וְכָתוּב (שם) אִם ה' הָאֱלֹהִים וְגוֹ'. כֵּיוָן שֶׁרָאָה בִלְעָם שֶׁעֲתִידִים יִשְׂרָאֵל לָזֶה, מִיָּד - וַיֹּאמֶר בִּלְעָם אֶל בָּלָק בְּנֵה לִי בָזֶה שִׁבְעָה מִזְבְּחֹת.</p>\n<p>רַבִּי יוֹסֵי וְרַבִּי יְהוּדָה. אֶחָד אָמַר, כְּנֶגֶד מִזְבְּחוֹת שֶׁל הָרִאשׁוֹנִים הִקְרִיב אוֹתָם שִׁבְעָה מִזְבְּחוֹת. וְאֶחָד אָמַר, בְּחָכְמָה עָשָׂה הַכֹּל, וּמָצָא שֶׁחֵלֶק יִשְׂרָאֵל בְּשֶׁבַע דְּרָגוֹת נִקְשְׁרוּ. וּמִשּׁוּם זֶה סִדֵּר שִׁבְעָה מִזְבְּחוֹת.</p>\n<p>לְאָדָם שֶׁהָיָה לוֹ אָהוּב אֶחָד שֶׁהִשְׁאִיר לוֹ אָבִיו, וּבְנֵי אָדָם פָּחֲדוּ לְהִתְקוֹטֵט עִמּוֹ בִּגְלַל אוֹתוֹ אוֹהֵב. לְיָמִים בָּא אָדָם אֶחָד וְרָצָה לְעוֹרֵר קְטָטָה עִמּוֹ. אָמַר: מָה אֶעֱשֶׂה? אִם אָעִיר קְטָטָה עִמּוֹ, הֲרֵי אוֹתוֹ אוֹהֵב שֶׁקָּשׁוּר אִתּוֹ, וַאֲנִי לֹא אוּכַל. אָמַר: מָה אֶעֱשֶׂה? שָׁלַח דּוֹרוֹן לְאוֹתוֹ אוֹהֵב. אָמַר אוֹתוֹ אוֹהֵב: וְכִי מַה יֵּשׁ לָאִישׁ הַזֶּה אִתִּי?! יָדַעְתִּי שֶׁזֶּה בִּגְלַל אוֹתוֹ בֶּן אֲהוּבִי. אָמַר: דּוֹרוֹן זֶה לֹא יִכָּנֵס לְפָנַי. זִרְקוּ אוֹתוֹ לַכְּלָבִים שֶׁיֹּא כְלוּה וּ.</p>\n<p>כָּךָ בִּלְעָם בָּא לְעוֹרֵר קְטָטָה בְּיִשְׂרָאֵל, וְרָאָה שֶׁלֹּא יָכוֹל, בִּגְלַל אוֹתוֹ אוֹהֵב עֶלְיוֹן שֶׁלָּהֶם. (כמו שנאמר (משלי כז) רעך ורע אביך אל תעזב) הִתְחִיל לְתַקֵּן לְפָנָיו דּוֹרוֹן. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: רָשָׁע! וּמַה יֵּשׁ לְךְ אֵלַי?! אַתָּה רוֹצֶה לְהִזְדַּוֵּג אִתִּי? הֲרֵי דּוֹרוֹנְךְ מְזֻמָּן לַכְּלָבִים. בֹּא וּרְאֵה מַה כָּתוּב, וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם. וְאָמַר רַבִּי שִׁמְעוֹן, לְשׁוֹן קֶרִי וְטֻמְאָה. דּוֹרוֹנְךְ יִמָּסֵר לְאֵלֶּה וְלֹא יִכָּנֵס לְפָנַי.</p>\n<p>רַבִּי אַבָּא אָמַר, וַיִּקָּר - כְּמוֹ שֶׁנֶּאֱמַר (תהלים קמז) לִפְנֵי קָרָתוֹ מִי יַעֲמֹד. הוּא הָיָה עָתִיד שֶׁבְּאוֹתוֹ דּוֹרוֹן יוּכַל לְיִשְׂרָאֵל. מַה כָּתוּב? וַיִּקָּר אֱלֹהִים. קֵרֵר עַצְמוֹ מִמַּה שֶּׁהָיָה חוֹשֵׁב, וַיִּקָּר אֱלֹהִים, כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁהִתְעוֹרֵר עָלָיו מִצַּד הַטֻּמְאָה.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, וַיִּקָּר - בִּלְעָם חָשַׁב שֶׁבְּאוֹתוֹ דּוֹרוֹן יִכָּנֵס לְהַזִּיק אֶת יִשְׂרָאֵל, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָקַר אוֹתוֹ מִלִּפְנֵי אוֹתוֹ דּוֹרוֹן. וְעָקַר אֶת בִּלְעָם מִמַּה שֶּׁחָשַׁב, וְעָקַר (אותו מאותה דרגה) אֶת אוֹתָהּ דַּרְגָּה. זֶהוּ שֶׁכָּתוּב וַיִּקָּר, כְּמוֹ שֶׁנֶּאֱמַר (משלי ל) יִקְּרוּהָ עֹרְבֵי נַחַל. אָמַר לוֹ: רָשָׁע! אֵינְךְ כְּדַאי לְהִתְקַשֵּׁר אֵלַי וּלְהִכָּנֵס לְפָנַי. דּוֹרוֹנְךְ נִמְסָר לַכְּלָבִים.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בּא רְאֵה, רָשָׁע זֶה הָיָה גֹּעַל הַכֹּל, שֶׁלֹּא תִמְצָא בְּכָל הַפָּרָשָׁה הַזּוֹ וַיֹּאמֶר ה' אֶל בִּלְעָם, אוֹ וַיְדַבֵּר ה', חַס וְשָׁלוֹם. מַה כָּתוּב? וַיָּשֶׂם ה' דָּבָר בְּפִי בִלְעָם וְגוֹ', כְּמִי שֶׁשָּׂם מַחְסוֹם בְּפִי הַחֲמוֹר שֶׁלֹּא יִסְטֶה כָּאן אוֹ כָּאן. כָּךְ - וַיָּשֶׂם ה' דָּבָר בְּפִי וְגוֹ'.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: רָשָׁע! אַתָּה חוֹשֵׁב שֶׁעַל יָדְךְ תִּהְיֶה וְתִתְקַיֵּם בְּרָכָה בְּבָנַי אוֹ הַהֵפֶךְ - לֹא צְרִיכִים הֵם לְךְ, כְּמוֹ שֶׁאוֹמְרִים לַצִּרְעָה וְכוּ'. אֶלָּא אַתָּה שׁוּב אֶל בָּלָק, וּכְשֶׁתִּפְתַּח פִּיךְ, לֹא יִהְיֶה בִרְשׁוּתְךְ. וְלֹא בְּפִיךְ תָּלוּי הַדִּבּוּר, אֶלָּא וְכֹה תְדַבֵּר. הֲרֵי כֹּה, שֶׁעָתִיד לְבָרְכָם כֹּה, תְּדַבֵּר בִּרְכַּת בָּנַי, שֶׁכְּשֶׁתִּפְתַּח פִּיךְ הִיא תְּדַבֵּר מִלִּים לְהִתְקַיֵּם עַל בָּנַי, שֶׁלֹּא אַשְׁאִיר דְּבָרִים לְךְ.</p>\n<p>בֹּא וּרְאֵה שֶׁכָּךְ הוּא. כֵּיוָן שֶׁבָּא בָלָק, וּבָלָק שָׁמַע כָּל אוֹתָם דְּבָרִים, הָיָה חוֹשֵׁב שֶׁמִּפִּי בִלְעָם יָצְאוּ, וְאָמַר: לָקֹב אֹיְבַי לְקַחְתִּיךְ. אָמַר בִּלְעָם: קַח כְּשָׁפִים אֵלּוּ בְּיָדְךְ, כְּדֵי לְעַכֵּב כָּאן אֶת הַכֹּה הַזֹּאת. וְאִם תּוּכַל לְעַכְּבָהּ (לעקרה) בַּכְּשָׁפִים הַלָּלוּ, אֲנִי אֶעֱקֹר אוֹתָהּ מֵאוֹתָם דְּבָרִים שֶׁהִיא אָמְרָה.</p>\n<p>מַה כָּתוּב? הִתְיַצֵּב כֹּה עַל עֹלָתֶךְ. בָּזֶה וּבַכְּשָׁפִים הַלָּלוּ תְּעַכֵּב אוֹתָהּ, וְאָנֹכִי אִקָּרֶה כֹּה. כְּלוֹמַר, אֶעֱקֹר אוֹתָהּ מֵהַדְּבָרִים הַלָּלוּ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: רָשָׁע! אֲנִי אֶעֱקֹר אוֹתְךְ! מַה כָּתוּב אַחֲרָיו? וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם. וְאוֹתוֹ דָּבָר הֵרִים קוֹל בְּדִבּוּרִים שֶׁל כֹּה. וַיֹּאמֶר שׁוּב אֶל בָּלָק וְכֹה תְדַבֵּר. כֹּה תְדַבֵּר בְּוַדַּאי.</p>\n<p>בֹּא וּרְאֵה, בַּתְּחִלָּה לֹא כָתוּב הִתְיַצֵּב כֹּה עַל עֹלָתְךְ, אֶלָּא הִתְיַצֵּב עַל עֹלָתֶךְ וְאֵלְכָה אוּלַי יִקָּרֶה ה' לִקְרָאתִי. כֵּיוָן שֶׁרָאָה שֶׁכֹּה אָמְרָה אוֹתָן בְּרָכוֹת, אָז אָמַר, הִתְיַצֵּב כֹּה עַל עֹלָתְךְ וְאָנֹכִי אִקָּרֶה כֹּה.</p>\n<p>לְכָה אָרָה לִּי יַעֲקֹב, כְּלוֹמַר לְקֹט. רַבִּי יוֹסֵי אָמַר, זְרֹק אוֹתָם מֵאוֹתָהּ דַּרְגָּה שֶׁהֵם עוֹמְדִים בָּהּ, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א כ) צִדָּהּ אוֹרֶה. אָמַר, אִם תּוּכַל לִזְרֹק (אותם מאותה דרגה) אֶת אוֹתָהּ דַּרְגָּה שֶׁלָּהֶם, הֲרֵי כֻּלָּם יֵעָקְרוּ מֵהָעוֹלָם. וּלְכָה זֹּעֲמָה יִשְׂרָאֵל - יִשְׂרָאֵל שֶׁלְּמַעְלָה, שֶׁיִּמָּצֵא רֹגֶז לְפָנָיו, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ז) וְאֵל זֹּעֵם בְּכָל יוֹם.</p>\n<p>כִּי מֵרֹאשׁ צֻרִים וְגוֹ'. אָמַר רַבִּי יִצְחָק, מֵרֹאשׁ צֻרִים - אֵלּוּ הֵם הָאָבוֹת, שֶׁכָּתוּב (ישעיה נא) הַבִּיטוּ אֶל צוּר חֻצַּבְתֶּם. וּמִגְּבָעוֹת אֲשׁוּרֶנּוּ - אֵלּוּ הָאִמָּהוֹת. בֵּין מִצַּד זֶה בֵּין מִצַּד זֶה לֹא יְכוֹלִים לְהִתְקַלֵּל.</p>\n<p>רַבִּי אַבָּא אָמַר, כִּי מֵרֹאשׁ צֻרִים - מִי יָכוֹל לְיִשְׂרָאֵל, שֶׁהֲרֵי הוּא אָחוּז מֵרֹאשׁ שֶׁכָּל הַצּוּרִים יוֹצְאִים. וּמִי אֵלּוּ צֻרִים? גְּבוּרוֹת, שֶׁהֲרֵי כָּל דִּינֵי הָעוֹלָם יוֹצְאִים מֵאוֹתָן גְּבוּרוֹת, וְהֵם נֶאֱחָזִים בָּהֶן. וּמִגְּבָעוֹת אֲשׁוּרֶנּוּ - אֵלּוּ שְׁאָר הַמַּחֲנוֹת (כתרים) שֶׁאֲחוּזִים בָּהֶם. הֶן עָם לְבָדָד וְגוֹ', כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) ה' בָּדָד יַנְחֶנּוּ.</p>\n<p>מִי מָנָה עֲפַר יַעֲקֹב וְגוֹ', הֲרֵי פֵּרְשׁוּהוּ. אֶלָּא אָמַר רַבִּי יוֹסֵי, שְׁתֵּי דְרָגוֹת הֵן - יַעֲקֹב וְיִשְׂרָאֵל. בַּתְּחִלָּה יַעֲקֹב, וְאַחַר כָּךְ יִשְׂרָאֵל. וְאַף עַל גַּב שֶׁהַכֹּל אֶחָד - שְׁתֵּי דְרָגוֹת הֵן, שֶׁהֲרֵי דַּרְגָּה עֶלְיוֹנָה הִיא יִשְׂרָאֵל.</p>\n<p>מִי מָנָה עֲפַר יַעֲקֹב וְגוֹ'. לְמַטָּה, מַה זֶּה עָפָר? רַבִּי שִׁמְעוֹן אָמַר, זֶה שֶׁכָּתוּב בּוֹ (ישעיה מא) יִתֵּן כֶּעָפָר חַרְבּוֹ וְגוֹ'. מִי חַרְבּוֹ? הֲרֵי יָדוּעַ, שֶׁכָּתוּב (שם לד) חֶרֶב לַה' מָלְאָה דָם. עָפָר, אוֹתוֹ מָקוֹם שֶׁמִּמֶּנּוּ נִבְרָא אָדָם הָרִאשׁוֹן, שֶׁכָּתוּב (בראשית ב) וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר וְגוֹ'. וּמֵאוֹתוֹ עָפָר כַּמָּה חֲיָלוֹת וְכַמָּה מַחֲנוֹת יָצְאוּ, כַּמָּה שַׁלְהָבוֹת, כַּמָּה שׁוֹמְרֵי חֹק וּמִנְהָגִים, כַּמָּה חִצִּים, כַּמָּה בַּלִּיסְטְרָאוֹת, כַּמָּה רְמָחִים וַחֲרָבוֹת וּכְלֵי זַיִן נִמְצְאוּ מֵאוֹתוֹ עָפָר. מִי מָנָה, כְּמוֹ שֶׁנֶּאֱמַר (איוב כה) הֲיֵשׁ מִסְפָּר לִגְדוּדָיו.</p>\n<p>וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל. רֹבַע יִשְׂרָאֵל הִיא הֵ\"א, וְדָבָר אֶחָד הִיא. רֹבַע יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר (שמות כג) רֹבֵץ תַּחַת מַשָּׂאוֹ, רְבִיעַ. זֶהוּ שֶׁכָּתוּב (שיר השירם ג) מִטָּתוֹ שֶׁלִּשְׁלֹמֹה. דָּבָר אַחֵר רֹבַע - כְּמוֹ רְבִיעִית מִיִּשְׂרָאֵל לְמַטָּה, רֹבַע נִקְרָא לְפִי הַכְּתָרִים מַשְׁמָע דָּוִד, שֶׁהוּא רֶגֶל רְבִיעִית שֶׁל הַכִּסֵּא.</p>\n<p>דָּבָר אַחֵר מִי מָנָה עֲפַר יַעֲקֹב וְגוֹ' - כָּל אֵלּוּ שֶׁחֲשׁוּבִים עָפָר, כְּמוֹ שֶׁבֵּאַרְנוּ. וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל, שֶׁכָּתוּב הֲיֵשׁ מִסְפָּר לִגְדוּדָיו. רֹבַע יִשְׂרָאֵל כְּמוֹ שֶׁבֵּאַרְנוּ. דָּבָר אַחֵר מִי מָנָה עֲפַר - אֵלּוּ מִצְווֹת שֶׁהֵם בֶּעָפָר, בִּזְרִיעָה, בִּנְטִיעָה, בִּקְצִירָה, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים. וּמִסְפָּר אֶת רֹבַע, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא יא) בְּהֶמְתְּךְ לֹא תַרְבִּיעַ. (אמר רבי אבא, בלק חכם היה בכשפיו כבלעם, פרט שלא ידע לכון השעה לקלל).</p>\n<p>וַיִּשָּׂא מְשָׁלוֹ וַיֹּאמַר. וַיְדַבֵּר לֹא כָתוּב. מַה זֶּה וַיִּשָּׂא מְשָׁלוֹ? רַבִּי חִיָּיא אָמַר, הוּא הָיָה מֵרִים קוֹל לְאוֹתוֹ מְדַבֵּר, וַיִּשָּׂא מְשָׁלוֹ בִּלְעָם. וַיֹּאמַר הַכֹּה הַזֹּאת, כְּמוֹ שֶׁכָּתוּב וְכֹה תְדַבֵּר, וַאֲמִירָה הִיא מִמֶּנָּה.</p>\n<p>בֹּא וּרְאֵה, כֵּיוָן שֶׁרָאָה בִלְעָם שֶׁבְּכָל כְּשָׁפָיו וּבְכָל אוֹתוֹ דּוֹרוֹן לֹא יָכֹל לַעֲקֹר אֶת אוֹתָהּ כֹּה, כְּמוֹ שֶׁנֶּאֱמַר וְאָנֹכִי אִקָּרֶה כֹּה, אֶעֱקֹר אֶת הַכֹּה הַזֹּאת - אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: רָשָׁע! אַתָּה סָבוּר לַעֲקֹר אוֹתָהּ?! אֲנִי אֶעֱקֹר אוֹתְךְ מִשַּׁלְשְׁלוֹתֶיךְ. מַה כָּתוּב? וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם, כְּמוֹ שֶׁנֶּאֱמַר. אַחַר כָּךְ, כֵּיוָן שֶׁרָאָה שֶׁלֹּא יָכֹל, חָזַר וְאָמַר, וּבֵרֵךְ וְלֹא אֲשִׁיבֶנָּה. וְלֹא אֲשִׁיבֶנּוּ הָיָה צָרִיךְ לוֹ לוֹמַר! אֶלָּא וַדַּאי וְלֹא אֲשִׁיבֶנָּה לְאוֹתָהּ שֶׁכָּתוּב עָלֶיהָ כֹּ\"ה, וְכֹה תְדַבֵּר. אֵינִי יָכוֹל לְהַחֲזִירָהּ.</p>\n<p>אָמַר בִּלְעָם: בִּשְׁתֵּי דְרָגוֹת רָצִיתִי לְהִכָּנֵס בָּהֶם; רָצִיתִי לְהִכָּנֵס בָּהֶם מִדַּרְגַּת יַעֲקֹב וְלֹא יָכֹלְתִּי. רָצִיתִי לְהִכָּנֵס בָּהֶם מִצַּד אַחֵר שֶׁל יִשְׂרָאֵל וְלֹא יָכֹלְתִּי. מָה הַטַּעַם? מִשּׁוּם שֶׁשֵּׁם זֶה אוֹ זֶה לֹא נִקְשָׁר בְּמִינִים רָעִים. זֶהוּ שֶׁכָּתוּב לֹא הִבִּיט אָוֶן בְּיַעֲקֹב וְגוֹ'.</p>\n<p>לָמַדְנוּ, שְׁתֵּי דְרָגוֹת הֵן: נַחַשׁ וְקֶסֶם. כְּנֶגְדָּן - עָמָל וָאָוֶן. אָמַר בִּלְעָם: הֲרֵי וַדַּאי נִמְצֵאתִי כְּנֶגֶד אֵלֶּה - יַעֲקֹב וְיִשְׂרָאֵל. אָוֶן כְּנֶגֶד יַעֲקֹב, שֶׁהוּא קָשׁוּר בְּנַחַשׁ. עָמָל כְּנֶגֶד יִשְׂרָאֵל, שֶׁקָּשׁוּר בְּקֶסֶם. כֵּיוָן שֶׁרָאָה שֶׁלֹּא יָכֹל, אָמַר, וַדַּאי לֹא הִבִּיט אָוֶן בְּיַעֲקֹב וְגוֹ'. מָה הַטַּעַם? מִשּׁוּם שֶׁה' אֱלֹהָיו עִמּוֹ וְגוֹ'.</p>\n<p>וְאִם תֹּאמַר, בְּאֵלֶּה לֹא יָכֹלְתִּי, בְּקֶסֶם וְנַחַשׁ יָכֹלְתִּי - כָּתוּב כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְגוֹ'. וְלֹא עוֹד, אֶלָּא שֶׁכָּל הַכֹּחוֹת שֶׁלְּמַעְלָה וְכָל מַחֲנוֹתֵיהֶם כֻּלָּם, לֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים בְּנִימוּסֵי הַמֶּלֶךְ הָעֶלְיוֹן עַד שֶׁשּׁוֹאֲלִים לַשְּׁנַיִם הַלָּלוּ - יַעֲקֹב וְיִשְׂרָאֵל. וּמָה אוֹמְרִים? מַה פָּעַל אֵל. אָמַר רַבִּי אֶלְעָזָר, כָּל הַדְּבָרִים הַלָּלוּ, כֹּה אָמַר. וְהוּא הֵרִים קוֹל כְּנֶגְדָּהּ וְלֹא יָדַע מַהוּ, וְלֹא נִשְׁמַע פְּרָט לְקוֹלוֹ.</p>\n<p>הֶן עָם כְּלָבִיא יָקוּם וְגוֹ'. מִי עַם תַּקִּיף כְּמוֹ יִשְׂרָאֵל. בְּשָׁעָה שֶׁמֵּאִיר הַבֹּקֶר, קָם וּמִתְגַּבֵּר כַּאֲרִי לַעֲבוֹדַת רִבּוֹנָם בְּכַמָּה שִׁירִים, בְּכַמָּה תִשְׁבָּחוֹת. מִשְׁתַּדְּלִים בַּתּוֹרָה כָּל הַיּוֹם, וּבַלַּיְלָה לֹא יִשְׁכַּב וְגוֹ'. כְּשֶׁרוֹצֶה הָאָדָם לִשְׁכַּב עַל מִטָּתוֹ, מְקַדֵּשׁ אֶת הַשֵּׁם הָעֶלְיוֹן, מַמְלִיכוֹ לְמַעְלָה וּלְמַטָּה. כַּמָּה שׁוֹמְרֵי הַחֻקִּים מִתְקַשְּׁרִים לִפְנֵיהֶם בְּשָׁעָה שֶׁפּוֹתְחִים פִּיהֶם עַל מִטָּתָם בִּשְׁמַע יִשְׂרָאֵל, וּמְבַקְשִׁים רַחֲמִים לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ בְּכַמָּה פְּסוּקֵי רַחֲמִים.</p>\n<p>רַבִּי אַבָּא אָמַר, הֶן עָם כְּלָבִיא יָקוּם - עֲתִידִים הָעָם הַזֶּה לָקוּם עַל כָּל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת כְּאַרְיֵה גִּבּוֹר וְתַקִּיף, וְיִתְנַפְּלוּ עֲלֵיהֶם. דֶּרֶךְ כָּל הָאֲרָיוֹת לִשְׁכַּב עַל טַרְפָּם, אֲבָל עַם זֶה לֹא יִשְׁכַּב עַד יֹאכַל טֶרֶף.</p>\n<p>דָּבָר אַחֵר הֶן עָם כְּלָבִיא יָקוּם - לְהַקְרִיב קָרְבָּנוֹת וְעוֹלוֹת לִפְנֵי מַלְכָּם עַל גַּבֵּי הַמִּזְבֵּחַ. וְלָמַדְנוּ, בְּשָׁעָה שֶׁהַקָּרְבָּן הָיָה נִשְׂרָף עַל גַּבֵּי הַמִּזְבֵּחַ, הָיוּ רוֹאִים דְּמוּת אַרְיֵה אֶחָד רָבוּץ עַל אוֹתוֹ קָרְבָּן וְאוֹכֵל אוֹתוֹ.</p>\n<p>וְאָמַר רַבִּי אַבָּא, אוּרִיאֵ\"ל מַלְאָךְ עֶלְיוֹן הָיָה, וְרָאוּ אוֹתוֹ בִּדְמוּת אַרְיֵה תַּקִּיף רוֹבֵץ עַל הַמִּזְבֵּחַ וְאוֹכֵל אֶת הַקָּרְבָּנוֹת. וּכְשֶׁיִּשְׂרָאֵל לֹא הָיוּ זַכָּאִים כָּל כָּךְ, הָיוּ רוֹאִים דְּמוּת כֶּלֶב אֶחָד חָצוּף רוֹבֵץ עָלָיו, אָז הָיוּ יִשְׂרָאֵל יוֹדְעִים שֶׁצְּרִיכִים תְּשׁוּבָה, וְאָז שָׁבִים. לֹא יִשְׁכַּב וְגוֹ' - אֵלּוּ קָרְבְּנוֹת הַלַּיְלָה, כְּמוֹ עוֹלוֹת. וְדַם חֲלָלִים יִשְׁתֶּה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹרֵךְ קְרָב שֶׁלָּהֶם עַל שׂוֹנְאֵיהֶם.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, לֹא יִשְׁכַּב, מַהוּ לֹא יִשְׁכַּב? אֶלָּא בְּכָל לַיְלָה וְלַיְלָה כְּשֶׁבֶּן אָדָם הוֹלֵךְ בְּמִצְווֹת רִבּוֹנוֹ, לֹא שׁוֹכֵב עַל מִטָּתוֹ עַד שֶׁהוֹרֵג אֶלֶף וּמֵאָה וְעֶשְׂרִים וְחָמֵשׁ מֵאוֹתָם מִינִים רָעִים שֶׁשּׁוֹרִים עִמּוֹ. רַבִּי אַבָּא אָמַר, אֶלֶף הֵם מִצַּד שְׂמֹאל, שֶׁכָּתוּב (תהלים צא) יִפֹּל מִצִּדְּךְ אֶלֶף, כְּמוֹ שֶׁכָּתוּב (שם קמט) יַעְלְזוּ חֲסִידִים בְּכָבוֹד וְגוֹ', רוֹמְמוֹת אֵל בִּגְרוֹנָם וְגוֹ', לַעֲשׂוֹת נְקָמָה וְגוֹ'. זֶהוּ שֶׁכָּתוּב לֹא יִשְׁכַּב וְגוֹ', וְזֶהוּ לַעֲשׂוֹת בָּהֶם מִשְׁפָּט וְגוֹ'.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, כְּנֶגֶד שְׁלֹשׁ הַפְּעָמִים שֶׁהִכָּה אֶת אֲתוֹנוֹ וְהִטְעִינָהּ בִּכְשָׁפָיו, הִתְבָּרְכוּ יִשְׂרָאֵל שָׁלֹשׁ פְּעָמִים. רַבִּי חִיָּיא אָמַר, כְּנֶגְדּוֹ הִתְבָּרְכוּ יִשְׂרָאֵל שָׁלֹשׁ פְּעָמִים, שֶׁעוֹלִים יִשְׂרָאֵל לְהֵרָאוֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>וַיַּרְא בִּלְעָם כִּי טוֹב בְּעֵינֵי ה' וְגוֹ', וְלֹא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים וְגוֹ'. מַה זֶּה לִקְרַאת נְחָשִׁים? אָמַר רַבִּי יוֹסֵי, שֶׁהַפַּעֲמַיִם הָרִאשׁוֹנוֹת הַלָּלוּ הָיָה הוֹלֵךְ בְּכָל כְּשָׁפָיו וְרָצָה לְקַלֵּל אֶת יִשְׂרָאֵל. כֵּיוָן שֶׁרָאָה רְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאָמַר שׁוּב אֶל בָּלָק, שֶׁהֲרֵי דִּבּוּרֶיךְ לֹא רוֹצִים בָּנַי - דִּבּוּר אַחֵר מְזֻמָּן מֵהַכֹּה הַזֹּאת, כְּמוֹ שֶׁכָּתוּב וְכֹה תְדַבֵּר. כֹּה תְדַבֵּר - וְלֹא אַתָּה. כֹּה תְדַבֵּר - שֶׁשּׁוֹלֶטֶת עַל כָּל הַשַּׁלִּיטִים, מְכַשְּׁפִים וְקוֹסְמִים וּמִינִים רָעִים שֶׁלֹּא יְכוֹלִים לְהָרַע לְבָנַי. וְאָז רָצָה לְהִסְתַּכֵּל בָּהֶם בְּעַיִן רָעָה.</p>\n<p>בֹּא וּרְאֵה, רָשָׁע זֶה כְּשֶׁהִסְתַּכֵּל בְּיִשְׂרָאֵל, הָיָה מִסְתַּכֵּל בִּשְׁתֵּי דְרָגוֹת אֵלּוּ - יַעֲקֹב וְיִשְׂרָאֵל - לְהָרַע לָהֶם, אוֹ בָזֶה אוֹ בָזֶה בִּכְשָׁפָיו. בִּגְלַל כָּךְ כָּל בְּרָכוֹת וּבְרָכוֹת, יַעֲקֹב וְיִשְׂרָאֵל הִתְבָּרְכוּ. וַיַּרְא בִּלְעָם כִּי טוֹב וְגוֹ'. בַּמָּה רָאָה? רָאָה שֶׁבְּשָׁעָה שֶׁפְּנֵי הַמֶּלֶךְ מְאִירוֹת, מִינִים רָעִים לֹא עוֹמְדִים בְּקִיּוּמָם, וְכָל הַכְּשָׁפִים וְכָל הַקְּסָמִים לֹא עוֹלִים בְּכִשְׁפֵיהֶם.</p>\n<p>בֹּא וּרְאֵה, בִּשְׁתֵּי הַפְּעָמִים הָאֵלֶּה כָּתוּב וַיִּקָּר., וַיִּקָּר אֱלֹהִים. וַיִּקָּר ה' אֶל בִּלְעָם וְגוֹ'. וְכָתוּב וְכֹה תְדַבֵּר. וְעַכְשָׁו, כֵּיוָן שֶׁרָאָה שֶׁהֲרֵי לֹא נִמְצָא רֹגֶז וּכְשָׁפָיו לֹא עָלוּ, אָז - וְלֹא הָלַךְ כְּפַעַם בְּפַעַם וְגוֹ'. כֵּיוָן שֶׁהִפְרִיד וְהֶעֱלָה עַצְמוֹ מִכְּשָׁפָיו, הִתְחִיל (ברוח אחרת) בְּהִתְעוֹרְרוּת אַחֶרֶת - לְשַׁבֵּחַ אֶת יִשְׂרָאֵל. אָמַר רַבִּי יְהוּדָה, אֵיזוֹ הִתְעוֹרְרוּת כָּאן? אָמַר לוֹ, (רוח אלהים ולא רוח ה', אלא) הִתְעוֹרְרוּת שֶׁל רוּחַ אַחַת מִצַּד שְׂמֹאל, אוֹתוֹ שֶׁהִתְקַשְּׁרוּ תַחְתָּיו אוֹתָם מִינִים וְכִשּׁוּפִים שֶׁלּוֹ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, כָּךְ לָמַדְנוּ, שֶׁאֲפִלּוּ בַּזְּמַן הַזֶּה לֹא שָׁרְתָה בּוֹ רוּחַ הַקֹּדֶשׁ. אָמַר לוֹ רַבִּי יוֹסֵי, אִם כָּךְ, הֲרֵי כָּתוּב וַתְּהִי עָלָיו רוּחַ אֱלֹהִים, וּבְכָל אוֹתָן פְּעָמִים אֲחֵרוֹת לֹא כָתוּב בָּהֶן כָּךְ. אָמַר לוֹ, כָּךְ זֶה. בּא וּרְאֵה, כָּתוּב (משלי כב) טוֹב עַיִן הוּא יְבֹרָךְ, וַהֲרֵי פֵּרְשׁוּהָ, אַל תִּקְרֵי יְבֹרָךְ אֶלָּא יְבָרֵךְ. וּבִלְעָם הָיָה רַע עַיִן, שֶׁלֹּא נִמְצָא רַע עַיִן בָּעוֹלָם כְּמוֹתוֹ, שֶׁבְּכָל מָקוֹם שֶׁהָיָה מִסְתַּכֵּל בְּעֵינָיו, הָיָה מִתְקַלֵּל. וְעַל זֶה אָמְרוּ, מִי שֶׁמַּעֲבִיר בְּנוֹ בַּשּׁוּק וּפוֹחֵד מֵעַיִן רָעָה, יָשִׂים סוּדָר עַל רֹאשׁוֹ כְּדֵי שֶׁעַיִן רָעָה לֹא תוּכַל לִשְׁלֹט בּוֹ. גַּם כָּאן, כֵּיוָן שֶׁרָאָה בִלְעָם שֶׁלֹּא יָכוֹל בִּכְשָׁפָיו וּבִקְסָמָיו לְהַזִּיק לְיִשְׂרָאֵל, רָצָה לְהִסְתַּכֵּל בָּהֶם בְּעַיִן רָעָה, בִּגְלַל שֶׁבְּכָל מָקוֹם שֶׁהָיָה מִסְתַּכֵּל בְּעֵינָיו הָרָעוֹת, הָיָה מִתְקַלֵּל.</p>\n<p>בֹּא וּרְאֵה מָה רְצוֹנוֹ כְּנֶגֶד יִשְׂרָאֵל. כָּתוּב וַיָּשֶׁת אֶל הַמִּדְבָּר פָּנָיו, כְּתַרְגּוּמוֹ: (ושם פניו (כּנגד הָעגל) לעגל שעשו ישראל במדבר), כְּדֵי שֶׁיִּהְיֶה לוֹ צַד סִיּוּעַ לְהָרַע לָהֶם.</p>\n<p>כָּעֵת רְאֵה מַה כָּתוּב, וַיִּשָּׂא בִלְעָם אֶת עֵינָיו וַיַּרְא אֶת יִשְׂרָאֵל. רָצָה לְהִסְתַּכֵּל בָּהֶם בְּעַיִן רָעָה. בְּשָׁעָה זוֹ אִלְמָלֵא הִקְדִּים הַקָּדוֹשׁ בָּרוּךְ הוּא רְפוּאָה, הָיָה מְאַבֵּד אוֹתָם בְּהִסְתַּכְּלוּת עֵינָיו. וְאֵיזוֹ רְפוּאָה נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל בְּאוֹתָהּ שָׁעָה? זֶהוּ שֶׁכָּתוּב וַתְּהִי עָלָיו רוּחַ אֱלֹהִים. וַתְּהִי עָלָיו, עַל יִשְׂרָאֵל הוּא אוֹמֵר. כְּמִי שֶׁפּוֹרֵשׂ סוּדָר עַל רֹאשׁ הַתִּינוֹק כְּדֵי שֶׁלֹּא תִשְׁלֹט בּוֹ עֵינוֹ.</p>\n<p>אָז הִתְחִיל וְאָמַר, מַה טֹּבוּ אֹהָלֶיךְ יַעֲקֹב. בֹּא וּרְאֵה, כָּל מִי שֶׁרוֹצֶה לְהִסְתַּכֵּל בְּעַיִן רָעָה, לֹא יָכוֹל, אֶלָּא כְּשֶׁמְּשַׁבֵּחַ וּמְכַבֵּד אֶת אוֹתוֹ הַדָּבָר שֶׁרוֹצֶה לְקַלֵּל בְּעַיִן רָעָה. וּמַה דַּרְכּוֹ? אָמַר, רְאוּ כַּמָּה טוֹב זֶה, כַּמָּה נָאֶה זֶה! כְּדֵי שֶׁתִּשְׁלֹט בּוֹ עַיִן רָעָה. גַּם כָּאן אָמַר, מַה בוּ אֹהָלֶיךְ יַעֲקֹב, כַּמָּה יָפִים הֵם, כַּמָּה נָאִים הֵם, כַּמָּה נְטִיעוֹת יָפוֹת שֶׁנִּנְטְעוּ מֵהֶם, דּוֹמִים לְאוֹתָן נְטִיעוֹת שֶׁנָּטַע הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַן עֵדֶן נָאוֹת. מִי יִתֵּן וְאֵלּוּ (שאלו) הַנְּטִיעוֹת נִמְצְאוּ מֵאוֹתָם עֲנִיִּים שֶׁבָּהֶם.</p>\n<p>יִזַּל מַיִם מִדָּלְיָו וְגוֹ'. לְאָדָם שֶׁהָיוּ לוֹ יָדַיִם יָפוֹת נָאוֹת לְמַרְאֶה. עָבַר אָדָם אֶחָד בַּעַל עַיִן הָרָע, הִסְתַּכֵּל בְּאוֹתָן יָדַיִם, וְהִתְחִיל לְשַׁבֵּחַ. אָמַר: כַּמָּה יָפוֹת הֵן, כַּמָּה נָאוֹת הֵן, רְאוּ אֶצְבָּעוֹת שֶׁנִּגְזְרוּ מִיֹּפִי עֶלְיוֹן! אַחַר כָּךְ אָמַר: מִי יִתֵּן יָדַיִם אֵלּוּ שֶׁשּׁוֹרוֹת בֵּין אֲבָנִים יְקָרוֹת וּבִלְבוּשֵׁי כָבוֹד שֶׁל אַרְגָּמָן (בביתנו וכו' בתבה שלו) בְּבֵיתוֹ לְהִשְׁתַּמֵּשׁ בָּהֶן, וְיִהְיוּ גְנוּזוֹת בַּתֵּבָה שֶׁלּוֹ.</p>\n<p>כָּךָ בִּלְעָם, הִתְחִיל לְשַׁבֵּחַ: מַה טֹּבוּ אֹהָלֶיךְ, רְאוּ כַּמָּה יָפִים, כַּמָּה נָאִים וְכוּ'. אַחַר כָּךְ אָמַר, יִזַּל מַיִם מִדָּלְיָו, לֹא תִמְצָא נְטִיעָה יָפָה זוֹ, נְטִיעַת הַתּוֹרָה, מִחוּץ לְאוֹתָם עֲנִיִּים (דליו, כלומר מסכנים) (משכנות). וְזַרְעוֹ בְּמַיִם רַבִּים, שֶׁלֹּא יִגְדַּל וְלֹא יִרְבֶּה רוּחַ הַקֹּדֶשׁ.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: רָשָׁע! לֹא יוּכְלוּ עֵינֶיךְ לְהַזִּיק, הֲרֵי פְּרִישַׂת הַקֹּדֶשׁ עֲלֵיהֶם. וְאָז אָמַר: אֵל מוֹצִיאוֹ מִמִּצְרַיִם וְגוֹ', הֲרֵי לֹא יְכוֹלִים כָּל בְּנֵי הָעוֹלָם לְהַזִּיק לָהֶם, שֶׁהֲרֵי כֹּחַ תַּקִּיף עֶלְיוֹן אָחוּז בָּהֶם, וּמִיהוּ? אֵל מוֹצִיאוֹ מִמִּצְרַיִם. וְלֹא עוֹד, אֶלָּא כְּתוֹעֲפֹת רְאֵם לוֹ, שֶׁלֹּא יָכוֹל בֶּן אָדָם לְהוֹשִׁיט יָדָיו עָלָיו מִתּוֹךְ גָּבְהוֹ. וּמִשֶּׁנִּמְצָא בִזְקִיפוּת עֶלְיוֹנָה כָּךְ, יֹאכַל גּוֹיִם צָרָיו וְגוֹ', וְאֵין מִי שֶׁיָּכוֹל לְהַזִּיק לָהֶם.</p>\n<p>וַאֲפִלּוּ בִּזְמַן שֶׁלֹּא זָקוּף, לֹא יְכוֹלִים. זֶהוּ שֶׁכָּתוּב כָּרַע שָׁכַב. לֹא פוֹחֵד, בִּגְלַל שֶׁנִּמְצָא גִבּוֹר כַּאֲרִי וּכְלָבִיא, אֲפִלּוּ כְּשֶׁהֵם בֵּין הָעַמִּים, וְכָרַע וְשָׁכַב בֵּינֵיהֶם, כַּאֲרִי הוּא יִמָּצֵא בְּנִימוּסֵי הַתּוֹרָה, בְּדַרְכֵי הַתּוֹרָה. (ואף על פי כן) יֵשׁ לָהֶם שִׁלְטוֹן בְּרִבּוֹנָם שֶׁאֲפִלּוּ כָּל מַלְכֵי הָעוֹלָם לֹא יַעַקְרוּ אוֹתוֹ, כְּאַרְיֵה זֶה כְּשֶׁשּׁוֹכֵב עַל טַרְפּוֹ לֹא יְכוֹלִים לַהֲקִימוֹ מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב כָּרַע שָׁכַב כַּאֲרִי וְגוֹ'.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, לֹא נִמְצָא בָעוֹלָם חָכָם לְהַזִּיק כְּמוֹ בִּלְעָם הָרָשָׁע, שֶׁהֲרֵי בַּתְּחִלָּה הָיָה נִמְצָא בְמִצְרַיִם, וְעַל יָדוֹ קָשְׁרוּ הַמִּצְרִים קֶשֶׁר עַל יִשְׂרָאֵל שֶׁלֹּא יֵצְאוּ מֵעֲבוֹדָתָם לְעוֹלָמִים. וְזֶהוּ שֶׁאָמַר, מָה אוּכַל לְהַזִּיק לָהֶם? שֶׁהֲרֵי אֲנִי עָשִׂיתִי שֶׁלֹּא יֵצְאוּ מֵעַבְדוּת הַמִּצְרִים לְעוֹלָמִים, אֲבָל אֵל מוֹצִיאוֹ מִמִּצְרַיִם, וְנֶגְדָּם (ונגדו) לֹא יְכוֹלִים חֲכָמִים וּמְכַשְּׁפִים שֶׁל הָעוֹלָם.</p>"],[9522012442,"<p>וְעַתָּה הִנְנִי הוֹלֵךְ לְעַמִּי וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (דברים כג) לֹא תַסְגִּיר עֶבֶד אֶל אֲדנָיו וְגוֹ' עִמְּךְ יֵשֵׁב בְּקִרְבְּךְ. כַּמָּה חֲבִיבִים דִּבְרֵי הַתּוֹרָה. כַּמָּה חֲבִיבָה הַתּוֹרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. כַּמָּה חֲבִיבָה הַתּוֹרָה שֶׁהוֹרִישׁ אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לִכְנֶסֶת יִשְׂרָאֵל. בֹּא וּרְאֵה, בְּשָׁעָה שֶׁיָּצְאוּ מִמִּצְרַיִם, שָׁמַע בִּלְעָם שֶׁהֲרֵי כְּשָׁפָיו וּקְסָמָיו וְכָל אוֹתָם קְשָׁרִים לֹא עָלוּ בְיִשְׂרָאֵל, הִתְחִיל לְגָרֵד עַצְמוֹ וְלִמְרֹט רֹאשׁוֹ. הָלַךְ לְאוֹתָם הָרֵי הַחֹשֶׁךְ, וְהִגִּיעַ לִפְנֵי אוֹתָם שַׁלְשְׁלָאוֹת בַּרְזֶל.</p>\n<p>וְכָךָ הוּא דֶּרֶךְ מִי שֶׁמַּגִּיעַ אֲלֵיהֶם. כֵּיוָן שֶׁנִּכְנָס הָאָדָם בְּרֹאשׁ הֶהָרִים, רוֹאֶה אוֹתוֹ עֲזָאֵ\"ל, אוֹתוֹ שֶׁנִּקְרָא גְּלוּי עֵינַיִם, מִיָּד אוֹמֵר לַעֲזָ\"א. אָז נוֹתְנִים קוֹל, וּמִתְכַּנְּסִים אֲלֵיהֶם נְחָשִׁים גְּדוֹלִים שֶׁבּוֹעֲרִים וְסוֹבְבִים אוֹתָם. שׁוֹלְחִים חַיָּה קְטַנָּה מוּל הָאָדָם, וְלָמַדְנוּ, כְּמִין חָתוּל הִיא, וְרֹאשָׁהּ כְּרֹאשׁ הַנָּחָשׁ, וּשְׁנֵי זְנָבוֹת לָהּ, וְיָדֶיהָ וְרַגְלֶיהָ קְטַנּוֹת. בֶּן אָדָם שֶׁרוֹאֶה אוֹתָהּ, מְכַסֶּה פָנָיו, וְהוּא מֵבִיא קְטֹרֶת אַחַת מִשְּׂרֵפַת תַּרְנְגוֹל לָבָן, זוֹרֵק בְּפָנֶיהָ, וְהִיא בָּאָה עִמּוֹ.</p>\n<p>עֵד שֶׁמַּגִּיעַ לְרֹאשׁ הַשַּׁלְשְׁלָאוֹת, וְאוֹתוֹ רֹאשׁ הַשַּׁלְשְׁלָאוֹת נָעוּץ בַּקַּרְקַע וּמַגִּיעַ עַד הַתְּהוֹם. וְשָׁם בַּתְּהוֹם עַמּוּד אֶחָד שֶׁנָּעוּץ בַּתְּהוֹם הַתַּחְתּוֹנָה, וּבְאוֹתוֹ עַמּוּד קָשׁוּר רֹאשׁ הַשַּׁלְשְׁלָאוֹת. כְּשֶׁמַּגִּיעַ הָאָדָם לְרֹאשׁ הַשַּׁלְשְׁלָאוֹת, מַכֶּה בָּהּ שָׁלֹשׁ פְּעָמִים, וְהֵם קוֹרְאִים לוֹ, וְאָז כּוֹרֵעַ וּמִשְׁתַּחֲוֶה עַל בִּרְכָּיו, וְהוֹלֵךְ וְאוֹטֵם עֵינָיו עַד שֶׁמַּגִּיעַ אֲלֵיהֶם. אָז יוֹשֵׁב לִפְנֵיהֶם, וְכָל אוֹתָם נְחָשִׁים סוֹבְבִים אוֹתוֹ מִצַּד זֶה וּמִצַּד זֶה. פּוֹתֵחַ עֵינָיו וְרוֹאֶה אוֹתָם, מִזְדַּעֲזֵעַ וְנוֹפֵל עַל פָּנָיו וּמִשְׁתַּחֲוֶה כְּנֶגְדָּם.</p>\n<p>אַחַר כָּךְ מְלַמְּדִים אוֹתוֹ כְּשָׁפִים וּקְסָמִים, וְיוֹשֵׁב לִפְנֵיהֶם חֲמִשִּׁים יוֹם. כְּשֶׁמַּגִּיעַ הַזְּמַן לָלֶכֶת לְדַרְכּוֹ, אוֹתָהּ הַחַיָּה וְכָל אוֹתָם נְחָשִׁים הוֹלְכִים לְפָנָיו עַד שֶׁיּוֹצֵא מֵהֶהָרִים בֵּין אוֹתוֹ חֹשֶׁךְ תַּקִּיף.</p>\n<p>וּבִלְעָם, כְּשֶׁהִגִּיעַ לִפְנֵיהֶם, הוֹדִיעַ לָהֶם דָּבָר, וְהִסְגִּיר עַצְמוֹ בֶּהָרִים עִמָּם. וְרָצָה לְקַטְרֵג עֲלֵיהֶם לְהָשִׁיב אוֹתָם לְמִצְרַיִם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְבֵּל וְקִלְקֵל כָּל חָכְמַת הָעוֹלָם וְכָל כִּשּׁוּפֵי הָעוֹלָם שֶׁלֹּא יוּכְלוּ לִקְרַב אֲלֵיהֶם.</p>\n<p>בֹּא וּרְאֵה, כָּעֵת, כֵּיוָן שֶׁרָאָה בִלְעָם שֶׁאֵינוֹ יָכוֹל לְהַזִּיק לְיִשְׂרָאֵל, הֶחֱזִיר עַצְמוֹ, וְהִמְלִיךְ אֶת בָּלָק, מַה שֶּׁלֹּא רָצָה מִמֶּנּוּ כְּדֵי לְהַזִּיק לָהֶם. וַעֲצָתוֹ הָיְתָה בְּאוֹתָן נְקֵבוֹת מִדְיָן שֶׁהֵן יָפוֹת, וְאִלְמָלֵא שֶׁאָמַר לוֹ מֹשֶׁה, לֹא הָיִיתִי יוֹדֵעַ, שֶׁכָּתוּב הֵן הֵנָּה הָיוּ לִבְנֵי יִשְׂרָאֵל בִּדְבַר בִּלְעָם.</p>\n<p>כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא עֲצָתוֹ, אָמַר: הֲרֵי וַדַּאי יִפֹּל בַּעֲצָתְךְ. מֶה עָשָׂה? אוֹתוֹ כֹּחַ שֶׁשּׁוֹלֵט עַל כָּל הַכְּשָׁפִים, הֶרְאָה לוֹ סוֹף הַכֹּל, וְכִי יֵשׁ לָהֶם רְשׁוּת לִזְמַן רָחוֹק. אָמַר רַבִּי יִצְחָק, עַיִן רָאָה, וּדְבָרִים נֶאֶמְרוּ מֵאוֹתוֹ שֶׁעוֹמֵד עָלָיו, וַהֲרֵי פֵּרְשׁוּהָ. וַיִּשָּׂא מְשָׁלוֹ וַיֹּאמַר. מִי שֶׁיֵּשׁ לוֹ לוֹמַר. מָה הַטַּעַם? בִּשְׁבִיל שֶׁלֹּא יִתְקַיְּמוּ דִּבְרֵי גֹעַל בְּרָצוֹן עֶלְיוֹן, (ובשביל שיתקימו דברים שלמעלה) בְּדַעַת עֶלְיוֹנָה בַּתּוֹרָה.</p>"],[9522012443,"<p>אֶרְאֶנּוּ וְלֹא עַתָּה, שֶׁהֲרֵי דְּבָרִים אֵלּוּ - מֵהֶם הִתְקַיְּמוּ בְאוֹתוֹ זְמַן, וּמֵהֶם לְאַחַר זְמַן, וּמֵהֶם בִּזְמַן מֶלֶךְ הַמָּשִׁיחַ. שָׁנִינוּ, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת אֶת יְרוּשָׁלַיִם וּלְהַרְאוֹת כּוֹכָב אֶחָד קָבוּעַ נוֹצֵץ בְּשִׁבְעִים רָצִים, וּבְשִׁבְעִים רוּחוֹת מְאִירוֹת מִמֶּנּוּ בְּאֶמְצַע הָרָקִיעַ, וְיִבָּלְעוּ בוֹ שִׁבְעִים כּוֹכָבִים אֲחֵרִים, וִיהֵא מֵאִיר וְלוֹהֵט שִׁבְעִים יוֹם.</p>\n<p>וּבַיּוֹם הַשִּׁשִּׁי יֵרָאֶה בְּכ\"ה לַחֹדֶשׁ הַשִּׁשִּׁי, וְיִתְכַּנֵּס בַּיּוֹם הַשְּׁבִיעִי לְסוֹף שִׁבְעִים יוֹם. יוֹם רִאשׁוֹן יֵרָאֶה בְּעִיר (אחת) שֶׁל רוֹמָא, וְאוֹתוֹ יוֹם יִפְּלוּ שָׁלֹשׁ חוֹמוֹת עֶלְיוֹנוֹת מֵאוֹתָהּ עִיר שֶׁל רוֹמִי, וְהֵיכָל גָּדוֹל יִפֹּל, וְשַׁלִּיט אוֹתָהּ הָעִיר יָמוּת. אָז יִתְפַּשֵּׁט אוֹתוֹ כּוֹכָב לְהֵרָאוֹת בָּעוֹלָם, וּבְאוֹתוֹ זְמַן יִתְעוֹרְרוּ קְרָבוֹת חֲזָקִים בָּעוֹלָם לְכָל אַרְבָּעָה צְדָדִים, וֶאֱמוּנָה לֹא תִמָּצֵא בֵינֵיהֶם.</p>\n<p>וּבְאֶמְצַע הָעוֹלָם, כְּשֶׁיָּאִיר אוֹתוֹ כּוֹכָב בְּאֶמְצַע הָרָקִיעַ, יָקוּם מֶלֶךְ אֶחָד גָּדוֹל וְשׁוֹלֵט בָּעוֹלָם, וְתִתְגָּאֶה רוּחוֹ עַל כָּל שְׁאָר הַמְּלָכִים, וִיעוֹרֵר קְרָבוֹת בִּשְׁנֵי צְדָדִים וְיִתְגַּבֵּר עֲלֵיהֶם.</p>\n<p>וּבַיּוֹם שֶׁיִּבָּרֵא (שיתכסה) הַכּוֹכָב, תִּזְדַּעֲזַע הָאָרֶץ הַקְּדוֹשָׁה אַרְבָּעִים וַחֲמִשָּׁה מִילִים סְבִיב הַמָּקוֹם שֶׁבּוֹ הָיָה בֵּית הַמִּקְדָּשׁ, וְתִתְגַּלֶּה מְעָרָה אַחַת מִתַּחַת הַקַּרְקַע. וּמֵאוֹתָהּ מְעָרָה תֵּצֵא אֵשׁ חֲזָקָה לִשְׂרֹף אֶת הָעוֹלָם. וּמֵאוֹתָהּ מְעָרָה יִגְדַּל עוֹף (ענף) אֶחָד גָּדוֹל עֶלְיוֹן שֶׁיִּשְׁלֹט בְּכָל הָעוֹלָם, וְלוֹ תִּנָּתֵן הַמַּלְכוּת. וּקְדוֹשִׁים עֶלְיוֹנִים יִתְכַּנְּסוּ אֵלָיו, וְאָז יִתְגַּלֶּה מֶלֶךְ הַמָּשִׁיחַ בְּכָל הָעוֹלָם, וְלוֹ תִּנָּתֵן הַמַּלְכוּת.</p>\n<p>וּבְנֵי הָעוֹלָם, בְּשָׁעָה שֶׁיִּתְגַּלֶּה, יִהְיוּ נִמְצָאִים בְּצָרָה אַחַר צָרָה, וְשׂוֹנְאֵיהֶם שֶׁל יִשְׂרָאֵל יִתְגַּבְּרוּ, אָז יִתְעוֹרֵר רוּחַ הַמָּשִׁיחַ עֲלֵיהֶם וְיַכְרִית לֶאֱדוֹם הָרְשָׁעָה, וְכָל אֶרֶץ שֵׂעִיר יִשְׂרֹף בָּאֵשׁ. אָז כָּתוּב, וְיִשְׂרָאֵל עֹשֶׂה חָיִל. זֶהוּ שֶׁכָּתוּב, וְהָיָה אֱדוֹם יְרֵשָׁה וְהָיָה יְרֵשָׁה שֵׂעִיר אֹיְבָיו. אוֹיְבָיו שֶׁל יִשְׂרָאֵל. וְאָז - וְיִשְׂרָאֵל עֹשֶׂה חָיִל. וּבַזְּמַן הַהוּא יָקִים הַקָּדוֹשׁ בָּרוּךְ הוּא לַמֵּתִים שֶׁל עַמּוֹ וְיִשְׁתַּכַּח מֵהֶם הַמָּוֶת. זֶה שֶׁכָּתוּב (תהלים קיח) יְמִין ה' עֹשָׂה חָיִל. לֹא אָמוּת כִּי אֶחְיֶה. וְכָתוּב (עובדיה א) וְעָלוּ מוֹשִׁעִים וְגוֹ'. וְאָז (זכריה יד) וְהָיָה ה' לְמֶלֶךְ.</p>\n<p>אָמַר רַבִּי אַבָּא, מַהוּ שֶׁכָּתוּב (ישעיה נה) כִּי בְשִׂמְחָה תֵצֵאוּ וְגוֹ'? אֶלָּא כַּאֲשֶׁר יֵצְאוּ יִשְׂרָאֵל מִן הַגָּלוּת, שְׁכִינָה יוֹצֵאת עִמָּהֶם וְעִמָּהּ יֵצְאוּ. זֶהוּ שֶׁכָּתוּב כִּי בְשִׂמְחָה תֵצֵאוּ. שָׂשׂוֹן - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי יִצְחָק אָמַר - זֶה צַדִּיק. זֶהוּ שֶׁכָּתוּב (שם נא) שָׂשׂוֹן וְשִׂמְחָה יִמָּצֵא בָהּ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, צַדִּיק נִקְרָא שָׂשׂוֹן, וּמִיּוֹם שֶׁכְּנֶסֶת יִשְׂרָאֵל נָפְלָה בַּגָּלוּת, נִמְנְעוּ בְרָכוֹת מִלָּרֶדֶת לָעוֹלָם מִזֶּה הַצַּדִּיק. בַּזְּמַן הַהוּא מַה כָּתוּב? (ישעיה יב) וּשְׁאַבְתֶּם מַיִם בְּשָׂשׂוֹן, זֶה צַדִּיק. מִמַּעַיְנֵי הַיְשׁוּעָה - אֵלּוּ אַבָּא וְאִמָּא. דָּבָר אַחֵר, אֵלּוּ נֵצַ\"ח וְהוֹ\"ד, וְהַכֹּל מִמְּקוֹרוֹת עֲמֻקִּים הַנּוֹבְעִים. וְאָז, (שם) וְאָמַרְתָּ בַּיּוֹם הַהוּא אוֹדְךְ ה' וְגוֹ', צַהֲלִי וָרֹנִּי יוֹשֶׁבֶת צִיּוֹן וְגוֹ'. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522012444,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵּאמֹר. פִּינְחָס בֶּן אֶלְעָזָר וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (משלי א) שְׁמַע בְּנִי מוּסַר אָבִיךְ וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ. שְׁמַע בְּנִי מוּסַר אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. מַה זֶּה מוּסַר אָבִיךְ? מוּסָר זוֹ הַתּוֹרָה, שֶׁיֵּשׁ בָּהּ כַּמָּה תוֹכֵחוֹת, כַּמָּה עֳנָשִׁים, כְּמוֹ שֶׁנֶּאֱמַר (שם ג) מוּסַר ה' בְּנִי אַל תִּמְאָס וְאַל תָּקֹץ בְּתוֹכַחְתּוֹ.</p>\n<p>וּמִשּׁוּם שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה בָּעוֹלָם הַזֶּה זוֹכֶה שֶׁיִּפָּתְחוּ לוֹ כַּמָּה שְׁעָרִים לָעוֹלָם הַהוּא, כַּמָּה אוֹרוֹת - בְּשָׁעָה שֶׁיֵּצֵא מֵהָעוֹלָם הַזֶּה הִיא מַקְדִּימָה לְפָנָיו, וְהוֹלֶכֶת לְכָל שׁוֹמְרֵי הַשְּׁעָרִים, מַכְרִיזָה וְאוֹמֶרֶת: (ישעיה כו) פִּתְחוּ שְׁעָרִים וְיָבֹא גוֹי צַדִּיק! הַתְקִינוּ כִסְאוֹת לִפְלוֹנִי עֶבֶד הַמֶּלֶךְ! שֶׁאֵין שִׂמְחָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא אֶלָּא בְּמִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, כָּל שֶׁכֵּן אָדָם שֶׁמִּתְעוֹרֵר בַּלַּיְלָה לְהִשְׁתַּדֵּל בַּתּוֹרָה, שֶׁהֲרֵי כָּל הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן מַקְשִׁיבִים לְקוֹלוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בֵינֵיהֶם, כְּמוֹ שֶׁפֵּרְשׁוּהָ (שיר השירים ח) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי.</p>"],[9522012445,"<p>רַבִּי שִׁמְעוֹן אָמַר, פָּסוּק זֶה יֵשׁ בּוֹ סוֹד חָכְמָה. הַיּוֹשֶׁבֶת בַּגַּנִּים - זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא בַּגָּלוּת עִם יִשְׂרָאֵל וְהוֹלֶכֶת עִמָּם בְּצָרָתָם. חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ - מַחֲנוֹת עֶלְיוֹנִים כֻּלָּם מַקְשִׁיבִים לְקוֹלֵךְ, לְקוֹל תִּשְׁבַּחְתֵּךְ בַּגָּלוּת. הַשְׁמִיעִנִי, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ב) הַרְאִינִי אֶת מַרְאַיִךְ הַשְׁמִיעִנִי אֶת קוֹלֵךְ. הַשְׁמִיעִינִי קוֹל אוֹתָם הַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, שֶׁהֲרֵי אֵין תִּשְׁבַּחַת לְפָנַי כְּאוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כִּבְיָכוֹל כָּל אוֹתָם שֶׁזַּכָּאִים לְהִשְׁתַּדֵּל בַּתּוֹרָה, וּמִכְּשֶׁנֶּחֱצָה הַלַּיְלָה וּבָאִים עִם הַמַּלְכָּה כְּשֶׁמֵּאִיר הַיּוֹם לְקַבֵּל פְּנֵי הַמֶּלֶךְ, מִתְחַזֵּק וְיוֹרֵשׁ בַּשְּׁכִינָה. וְלֹא עוֹד, אֶלָּא שֶׁשּׁוֹרֶה בּוֹ חוּט שֶׁל חֶסֶד, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>בֹּא וּרְאֵה, כָּל מִי שֶׁזּוֹכֶה לְהִתְחַזֵּק בַּשְּׁכִינָה, יִשְׁמֹר עַצְמוֹ מֵאוֹתָם דְּבָרִים שֶׁאֲחוּזִים מוּלָהּ, כְּמוֹ מִי? אוֹתָם שֶׁלֹּא מְשַׁקְּרִים בָּאוֹת הַקָּדוֹשׁ, כְּגוֹן בַּת אֵל נֵכָר. וְכָל מִי שֶׁשּׁוֹמֵר עַצְמוֹ, כִּבְיָכוֹל כְּנֶסֶת יִשְׂרָאֵל אֲחוּזָה בּוֹ וְשׁוֹמֶרֶת אוֹתוֹ וְהִיא מַקְדִּימָה לוֹ שָׁלוֹם, וְכָל שֶׁכֵּן אִם זוֹכֶה וְקוֹנֶה אֶת זֶה.</p>\n<p>וְאָמַר רַבִּי שִׁמְעוֹן, רְאוּיִים הָיוּ יִשְׂרָאֵל לִהְיוֹת מֻשְׁמָדִים בְּאוֹתָהּ שָׁעָה, פְּרָט לָזֶה שֶׁהִקְדִּים פִּנְחָס לַמַּעֲשֶׂה הַזֶּה וְשִׁכֵּךְ אֶת הָרֹגֶז. זֶהוּ שֶׁכָּתוּב פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן הֵשִׁיב וְגוֹ'. דָּבָר אַחֵר פִּינְחָס בֶּן אֶלְעָזָר וְגוֹ' - אָמַר רַבִּי שִׁמְעוֹן, בֶּן בֶּן פַּעֲמַיִם, בָּא לְהַשְׁלִים הָאֲבֵדָה (המעשה).</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אָדָם זֶה שֶׁנּוֹטֵל גִּלְגּוּל הַנְּשָׁמָה וְלֹא זָכָה לְהִתְתַּקֵּן בּוֹ, כְּאִלּוּ מְשַׁקֵּר בֶּאֱמֶת הַמֶּלֶךְ, וַאֲנִי קוֹרֵא עָלָיו פָּסוּק זֶה, (ויקרא ה) אוֹ מָצָא אֲבֵדָה וְכִחֶשׁ בָּהּ וְנִשְׁבַּע עַל שָׁקֶר. וְכִחֶשׁ בָּהּ, טוֹב לוֹ שֶׁלֹּא נִבְרָא.</p>"],[9522012446,"<p>שָׁנִינוּ, צַדִּיק גָּמוּר אֵינוֹ נִדְחֶה, וְצַדִּיק שֶׁאֵינוֹ גָמוֹר נִדְחֶה. מִיהוּ צַדִּיק גָּמוּר וּמִיהוּ צַדִּיק שֶׁאֵינוֹ גָמוּר? וְכִי מִי שֶׁלֹּא שָׁלֵם בִּדְבָרָיו נִקְרָא צַדִּיק? אֶלָּא צַדִּיק גָּמוּר, יָדוּעַ שֶׁהֲרֵי לֹא לוֹקֵחַ גִּלְגּוּלִים עֲקֻמִּים, וּבִירֻשָּׁתוֹ בּוֹנֶה בִּנְיָן, וּמַתְקִין חוֹמוֹת, וְחוֹצֵב בּוֹרוֹת וְנוֹטֵעַ אִילָנוֹת.</p>\n<p>צַדִּיק שֶׁאֵינוֹ גָמוֹר בּוֹנֶה בִּנְיָן בִּירֻשָּׁה אַחֶרֶת, חוֹפֵר בָּהּ בּוֹרוֹת וְעוֹדֵר, הֲרֵי הִתְקִין אַבְנֵי יְסוֹד כְּמוֹ מִקֹּדֶם וְעָמֵל בָּהּ, וְלא יוֹדֵעַ אִם נִשְׁאָר שֶׁלּוֹ. מִצִּדּוֹ הוּא נִקְרָא טוֹב וְצַדִּיק, וּמִצַּד אוֹתָהּ יְרֻשָּׁה לֹא כָּךְ.</p>\n<p>לְאָדָם שֶׁבּוֹנֶה בִּנְיָן יָפֶה, נָאֶה לְמַרְאֶה, הִסְתַּכֵּל בַּיְסוֹד וְרָאָה אוֹתוֹ שׁוֹקֵעַ עָקֹם מִכָּל הַצְּדָדִים. הֲרֵי הַבִּנְיָן לֹא שָׁלֵם עַד שֶׁסּוֹתֵר אוֹתוֹ וּמַתְקִין אוֹתוֹ כְּמִקֹּדֶם. מִצַּד אוֹתוֹ בִּנְיָן שֶׁלּוֹ נִמְצָא טוֹב וְיָפֶה - מִצַּד הַיְסוֹד רַע וְעָקֹם, וְלָכֵן לֹא נִקְרָא מַעֲשֶׂה שָׁלֵם, לֹא נִקְרָא בִּנְיָן שָׁלֵם. בִּגְלַל כָּךְ נִקְרָא צַדִּיק שֶׁאֵינוֹ גָמוּר, וְנִדְחֶה. וְעַל זֶה (חבקוק א) כְּבַלַּע רָשָׁע צַדִּיק מִמֶּנּוּ.</p>\n<p>בֹּא וּרְאֵה, מִי שֶׁמְּקַנֵּא לַשֵּׁם הַקָּדוֹשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאֲפִלּוּ לֹא יִזְכֶּה לִגְדֻלָּה וְלֹא יִהְיֶה רָאוּי לָהּ, (שיורש אותה) יַרְוִיחַ אוֹתָהּ וְיִקַּח אוֹתָהּ. פִּנְחָס לֹא הָיָה רָאוּי לָהּ בְּאוֹתוֹ זְמַן, וּמִשּׁוּם שֶׁקִּנֵּא לְשֵׁם רִבּוֹנוֹ הִרְוִיחַ אֶת הַכֹּל, וְעָלָה לַכֹּל וְהִתְתַּקֵּן בּוֹ הַכֹּל, וְזָכָה לְהִשְׁתַּמֵּשׁ בִּכְהֻנָּה עֶלְיוֹנָה. מֵאוֹתָהּ שָׁעָה - פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן, שֶׁהִשְׁלִים לִשְׁתֵּי דְרָגוֹת מִשּׁוּם שֶׁקִּנֵּא לְשֵׁם רִבּוֹנוֹ, שֶׁתִּקֵּן מַה שֶּׁהִתְעַקֵּם.</p>"],[9522012447,"<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים פו) שָׁמְרָה נָפְשִׁי כִּי חָסִיד אָנִי הוֹשַׁע עַבְדְּךְ וְגוֹ'. יֵשׁ לְהִסְתַּכֵּל בְּסוֹף הַפָּסוּק, וְאַחַר כָּךְ עַל כָּל הַפָּסוּק. בְּסוֹף הַפָּסוּק כָּתוּב הַבּוֹטֵחַ אֵלֶיךְ, צָרִיךְ לוֹ לִהְיוֹת הַבּוֹטֵחַ בָּךְ! מַה זֶּה הַבּוֹטֵחַ אֵלֶיךְ? אֶלָּא כִּבְיָכוֹל דָּוִד מַבְטִיחַ לוֹ שֶׁלֹּא יַעֲבֹר עָלָיו חֲצוֹת הַלַּיְלָה בְּשֵׁנָה, כְּמוֹ שֶׁכָּתוּב (שם קיט) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ. קַמְתִּי הָיָה לוֹ לִהְיוֹת! אֶלָּא אָקוּם, וְאֶתְקַשֵּׁר בְּךְ לְעוֹלָמִים.</p>\n<p>שָׁמְרָה נַפְשִׁי, שְׁמֹר הָיָה צָרִיךְ לוֹ לִהְיוֹת! וַהֲרֵי לָמַדְנוּ שֶׁאֵין אוֹת בַּתּוֹרָה שֶׁאֵין בָּהּ סוֹדוֹת עֶלְיוֹנִים וְנִכְבָּדִים. שָׁמְרָה - לַקָּדוֹשׁ-בָּרוּךְ- הוּא הוּא אָמַר, שָׁמְרָה אֶת אוֹתוֹ חֵלֶק שֶׁנֶּאֱחֶזֶת בּוֹ נֶפֶשׁ. שֶׁכְּשֶׁיּוֹצֵאת הַנֶּפֶשׁ מֵהָעוֹלָם הַזֶּה, בָּאָה לָרֶשֶׁת עוֹלָם (הבא). אִם זוֹכֶה, כַּמָּה חֲיָלוֹת עֶלְיוֹנִים יוֹצְאִים לְקַבְּלָהּ וְלִשְׁמֹר אוֹתָהּ וּלְהַכְנִיסָהּ לִמְדוֹר מְקוֹמָהּ. וְהַה' הַזּוֹ לְקַחְתָּהּ לְהִתְאַחֵד עִמָּהּ בְּרָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת.</p>\n<p>וְאִם לֹא זוֹכֶה, כַּמָּה שׁוֹמְרֵי חֹק בַּעֲלֵי דִינִים מִזְדַּמְּנִים מוּלָהּ וְדוֹחִים אוֹתָהּ הַחוּצָה. אוֹי לְאוֹתָהּ נֶפֶשׁ שֶׁמִּתְגַּלְגֶּלֶת בְּרֵיקָנוּת, כְּמוֹ אֶבֶן בְּכַף הַקֶּלַע. זֶהוּ שֶׁכָּתוּב (שמואל א כה) וְאֵת נֶפֶשׁ אֹיְבֶיךְ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע. וְדָוִד בִּקֵּשׁ בַּקָּשָׁתוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר שָׁמְרָה נַפְשִׁי, שֶׁלֹּא יִדְחוּ אוֹתָהּ הַחוּצָה. וּכְשֶׁיַּגִּיעַ (למולך, יפתחו לך) מוּלָהּ, יִפְתְּחוּ לָהּ פְּתָחִים, וּתְקַבֵּל אוֹתָהּ לְפָנֶיךְ. כִּי חָסִיד אָנִי, וְכִי חָסִיד נִקְרָא? אָמַר רַבִּי יְהוּדָה, כֵּן, שֶׁכָּתוּב (ישעיה נה) חַסְדֵי דָוִד הַנֶּאֱמָנִים. בִּגְלַל כָּךְ שָׁמְרָה נַפְשִׁי, שֶׁלֹּא תַעֲזֹּב אוֹתָהּ לָלֶכֶת הַחוּצָה.</p>\n<p>רַבִּי יִצְחָק אָמַר, כָּל אָדָם שֶׁיֵּשׁ לוֹ חֵלֶק בְּצַדִּיק, יוֹרֵשׁ אֶרֶץ זוֹ, כְּמוֹ שֶׁכָּתוּב (שם ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'. וְצַדִּיק זֶה נִקְרָא חָסִיד. אָמַר דָּוִד, אַחַר שֶׁבְּמָקוֹם זֶה נֶאֱחַזְתִּי, חָסִיד אָנִי, וְלָכֵן שָׁמְרָה נַפְשִׁי לְהִתְקַשֵּׁר בְּךְ.</p>"],[9522012448,"<p>רַבִּי חִיָּיא פָּתַח, (תהלים פא) עֵדוּת בִּיהוֹסֵף שָׂמוֹ וְגוֹ'. הֲרֵי פֵּרְשׁוּהָ שֶׁלָּמַד שִׁבְעִים לָשׁוֹן, וּלְשׁוֹן הַקֹּדֶשׁ יוֹתֵר. זֶהוּ שֶׁכָּתוּב (שם) שְׂפַת לֹא יָדַעְתִּי אֶשְׁמָע. אֲבָל מַה זּוֹ עֵדוּת? בּא וּרְאֵה, בְּשָׁעָה שֶׁאֵשֶׁת פּוֹטִיפַר אָחֲזָה בּוֹ לְאוֹתוֹ הַדָּבָר, עָשָׂה יוֹסֵף עַצְמוֹ כְּמִי שֶׁלֹּא יוֹדֵעַ לְשׁוֹנָהּ, וְכֵן בְּכָל יוֹם עַד אוֹתָהּ שָׁעָה אַחֲרוֹנָה, שֶׁכָּתוּב (בראשית לט) וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ. מַה זֶּה וַתִּתְפְּשֵׂהוּ? אֶלָּא מִשּׁוּם שֶׁעָשָׂה עַצְמוֹ כְּמִי שֶׁלֹּא יוֹדֵעַ לְשׁוֹנָהּ, וְרוּחַ הַקֹּדֶשׁ צוֹוַחַת כְּנֶגְדּוֹ: (משליז) לִשְׁמָרְךְ מֵאִשָּׁה זָרָה מִנָּכְרִיָּה אֲמָרֶיהָ הֶחֱלִיקָה. מַה בָּא לְהַשְׁמִיעֵנוּ? אֶלָּא כָּל מִי שֶׁשּׁוֹמֵר עַצְמוֹ מִזֶּה, מִתְקַשֵּׁר לַשְּׁכִינָה וְאָחוּז בְּאוֹתָהּ עֵדוּת. וּמַהִי? ה' שֶׁנִּתּוֹסְפָה בּוֹ, שֶׁכָּתוּב עֵדוּת בִּיהוֹסֵף שָׂמוֹ. גַּם כָּאן הִתּוֹסְפָה י' בְּפִינְחָס עַל שֶׁקִּנֵּא בָזֶה.</p>"],[9522012449,"<p>רַבִּי יֵיסָא פָּתַח, (תהלים קלז) עַל נַהֲרוֹת בָּבֶל שָׁם יָשַׁבְנוּ גַּם בָּכִינוּ בְּזָכְרֵנוּ אֶת צִיּוֹן. אֶת יְרוּשָׁלַיִם הָיָה צָרִיךְ לוֹ לִהְיוֹת, כְּמוֹ שֶׁכָּתוּב אִם אֶשְׁכָּחֵךְ יְרוּשָׁלם תִּשְׁכַּח יְמִינִי! מַה זֶּה בְּזָכְרֵנוּ אֶת צִיּוֹן? לְאָדָם שֶׁהָיָה לוֹ הֵיכָל נִכְבָּד, נָאֶה וְיָפֶה, בָּאוּ לִסְטִים וְשָׂרְפוּ אוֹתוֹ. צַעֲרוֹ שֶׁל מִי הוּא? לֹא שֶׁל בַּעַל הַהֵיכָל?! גַּם כָּאן הַשְּׁכִינָה שְׁרוּיָה בַּגָּלוּת, צַעַר שֶׁל מִי הוּא? לֹא שֶׁל הַצַּדִּיק?! וְזֶה הוֹלֵךְ כְּפִי שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (ישעיה נז) הַצַּדִּיק אָבָד, אָבָד מַמָּשׁ. גַּם כָּאן בְּזָכְרֵנוּ אֶת צִיּוֹן, בְּזָכְרֵנוּ אֶת אוֹתוֹ צַעַר שֶׁלּוֹ עַל זוּגָתוֹ, צַעַר שֶׁלּוֹ הוּא.</p>\n<p>אָמַר רַבִּי יֵיסָא, מִי שֶׁמּוֹקִיר שֵׁם רִבּוֹנוֹ בָּזֶה וְשׁוֹמֵר זֶה, זוֹכֶה שֶׁיּוֹקִיר אוֹתוֹ רִבּוֹנוֹ עַל הַכֹּל. מִנַּיִן לָנוּ? מִיּוֹסֵף, שֶׁכָּתוּב (בראשית מא) וַיַּרְכֵּב אֹתוֹ בְּמִרְכֶּבֶת הַמִּשְׁנֶה אֲשֶׁר לוֹ, וְכָתוּב וְנָתוֹן אֹתוֹ עַל כָּל אֶרֶץ מִצְרָיִם. וְלֹא עוֹד, אֶלָּא כְּשֶׁעָבְרוּ יִשְׂרָאֵל אֶת הַיָּם, אֲרוֹנוֹ שֶׁל יוֹסֵף נִכְנַס בִּפְנִים בַּהַתְחָלָה, וְלֹא הָיוּ הַמַּיִם עוֹמְדִים עַל עָמְדָם לְפָנָיו. זֶהוּ שֶׁכָּתוּב (תהלים קיד) הַיָּם רָאָה וַיָּנֹס. מַה זֶּה וַיָּנֹס? אֶלָּא רָאָה אוֹתוֹ שֶׁכָּתוּב בּוֹ (בראשית לט) וַיָּנָס וַיֵּצֵא הַחוּצָה.</p>\n<p>בֹּא וּרְאֵה, זוֹכֶה לְכָבוֹד בְּחַיָּיו וְזוֹכֶה לְכָבוֹד בְּמִיתָתוֹ. בְּחַיָּיו מַדּוּעַ? בִּגְלַל אוֹתוֹ זְמַן שֶׁלֹּא רָצָה לְהִתְדַּבֵּק בָּהּ, שֶׁכָּתוּב (שם) וַיְמָאֵן וַיֹּאמֶר אֶל אֵשֶׁת אֲדנָיו. וְכָתוּב, וְלֹא שָׁמַע אֵלֶיהָ לִשְׁכַּב אֶצְלָהּ לִהְיוֹת עִמָּהּ. בִּגְלַל זֶה זָכָה בְּזֶה הָעוֹלָם. כֵּיוָן שֶׁכָּתוּב וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ, וְכָתוּב וַיָּנָס וַיֵּצֵא הַחוּצָה, זָכָה לְבַסּוֹף שֶׁנִּכְנַס לְתוֹךְ מְחִצָּה עֶלְיוֹנָה, וְכָךְ רָאוּי לוֹ - אֶת שֶׁלּוֹ לָקַח בְּזֶה הָעוֹלָם, וְאֶת שֶׁלּוֹ לָקַח בָּעוֹלָם הָאַחֵר.</p>\n<p>פִּנְחָס זָכָה בְּזֶה הָעוֹלָם, וְזָכָה בָּעוֹלָם הַבָּא, וְזָכָה לְהִתְקַיֵּם יוֹתֵר מִכָּל אֵלּוּ שֶׁיָּצְאוּ מִמִּצְרַיִם, וְזָכָה לִכְהֻנָּה גְּדוֹלָה, הוּא וְכָל בָּנָיו אַחֲרָיו. וְאִם תֹּאמַר שֶׁלֹּא (שהרי) זָכָה לִכְהֻנָּה עַד שֶׁלֹּא עָשָׂה מַעֲשֶׂה זֶה - נָכוֹן (לא). שֶׁהֲרֵי אוֹתָם שֶׁאוֹמְרִים (שלא) זָכָה קֹדֶם - לֹא כָּךְ. אֶלָּא כְּמוֹ שֶׁבֵּאַרְנוּ - תַּחַת אֲשֶׁר קִנֵּא לֵאלֹהָיו, שֶׁמַּשְׁמָע שֶׁבִּגְלַל מַעֲשֶׂה זֶה הִרְוִיחַ הַכְּהֻנָּה, מַה שֶּׁלֹּא הָיָה מִקֹּדֶם.</p>\n<p>בֹּא וּרְאֵה, כָּל כֹּהֵן שֶׁהוֹרֵג נֶפֶשׁ, נִפְסְלָה כְהֻנָּתוֹ לְעוֹלָמִים, שֶׁהֲרֵי וַדַּאי פָּסַל אוֹתָהּ דַּרְגָּה שֶׁלּוֹ אֵלָיו. וּפִנְחָס מֵהַדִּין הָיָה פָּסוּל לִכְהֻנָּה, וּבִגְלַ שֶׁקִּנֵּא לַקָּדוֹשׁ-בָּרוּךְ-הוּא, הִצְטָרֵךְ לְיַחֵס לוֹ כְּהֻנַּת עוֹלָמִים, לוֹ וּלְבָנָיו אַחֲרָיו לְדוֹרֵי דוֹרוֹת. אָמַר רַבִּי יִצְחָק, בּא וּרְאֵה, פִּנְחָס רָשׁוּם הוּא לְמַעְלָה, וְרָשׁוּם הוּא לְמַטָּה, עַד שֶׁלֹּא יֵצֵא לָעוֹלָם, שֶׁהֲרֵי עִם אוֹתָם שֶׁיָּצְאוּ מִמִּצְרַיִם נִמְנָה.</p>\n<p>רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּמִּדְבָּר. אָמַר רַבִּי יוֹסֵי, זֶה שֶׁכָּתוּב בְּפִנְחָס הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. שָׁלוֹם מִמַּלְאַךְ הַמָּוֶת שֶׁלֹּא שׁוֹלֵט בּוֹ לְעוֹלָמִים וְלֹא נִדּוֹן בְּדִינָיו. וְאִם תֹּאמַר שֶׁלֹּא מֵת - וַדַּאי לֹא מֵת כִּשְׁאָר בְּנֵי הָעוֹלָם, וְהֶאֱרִיךְ יָמִים עַל כָּל בְּנֵי דוֹרוֹ, מִשּׁוּם שֶׁהִתְאַחֵז בַּבְּרִית הָעֶלְיוֹנָה הַזּוֹ. וּכְשֶׁהִסְתַּלֵּק מֵהָעוֹלָם, בְּתַאֲוָה עֶלְיוֹנָה וּבִדְבֵקוּת נָאָה הִסְתַּלֵּק מִשְּׁאָר בְּנֵי הָעוֹלָם.</p>"],[9522012450,"<p>רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (זכריה ג) וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל עֹמֵד לִפְנֵי מַלְאַךְ ה' וְגוֹ'. בֹּא וּרְאֵה, אוֹי לְאוֹתָם בְּנֵי אַדָם שֶׁלֹּא מִסְתַּכְּלִים בִּכְבוֹד רִבּוֹנָם, וְכָל יוֹם וָיוֹם הַכָּרוֹז קוֹרֵא עֲלֵיהֶם, וְלֹא מַשְׁגִּיחִים. בָּא אָדָם לְהִסְתַּכֵּל בְּמִצְווֹת הַתּוֹרָה - כַּמָּה סָנֵגוֹרִים עוֹמְדִים לְהַזְכִּירוֹ לְטוֹב. בָּא אָדָם וְעוֹבֵר עַל מִצְווֹת הַתּוֹרָה - אוֹתָם מַעֲשִׂים מְקַטְרְגִים עָלָיו לְרַע לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. יְהוֹשֻׁעַ כֹּהֵן גָּדוֹל הָיָה, וּפֵרְשׁוּהָ, מַה כָּתוּב בּוֹ? וְהַשָּׂטָן עֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. וּמַה בָּזֶה כָּךְ, בִּשְׁאָר בְּנֵי אָדָם שֶׁלֹּא מִסְתַּכְּלִים בִּכְבוֹד רִבּוֹנָם עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>רְאֵה מַה כָּתוּב, וִיהוֹשֻׁעַ הָיָה לָבֻשׁ בְּגָדִים צוֹאִים, וּפֵרְשׁוּהָ. אֲבָל בְּגָדִים צוֹאִים, וַדַּאי אוֹתָם לְבוּשִׁים שֶׁהָרוּחַ הִתְלַבְּשָׁה בָהֶם בְּאוֹתוֹ עוֹלָם. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁלְּבוּשָׁיו מְתֻקָּנִים וּשְׁלֵמִים בְּאוֹתוֹ עוֹלָם. וַהֲרֵי נִתְבָּאֵר, כָּל מִי שֶׁצְּרִיכִים לְהַכְנִיסוֹ לַגֵּיהִנֹּם, אוֹתָם לְבוּשִׁים שֶׁמַּלְבִּישִׁים אוֹתוֹ אֵיךְ הֵם? מַה כָּתוּב כָּאן? וִיהוֹשֻׁעַ הָיָה לָבֻשׁ בְּגָדִים צוֹאִים וְעֹמֵד לִפְנֵי הַמַּלְאָךְ. אֵיזֶה מַלְאָךְ? זֶה הַמַּלְאָךְ הַמְמֻנֶּה עַל גֵּיהִנֹּם וּמְמֻנֶּה עַל מִי שֶׁרָאָה בְּאוֹתָם לְבוּשִׁים. עַד שֶׁבָּא קוֹל וְאָמַר: הָסִירוּ הַבְּגָדִים הַצּאִים מֵעָלָיו.</p>\n<p>מִכָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁמַּעֲשִׂים רָעִים שֶׁל אָדָם עוֹשִׂים לוֹ בְּגָדִים צוֹאִים. וַיֹּאמֶר אֵלָיו רְאֵה הֶעֱבַרְתִּי מֵעָלֶיךְ עֲונֶךְ וְהַלְבֵּשׁ אֹתְךְ מַחֲלָצוֹת. הִלְבִּישׁוּהוּ לְבוּשִׁים אֲחֵרִים מְתֻקָּנִים שֶׁבָּהֶם מִסְתַּכֵּל אָדָם בְּזִיו כְּבוֹד רִבּוֹנוֹ.</p>\n<p>בֹּא וּרְאֵה, כְּמוֹ זֶה פִּנְחָס, שֶׁלֹּא הִסְתַּלֵּק מֵהָעוֹלָם עַד שֶׁהִתְקִינוּ לְפָנָיו לְבוּשִׁים אֲחֵרִים שֶׁהָרוּחַ נֶהֱנֵית בָּהֶם לָעוֹלָם הַבָּא. בְּשָׁעָה אַחַת הִתְפַּשֵּׁט מֵאֵלֶּה וְהִתְלַבֵּשׁ בְּאֵלֶּה, לְקַיֵּם אֶת הַכָּתוּב הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. עַד שֶׁהָיוּ הוֹלְכִים, הַשֶּׁמֶשׁ הָיְתָה חֲזָקָה, וְיָשְׁבוּ תַּחַת צֵל שֶׁל סֶלַע אֶחָד שֶׁל הַמִּדְבָּר. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי צֵל חֶדְוַת הַנֶּפֶשׁ הוּא.</p>"],[9522012451,"<p>אָמַר רַבִּי חִיָּיא לְרַבִּי אֶלְעָזָר, יָמִים אֵלּוּ מֵרֹאשׁ הַשָּׁנָה עַד יוֹם הָאַחֲרוֹן שֶׁל חַג בִּרְצוֹנִי לַעֲמֹד עֲלֵיהֶם. אָמַר רַבִּי אֶלְעָזָר, זֶה נֶאֱמַר, וְהַחֲבֵרִים הִתְעוֹרְרוּ בָזֶה. אָמַר רַבִּי חִיָּיא, וַדַּאי כָּךְ הוּא, אֲבָל אֲנִי שָׁמַעְתִּי מֵהַמְּנוֹרָה הַקְּדוֹשָׁה עֶלְיוֹנָה דָּבָר בָּהֶם. אָמַר לוֹ, אֱמֹר אוֹתוֹ דָּבָר. אָמַר לוֹ, עֲדַיִן לֹא עָמַדְתִּי בוֹ. אָמַר רַבִּי אֶלְעָזָר, אַף עַל גַּב שֶׁהַחֲבֵרִים בֵּאֲרוּ דָבָר וְיָפֶה הוּא, אֲבָל סִדּוּר הַיָּמִים הַלָּלוּ הוּא סוֹד חָכְמָה בֵּין קוֹצְרֵי הַשָּׂדֶה.</p>\n<p>בֹּא וּרְאֵה, הֲרֵי נֶאֱמַר סִדּוּר שֶׁל יִחוּד הַכֹּל בְּאֶחָד אֵיךְ הָיָה, וַהֲרֵי נִתְבָּאֵר. פָּתַח וְאָמַר, (ישעיהנב) חָשַׂף ה' אֶת זְרוֹע קָדְשׁוֹ - זוֹ זְרוֹעַ אַחַת שֶׁבָּהּ תְּלוּיָה הַיְשׁוּעָה, שֶׁבָּהּ תְּלוּיָה הַנְּקָמָה, שֶׁבָּהּ תְּלוּיָה הַגְּאֻלָּה. וְלָמָּה? לְהָקִים אֶת כְּנֶסֶת יִשְׂרָאֵל מֵהֶעָפָר וּלְקַבְּלָהּ אֵלָיו לְהִזְדַּוֵּג כֶּחָד. וּכְשֶׁזֶּה מִתְעוֹרֵר לְקַבְּלָהּ, כַּמָּה פַּחַד שָׁרוּי בָּעוֹלָם, עַד שֶׁיָּנִיחַ אוֹתָהּ זְרוֹעַ תַּחַת רֹאשָׁהּ לְהִתְחַבֵּר, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וְגוֹ'. וְאָז נָח הַדִּין וּמְכַפֵּר עַל חֲטָאִים.</p>\n<p>אַחַר כָּךְ בָּאָה הַיָּמִין לְחַבֵּק, וְאָז חֶדְוָה שְׁרוּיָה בָּעוֹלָם וְכָל הַפָּנִים מְאִירוֹת. אַחַר כָּךְ מִזְדַּוֶּגֶת בְּגוּף, וְאָז הַכֹּל נִקְרָא אֶחָד, בְּלִי פֵרוּד, וְאָז הוּא שְׁלֵמוּת וְחֶדְוַת הַכֹּל, וַאֲחוּזִים בְּוַדַּאי מַה שֶּׁלֹּא נִמְצָא כָּךְ בְּיֶתֶר הַזְּמַנִּים.</p>\n<p>כְּמוֹ שֶׁל זֶה, סִדּוּר הַיָּמִים הַלָּלוּ מֵרֹאשׁ הַשָּׁנָה עַד יוֹם הָאַחֲרוֹן שֶׁל חַג. בְּרֹאשׁ הַשָּׁנָה מִתְעוֹרֶרֶת זְרוֹעַ שְׂמֹאל לְקַבֵּל אֶת הַמַּלְכָּה, וְאָז כָּל הָעוֹלָם בְּפַחַד בַּדִּין, וְצָרִיךְ אוֹתוֹ הַזְּמַן בִּתְשׁוּבָה שְׁלֵמָה שֶׁיִּמָּצֵא הָעוֹלָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אַחַר כָּךְ בָּאָה הַמַּלְכָּה, וּמִתְבַּקְשִׁים בְּנֵי הַהֵיכָל בַּתְּשִׁיעִי לַחֹדֶשׁ לַעֲשׂוֹת חֶדְוָה וְלִטְבֹּל בְּנָהָר, לְטַהֵר עַצְמָם בְּזִוּוּג הַמַּלְכָּה בַּיּוֹם הָאַחֵר, הוּא זִוּוּג שֶׁלָּהּ לָשִׂים שְׂמֹאל תַּחַת רֹאשָׁהּ (ראש המלך), כְּמוֹ שֶׁנֶּאֱמַר שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי.</p>\n<p>וְאָז יִשְׂרָאֵל בְּתַעֲנִית עַל חֲטָאֵיהֶם, וּמְכַפֶּרֶת לָהֶם. שֶׁהֲרֵי הָאֵם הָעֶלְיוֹנָה מְאִירָה פָנֶיהָ לַמַּלְכָּה בְּזִוּוּגָהּ, וּמִתְכַּפְּרִים כָּל בְּנֵי הַהֵיכָל, כֵּיוָן שֶׁהַשְּׂמֹאל מְקַבֵּל אוֹתָהּ בַּיּוֹם הַזֶּה, שֶׁרֹאשׁ הַמַּלְכָּה עַל הַשְּׂמֹאל.</p>\n<p>בַּיּוֹם הָרִאשׁוֹן שֶׁל הֶחָג יִתְעוֹרֵר הַיָּמִין לְקַבְּלָהּ בִּשְׁבִיל לְחַבְּקָהּ, וְאָז כָּל הַחֶדְוָה וְכָל הַפָּנִים מְאִירוֹת, וְחֶדְוַת הַמַּיִם הַצְּלוּלִים לְנַסֵּךְ עַל הַמִּזְבֵּחַ, וּצְרִיכִים בְּנֵי אָדָם לִשְׂמֹחַ בְּכָל מִינֵי חֶדְוָה, שֶׁהֲרֵי הַיָּמִין גּוֹרֵם. בְּכָל מָקוֹם שֶׁשָּׁרוּי יָמִין, חֶדְוָה צְרִיכָה בַּכֹּל, וְאָז חֶדְוָה הִיא לְהִשְׁתַּעֲשֵׁעַ.</p>\n<p>אַחַר כָּךְ בַּיּוֹם הַשְּׁמִינִי חֶדְוַת הַתּוֹרָה הִיא, שֶׁהֲרֵי אָז זִוּוּג הַגּוּף הוּא, זִוּוּג הַכֹּל, לִהְיוֹת הַכֹּל אֶחָד, וְזֶהוּ שְׁלֵמוּת הַכֹּל, וְזֶהוּ יוֹם שֶׁל יִשְׂרָאֵל וַדַּאי וְחֵלֶק שֶׁלָּהֶם לְבַדָּם, שֶׁאֵין בּוֹ חֵלֶק לְאַחֵר. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (דברים יד) כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ וְגוֹ'.</p>"],[9522012452,"<p>פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן הֵשִׁיב אֶת חֲמָתִי מֵעַל בְּנֵי יִשְׂרָאֵל וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (איוב ד) זְכָר נָא מִי הוּא נָקִי אָבָד וְאֵיפֹה יְשָׁרִים נִכְחָדוּ. שָׁם שָׁנִינוּ, מִי שֶׁרוֹאֶה קֶשֶׁת בִּגְוָנֶיהָ (מאירים), צָרִיךְ לְבָרֵךְ בָּרוּךְ זוֹכֵר הַבְּרִית, מִשּׁוּם שֶׁזֶּהוּ בְּרִית הַקַּיָּם הַקָּדוֹשׁ שֶׁשָּׂם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ כְּדֵי שֶׁלֹּא יָבֹא עָלֶיהָ מֵי הַמַּבּוּל. מִשּׁוּם שֶׁכְּשֶׁמִּתְרַבִּים רְשָׁעִים בָּעוֹלָם, רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַאֲבִיד אוֹתָם, וְאָז זוֹכֵר לָהֶם שְׁבוּעָה זוֹ שֶׁנִּשְׁבַּע לָאָרֶץ, שֶׁכָּתוּב פַּעֲמַיִם לֹא לֹא: (בראשית ח) לֹא אֹסִף לְקַלֵּל, וְלֹא אֹסִף עוֹד לְהַכּוֹת. זוֹהִי הַשְּׁבוּעָה, כְּמוֹ שֶׁכָּתוּב (ישעיה נד) אֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבֹר מֵי נֹחַ.</p>\n<p>רַבִּי יוֹסֵי אָמַר, הַקֶּשֶׁת בָּאָה לְהָגֵן עַל הָעוֹלָם. לְמֶלֶךְ שֶׁכָּל הַפְּעָמִים שֶׁבְּנוֹ חָטָא כְּנֶגְדּוֹ, בָּא הַמֶּלֶךְ לְהַלְקוֹתוֹ - הִתְגַּלְּתָה עָלָיו הַמַּלְכָּה בִּלְבוּשֵׁי כָבוֹד שֶׁל מַלְכוּת. כְּשֶׁהַמֶּלֶךְ רוֹאֶה אוֹתָהּ, מִסְתַּלֵּק הָרֹגֶז שֶׁל בְּנוֹ, וְשָׂמֵחַ בָּהּ, שֶׁכָּתוּב (בראשית ט) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וְעַל כָּךְ לֹא נִרְאֵית הַקֶּשֶׁת בָּעוֹלָם אֶלָּא בִּלְבוּשֵׁי כָבוֹד שֶׁל מַלְכוּת. וּבְשָׁעָה שֶׁיֵּשׁ צַדִּיק בָּעוֹלָם, הוּא בְּרִית לְהַעֲמִיד בְּרִית וּמָגֵן עַל הָעוֹלָם. אִם אֵין צַדִּיק, הֲרֵי הַקֶּשֶׁת, לְהֵרָאוֹת שֶׁהָעוֹלָם עוֹמֵד לְהֵאָבֵד, אֶלָּא בִּגְלַל קֶשֶׁת זוֹ. רַבִּי אֶלְעָזָר אָמַר, לְעוֹלָם לֹא מִתְלַבֶּשֶׁת קֶשֶׁת זוֹ, אֶלָּא בִּלְבוּשׁ הָאָבוֹת הָרִאשׁוֹנִים, יָרֹק אָדֹם וְלָבָן. יָרֹק, זֶה לְבוּשׁ אַבְרָהָם, נִצְבַּע לְבוּשׁ (גון) זֶה כְּשֶׁיָּצָא מִמֶּנּוּ יִשְׁמָעֵאל. אָדם זֶה הַגָּוֶן שֶׁל יִצְחָק, שֶׁבָּא אָדם וְנִצְבַּע כְּשֶׁיָּצָא מִמֶּנּוּ עֵשָׂו, וְנִמְשַׁךְ אוֹתוֹ הָאָדם לְמַטָּה עַד כּוֹכָב מַאְדִּים, שֶׁנֶּאֱחָז בּוֹ עֵשָׂו. לָבָן זֶהוּ לְבוּשׁ טוֹב שֶׁל יַעֲקֹב, שֶׁהֲרֵי לֹא הִשְׁתַּנּוּ פָנָיו לְעוֹלָמִים. רַבִּי אַבָּא אָמַר, יָפֶה הוּא, אֲבָל כָּךְ אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, לָבָן זֶה אַבְרָהָם, שֶׁהִתְלַבֵּן בְּלֹבֶן הָאֵשׁ. אָדם זֶה וַדַּאי יִצְחָק. יָרֹק זֶהוּ יַעֲקֹב, שֶׁעוֹמֵד בֵּין שְׁנֵי גְוָנִים, וְכָתוּב בּוֹ בְּיַעֲקֹב, (ישעיה כט) לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ, שֶׁהֲרֵי כָּל מִטָּתוֹ הָיְתָה שְׁלֵמָה. וְכָךְ הוּא לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב - לְהֵרָאוֹת בְּגָוֶן אָדם כְּיִצְחָק שֶׁיָּצָא מִמֶּנּוּ עֵשָׂו, וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ - כְּמוֹ אַבְרָהָם, לְהֵרָאוֹת בְּגָוֶן לָבָן, שֶׁיָּצָא מִמֶּנּוּ יִשְׁמָעֵאל. אֶלָּא לָקַח גְּוָנִים לְהִתְעַטֵּר בָּהֶם עַל הָאָבוֹת שֶׁלּוֹ. וּבַלְּבוּשִׁים הַלָּלוּ מִתְלַבֶּשֶׁת הַקֶּשֶׁת בְּשָׁעָה שֶׁנִּרְאֵית לִפְנֵי הַמֶּלֶךְ. בֹּא וּרְאֵה, סוֹד הַבְּרִית הַקְּדוֹשָׁה הִיא אוֹת יוֹ\"ד שֶׁמִּתְעַטֶּרֶת בְּרֹשֶׁם עֶלְיוֹן, וַהֲרֵי (וזה) הוּא שֶׁנִּרְשָׁם בַּבְּרִית תָּמִיד לְעוֹלָמִים, וּמִשּׁוּם שֶׁקִּנֵּא פִּנְחָס עַל הַבְּרִית, נִרְשְׁמָה בִּשְׁמוֹ הָאוֹת הַזּוֹ כָּאן, פִּינְחָס, יוֹ\"ד קְטַנָּה, הִיא יוֹ\"ד שֶׁהִיא בְּרִית וַדַּאי, שֶׁיּוֹצֵאת מִתּוֹךְ יוֹ\"ד עֶלְיוֹנָה קְדוֹשָׁה. וְלָכֵן הוּא עוֹמֵד בְּקִיּוּם שָׁלֵם לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁלֹּא נֶאֱבָד מִתּוֹךְ הָעוֹלָם. וְכָךְ הוּא נָקִי מֵאוֹתוֹ חֵטְא שֶׁל פְּעוֹר, וְלֹא נֶאֱבָד תָּמִיד בְּתוֹךְ קֹדֶשׁ הָעוֹלָם (ולא נאבד מתוך העולם). (איוב ד) וְאֵיפֹה יְשָׁרִים נִכְחָדוּ - אֵלּוּ נָדָב וַאֲבִיהוּא שֶׁלֹּא נִשְׁמְדוּ מֵאוֹתוֹ הָעוֹלָם בִּגְלָלוֹ.</p>\n<p>אָמַר לוֹ הָרוֹעֶה הַנֶּאֱמָן, יָפֶה אָמַרְתָּ, אֲבָל מִשּׁוּם שֶׁאֵלִיָּהוּ, שֶׁהוּא פִּנְחָס, קִנֵּא עַל הַבְּרִית, צָרִיךְ לְחַדֵּשׁ דְּבָרִים רַבִּים בָּהּ, שֶׁהֲרֵי הַפָּרָשָׁה כְּתוּבָה בַּתּוֹרָה עַל שְׁמוֹ, שֶׁעָלָיו נֶאֱמַר (מלכים איט) קַנֹּא קִנֵּאתִי, שְׁתֵּי קְנָאוֹת. אַחַת בְּשַׁדַּ\"י שֶׁלְּמַעְלָה, וְהַשֵּׁנִית בְּשַׁדַּ\"י שֶׁלְּמַטָּה. וְלָכֵן עָשָׂה שְׁתֵּי שְׁבוּעוֹת (בשני לא לא) (בפעמים) בִּשְׁתֵּיהֶן, וּפַעֲמַיִם לֹא לֹא.</p>\n<p>אֲבָל רַבִּי יְהוּדָה אָמַר, מִי שֶׁרוֹאֶה קֶשֶׁת בִּגְוָנִים מְאִירִים, צָרִיךְ לְבָרֵךְ בָּרוּךְ זוֹכֵר הַבְּרִית. וּבַגָּלוּת, שֶׁאֵינָהּ מְאִירָה בִּגְוָנֶיהָ כָּרָאוּי, וְלֹא עוֹד, אֶלָּא שֶׁלִּפְעָמִים מְאִירָה מְעַט וְלִפְעָמִים לֹא מְאִירָה בִּכְלָל, לִפְעָמִים נִרְאֵית בִּשְׁלֵמוּת וְלִפְעָמִים לֹא. שֶׁקֶּשֶׁת רוֹמֶזֶת גְּוָנֶיהָ לִזְכֻיּוֹת הַכֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים כְּשֶׁהֵם יָפִים, שֶׁהַקֶּשֶׁת מְאִירָה בִּגְוָנֶיהָ שֶׁהֵם שְׁלֹשָׁה.</p>\n<p>קוּם אַתָּה רַבִּי יוֹסֵי הַגְּלִילִי וֶאֱמֹר, שֶׁהֲרֵי דְּבָרִים יָפִים אָמַרְתָּ בַּחִבּוּר הָרִאשׁוֹן, שֶׁקֶּשֶׁת לֹא בָאָה אֶלָּא לְהָגֵן עַל הָעוֹלָם. לְמֶלֶךְ, שֶׁבְּכָל זְמַן שֶׁבְּנוֹ חוֹטֵא וְהַמֶּלֶךְ רוֹאֶה אֶת הַמַּלְכָּה, מִסְתַּלֵּק רֹגֶז בְּנוֹ, שֶׁכָּתוּב (בראשית יט) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וְלָכֵן לֹא נִרְאֵית קֶשֶׁת אֶלָּא לְהָגֵן עַל הָעוֹלָם. וְלֹא נִגְלֵית אֶלָּא בִּלְבוּשׁ נִכְבָּד שֶׁל מַלְכוּת, וּבְשָׁעָה שֶׁיֵּשׁ צַדִּיק בָּאָרֶץ, הוּא הַבְּרִית, לְהַעֲמִיד בְּרִית.</p>\n<p>וְכִי בַגָּלוּת הִתְרַחֵק הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהַמַּלְכָּה? וְאֵיךְ הַמַּלְכָּה הִתְלַבְּשָׁה לְבוּשֵׁי מַלְכוּת בַּגָּלוּת? לֹא. אֲבָל בַּגָּלוּת לְבוּשָׁהּ שֶׁל קַדְרוּת, וְהִיא אוֹמֶרֶת, (שיר השירים א) אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת. אֶלָּא וַדַּאי אוֹתָהּ קֶשֶׁת שֶׁנִּגְלֵית בַּגָּלוּת אֵינָהּ אֶלָּא מְטַטְרוֹ\"ן, שֶׁנִּקְרָא שַׁדַּ\"י, וְהוּא עַבְדּוֹ זְקַן בֵּיתוֹ שֶׁשּׁוֹלֵט בְּכָל אֲשֶׁר לוֹ (בגלות), וּבָנָיו נִקְרָאִים עַבְדֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וּבְנֵי הַמַּלְכָּה בָּנִים, וּמִשּׁוּם זֶה אִם כְּבָנִים אִם כַּעֲבָדִים.</p>\n<p>וּכְשֶׁחָרַב בֵּית הַמִּקְדָּשׁ, פֵּרְשׁוּהָ שֶׁעֲבָדִים חָפוּ רֹאשָׁם וְנִדַּלְדְּלוּ אַנְשֵׁי מַעֲשֶׂה. וַדַּאי אַנְשֵׁי מַעֲשֶׂה נִקְרְאוּ עַל שֵׁם הַמַּלְכָּה, שֶׁנֶּאֱמַר עָלֶיהָ (משלי לא) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל וְאַתְּ עָלִית עַל כֻּלָּנָה. אֲבָל אִם יֵשׁ צַדִּיק שֶׁזְּכֻיּוֹתָיו וּמַעֲשָׂיו לְהָאִיר בָּהֶם אֶת הַמַּלְכָּה, וְלִפְשֹׁט מִמֶּנָּה לְבוּשֵׁי קַדְרוּת הַפְּשׁוּטִים וּלְקַשֵּׁט אוֹתָהּ בִּלְבוּשִׁים שֶׁל גְּוָנִים מְאִירִים שֶׁל סוֹדוֹת הַתּוֹרָה, מַה כָּתוּב בּוֹ? וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וּרְאִיתִיהָ, בְּסוֹדוֹת מְאִירִים שֶׁל הַתּוֹרָה, שֶׁאוֹ\"ר נִקְרָא רָ\"ז. זֶהוּ שֶׁכָּתוּב (משלי ו) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר. וּבַסּוֹדוֹת הַלָּלוּ נֶאֱמַר וּרְאִיתִיהָ.</p>\n<p>וּבְאוֹתוֹ זְמַן עוֹלֶה מִמֶּנּוּ רֹגֶז בְּנוֹ, (אסתר ז) וַחֲמַת הַמֶּלֶךְ שָׁכָכָה, וְיֹאמַר לָהּ הַמֶּלֶךְ בִּתְפִלַּת הָעֲמִידָה לְפָנָיו, (שם ה) מַה שְּׁאֵלָתֵךְ וְיִנָּתֶן לָךְ וּמַה בַּקָּשָׁתֵךְ. בְּאוֹתוֹ זְמַן שׁוֹאֶלֶת עַל גְּאֻלָּתָהּ וּבָנֶיהָ עִמָּהּ, זֶהוּ שֶׁכָּתוּב (שם ז) תִּנָּתֶן לִי נַפְשִׁי בִּשְׁאֵלָתִי וְעַמִּי בְּבַקָּשָׁתִי. אֲבָל קֶשֶׁת שֶׁנִּרְאֵית בָּעוֹלָם בַּגָּלוּת, שֶׁעֶבֶד הוּא, לִפְעָמִים יוֹצֵא בִשְׁלֵמוּת, כְּשֶׁבָּנָיו מַכְשִׁירִים מַעֲשֵׂיהֶם, וְלִפְעָמִים לֹא נִמְצָא בִשְׁלֵמוּת, כְּשֶׁבָּנָיו לֹא מַכְשִׁירִים מַעֲשֵׂיהֶם. וְאִם לֹא בִּגְלַל אוֹת יוֹ\"ד שֶׁל שַׁדַּ\"י שֶׁקִּנֵּא עָלֶיהָ פִּנְחָס שֶׁהֵגֵנָּה עָלָיו מִשִּׁבְטוֹ שֶׁל שִׁמְעוֹן, הָיוּ הוֹרְגִים אוֹתוֹ וּמְאַבְּדִים אוֹתוֹ מִן הָעוֹלָם.</p>\n<p>וּמִשּׁוּם זֶה, (איוב ד) זְכָר נָא מִי הוּא נָקִי אָבָד - זֶה פִּנְחָס. וְאֵיפֹה רְשָׁעִים נִכְחָדוּ - אֵלּוּ שֶׁמַּעֲשֵׂיהֶם כְּשֵׁרִים לִפְנֵי הַמֶּלֶךְ וּמְקַנְּאִים עַל שְׁמוֹ וּמְקַדְּשִׁים אוֹתוֹ בָּרַבִּים, כָּךְ מְקַדְּשִׁים אוֹתוֹ לְמַעְלָה בֵּין מְמֻנֵּי שְׁאָר הָעַמִּים, וְנוֹדָעִים לוֹ כָּל מְמֻנֶּה בְּכִנּוּיוֹ. אֲבָל יִשְׂרָאֵל נוֹדָעִים לְמַעְלָה הַכֹּל בְּשֵׁם יְהֹוָ\"ה, שֶׁהוּא מְחַיֶּה כָּל הַכִּנּוּיִים.</p>\n<p>וְכָל שֵׁם וְכִנּוּי מֵעִיד עָלָיו. אֵ\"ל מֵעִיד עָלָיו שֶׁיֵּשׁ לוֹ יְכֹלֶת עַל כָּל אֵל, זֶהוּ שֶׁכָּתוּב אֲנִי אֶדְר!שׁ אֶל אֵל. אֵל - בַּעַל הָאֵל. אֱלֹהִים מֵעִיד עָלָיו שֶׁהוּא אֱלֹהֵי הָאֱלֹהִים. אֲדנָ\"י מֵעִיד עָלָיו שֶׁהוּא אֲדוֹנֵי הָאֲדוֹנִים. גַּם כָּךְ כָּל שֵׁם. שֶׁלְּכָל (ספירה ומלאך) מַלְאָךְ יֵשׁ שֵׁם יָדוּעַ, לְהוֹדִיעַ לְכָל כַּת בְּאוֹתוֹ שֵׁם שֶׁל מַלְכּוֹ. אֲבָל יִשְׂרָאֵל נוֹדָעִים לוֹ בְּיהו\"ה.</p>\n<p>וְסוֹד הַדָּבָר - לְבֶן אָדָם אֶחָד יְכוֹלִים לִהְיוֹת כַּמָּה סוּסִים, גַּם כָּךְ כָּל יִשְׂרָאֵל הֵם בָּנָיו שֶׁל אָדָם, וְכָל בֵּן צָרִיךְ לִהְיוֹת לוֹ לְאָבִיו כְּסוּס וְכַחֲמוֹר לְמַשָּׂא וְלִהְיוֹת כָּפוּף תַּחְתָּיו, וְזֶהוּ סוֹד (תהלים לו) אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'. שֶׁהוּא בֵּן שֶׁל אָדָם, וְעוֹשֶׂה עַצְמוֹ כִּבְהֵמָה תַּחְתָּיו.</p>"],[9522012453,"<p>וְלָכֵן זוֹהִי מִצְוַת הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתּוֹרָה לִהְיוֹת אָח מְיַבֵּם אֶת אֵשֶׁת אָחִיו לַעֲשׂוֹת בֵּן לְאָחִיו, כְּדֵי שֶׁלֹּא יֹאבַד מֵאוֹתוֹ עוֹלָם. וְזֶהוּ כְּמוֹ סוֹד כִּלְאַיִם בְּצִיצִית. שֶׁאָמְרוּ, מַה שֶּׁאָסַרְתִּי לְךְ כָּאן - הִתַּרְתִּי לְךְ כָּאן. אָסַרְתִּי לְךְ כִּלְאַיִם שֶׁל הָעוֹלָם - הִתַּרְתִּי לְךְ כִּלְאַיִם שֶׁל צִיצִית. אָסַרְתִּי לְךְ אֵשֶׁת אָח - הִתַּרְתִּי לְךְ יְבָמָה. כְּגוֹן מַרְכִּיבִים תַּפּוּחִים אוֹ דְקָלִים מִין בְּמִינוֹ, וְאָסוּר לְהַרְכִּיב מִין בְּשֶׁאֵינוֹ מִינוֹ. וְנֶאֱמַר בּוֹ (דברים כ) כִּי הָאָדָם עֵץ הַשָּׂדֶה. וּבִיבָמָה מַרְכִּיבִים מִין בְּשֶׁאֵינוֹ מִינוֹ, כְּדֵי שֶׁלֹּא תֹאבַד (להאביד) נֶפֶשׁ הַמֵּת, (שם כה) וְלֹא יִמָּחֶה שְׁמוֹ מִיִּשְׂרָאֵל.</p>\n<p>וְזְהִוּ סוֹד הַגִּלְגּוּל. לַגַּלְגַּל אֵין תְּנוּעָה בְּלִי אַמַּת הַמַּיִם, גַּם כָּךְ אַמַּת הַמַּיִם סוֹד שֶׁל אוֹת ו', בָּהּ נַעֲשֶׂה הַגַּלְגַּל גִּלְגּוּל. וְסוֹד הַדָּבָר - מַה גַּלְגַּל אֵין לוֹ תְּנוּעָה בְּלֹא אַמַּת הַמַּיִם - גַּם כָּךְ גַּלְגַּל הוּא י' וְאֵין לוֹ תְּנוּעָה בְּלִי אַמַּת מַיִם, שֶׁהִיא ו'. יְבָמָה ה'. לָזֶה הוּא בִּינָ\"ה בֶּ\"ן יָ\"הּ. בְּאוֹת י' בָּרָא אֶת הָעוֹלָם הַבָּא, עוֹלָם אָרֹךְ, שֶׁהוּא ו'.</p>\n<p>בִּגְלַל זֶה מִי שֶׁאֵין לוֹ בֵּן אֵינוֹ מִבְּנֵי הָעוֹלָם הַבָּא, שֶׁהַיָּם לְמוּלוֹ, וּמִמֶּנּוּ יָצָא, מִבֵּינֵיהֶם ו', וּמִמֶּנּוּ נֶחֱלָקִים כַּמָּה נְחָלִים שֶׁמְּסוֹבְבִים אֶת הָעוֹלָם, עַד שֶׁחוֹזְרִים לַיָּם שֶׁיָּצְאוּ מִשָּׁם, וּמִשּׁוּם זֶה אָמַר הַפָּסוּק (קהלתא) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא אֶל מְקוֹם שֶׁהַנְּחָלִים וְגוֹ'. עַד שֶׁחוֹזְרִים כְּמוֹ שֶׁיָּצְאוּ.</p>\n<p>גַּם כָּךְ - (שם יב) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. כְּמוֹ שֶׁנָּתַן אוֹתָהּ שְׁלֵמָה אִם תָּשׁוּב בִּתְשׁוּבָה, שֶׁהִיא בִּינָ\"ה, בֶּ\"ן יָ\"הּ, עֶלְיוֹן. אוֹת ה' עוֹלָה בָּאוֹת י' לַחֲמִשִּׁים, עֶשֶׂר פְּעָמִים חָמֵשׁ. הֲרֵי הִיא יָ\"ם, יָ\"הּ. בֵּ\"ן, נַחַל שֶׁיּוֹצֵא מֵהַיָּם וְנֶחֱלָק לְכַמָּה נְחָלִים, כְּמוֹ אִילָן שֶׁמִּתְפַּשֵּׁט לְכַמָּה עֲנָפִים.</p>\n<p>וְאִם לֹא חָזְרָה נְשָׁמָה שְׁלֵמָה כְּמוֹ שֶׁהִשְׁתַּלְּמָה, נֶאֱמַר בָּהּ (שם א) שָׁם הֵם שָׁבִים לָלָכֶת, הִיא וְכָל הַנְּשָׁמוֹת הָאֲחֵרוֹת. גַּם כָּךְ אֵינֶנּוּ שָׁלֵם בְּבֵן אִם אֵין לוֹ בַּת, שֶׁהִיא הָעוֹלָם הַזֶּה, לִהְיוֹת שָׁלֵם בָּעוֹלָם הַזֶּה שֶׁנִּבְרָא בְה'. זֶהוּ שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. (אלא)</p>\n<p>יְה\"וּ, (איוב לג) הֶן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלוֹשׁ עִם גָּבֶר. וְהָרְשָׁעִים שֶׁנֶּאֱמַר בָּהֶם (קהלת ח) וּבְכֵן רָאִיתִי רְשָׁעִים קְבֻרִים וָבָאוּ, גָּרְמוּ (שמות לב) אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל, שֶׁנֶּאֱמַר עֲלֵיהֶם (עמוסב) עַל שְׁלֹשָׁה פִּשְׁעֵי יִשְׂרָאֵל. אַחֲרֵי שֶׁקִּלְקְלוּ עַצְמָם שָׁלֹשׁ פְּעָמִים וְלֹא זָכוּ בְּיה\"ו, שֶׁנֶּאֱמַר בּוֹ (קהלת יא) מְקוֹם שֶׁיִּפּוֹל הָעֵץ שָׁם יְהוּא. (ו) עַל אַרְבָּעָה לֹא אֲשִׁיבֶנּוּ, דְּהַיְנוּ ה'. וְנִדּוֹנוּ בַגֵּיהִנֹּם בְּמַשְׁחִית אַף וְחֵמָה.</p>\n<p>וּלְבוּשִׁים שֶׁל שָׁלֹשׁ אוֹתִיּוֹת הַלָּלוּ נוֹדָעִים בַּקֶּשֶׁת, שֶׁהֵם לָבָן, אָדֹם וְיָרֹק. מִי שֶׁיָּבא בִּזְמַן אֶחָד הוּא לָבָן, בַּשֵּׁנִי אָדם, בַּשְּׁלִישִׁי יָרֹק. וּמִשּׁוּם שֶׁבְּיַעֲקֹב נִכְלְלוּ הָאוֹתִיּוֹת, וְנִשְׁרַשׁ הָאִילָן וְנִנְטַע וְהִתְגַּדֵּל וְנַעֲשָׂה פְרִי טוֹב - (ישעיה כט) לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ, לִהְיוֹת מֶרְכַּבְתּוֹ בַּיֵּצֶר הָרָע, שֶׁהוּא נָחָשׁ וְכָל מִינֵי חַיָּה רָעָה, וּמִשּׁוּם זֶה - (הושע יב) וַיָּשַׂר אֶל מַלְאָךְ וַיּוּכָל. וּמִשּׁוּם שֶׁאָדָם נִקְרָא אִילָן, הוּא סוֹד זֶה לְאִילָן שֶׁנִּנְטַע בְּמָקוֹם שֶׁלֹּא עוֹשֶׂה פְרִי, מֶה עָשָׂה? עָקַר אוֹתוֹ וּנְטָעוֹ בְמָקוֹם אַחֵר. וּמִשּׁוּם זֶה פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, שֶׁלֹּא הָיָה מֻחְזָק לִהְיוֹת עָקָר, עַד שֶׁהָלַךְ לְאֶרֶץ יִשְׂרָאֵל וְנִנְטַע שָׁם בְּאִשָּׁה.</p>\n<p>גַּם כָּךְ צַדִּיק, שֶׁהוּא מִטַּלְטֵל מִמָּקוֹם לְמָקוֹם, מִבַּיִת לְבַיִת, כְּאִלּוּ יָבא בְגִלְגּוּל פְּעָמִים רַבּוֹת, וְהַיְנוּ (שמות כ) וְעֹשֶׂה חֶסֶד לַאֲלָפִים לְאֹהֲבַי (ו), עַד שֶׁיִּזְכֶּה לְעוֹלָם (הבא) שָׁלֵם. אֲבָל לָרְשָׁעִים לֹא מְבִיאִים יוֹתֵר מִשָּׁלֹשׁ פְּעָמִים. וְאִם חָזַר בִּתְשׁוּבָה, נֶאֱמַר בּוֹ גָּלוּת מְכַפֶּרֶת עָון. וּמִשּׁוּם זֶה פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, צַדִּיקִים שׁוּב אֵינָן חוֹזְרִים לַעֲפָרָם.</p>\n<p>אֶלָּא רוֹמֵז, (ויקרא יד) וְעָפָר אַחֵר יִקַּח וְטָח אֶת הַבָּיִת. (איוב לד) וְאָדָם עַל עָפָר יָשׁוּב. (קהלת יב) וְיָשׁוֹב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה. מִשּׁוּם שֶׁהוּא מְנֻגָּע, וְאֵין בּוֹ אֶלָּא אִשָּׁה רָעָה, יֵצֶר הָרָע, שֶׁנֶּאֱמַר בָּהּ אִשָּׁה רָעָה צָרַעַת לְבַעְלָהּ. מַה תַּקָּנָתוֹ? יְגָרְשֶׁנָּה וְיִתְרַפֵּא, שֶׁהִיא גּוֹרֶמֶת (בראשית כג) וַיְגָרֶשׁ אֶת הָאָדָם. הָאָדָם - זוֹ הַנְּשָׁמָה. אֶ\"ת - בַּת זוּג הָאָדָם. (משלי כז) כְּצִפּוֹר נוֹדֶדֶת מִן קִנָּהּ כֵּן אִישׁ נוֹדֵד מִמְּקוֹמוֹ.</p>\n<p>וּמִשּׁוּם זֶה, (תהלים פד) גַּם צִפּוֹר מָצְאָה בַיִת, הַיְנוּ יְבָמָה. וּדְרוֹר קֵן לָהּ, הַיְנוּ גּוֹאֵל. אֲשֶׁר שָׁתָה אֶפְרֹחֶיהָ, בֵּן וּבַת. אַשְׁרֵי מִי שֶׁעוֹשֶׂה (להם) קֵן, (ויקרא כה) וְגָאַל אֶת מִמְכַּר אָחִיו, שֶׁהוּא מָכוּר בַּעֲבוּר מַה שֶּׁלֹּא שֶׁלּוֹ.</p>\n<p>וּמִשּׁוּם זֶה אָמַר מֹשֶׁה, (דברים ג) וַיִּתְעַבֵּר ה' בִּי לְמַעַנְכֶם. כָּאן הוּא סוֹד הָעִבּוּר. רוֹעֶה נֶאֱמָן הִשְׁאִיר שִׁשִּׁים רִבּוֹא, כַּמָּה פְעָמִים שֶׁבָּא בְגִלְגּוּל, וּמִשּׁוּם זֶה זְכוּת כֻּלָּם תָּלָה בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם זֶה פֵּרְשׁוּהָ חֲכָמִים, אִשָּׁה אַחַת יָלְדָה בְמִצְרַיִם שִׁשִּׁים רִבּוֹא בְּכֶרֶס אֶחָד. וְאַף עַל גַּב שֶׁחֲכָמִים פֵּרְשׁוּהָ בִּדְבָרִים אֲחֵרִים - שִׁבְעִים פָּנִים לַתּוֹרָה.</p>\n<p>שֶׁכֵּן דֶּרֶךְ בַּעֲלֵי הַסּוֹדוֹת: אוֹמְרִים מַרְגָּלִית לְתַלְמִידֵיהֶם, וְלֹא נוֹדְעוּ בוֹ בִּרְמִיזָה, חוֹזֵר לָהֶם אוֹתוֹ דָּבָר בִּדְבַר שְׂחוֹק, כְּמוֹ אוֹתוֹ שֶׁאָמַר, בֵּיצָה אַחַת הִפִּילָה שִׁשִּׁים כְּרַכִּים. וּבָאָה בֵיצָה וְנָפְלָה מֵעוֹף שֶׁהָיָה פוֹרֵחַ בָּאֲוִיר וְהִכְּתָה שִׁשִּׁים כְּרַכִּים אֵלּוּ. וּבַעֲלֵי לֵיצָנוּת אָמְרוּ שֶׁלֹּא אָמַר הוּא, רַק שֶׁבֶּן אָדָם כָּתַב שִׁשִּׁים כְּרַכִּים, וּבָאָה בֵיצָה שֶׁיָּצְאָה מֵעוֹף וּמָחֲקָה שִׁשִּׁים כְּרַכִּים שֶׁל כְּתִיבָה. וְחַס וְשָׁלוֹם שֶׁבַּעֲלֵי הַתּוֹרָה אוֹמְרִים דִּבְרֵי שְׂחוֹק וּדְבָרִים בְּטֵלִים בַּתּוֹרָה.</p>\n<p>אֶלָּא כָּךְ פֵּרְשׁוּהָ, (דברים כב) אֶפְרֹחִים - אֵלּוּ בַּעֲלֵי מִשְׁנָה. אוֹ בֵיצִים - אֵלּוּ בַּעֲלֵי מִקְרָא. וּכְמוֹ שֶׁנָּפַל מֵאוֹתוֹ אֶפְרוֹחַ, שֶׁהוּא בַּר נַפְלֵי, נְפִילַת בֵּיצָה שֶׁהוּא אֶתְרוֹג שִׁעוּר שֶׁכַּבֵּיצָה, וּבִגְלָלָהּ נֶאֱמַר (עמוס ט) בַּיּוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִיד הַנֹּפֶלֶת. וְנָפְלוּ עִמָּהּ (שיר ו) שִׁשִּׁים הֵמָּה מְלָכוֹת, שֶׁהֵם כְּרוּכִים בָּהּ, כְּגוֹן כֵּיצַד כּוֹרְכִים אֶת שְׁמַע. וְהֵם כְּנֶגֶד שִׁשִּׁים מַסֶּכְתּוֹת. וַעֲלָמוֹת אֵין מִסְפָּר, אֵלּוּ (תהלים מה) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ, שֶׁהֵן הֲלָכוֹת שֶׁאֵין לָהֶן חֶשְׁבּוֹן.</p>\n<p>וְאוֹתוֹ אֶפְרוֹחַ הוּא בֶּן יָ\"הּ, הוּא בְּתוֹךְ חֲמִשִּׁים שַׁעֲרֵי בִינָ\"ה, דְּהַיְנוּ יָ\"הּ חָמֵשׁ פְּעָמִים עֶשֶׂר, ו' הוּא נִיפּוֹל, שֶׁנָּפַל אַחַר אוֹתָהּ שֶׁנֶּאֱמַר, (ישעיה יד) אֵיךְ נָפַלְתָּ מִשָּׁמַיִם הֵילֵל בֶּן שָׁחַר. וְנִקְרָא נִיפּוֹל, וְלֹא נָפַל, וְלֹא נוֹפֵל. מִשּׁוּם שֶׁבּוֹ נִיפּוֹל יֵשׁ י\"ו, וְיוֹרֵד בָּהֶם לְגַבֵּי ה' ה', שֶׁנֶּאֱמַר בָּהֶן (רות א) וַתֵּלַכְנָה שְׁתֵּיהֶן. זֶהוּ שֶׁכָּתוּב (דברים כב) שַׁלֵּחַ תְּשַׁלַּח. אֶחָד מִבַּיִת רִאשׁוֹן, וְהַשֵּׁנִי מִבַּיִת שֵׁנִי, לַהֲקִימָם. זֶהוּ שֶׁכָּתוּב (תהלים צו) יִ\"שְׂמְחוּ הַ\"שָּׁמַיִם וְ\"תָגֵל הָ\"אָרֶץ.</p>\n<p>בֹּא וּרְאֵה, הַשֶּׁמֶשׁ הַזֶּה מִתְגַּלֶּה בַיּוֹם, וּמִתְכַּסֶּה בַלַּיְלָה, וּמֵאִיר בְּשִׁשִּׁים רִבּוֹא כּוֹכָבִים. גַּם כָּךְ רוֹעֶה הַנֶּאֱמָן, כְּשֶׁהִתְכַּנֵּס מֵהָעוֹלָם, מֵאִיר בְּשִׁשִּׁים רִבּוֹא נִשְׁמוֹת יִשְׂרָאֵל, אִם הַדּוֹר כָּרָאוּי. וְזֶה סוֹד הַגִּלְגּוּל שֶׁאָמַר עָלָיו קֹהֶלֶת (קהלת א) דּוֹר הֹלֵךְ וְדוֹר בָּא. וּפֵרְשׁוּהָ שֶׁאֵין דּוֹר פָּחוֹת מִשִּׁשִּׁים רִבּוֹא. וְהָאָרֶץ לְעוֹלָם עֹמָדֶת - זוֹ כְּנֶסֶת יִשְׂרָאֵל, אוֹתָהּ שֶׁנֶּאֱמַר בָּהּ (ישעיה סו) וְהָאָרֶץ הֲדם רַגְלָי, (בראשית כח) וְהָיָה זַרְעֲךְ כַּעֲפַר הָאָרֶץ.</p>\n<p>וְעוֹד סוֹד אַחֵר בֵּאֲרוּ הַחֲכָמִים, הַדּוֹר שֶׁהוֹלֵךְ הוּא הַדּוֹר שֶׁבָּא. הָלַךְ חִגֵּר בָּא חִגֵּר, הָלַךְ סוּמָא בָּא סוּמָא. וְעוֹד פֵּרְשׁוּהָ חֲכָמִים, שֶׁעָתִיד הָיָה מֹשֶׁה לְקַבֵּל תּוֹרָה בְּדוֹר הַמַּבּוּל, אֶלָּא מִשּׁוּם שֶׁהָיוּ רְשָׁעִים, זֶהוּ שֶׁכָּתוּב (שם ו) בְּשַׁגַּ\"ם הוּא בָשָׂר. בְּשַׁגַּ\"ם זֶה מֹשֶׁ\"ה. וְלָמָּה קָרָא לוֹ בְּשַׁגַּ\"ם? אֶלָּא קֹהֶלֶת חִסֵּר ב' מִבְּשַׁגַּ\"ם לְכַסּוֹת הַדָּבָר. אָמַר, (קהלת ח) אָמַרְתִּי שֶׁגַּם זֶה הָבֶל.</p>\n<p>וּפֵרְשׁוּהָ עַל יִתְרוֹ, לָמָּה נִקְרָא שְׁמוֹ קֵינִי? שֶׁנִּפְרַד מִקַּיִן. קָם מְנוֹרָה הַקְּדוֹשָׁה וְאָמַר, עַל זֶה כָּתוּב (בראשית ד) קָנִיתִי אִישׁ אֶת יְהֹוָ\"ה. שֶׁרָאֲתָה אוֹתוֹ בְּרוּחַ הַקֹּדֶשׁ שֶׁעֲתִידִים בָּנָיו לָשֶׁבֶת בְּלִשְׁכַּת הַגָּזִית.</p>\n<p>וְגַם כָּךְ רַבִּי אִלעָזָר בִּן פְּדָת, שֶׁהָיְתָה דְחוּקָה לוֹ הַשָּׁעָה, שֶׁלֹּא הָיָה לוֹ אֶלָּא קַב חָרוּבִים מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת, כְּמוֹ לְרַבִּי חֲנִינָא. לָמָּה זֶה? לְאַחַר שֶׁיָּצְאָה בַּת קוֹל וְאוֹמֶרֶת: כָּל הָעוֹלָם כֻּלּוֹ אֵינוֹ נִזּוֹן אֶלָּא בִּשְׁבִיל חֲנִינָא בְּנִי.</p>\n<p>אֶלָּא הוּא גָּרַם קֹדֶם שֶׁהֶחֱרִיב קַ\"ב מִן י', שֶׁהוּא יַבֹּ\"ק. גַּם כָּךְ לֹא הָיָה לוֹ אֶלָּא קַב חָרוּבִים, שֶׁאוֹת י' הִיא יִחוּד, וּמִמֶּנָּה בָּאָה נְבִיעָה לָאוֹת ב', שֶׁהִיא בְּרָכָה, וְהִיא קֹדֶשׁ, וּמִמֶּנָּה מִתְקַדֵּשׁ ק, שֶׁהִיא קֹדֶשׁ. וְרַבִּי אֶלְעָזָר בֶּן פְּדָת גָּרַם לִהְיוֹת חָרוּבִים שֶׁלּוֹ קַ\"ב, שֶׁהֵם קְ\"דֻשָּׁה בְּ\"רָכָה. גַּם כָּךְ לֹא הָיָה לוֹ אֶלָּא קַב חָרוּבִים. גַּם כָּךְ אִיּוֹב בֶּן יְבָמָה הָיָה, וּמִשּׁוּם זֶה נֶעֱנַשׁ עַל מַה שֶּׁכְּבָר אֵרַע לוֹ.</p>"],[9522012454,"<p>וְהֵם שֶׁלֹּא יָדְעוּ סוֹד זֶה, אָמְרוּ, בָּנִים חַיִּים וּמְזוֹנוֹת לֹא בִזְכוּת תָּלוּי הַדָּבָר, אֶלָּא בְּמַזָּל תָּלוּי הַדָּבָר. הֲרֵי רָאִינוּ אֶת אַבְרָהָם שֶׁרָאָה בְמַזָּלוֹ שֶׁלֹּא הָיָה עָתִיד לִהְיוֹת לוֹ בֵּן, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹצִיאוֹ הַחוּצָה, כְּמוֹ שֶׁכָּתוּב (שם טו) וַיּוֹצֵא אֹתוֹ הַחוּצָה וַיֹּאמֶר הַבֶּט וְגוֹ'. וּפֵרְשׁוּהָ שֶׁאָמַר לוֹ: צֵא מֵאִצְטַגְנִינוּת שֶׁלְּךְ, וְהֶעֱלָהוּ לְמַעְלָה מֵהַכּוֹכָבִים, וְאָמַר לוֹ: הַבֶּט נָא הַשָּׁמַיְמָה וּסְפֹר הַכּוֹכָבִים. עַד כָּאן דִּבְרֵי רַבּוֹתֵינוּ, וְצָרִיךְ לְפָרֵשׁ אוֹתָם בְּדֶרֶךְ נִסְתָּר.</p>\n<p>בֹּא וּרְאֵה, כָּל בְּרִיּוֹת הָעוֹלָם, קֹדֶם שֶׁנִּתְּנָה הַתּוֹרָה לְיִשְׂרָאֵל הָיוּ תְלוּיִים בְּמַזָּל, וַאֲפִלּוּ בָּנִים חַיִּים וּמְזוֹנוֹת. אֲבָל אַחַר שֶׁנִּתְּנָה תוֹרָה לְיִשְׂרָאֵל, הוֹצִיא אוֹתָם מֵחִיּוּב כּוֹכָבִים וּמַזָּלוֹת, וְזֶה לָמַדְנוּ מֵאַבְרָהָם, מִשּׁוּם שֶׁהָיוּ בָנָיו עֲתִידִים לְקַבֵּל ה' מֵאַבְרָהָם, שֶׁהִיא חֲמִשָּׁה חֻמְשֵׁי תוֹרָה, שֶׁנֶּאֱמַר בָּהּ (שם ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. אָמַר לְאַבְרָהָם: בִּגְלַל הַה' הַזּוֹ שֶׁנּוֹסְפָה לְשִׁמְךְ, הַשָּׁמַיִם תַּחְתֶּיךְ וְכָל הַכּוֹכָבִים וְהַמַּזָּלוֹת שֶׁמְּאִירִים בַּה'. וְלֹא עוֹד, אֶלָּא שֶׁנֶּאֱמַר בָּהּ (שם מז) הֵ\"א לָכֶם זֶרַע. וּזְרַעְתֶּם בְּהֵ\"א. (שם כא) כִּי בְיִצְחָק יִקָּרֵא לְךְ זָרַע.</p>\n<p>וּמִשּׁוּם זֶה, כָּל הַמִּשְׁתַּדֵּל בַּתּוֹרָה בִּטֵּל מִמֶּנּוּ חִיּוּב כּוֹכָבִים וּמַזָּלוֹת, אִם לוֹמֵד אוֹתָהּ כְּדֵי לְקַיֵּם מִצְווֹתֶיהָ. וְאִם לֹא - כְּאִלּוּ לֹא הִשְׁתַּדֵּל בָּהּ, וְלֹא בִטֵּל מִמֶּנּוּ חִיּוּב כּוֹכָבִים וּמַזָּלוֹת. כָּל שֶׁכֵּן עַמֵּי הָאָרֶץ שֶׁנִּמְשְׁלוּ לִבְהֵמוֹת, שֶׁבֵּאֲרוּ עֲלֵיהֶם (דברים כז) אָרוּר שֹׁכֵב עִם כָּל בְּהֵמָה, שֶׁלֹּא הִתְבַּטְּלוּ מֵהֶם חִיּוּב שֶׁל כּוֹכָבִים וּמַזָּלוֹת.</p>\n<p>אֱנוֹשׁ כֶּחָצִיר יָמָיו כְּצִיץ הַשָּׂדֶה כֵּן יָצִיץ (תהלים קג). וְנֶאֱמַר בּוֹ (שם לז) נַעַר הָיִיתִי גַּם זָקַנְתִּי. אַחַר כָּךְ (איובלג) יָשׁוּב לִימֵי עֲלוּמָיו. שֶׁאִילָן שֶׁנִּקְצְצוּ עֲנָפִים עַתִּיקִים שֶׁלּוֹ וְצָמְחוּ כְּמוֹ מִקֹּדֶם בְּשָׁרָשָׁיו, חָזְרוּ בָעוֹלָם כְּמִקֹּדֶם. מֵתוּ זְקֵנִים, וְחָזְרוּ לָעוֹלָם הַזֶּה עֲלָמִים. וְזֶהוּ סוֹד שֶׁמְּחַדֵּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל יוֹם תָּמִיד מַעֲשֵׂה בְרֵאשִׁית, שֶׁמֵּתִים אֶלֶף בְּכָל יוֹם, וּמִתְחַדְּשִׁים אֶלֶף בְּכָל יוֹם.</p>"],[9522012455,"<p>וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ (תהלים קד) - זֶה יֵין הַתּוֹרָה. שֶׁכָּךְ עוֹלֶה יַיִן, כְּחֶשְׁבּוֹן סוֹ\"ד. וּמַה יַּיִ\"ן צָרִיךְ לִהְיוֹת סָתוּם וְחָתוּם שֶׁלֹּא יִתְנַסֵּךְ לַעֲבוֹדָה זָרָה, גַּם כָּךְ צָרִיךְ לִהְיוֹת סָתוּם וְחָתוּם סוֹד הַתּוֹרָה, וְכָל סוֹדוֹתֶיהָ, וְלֹא מַשְׁקִים אוֹתָם, רַק לִירֵאָיו. וְלֹא לְחִנָּם עוֹשִׂים כַּמָּה מִצְווֹת בַּיַּיִן וּמְבָרְכִים בּוֹ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. וְלַיַּיִן יֵשׁ שְׁנֵי גְוָנִים - לָבָן וְאָדם, דִּין וְרַחֲמִים, וְהַיְנוּ ב' תּוֹסֶפֶת בַּיַּיִן. כְּמוֹ שׁוֹשַׁנָּה לְבָנָה וַאֲדֻמָּה. לָבָן מִצַּד יָמִין, אָדם מִצַּד שְׂמֹאל.</p>\n<p>וּמַה זֶּה לְבַב אֱנוֹשׁ? לֵב הָיָה לוֹ לוֹמַר! אֶלָּא שֶׁיֵּשׁ לֵב מָסוּר לְלֵב, וְהֵם ל\"ב אֱלֹהִים שֶׁל מַעֲשֵׂה בְרֵאשִׁית, ב' מִבְּרֵאשִׁית, ל' מִלְּעֵינֵי כָּל יִשְׂרָאֵל. זֶהוּ ל\"ב שֵׁנִי. זֶה ל\"ב ל\"ב (הם) שְׁנַיִם - ס\"ד, חָסֵר שְׁמוֹנֶה לְע\"ב, שֶׁהוּא וַיְכֻלּוּ. הֵם שִׁבְעָה יְמֵי בְרֵאשִׁית. שְׁמִינִי מַהוּ? שִׁבְעָה יְמֵי בְרֵאשִׁית עִם (בראשית ה) זֶה סֵפֶר תּוֹלְדת אָדָם. זֶה ע\"ב בְּחֶשְׁבּוֹן בְּיַיִן.</p>\n<p>מַה זֶּה לְהַצְהִיל פָּנִים מִשָּׁמֶן? אֵלּוּ שְׁנֵים עָשָׂר פָּנִים - אַרְבָּעָה שֶׁל אַרְיֵה, אַרְבָּעָה שֶׁל שׁוֹר אַרְבָּעָה שֶׁל נֶשֶׁר, שֶׁהֵם: מִיכָאֵל אַרְיֵה, אַרְבַּע פָּנִים שֶׁלּוֹ יֶהֹוֶ\"ה. אַרְבַּע פְּנֵי שׁוֹר, וְהוּא גַּבְרִיאֵל, וְהֵם יַהֹוַ\"ה. אַרְבַּע פְּנֵי נֶשֶׁר, וְהוּא נוּרִיאֵל, וְהֵם יִהֹוְ\"ה. וְהֵם מְמֻנִּים תַּחַת חֶסֶ\"ד פַּחַ\"ד אֱמֶ\"ת, דַּרְגוֹת שְׁלֹשֶׁת הָאָבוֹת. וּפֵרְשׁוּהָ רַבּוֹתֵינוּ, הָאָבוֹת הֵן הֵן הַמֶּרְכָּבָה. וְעוֹלִים (נקודים) הָאוֹרוֹת לְחֶשְׁבּוֹן יַבֹּ\"ק. וְהֵם מֶלֶךְ מַלַךְ יִמְלֹךְ, יְהֹוָ\"ה אֶהְיֶ\"ה אֲדנָ\"י. סַךְ הַכֹּל - יַבֹּ\"ק.</p>\n<p>רַבִּי שִׁמְעוֹן הָיָה יוֹשֵׁב וְעוֹסֵק בְּפָרָשָׁה זוֹ, בָּא לְפָנָיו רַבִּי אֶלְעָזָר בְּנוֹ. אָמַר לוֹ, נָדָב וַאֲבִיהוּא מָה עוֹשִׂים בְּפִנְחָס? אִם פִּנְחָס לֹא הָיָה בָּעוֹלָם כְּשֶׁמֵּתוּ, וְאַחַר כָּךְ בָּא לָעוֹלָם וְהִשְׁלִים מְקוֹמָם - אָז יָפֶה. אֲבָל פִּנְחָס הָיָה בָּעוֹלָם, (וסגן היה) וְנִשְׁמָתוֹ בּוֹ בְּקִיּוּם עוֹמֶדֶת.</p>\n<p>אָמַר לוֹ, בְּנִי, סוֹד עֶלְיוֹן כָּאן, וְכָךְ הוּא. שֶׁבְּשָׁעָה שֶׁהִסְתַּלְּקוּ מִן הָעוֹלָם, לֹא הָיוּ נִסְתָּרִים תַּחַת כַּנְפֵי הַסֶּלַע הַקָּדוֹשׁ. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (במדבר ג) וּבָנִים לֹא הָיוּ לָהֶם. שֶׁהִקְטִינוּ דְמוּת הַמֶּלֶךְ, שֶׁהֲרֵי הֵם לֹא רְאוּיִים לְשַׁמֵּשׁ בִּכְהֻנָּה גְדוֹלָה.</p>\n<p>בְּשָׁעָה שֶׁקִּנֵּא פִנְחָס עַל הַבְּרִית הַקָּדוֹשׁ וְנִכְנַס בְּתוֹךְ כַּמָּה אוּכְלוּסִין וֶהֱרִימָם עַל הָרֹמַח לְעֵינֵי כָּל יִשְׂרָאֵל, כְּשֶׁרָאָה שֵׁבֶט שִׁמְעוֹן, בָּאוּ אֵלָיו בְּכַמָּה אוּכְלוּסִין. פָּרְחָה מִמֶּנּוּ נִשְׁמָתוֹ, וּשְׁתֵּי נְשָׁמוֹת שֶׁהָיוּ מְעֻרְטָלוֹת בְּלִי מָקוֹם קָרְבוּ אֵלֶיהָ, וְנִכְלְלוּ כְאַחַת, וְחָזְרָה נִשְׁמָתוֹ כְּלוּלַת רוּחַ, שֶׁנִּכְלְלָה בִּשְׁתֵּי רוּחוֹת, וְהִתְחַזְּקוּ בָהּ, וְאָז הִרְוִיחַ מְקוֹמָם לִהְיוֹת כֹּהֵן (גדול), מַה שֶּׁלֹּא (היה ראוי) מִקֹּדֶם.</p>\n<p>וְלָכֵן כָּתוּב, (איובד) זְכָר-נָא מִי הוּא נָקִי אָבָד, שֶׁלֹּא אָבַד בְּאוֹתָהּ שָׁעָה, וְלֹא אָבְדָה רוּחַ כְּשֶׁפָּרְחָה מִמֶּנּוּ. וְאֵיפֹה יְשָׁרִים נִכְחָדוּ - אֵלּוּ בְּנֵי אַהֲרֹן שֶׁחָזְרוּ לָעוֹלָם, מַה שֶּׁאָבַד בְחַיֵּיהֶם. וְלָכֵן כָּתוּב בּוֹ בְּפִנְחָס בֶּן בֶּן פַּעֲמַיִם, פִּנְחָס בֶּן אֶלְעָזָר בֶּן.</p>\n<p>מַה כָּתוּב לְמַעְלָה מִפָּרָשָׁה זוֹ? (במדבר כה) וַיֹּאמֶר ה' אֶל מֹשֶׁה קַח אֶת כָּל רָאשֵׁי הָעָם וְהוֹקַע אוֹתָם לַה' נֶגֶד הַשָּׁמֶשׁ. וְכִי עַל שֶׁהָרְגוּ בַלַּיְלָה, אוֹ עַל שֶׁהָרְגוּ בַיּוֹם, בְּיוֹם מְעֻנָּן, כָּתוּבּ נֶגֶד הַשָּׁמֶשׁ? אָמַר רַבִּי יְהוּדָה, שֶׁתִּהְיֶה מִיתָתָם בְּגָלוּי כְּמוֹ שֶׁחָטְאוּ בְגָלוּי.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, לֹא בִּגְלַל זֶה נֶאֱמַר, אֶלָּא מִכָּאן לָמַדְנוּ, בְּדַרְגָּה שֶׁחָטָא אָדָם לַקָּדוֹשׁ-בָּרוּךְ-הוּא, לְאוֹתוֹ מָקוֹם יֵשׁ לַעֲשׂוֹת תַּקָּנָה לְנַפְשׁוֹ. הֵם חָטְאוּ בִּבְרִית קֹדֶשׁ שֶׁנִּקְרֵאת שֶׁמֶשׁ, בִּגְלַל כָּךְ דִּין וְתִקּוּן שֶׁלָּהֶם הוּא כְּנֶגֶד הַשָּׁמֶשׁ, וְלֹא בְמָקוֹם אַחֵר. מִכָּאן שֶׁלֹּא צָרִיךְ אָדָם לְתַקֵּן נַפְשׁוֹ אֶלָּא בְּאוֹתוֹ מָקוֹם שֶׁחָטָא אֵלָיו, וּמִי שֶׁלֹּא יַעֲשֶׂה כָּךְ, אֵין לוֹ תִּקּוּן לְעוֹלָמִים כָּרָאוּי.</p>\n<p>רַבִּי חִיָּיא פָּתַח, (תהלים קד) יִשְׂבְּעוּ עֲצֵי ה' אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע. מַה כָּתוּב לְמַעְלָה? וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ וְגוֹ'. וְכִי מַה זֶּה לָזֶה? אֶלָּא כָּךְ לָמַדְנוּ, שֶׁכָּתוּב מַצְמִיחַ חָצִיר לַבְּהֵמָה וְגוֹ' - וְכִי שֶׁבַח לַבְּהֵמָה שֶׁיֵּשׁ לָהּ חָצִיר, בָּא דָוִד לוֹמַר בְּרוּחַ הַקֹּדֶשׁ? אֶלָּא מַצְמִיחַ חָצִיר - אֵלֶּה הֵם שִׁשִּׁים אֶלֶף רִבּוֹא שֶׁל מַלְאָכִים, שְׁלִיחִים, שֶׁנִּבְרְאוּ בַּיּוֹם הַשֵּׁנִי שֶׁל בְּרֵאשִׁית, וְכֻלָּם אֵשׁ לוֹהֶטֶת. אֵלֶּה הֵם חָצִיר. לָמָּה חָצִיר? מִשּׁוּם שֶׁצּוֹמְחִים כְּחָצִיר זֶה בָּעוֹלָם, שֶׁכָּל יוֹם וָיוֹם נִקְצְרוּ כָּעֵת, וְאַחַר כָּךְ צוֹמְחִים וְחוֹזְרִים כְּמִקֹּדֶם.</p>\n<p>וְלָכֵן כָּתוּב מַצְמִיחַ חָצִיר לַבְּהֵמָה, זֶהוּ שֶׁכָּתוּב (משלי יב) יוֹדֵעַ צַדִּיק נֶפֶשׁ בְּהֶמְתּוֹ. וְשָׁנִינוּ, אֶלֶף הָרִים מַעֲלִים לָהּ בְּכָל יוֹם וָיוֹם, וּבְכָל הַר וְהַר יֵשׁ שִׁשִּׁים רִבּוֹא, וְהִיא אוֹכֶלֶת.</p>\n<p>וְעֵשֶׂב לַעֲבדַת הָאָדָם - אֵלּוּ אוֹתָם נִשְׁמוֹת הַצַּדִּיקִים, שֶׁאוֹתוֹ אָדָם שֶׁרוֹכֵב וְשׁוֹלֵט עַל בְּהֵמָה זוֹ אוֹכֵל וּמַכְנִיסָם בְּתוֹכוֹ, וּבִזְכוּתָם נִזּוֹן כָּל הָעוֹלָם מֵאוֹתוֹ אָדָם, שֶׁכָּתוּב בּוֹ (יחזקאל א) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם וְגוֹ'. וְעַל זֶה כָּתוּב הָאָדָם, אוֹתוֹ שֶׁנּוֹדָע, כְּדֵי לְהוֹצִיא לֶחֶם מִן הָאָרֶץ, לְהוֹצִיא מָזוֹן לָעוֹלָם מֵהָאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>וְיַיִן - זֶה יַיִן עַתִּיק שֶׁשּׁוֹפֵעַ מִלְמַעְלָה. יְשַׂמַּח לְבַב אֱנוֹשׁ - אֱנוֹשׁ זֶה סוֹד שֶׁל אוֹתוֹ נַעַר שֶׁעָלָה לְשֵׂיבָה וְחָזַר כְּמִקֹּדֶם. וְעַל זֶה כָּתוּב (תהלים קג) אֱנוֹשׁ כֶּחָצִיר יָמָיו.</p>\n<p>לְהַצְהִיל פָּנִים - אֵלּוּ אוֹתָם פָּנִים שֶׁנִּקְרָאִים פָּנִים גְּדוֹלוֹת וּפָנִים קְטַנּוֹת. מִשָּׁמֶן, מִשֶּׁפַע הָעוֹלָם הַבָּא, שֶׁמֶן וּמִשְׁחָה קָדוֹשׁ עֶלְיוֹן. וְלֶחֶם לְבַב אֱנוֹשׁ יִסְעָד - אוֹתוֹ לֶחֶם שֶׁמַּזִּילִים הַשְּׁחָקִים, וְטוֹחֲנִים מָן לְמַאֲכָל שֶׁל צַדִּיקִים סְתָם, וּמִשָּׁם שׁוֹפֵעַ לְכַמָּה חֲיָלוֹת שֶׁנִּקְרָאִים לְבַב אֱנוֹשׁ, וְהַכֹּל בָּא מִשֶּׁפַע עֶלְיוֹן.</p>\n<p>יִשְׂבְּעוּ עֲצֵי ה' - אֵלּוּ אוֹתָם עֵצִים עֶלְיוֹנִים פְּנִימִיִּים. אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע, שֶׁהֲרֵי נֶעֶקְרוּ וּנְטָעָם הַקָּדוֹשׁ בָּרוּךְ הוּא. מַה בֵּין עֲצֵי ה' לְאַרְזֵי לְבָנוֹן? עֲצֵי ה' - אֵלּוּ עֵץ הַחַיִּים וְעֵץ הַדַּעַת טוֹב וָרָע. אַרְזֵי לְבָנוֹן - אֵלּוּ חֲמִשִּׁים שְׁעָרִים שֶׁנִּקְרָאִים חֲמֵשׁ מֵאוֹת שָׁנָה.</p>\n<p>אֲשֶׁר נָטָע. אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ, בְּצִלָּם מְקַנְּנוֹת נִשְׁמוֹת הַצַּדִּיקִים, וְכָל חֵילוֹת הַקֹּדֶשׁ נִזּוֹנִים מִשָּׁם. חֲסִידָה - בִּתּוֹ שֶׁל אַבְרָהָם אָבִינוּ, שֶׁנִּקְרָא חָסִיד, וְעָשָׂה חֶסֶד עִם כָּל בְּנֵי הָעוֹלָם, בִּגְלַל זֶה נִקְרֵאת חֲסִידָה. בְּרוֹשִׁים בֵּיתָהּ, בֵּין זְרוֹעוֹת עוֹלָם יוֹשֶׁבֶת.</p>"],[9522012456,"<p>רַבִּי אַבָּא וְרַבִּי יוֹסֵי קָמוּ לַעֲסֹק בַּתּוֹרָה בַּחֲצוֹת הַלַּיְלָה. עַד שֶׁיָּשְׁבוּ וְעָסְקוּ בַתּוֹרָה אָמַר רַבִּי יוֹסֵי, זֶה שֶׁאָמַר רַבִּי חִיָּיא (תהלים קג) אֱנוֹשׁ כֶּחָצִיר יָמָיו - יָפֶה אָמַר. אֲבָל בַּמֶּה בֵּאַרְנוּ סוֹף הַפָּסוּק - כִּי רוּחַ עָבְרָה בּוֹ וְאֵינֶנּוּ וְלֹא יַכִּירֶנּוּ עוֹד מְקוֹמוֹ. אָמַר לוֹ, כָּךְ הוּא בְּוַדַּאי, אֱנוֹשׁ כֶּחָצִיר יָמָיו כְּמוֹ שֶׁאָמַר. כְּצִיץ הַשָּׂדֶה - כְּצִיץ אוֹתוֹ שָׂדֶה הַנּוֹדָע - כֵּן יָצִיץ, שֶׁהִתְחַדֵּשׁ וְחָזַר כְּמִקֹּדֶם. (כך יציץ ועולה. מה הטעם, ' משום)</p>\n<p>כִּי רוּחַ עָבְרָה בּוֹ וְאֵינֶנּוּ - זֶה רוּחַ עֶלְיוֹן טָמִיר קָדוֹשׁ גָּנוּז מֵהַכֹּל, שֶׁכּוֹלֵל אוֹתוֹ בְּתוֹכוֹ, וְאָז אֵינֶנּוּ. וְזֶהוּ סוֹד שֶׁל חֲנוֹךְ, שֶׁכָּתוּב בּוֹ (בראשית ה) וְאֵינֶנּוּ כִּי לָקַח אֹתוֹ אֱלֹהִים, זֶה אֱלֹהִים עֶלְיוֹן. רוּחַ עֶלְיוֹנָה, רוּחַ גְּנוּזָה וּטְמִירָה. וְלֹא יַכִּירֶנּוּ עוֹד מְקוֹמוֹ, שֶׁהֲרֵי נִכְלֶלֶת רוּחַ קְטַנָּה בְּרוּחַ עֶלְיוֹנָה. מַה כָּתוּב אַחֲרָיו? וְחֶסֶד ה' מֵעוֹלָם וְעַד עוֹלָם. וְנִכְנָס לוֹ כֹּהֵן גָּדוֹל לְתוֹךְ קֹדֶשׁ הַקְּדָשִׁים, וְלוֹקְחוֹ וּמוֹלִידוֹ כְּמִקֹּדֶם, וּמִתְחַדֵּשׁ כַּנֶּשֶׁר עֲלוּמָיו, וְחוֹזֵר הוּא נַעַר.</p>\n<p>וּבְחִבּוּר רִאשׁוֹן אָמַר הָרוֹעֶה הַנֶּאֱמָן, מְנוֹרָה הַקְּדוֹשָׁה, יָפֶה אָמְרוּ רַבִּי אַבָּא וְרַבִּי חִיָּיא וְרַבִּי יוֹסֵי, אֲבָל (תהלים קג) כִּי רוּחַ עָבְרָה בּוֹ וְאֵינֶנּוּ - כָּאן צָרִיךְ לִפְתֹּחַ בִּדְבָרִים, מַה זֶּה עָבְרָה בּוֹ? זוֹ עֶבְרָה וְזַעַם וְצָרָה, אֶחָד מֵאוֹתָם מַלְאָכִים רָעִים.</p>\n<p>שֶׁמִשּׁוּם שֶׁלֹּא יָדְעוּ בּוֹ אוֹתָם בַּעֲלֵי חֲטָאִים, צָרִיךְ לַעֲשׂוֹת לוֹ שִׁנּוּי מָקוֹם וְשִׁנּוּי הַשֵּׁם וְשִׁנּוּי מַעֲשֶׂה, כְּמוֹ אַבְרָהָם, שֶׁנֶּאֱמַר בּוֹ (בראשית יב) לֶךְ לְךְ מֵאַרְצְךְ וּמִמּוֹלַדְתְּךְ - הֲרֵי שִׁנּוּי מָקוֹם. (שם יז) וְלֹא יִקָּרֵא עוֹד אֶת שִׁמְךְ אַבְרָם וְהָיָה שִׁמְךְ אַבְרָהָם - הֲרֵי שִׁנּוּי הַשֵּׁם. שִׁנּוּי מַעֲשֶׂה - שֶׁהִשְׁתַּנָּה מִמַּעֲשִׂים רָעִים שֶׁעָשָׂה בַתְּחִלָּה לְמַעֲשִׂים טוֹבִים. הוּא מָשָׁל לְרוּחַ שֶׁל אוֹתוֹ שֶׁמֵּת בְּלֹא בָנִים. כְּמוֹ זֶה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם כְּשֶׁגֵּרַשׁ אוֹתוֹ מֵאוֹתוֹ עוֹלָם, וֶהֱבִיאוֹ לָעוֹלָם הַזֶּה, וַהֲרֵי נִתְבָּאֵר לְמַעְלָה.</p>\n<p>מְשַׁנֶּה פָּנָיו וַתְּשַׁלְּחֵהוּ (איוב יד). וּמִשּׁוּם זֶה כִּי רוּחַ עָבְרָה בּוֹ. אֶחָד מֵאוֹתָם מַלְאָכִים רָעִים, כְּשֶׁרוֹאֶה אוֹתוֹ מְשֻׁנֶּה בִּזְמַן שֶׁנִּפְגָּשׁ (בו) עִמּוֹ, שׁוֹאֲלִים אוֹתוֹ שְׁאָר הַמַּשְׁחִיתִים עָלָיו: זֶהוּ בַּעַל חוֹבְךְ? הוּא עוֹנֶה לָהֶם וְאוֹמֵר: אֵינֶנּוּ.</p>\n<p>כְּשֶׁמִּתְגָּרֵשׁ מִמְּקוֹמוֹ וְנִנְטָע בְּמָקוֹם אַחֵר, נֶאֱמַר בּוֹ וְלֹא יַכִּירֶנּוּ עוֹד מְקוֹמוֹ, בִּגְלַל (ויקרא יד) שֶׁעָפָר אַחֵר יִקַּח וְטָח אֶת הַבָּיִת. וְזֶהוּ סוֹד וְנָתַץ אֶת הַבַּיִת אֶת אֲבָנָיו וְאֶת עֵצָיו - אוֹתָם עֲצָמוֹת וְגִידִים וּבָשָׂר שֶׁהָיָה, חָזַר לְעָפָר. מַה כָּתוּב בּוֹ? (ישעיה סה) וְנָחָשׁ עָפָר לַחְמוֹ, מִשּׁוּם שֶׁהָיָה מְנֻגָּע. וְאַחַר כָּךְ, וְעָפָר אַחֵר יִקַּח וְטָח אֶת הַבָּיִת, וּבוֹנֶה לוֹ עֲצָמוֹת וְגִידִים וּמִתְחַדֵּשׁ, כְּמוֹ בַּיִת יָשָׁן שֶׁעוֹשִׂים אוֹתוֹ חָדָשׁ, וַדַּאי שֶׁהוּא מִתְחַדֵּשׁ.</p>\n<p>וּמַה שֶּׁאָמַר וְלֹא יַכִּירֶנּוּ עוֹד מְקוֹמוֹ - עַל רוּחַ, שֶׁנִּכְלְלָה רוּחַ קְטַנָּה בְּרוּחַ עֶלְיוֹנָה. זֶהוּ מָשָׁל לְאִילָן שֶׁלֹּא עוֹשֶׂה פֵרוֹת, לוֹקְחִים עֲנָפִים שֶׁלּוֹ וּמַרְכִּיבִים אוֹתוֹ בְּעָנָף שֶׁל עֵץ אַחֵר עֶלְיוֹן (זהבזה) שֶׁעוֹשֶׂה פֵרוֹת, וְנִכְלָל זֶה בָּזֶה וְעוֹשֶׂה פֵרוֹת. בְּאוֹתוֹ זְמַן נֶאֱמַר בּוֹ, וְלֹא יַכִּירֶנּוּ עוֹד מְקוֹמוֹ.</p>\n<p>גַּם כָּךְ בֶּן אָדָם שֶׁיּוֹשֵׁב בְּעִיר שֶׁיּוֹשְׁבִים בָּהּ אֲנָשִׁים רָעִים, וְלֹא יָכוֹל לְקַיֵּם מִצְווֹת הַתּוֹרָה וְלֹא מַצְלִיחַ בַּתּוֹרָה - עוֹשֶׂה שִׁנּוּי מָקוֹם וְנֶעֱקָר מִשָּׁם, וְנִשְׁרָשׁ בְּמָקוֹם שֶׁגָּרִים בּוֹ אֲנָשִׁים טוֹבִים, בַּעֲלֵי תוֹרָה, בַּעֲלֵי מִצְווֹת. שֶׁהַתּוֹרָה נִקְרֵאת עֵץ, זֶהוּ שֶׁכָּתוּב (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וְהָאָדָם הוּא עֵץ, שֶׁכָּתוּב (דברים כ) כִּי הָאָדָם עֵץ הַשָּׂדֶה. וְהַמִּצְווֹת שֶׁבָּהּ דּוֹמוֹת לִפְרִי. וּמַה כָּתוּב בּוֹ? רַק עֵץ אֲשֶׁר תֵּדַע כִּי לֹא עֵץ מַאֲכָל הוּא אֹתוֹ תַשְׁחִית וְכָרָתָּ. אֹתוֹ תַשְׁחִית - מֵהָעוֹלָם הַזֶּה. וְכָרָתָּ - מֵהָעוֹלָם הַבָּא. וְלָכֵן צָרִיךְ לַעֲקֹר (אותו מאותו) מֵאוֹתוֹ מָקוֹם, וְיִנָּטַע בְּמָקוֹם אַחֵר בֵּין צַדִּיקִים.</p>\n<p>מָה אָדָם בְּלִי בָנִים נִקְרָא עָקָר וְאִשְׁתּוֹ עֲקָרָה, גַּם כָּךְ תּוֹרָה בְּלִי מִצְווֹת נִקְרֵאת עֲקָרָה. וְלָכֵן פֵּרְשׁוּהָ, לֹא הַמִּדְרָשׁ הוּא עִקָּר אֶלָּא הַמַּעֲשֶׂה. בָּאוּ הַחֲבֵרִים וְהִשְׁתַּטְּחוּ לְפָנָיו וְאָמְרוּ, כָּעֵת לָמַדְנוּ חִדּוּשׁ אֵיךְ נִכְלֶלֶת רוּחַ בְּרוּחַ, כְּמִי שֶׁרָאָה דָבָר בָּעַיִן וְהֻבְרַר לוֹ. מִקֹּדֶם זֶה הָיָה קַבָּלָה לָנוּ, וְכָעֵת בֵּרוּר הַדָּבָר.</p>"],[9522012457,"<p>וְעוֹד נֶאֱמַר בְּחִבּוּר רִאשׁוֹן, שֶׁהֲרֵי נוֹחַ לוֹ לַסִּטְרָא אַחֲרָא לִשְׁלֹט עַל הַצַּדִּיק יוֹתֵר מֵהַכֹּל, וְלֹא חוֹשֵׁשׁ אָז לְכָל הָעוֹלָם. בֵּין כָּךְ הֲרֵי צֵל הִזְדַּמֵּן לִפְנֵיהֶם, וְאָמַר לוֹ, מִנַּיִן? מֵאִיּוֹב. שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהַדּוֹר מְחֻיָּבִים כְּלָיָה, וּבָא שָׂטָן לְקַטְרֵג, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: (איובב) הֲשַׂמְתָּ לִבְּךְ אֶל עַבְדִּי אִיּוֹב כִּי אֵין כָּמֹהוּ בָּ (בכל ה) אָרֶץ, לְהַצִּיל אֶת הַדּוֹר. וְהוּא מָשָׁל לְרוֹעֶה שֶׁבָּא הַזְּאֵב לִטְרֹף אֶת צֹאנוֹ וּלְהַאֲבִידוֹ. מֶה עָשָׂה אוֹתוֹ רוֹעֶה שֶׁהָיָה חָכָם? נָתַן לוֹ תַּיִשׁ חָזָק וְשָׁמֵן וְגָדוֹל מִכֻּלָּם, אוֹתוֹ שֶׁכֻּלָּם נוֹהֲגִים אַחֲרָיו, וּבְרָצוֹן לִשְׁלֹט עַל אוֹתוֹ תַּיִשׁ טוֹב, שָׁכַח (השאיר) אֶת כֻּלָּם. מֶה עָשָׂה אוֹתוֹ רוֹעֶה? בְּשָׁעָה שֶׁהַזְּאֵב הָיָה מִתְעַסֵּק עִם אוֹתוֹ תַּיִשׁ, בָּרַח הָרוֹעֶה עִם הַצֹּאן וְשָׂם אוֹתָם בִּמְקוֹמָם, וְאַחַר כָּךְ שָׁב לַתַּיִשׁ וְהִצִּילוֹ מֵהַזְּאֵב.</p>\n<p>כָּךָ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא עִם הַדּוֹר. נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַצַּדִּיק בִּרְשׁוּת הַמְקַטְרֵג לְהַצִּיל אֶת הַדּוֹר בִּגְלָלוֹ. וְאִם הוּא חָזָק כְּיַעֲקֹב, נֶאֱמַר בּוֹ (בראשיתלב) וַיֵּאָבֵק אִישׁ עִמּוֹ. כָּל שֶׁכֵּן וְכָל שֶׁכֵּן שֶׁנִּצַּח אוֹתוֹ, עַד שֶׁאָמַר שַׁלְּחֵנִי. אָמַר, צֵל צֵל, כָּךְ הוּא. אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ צַדִּיק שֶׁהוּא חָזָק לִסְבֹּל יִסּוּרִים. כָּל שֶׁכֵּן מִי שֶׁמְּנַצֵּחַ בָּהֶם אֶת הַמְקַטְרֵג שֶׁלּוֹ, שֶׁהוּא שׁוֹלֵט עַל כָּל דּוֹר, וְנֶחְשָׁב לוֹ כְּאִלּוּ הוּא הִצִּיל אוֹתָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה אוֹתוֹ רוֹעֶה עֲלֵיהֶם בִּמְקוֹמוֹ, וְלָכֵן זָכָה רוֹעֶה הַנֶּאֱמָן לִהְיוֹת רוֹעֶה עַל יִשְׂרָאֵל. וְלֹא עוֹד, אֶלָּא שֶׁכָּךְ מַשְׁלִיטוֹ עֲלֵיהֶם בָּעוֹלָם הַבָּא, מִשּׁוּם שֶׁהִצִּיל אוֹתָם שֶׁלֹּא נֶאֶבְדוּ מִשָּׁם, שֶׁהִנְהִיגָם בְּתוֹרָה וּבְמַעֲשִׂים טוֹבִים.</p>\n<p>בֵּין כָּךְ בָּא רוֹעֶה הַנֶּאֱמָן, אָמַר לָהֶם, וְלָמָּה לוֹקָה זְרוֹעַ יָמִין? שֶׁדֶּרֶךְ כָּל בַּעֲלֵי הָרְפוּאָה שֶׁמַּקִּיזִים בַּהַתְחָלָה זְרוֹעַ יָמִין, וַהֲרֵי זְרוֹעַ שְׂמֹאל קְרוֹבָה לַלֵּב, וּמַדּוּעַ לֹא מַקִּיזִים אוֹתָהּ? אָמַר לוֹ, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא רוֹצֶה לְהַלְקוֹת יוֹתֵר, שֶׁהֲרֵי בָּזֶה מַסְפִּיק, וְאִם כְּבֵדָה הַמַּחֲלָה עַל אֵיבְרֵי הַגּוּף, מַקִּיז מִזְּרוֹעַ שְׂמֹאל.</p>\n<p>אָמַר לוֹ, אִם לֹא הָיוּ שְׁנֵיהֶם בִּזְמַן אֶחָד - יָפֶה, אֲבָל כָּאן יֵשׁ צַדִּיק, וְכָאן יֵשׁ צַדִּיק. לָזֶה יֵשׁ חֳלָאִים וּמַכּוֹת, וְלָזֶה יֵשׁ טוֹב. לָמָּה? אִם יִכְבַּד הַחֹלִי - יַקִּיז לִשְׁנֵיהֶם, שֶׁהֵם שְׁתֵּי זְרוֹעוֹת, לָתֵת רְפוּאָה לְכָל הָאֵיבָרִים. וְאִם לֹא יִכְבַּד בּוֹ הַחֹלִי עַל כָּל הָאֵיבָרִים, לָמָּה מַקִּיז לִזְרוֹעַ יָמִין יוֹתֵר מֵהַשְּׂמֹאל? אֶלָּא (אמר לו), אֱמֹר אַתָּה.</p>\n<p>אָמַר לוֹ, וַדַּאי גּוּף וּשְׁתֵּי זְרוֹעוֹת הֵם כְּנֶגֶד הָאָבוֹת. רֹאשׁ כְּנֶגֶד אָדָם הָרִאשׁוֹן, זְרוֹעַ יָמִין כְּנֶגֶד אַבְרָהָם, זְרוֹעַ שְׂמֹאל כְּנֶגֶד יִצְחָק, גּוּף כְּנֶגֶד יַעֲקֹב. וּמִתּוֹךְ לַגּוּף - כָּבֵד לְיָמִין, טְחוֹל לִשְׂמֹאל - עֵשָׂו וְיִשְׁמָעֵאל. לֵב יַעֲקֹב, בָּאֶמְצַע. כַּנְפֵי רֵאָה וּכְלָיוֹת כְּנֶגֶד אַבְרָהָם וְיִצְחָק. רֵאָה מַיִם, שֶׁהֵם (כנפי ראה שואבים) שׁוֹאֲבִים כָּל מִינֵי מַשְׁקִים. כְּלָיוֹת אֵשׁ, שֶׁמְּבַשְּׁלוֹת זֶרַע שֶׁיּוֹרֵד מֵהַמֹּחַ.</p>\n<p>וּמִשּׁוּם שֶׁאַבְרָהָם הוּא מַיִם, שָׂם זַרְעוֹ בְּגָלוּת אֱדוֹם, וּמִשּׁוּם זֶה כָּבֵד לִימִין אַבְרָהָם. וּמָרָה, שֶׁהַכָּבֵד הוּא חֶרֶב שֶׁלָּהּ, הִיא מָרָה, נֶאֱמַר בָּהּ (משלי ה) וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה. וְאִם מִתְרַבִּים הַחֲטָאִים בִּבְנֵי אַבְרָהָם, שֶׁהֵם בְּגָלוּת אֱדוֹם, נִכְבָּד בּוֹ הַחֹלִי עֲלֵיהֶם מִצַּד הַכָּבֵד. זְרוֹעַ יָמִין צָרִיךְ לְהַלְקוֹת, לְהַקִּיז מִמֶּנּוּ דָם. שֶׁמִּי שֶׁלָּקְחוּ מִמֶּנּוּ מָמוֹנוֹ כְּאִלּוּ שָׁפְכוּ דָמוֹ, וְנִשְׁאַר עָנִי, שֶׁעָנִי חָשׁוּב כַּמֵּת.</p>\n<p>וְאִם הַחֲטָאִים מִתְרַבִּים מִצַּד בְּנֵי יִצְחָק, שֶׁהֵם (בגלות) בֵּין יִשְׁמָעֵאל, בֵּית חָלְיוֹ יִכְבַּד מִצַּד טְחוֹל שֶׁבִּשְׂמֹאל, וְצָרִיךְ לְהַקִּיז זְרוֹעַ שְׂמֹאל, וְלֹא יוֹתֵר.</p>\n<p>וְאִם מִתְרַבִּים הַחֲטָאִים בִּבְנֵי יַעֲקֹב, שֶׁהֵם אֲחוּזִים לִשְׁנֵי צְדָדִים, שֶׁהֵם מְפֻזָּרִים בִּבְנֵי עֵשָׂו וְיִשְׁמָעֵאל, הֲרֵי הַחֹלִי נִכְבָּד עַל הַגּוּף, וְצָרִיךְ לְהַקִּיז מִשְּׁתֵי זְרוֹעוֹת. וְאִם כָּל הַשְּׁלֹשָׁה בְּמַחֲלוֹת כְּאֶחָד, הֲרֵי הַחֹלִי עָלָה לָרֹאשׁ, וְצָרִיךְ לְהַקִּיז וְרִידֵי הָרֹאשׁ, וּשְׁלֹשֶׁת אֵלֶּה נַעֲשׂוּ מֶרְכָּבָה לְאָדָם הָרִאשׁוֹן וְלָאָבוֹת, וּבָהֶם הִתְחַזְּקוּ לִסְבֹּל יִסּוּרִים, לְהָגֵן עַל הַדּוֹר לְאַרְבַּעַת צִדְדֵי הָעוֹלָם.</p>\n<p>אוֹי לָהֶם לַדּוֹר שֶׁגּוֹרְמִים שֶׁיִּלְקוּ הָאָבוֹת וְאָדָם הָרִאשׁוֹן וְאֵלֶּה הַצַּדִּיקִים שֶׁבֵּינֵיהֶם, שֶׁאֵין הַפְרָדָה בֵּין צַדִּיקִים אֵלּוּ לָאָבוֹת וְאָדָם, שֶׁהֵם נְשָׁמוֹת שֶׁלָּהֶם, וְהַדֹּחַק וְהַצַּעַר וְהַיָּגוֹן שֶׁלָּהֶם מַגִּיעִים לָאָבוֹת וּלְאָדָם. כְּמוֹ שֶׁהַיָּם, נְחָלִים אֵלּוּ שֶׁיּוֹצְאִים מִשָּׁם, אִם חוֹזְרִים עֲכוּרִים וּמְלֻכְלָכִים לַיָּם, הֲרֵי הָיָּם נוֹטֵל מֵעֲכִירוּת וְלִכְלוּךְ שֶׁלָּהֶם. וּבְכֹחַ הַיָּם שֶׁהוּא תַּקִּיף, לֹא סוֹבֵל לִכְלוּךְ שֶׁלָּהֶם וְזוֹרֵק אוֹתוֹ הַחוּצָה, וְנִשְׁאֲרוּ הַנְּחָלִים צְלוּלִים וְזַכִּים מֵאוֹתוֹ לִכְלוּךְ.</p>\n<p>כְּמוֹ שֶׁאִמָּא מְנַקָּה לִכְלוּכֵי בָנֶיהָ הַקְּטַנִּים, כָּךְ הָאָבוֹת מְטַהֲרִים חֲטָאִים וְלִכְלוּכִים שֶׁל בְּנֵי יִשְׂרָאֵל, כְּשֶׁנִּמְצָאִים בָּהֶם צַדִּיקִים בְּמַעֲשֵׂיהֶם, חֲזָקִים לִסְבֹּל יִסּוּרִים עַל דּוֹרָם. בְּאוֹתוֹ זְמַן אֵין הַפְרָדָה בָּהֶם. בָּאוּ כֻלָּם וּבֵרְכוּהוּ, וְאָמְרוּ לוֹ, סִינַי סִינַי, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ מְדַבֶּרֶת בְּפִיו, מִי יָכוֹל לַעֲמֹד לְפָנָיו בַּכֹּל? אַשְׁרֵי חֶלְקֵנוּ שֶׁזָּכִינוּ לְחַדֵּשׁ חִבּוּר רִאשׁוֹן זֶה בְּךְ לְהָאִיר שְׁכִינָה בַגָּלוּת.</p>"],[9522012458,"<p>אָמַר לָהֶם, רַבָּנִים שֶׁל כָּל דּוֹר הֱיִיתֶם בִּזְמַנָּם, כָּל שֶׁכֵּן מְנוֹרָה הַקְּדוֹשָׁה, שֶׁחָכְמָתוֹ מְאִירָה בְּכָל הַדּוֹרוֹת שֶׁהָיוּ אַחֲרָיו, אַל תִּתְּנוּ דֳמִי לַקָּדוֹשׁ-בָּרוּךְ-הוּא בַּתּוֹרָה עַד יַעֲרֶה עָלָיו רוּחַ הַקֹּדֶשׁ (אל שכינתו), שֶׁהֲרֵי אֵין רְשׁוּת לְהִשְׁתַּמֵּשׁ בִּמְטַטְרוֹ\"ן שַׂר הַפָּנִים רַק לְךְ, שֶׁאוֹתִיּוֹת שֶׁלּוֹ רְמוּזִים בְּשִׁמְךְ.</p>\n<p>וְכָעֵת צָרִיךְ רוֹפֵא לָדַעַת בְּכַמָּה מַעֲלוֹת עָלָה דּפֶק אוֹתוֹ הַחוֹלֶה בְּגָלוּת אֱדוֹם, שֶׁנֶּאֱמַר עָלָיו שֶׁחוֹלַת אַהֲבָה אָנִי. שֶׁהֲרֵי כַּמָּה רוֹפְאִים הִתְכַּנְּסוּ עָלָיו לָדַעַת סוֹף הַחֹלִי שֶׁלּוֹ בַּדְּפִיקוֹת הַלָּלוּ, וְלֹא הָיָה אֶחָד מֵהֶם שֶׁיּוֹדֵעַ בָּהֶם שֶׁדּפֶק אוֹתוֹ חוֹלֶה לֹא כָּל רוֹפֵא בָּקִי לָדַעַת בּוֹ, שֶׁיֵּשׁ דְּפִיקוֹת שֶׁל קשר\"ק קש\"ק קר\"ק, שֶׁהַנָּבִיא אָמַר עֲלֵיהֶם (ישעיה כו) כְּמוֹ הָרָה תַּקְרִיב לָלֶדֶת תָּחִיל תִּזְעַק בַּחֲבָלֶיהָ.</p>\n<p>וְכֻלָּם עֲשָׂרָה שׁוֹפָרוֹת, כְּלוּלִים בִּשְׁלֹשָׁה, שֶׁהֵם סִימַן קש\"ר, שֶׁהוּא תְּקִיעָה שְׁבָרִים תְּרוּעָה. וּתְקִיעָה נִרְאֵית אֹרֶךְ הַגָּלוּת, שְׁבָרִים הִתְקָרְבוּת הַגָּלוּת. בִּתְרוּעָה תָּבֹא הַגְּאֻלָּה, שֶׁנִּרְאֶה דֹחַק אַחַר דּחַק, וְאֵין רֶוַח בֵּין זֶה לָזֶה, שֶׁוַּדַּאי כֵּיוָן שֶׁשְּׁאָר עַמִּים מְעַכְּבִים אֶת יִשְׂרָאֵל בַּגָּלוּת, דָּחֳקָם מְקָרֵב לָהֶם הַגְּאֻלָּה. גַּם כָּךְ מְהִירוּת הַדֹּפֶק זֶה אַחַר זֶה, בּוֹ יוֹצֵאת נֶפֶשׁ הָאָדָם, אַחַר שֶׁאֵין רֶוַח בֵּין זֶה לָזֶה.</p>\n<p>קשר\"ק קש\"ק קר\"ק, הוּא שֶׁשָּׂם קש\"ר, תְּקִיעָה שְׁבָרִים תְּרוּעָה, שֶׁיַּעֲבֹר בּוֹ שֶׁקֶר מִן הָעוֹלָם, שֶׁבּוֹ שְׁבוּעָה - (שמות יז) מִלְחָמָה לַה' בַּעֲמָלֵק. יִתְעוֹרֵר בָּעוֹלָם שִׁיר פָּשׁוּט, וְכָפוּל, וּמְשֻׁלָּשׁ, וּמְרֻבָּע, שֶׁהוּא עוֹלֶה אוֹתִיּוֹת שֶׁלּוֹ: י', י\"ה, יה\"ו, יהו\"ה - ע\"ב. בְּאוֹתוֹ זְמַן - וּבְכֵן צַדִּיקִים יִרְאוּ וְיִשְׂמָחוּ וִישָׁרִים יַעֲלוֹזוּ וַחֲסִידִים בְּרִנָּה יָגִילוּ. ו' תּוֹסֶפֶת - אֶלֶף הַשִּׁשִּׁי. קֹדֶם שֶׁלּוֹ עָקֵ\"ב, חָרֵב בֵּית הַמִּקְדָּשׁ, וּלְאַחֲרָיו עַד תַּשְׁלוּם רָעָ\"ב יִהְיֶה עֶרֶ\"ב. זֶהוּ שֶׁכָּתוּב (שם טז) עֶרֶב וִידַעְתֶּם כִּי ה' הוֹצִיא אֶתְכֶם וְגוֹ'. (בראשית מד) כִּי עַבְדְּךְ עָרַב אֶת הַנַּעַר וְגוֹ'.</p>\n<p>עַד שֶׁיָּשְׁבוּ, רָאוּ צֵל שֶׁעוֹמֵד עֲלֵיהֶם, הוֹלֵךְ וּבָא, הוֹלֵךְ וּבָא בְּתוֹךְ הַבַּיִת. תָּמְהוּ. אָמַר רַבִּי אַבָּא, יוֹסֵי בְּנִי, אֹמַר לְךְ מֶה הָיָה לִי עִם הַמְּנוֹרָה הַקְּדוֹשָׁה. יוֹם אֶחָד הָיִינוּ הוֹלְכִים בְּבִקְעַת אוֹנוֹ, וְהָיִינוּ עוֹסְקִים בַּתּוֹרָה כָּל אוֹתוֹ יוֹם, וּמִתּוֹךְ חֹזֶק הַשֶּׁמֶשׁ יָשַׁבְנוּ לְיַד סֶלַע אֶחָד בְּתוֹךְ נֶקֶב אֶחָד.</p>\n<p>אָמַרְתִּי לוֹ, מַה זֶּה שֶׁבְּכָל שָׁעָה שֶׁמִּתְרַבִּים הָרְשָׁעִים בָּעוֹלָם וְהַדִּין שָׁרוּי בָּעוֹלָם, צַדִּיקִים שֶׁבָּהֶם לוֹקִים עֲלֵיהֶם?! שֶׁכָּךְ שָׁנִינוּ, בְּחֵטְא הַדּוֹר, קְדוֹשִׁים וְצַדִּיקִים יִתָּפְסוּ. לָמָּה? אִם מִשּׁוּם שֶׁהֵם לֹא מוֹכִיחִים אֶת הָעוֹלָם עַל מַעֲשֵׂיהֶם - כַּמָּה הֵם שֶׁמּוֹכִיחִים וְלֹא מְקַבְּלִים מֵהֶם, וְהַצַּדִּיקִים כְּפוּפִים לִפְנֵיהֶם. וְאִם מִשּׁוּם שֶׁאֵין מִי שֶׁיָּגֵן עַל הָעוֹלָם - לֹא יָמוּתוּ וְלֹא יִתָּפְסוּ בַחֲטָאֵיהֶם, שֶׁהֲרֵי חֶדְוָה הִיא לַצַּדִּיקִים בְּאִבּוּדָם.</p>\n<p>אָמַר לוֹ, בְּוַדַּאי בְּחֵטְא הַדּוֹר נִתְפָּסִים הַצַּדִּיקִים, וַהֲרֵי בֵּאַרְנוּ דְבָרִים אֵלּוּ. אֲבָל בְּשָׁעָה שֶׁנִּתְפָּסִים הַצַּדִּיקִים בֶּחֳלָאִים אוֹ בְמַכּוֹת, זֶה בִּשְׁבִיל לְכַפֵּר עַל הָעוֹלָם, וְאָז יִתְכַּפְּרוּ כָּל חֲטָאֵי הַדּוֹר. מִנַּיִן לָנוּ? מִכָּל אֵיבְרֵי הַגּוּף. בְּשָׁעָה שֶׁכָּל הָאֵיבָרִים בִּמְצוּקָה וְחֹלִי גָדוֹל שׁוֹרֶה עֲלֵיהֶם, אֵיבָר אֶחָד צָרִיךְ לִלְקוֹת כְּדֵי שֶׁיִּתְרַפְּאוּ כֻלָּם. וּמִיהוּ? הַזְּרוֹעַ. הַזְּרוֹעַ לוֹקָה וּמוֹצִיאִים מִמֶּנָּה דָּם, וְאָז הֲרֵי רְפוּאָה לְכָל אֵיבְרֵי הַגּוּף.</p>\n<p>גַּם כָּךְ בְּנֵי הָעוֹלָם הֵם אֵיבָרִים זֶה עִם זֶה. בְּשָׁעָה שֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת רְפוּאָה לָעוֹלָם, מַלְקֶה צַדִּיק אֶחָד בֵּינֵיהֶם בְּמַחֲלוֹת וּמַכּוֹת, וּבִגְלָלוֹ נוֹתֵן רְפוּאָה לַכֹּל. מִנַּיִן לָנוּ? שֶׁכָּתוּב (ישעיה נג) וְהוּא מְחֹלָל מִפְּשָׁעֵינוּ מְדֻכָּא מֵעֲונֹתֵינוּ וְגוֹ', וּבַחֲבֻרָתוֹ נִרְפָּא לָנוּ. וּבַחֲבֻרָתוֹ - הַקָּזַת דָּם, כְּמוֹ מִי שֶׁמַּקִּיז זְרוֹעַ, וּבְאוֹתָהּ חֲבוּרָה נִרְפָּא לָנוּ, רְפוּאָה הוּא לָנוּ לְכָל אֵיבְרֵי הַגּוּף.</p>\n<p>וּלְעוֹלָם לֹא מַלְקֶה צַדִּיק, אֶלָּא כְּדֵי לָתֵת רְפוּאָה לַדּוֹר וּלְכַפֵּר עֲלֵיהֶם, (וסוד זה צדיק ורע לו) שֶׁזֶּה נוֹחַ לַצַּד הָאַחֵר שֶׁהַדִּין שׁוֹלֵט (לשלט) עַל הַצַּדִּיק יוֹתֵר מֵהַכֹּל, שֶׁלֹּא חוֹשֵׁשׁ אָז לְכָל הָעוֹלָם וְלֹא מַשְׁגִּיחַ בָּהֶם מֵהַשִּׂמְחָה שֶׁהוּא שׁוֹלֵט עָלָיו. וְאוֹתוֹ צַדִּיק זוֹכֶה לְשִׁלְטוֹן עֶלְיוֹן בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. צַדִּיק וְטוֹב לוֹ, שֶׁלֹּא חוֹשֵׁשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא לְכַפֵּר עַל הָעוֹלָם.</p>\n<p>אָמַרְתִּי לוֹ, אִלּוּ לֹא הָיוּ בִּזְמַן אֶחָד - יָפֶה. אֲבָל כָּאן יֵשׁ צַדִּיק, וְכָאן יֵשׁ צַדִּיק. לָזֶה יֵשׁ מַחֲלוֹת, וְלָזֶה יֵשׁ אֶת כָּל טוֹב הָעוֹלָם. אָמַר לִי, בְּאֶחָד מֵהֶם אוֹ בִשְׁנַיִם מַסְפִּיק, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא רוֹצֶה לְהַלְקוֹת הַכֹּל, (ס\"א כל עוד) כְּמוֹ שֶׁלֹּא צָרִיךְ אֶלָּא זְרוֹעַ אַחַת לְהַלְקוֹת וּלְהַקִּיז לָתֵת רְפוּאָה לְכָל הָאֵיבָרִים. גַּם כָּאן, בְּצַדִּיק אֶחָד מַסְפִּיק.</p>\n<p>וְאִם מִתְחַזֶּקֶת (מכבידה) הַמַּחֲלָה עַל כָּל הָאֵיבָרִים, אָז צָרִיךְ לְהַקִּיז מִשְּׁתֵי זְרוֹעוֹת. גַּם כָּךְ, אִם הִתְרַבּוּ הַחֲטָאִים וּכְבֵדִים עַל הָעוֹלָם, אָז כָּל הַצַּדִּיקִים לוֹקִים, לָתֵת רְפוּאָה עַל כָּל הַדּוֹר. אֲבָל בִּזְמַן שֶׁלֹּא הִתְרַבּוּ כָּל כָּךְ, אָז רַק צַדִּיק אֶחָד לוֹקֶה, וּשְׁאָר הַצַּדִּיקִים בְּשָׁלוֹם, שֶׁהֲרֵי לֹא צָרִיךְ הָעוֹלָם שֶׁכֻּלָּם יִלְקוּ. נִרְפָּא הָעָם - נִרְפְּאוּ הַצַּדִּיקִים. וְלִפְעָמִים שֶׁכָּל יְמֵיהֶם עוֹמְדִים בְּמַחֲלוֹת לְהָגֵן עַל הַדּוֹר. אִם מֵתוּ - הֲרֵי נִרְפָּא הַכֹּל וְנִתְכַּפֵּר, לִפְעָמִים כְּשֶׁהַחֲטָאִים הֵם נִכְבָּדִים יוֹתֵר.</p>"],[9522012459,"<p>קַמְנוּ וְהָלַכְנוּ, וְחֹזֶק הַשֶּׁמֶשׁ הָיָה יוֹתֵר, וְהַדֶּרֶךְ הָיְתָה דְחוּקָה לָנוּ. רָאִינוּ אִילָנוֹת בַּמִּדְבָּר וּמַיִם תַּחְתֵּיהֶם. יָשַׁבְנוּ תַחַת צֵל שֶׁל אִילָן אֶחָד שֶׁל הַמִּדְבָּר. שְׁאַלְנוּהוּ, מַה זֶּה שֶׁכָּל עַמֵּי עוֹלָם לֹא עוֹשִׂים נִעְנוּעַ, רַק יִשְׂרָאֵל לְבַדָּם? שֶׁכְּשֶׁעוֹסְקִים בַּתּוֹרָה מִתְנַעְנְעִים לְכָאן וּלְכָאן בְּלִי לִמּוּד שֶׁל אָדָם בָּעוֹלָם, וְלֹא יְכוֹלִים לַעֲמֹד בְּעַצְמָם?</p>\n<p>אָמַר לִי, הִזְכַּרְתַּנִי דָּבָר עֶלְיוֹן, וּבְנֵי אָדָם לֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים. יָשַׁב שָׁעָה וּבָכָה. אָמַר, אוֹי לִבְנֵי הָאָדָם שֶׁהוֹלְכִים כְּבַהֲמוֹת הַשָּׂדֶה בְּלִי שֵׂכֶל. בַּדָּבָר הַזֶּה לְבַדּוֹ נוֹדָעוֹת נְשָׁמוֹת קְדוֹשׁוֹת שֶׁל יִשְׂרָאֵל בֵּין נִשְׁמוֹת עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. נִשְׁמוֹת יִשְׂרָאֵל נִגְזְרוּ מִתּוֹךְ נֵר קָדוֹשׁ שֶׁדּוֹלֵק, שֶׁכָּתוּב (משלי כ) נֵר ה' נִשְׁמַת אָדָם. וְנֵר זֶה, בְּשָׁעָה שֶׁנֶּאֱחָז (שנדלק) מִתּוֹךְ תּוֹרָה הָעֶלְיוֹנָה, לֹא שׁוֹכֵךְ הָאוֹר עָלָיו אֲפִלּוּ רֶגַע. וְסוֹד זֶה - (תהלים פז) אֱלֹהִים אַל דֳּמִי לָךְ. כְּמוֹ זֶה כָּתוּב - (ישעיה סב) הַמַּזְכִּירִים אֶת ה' אַל דֳּמִי לָכֶם. אֵין שִׁכּוּךְ לָכֶם. אוֹר הַנֵּר, כֵּיוָן שֶׁנֶּאֱחָז תּוֹךְ הַפְּתִילָה, אוֹתוֹ הָאוֹר לֹא שׁוֹכֵךְ לְעוֹלָמִים, אֶלָּא מִתְנַעְנֵעַ הָאוֹר לְכָאן וּלְכָאן וְלֹא שׁוֹכֵךְ לְעוֹלָמִים.</p>\n<p>כְּמוֹ זֶה יִשְׂרָאֵל, שֶׁנִּשְׁמוֹתֵיהֶם מִתּוֹךְ אוֹתוֹ אוֹר הַנֵּר - כֵּיוָן שֶׁאָמַר דָּבָר אֶחָד שֶׁל הַתּוֹרָה, הֲרֵי הָאוֹר דּוֹלֵק, וְלֹא יְכוֹלִים הֵם לִשְׁכֹּךְ, וּמִתְנַעְנְעִים לְכָאן וּלְכָאן וּלְכָל הַצְּדָדִים כְּאוֹר הַנֵּר, שֶׁהֲרֵי כָּתוּב (משלי כ) נֵר ה' נִשְׁמַת אָדָם.</p>\n<p>וְכָתוּב (יחזקאל לד) אָדָם אַתֶּם. אַתֶּם קְרוּיִים אָדָם וְלֹא אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. נִשְׁמוֹת עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת מִדְּעִיכַת הַקַּשׁ, בְּלֹא אוֹר שֶׁשּׁוֹרֶה עֲלֵיהֶם, וְלָכֵן שׁוֹכְכִים וְלֹא מִתְנַעְנְעִים, שֶׁהֲרֵי אֵין לָהֶם תּוֹרָה וְלֹא דוֹלְקִים בָּהּ, וְאֵין אוֹר שׁוֹרֶה בָהֶם. הֵם עוֹמְדִים כְּמוֹ עֵצִים בְּתוֹךְ אֵשׁ שֶׁדּוֹלֵק בְּלִי אוֹר שֶׁשּׁוֹרֶה עֲלֵיהֶם, וְעַל זֶה שׁוֹכְכִים בְּלִי אוֹר כְּלָל. אָמַר רַבִּי יוֹסֵי, זֶהוּ בֵּרוּר הַדָּבָר! אַשְׁרֵי חֶלְקִי שֶׁזָּכִיתִי לָזֶה לִשְׁמֹעַ אֶת זֶה.</p>"],[9522012460,"<p>קוּם רַבִּי אַבָּא לְחַדֵּשׁ דִּבְרֵי תוֹרָה שֶׁאָמַרְתָּ בְּחִבּוּר רִאשׁוֹן. פָּתַח רַבִּי אַבָּא וְאָמַר, (ישעיה מב) שִׁירוּ לַה' שִׁיר חָדָשׁ תְּהִלָּתוֹ מִקְצֵה הָאָרֶץ וְגוֹ'. כַּמָּה חֲבִיבִים יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁחֶדְוָה שֶׁלָּהֶם וְתִשְׁבַּחַת שֶׁלָּהֶם אֵינָהּ אֶלָּא (לשתף את הקדוש ברוך הוא ושכינתו באותו שכך וכו') בּוֹ. שֶׁכָּךְ שָׁנִינוּ, כָּל חֶדְוָה שֶׁל יִשְׂרָאֵל שֶׁלֹּא מְשַׁתְּפִים בָּהּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא (ושכינתו), אֵינָהּ חֶדְוָה. וְעָתִיד הוּא סָמָאֵל וְכָל סִיעָתוֹ לְקַטְרֵג לְאוֹתָהּ חֶדְוָה, (ויחזר) וְיִשָּׁאֵר בְּצַעַר וּבֶכִי, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מִשְׁתַּתֵּף בְּאוֹתוֹ הַצַּעַר.</p>\n<p>אֲבָל מִי שֶׁמְּשַׁתֵּף אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְחֶדְוָתוֹ, אִם יָבא מְקַטְרֵג לְקַטְרֵג בְּאוֹתָהּ חֶדְוָה, הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ מִשְׁתַּתֵּף בְּאוֹתוֹ צַעַר. מַה כָּתוּב בּוֹ? (שם סג) בְּכָל צָרָתָם לוֹ צָר. וּבַמֶּה? מִשּׁוּם שֶׁעִמּוֹ אָנֹכִי בְצָרָה.</p>\n<p>וּמִנַּיִן לָנוּ שֶׁיֵּשׁ לָהֶם לְיִשְׂרָאֵל לְשַׁתֵּף אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְחֶדְוָתָם? (משום שאינה שמחה, אלא בשתפות שלו מאלו) שֶׁכָּתוּב (תהלים קמט) יִשְׂמַח יִשְׂרָאֵל בְּעֹשָׂיו. אוֹתָהּ חֶדְוָה שֶׁל יִשְׂרָאֵל אֵינָהּ, אֶלָּא בְּעֹשָׂיו. בְּעֹשָׂיו?! בְּעוֹשׂוֹ צָרִיךְ לוֹ לִכְתֹּב! אֶלָּא אֵלּוּ הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, וְאָבִיו וְאִמּוֹ. שֶׁאַף עַל גַּב שֶׁמֵּתוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹקְרָם מִגַּן עֵדֶן וּמְבִיאָם עִמּוֹ לְאוֹתָהּ חֶדְוָה, לָקַחַת חֵלֶק שֶׁל חֶדְוָה עִם הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (איוב מ) הָעֹשׂוֹ יַגֵּשׁ חַרְבּוֹ.</p>"],[9522012461,"<p>דָּבָר אַחֵר בְּעֹשָׂיו - מִשּׁוּם שֶׁבֶּן אָדָם נַעֲשָׂה בְּשֻׁתָּפוּת אִישׁ וְאִשָּׁה וְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל סוֹד זֶה כָּתוּב (בראשית א) נַעֲשֶׂה אָדָם, בְּשֻׁתָּפוּת. שֶׁשָּׁנִינוּ, שְׁלֹשָׁה אֻמָּנִים עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא מֵהֶם עוֹלָם, וְאֵלּוּ הֵם: הַשָּׁמַיִם, וְהָאָרֶץ, וְהַמַּיִם. וְכָל אֶחָד שִׁמֵּשׁ יוֹם אֶחָד, וְחָזְרוּ כְּמִקֹּדֶם.</p>\n<p>יוֹם רִאשׁוֹן הוֹצִיאוּ הַשָּׁמַיִם אֻמָּנוּת שֶׁלָּהֶם, שֶׁכָּתוּב (שם) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. יוֹם שֵׁנִי הוֹצִיאוּ הַמַּיִם אֻמָּנוּת לְמַעֲשֶׂה, שֶׁכָּתוּב (שם) וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וְגוֹ'. עָלוּ חֲצִי מַיִם לְמַעְלָה, וַחֲצִי מַיִם נִשְׁאֲרוּ לְמַטָּה. וְאִלְמָלֵא כָּךְ שֶׁהַמַּיִם נִפְרְדוּ, הָעוֹלָם לֹא הָיָה עוֹמֵד. יוֹם שְׁלִישִׁי עָשְׂתָה הָאָרֶץ וְהוֹצִיאָה כְּמוֹ שֶׁצֻּוְּתָה, שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב, וְכָתוּב וַתּוֹצֵא הָאָרֶץ דֶּשֶׁא וְגוֹ'.</p>\n<p>עֵד כָּאן כָּל אֻמָּנוּת מִשְּׁלֹשָׁה אֵלֶּה הוֹצִיא אֻמָּנוּתוֹ, וְעָשׂוּ מַה שֶּׁהִצְטַוּוּ. נִשְׁאֲרוּ שְׁלֹשָׁה יָמִים אַחֲרוֹנִים. יוֹם רְבִיעִי הִצְטַוָּה אֻמָּן רִאשׁוֹן לַעֲשׂוֹת אֻמָּנוּתוֹ, שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת וְגוֹ', וְהַיְנוּ שָׁמַיִם. בַּיּוֹם הַחֲמִישִׁי הוֹצִיאוּ הַמַּיִם, שֶׁהוּא אֻמָּנוּת אַחֶרֶת, שֶׁכָּתוּב וַיּאמִר אִלהיּם יּשּרצּוּ הַמַּיּם וגו', בַּיּוֹם הַשִּׁשִּׁי עָשְׂתָה הָאָרֶץ אֻמָּנוּתָהּ, שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה וְגוֹ'.</p>\n<p>כֵּיוָן שֶׁשְּׁלֹשֶׁת הָאֻמָּנִים הָאֵלֶּה הִשְׁלִימוּ מַעֲשֵׂיהֶם, אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא: אֻמָּנוּת אַחַת יֵשׁ לִי לַעֲשׂוֹת, וְהוּא אָדָם. הִתְחַבְּרוּ כְאֶחָד, וַאֲנִי עִמָּכֶם, נַעֲשֶׂה אָדָם. גּוּף שֶׁלָּכֶם, וַאֲנִי אֶהְיֶה שֻׁתָּף עִמָּכֶם וְנַעֲשֶׂה אָדָם. כְּמוֹ שֶׁבַּתְּחִלָּה הָיָה בְשֻׁתָּפוּת, גַּם אַחַר כָּךְ כֵּן. אַבָּא - שֶׁבּוֹ עוֹשֶׂה מַעֲשֵׂה הַשָּׁמַיִם וּמַעֲשֵׂה הַמַּיִם, וְהָאִשָּׁה - שֶׁהִיא אֻמָּן שְׁלִישִׁי כְּמוֹ הָאָרֶץ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהִשְׁתַּתֵּף יַחַד אִתָּם. וְעַל סוֹד זֶה כָּתוּב בְּעֹשָׂיו.</p>\n<p>וְאַף עַל גַּב שֶׁאַבָּא וְאִמָּא נִפְרְדוּ מֵהָעוֹלָם הַזֶּה, יֵשׁ חֶדְוָה בְּכָל שֻׁתָּפוּת. שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁהָאָדָם מְשַׁתֵּף אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בַּחֶדְוָה שֶׁלּוֹ, בָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַן עֵדֶן וְעוֹקֵר מִשָּׁם אֶת אָבִיו וְאִמּוֹ, שֶׁהֵם שֻׁתָּפִים אִתּוֹ, וּמֵבִיא אוֹתָם עִמּוֹ לְאוֹתָהּ חֶדְוָה, וְכֻלָּם מְזֻמָּנִים שָׁם, וּבְנֵי אָדָם לֹא יוֹדְעִים. אֲבָל בְּצָרַת הָאָדָם, הַקָּדוֹשׁ בָּרוּךְ הוּא מְזֻמָּן אֵלָיו לְבַדּוֹ, וְלֹא מוֹדִיעַ לְאָבִיו וּלְאִמּוֹ. זֶהוּ שֶׁכָּתוּב (תהלים יח) בַּצַּר לִי אֶקְרָא ה' וְאֶל אֱלֹהַי אֲשַׁוֵּעַ וְגוֹ'.</p>"],[9522012462,"<p>אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲנִי וּשְׁכִינָתִי שֻׁתָּפוּת הַנְּשָׁמָה, וְאָבִיו וְאִמּוֹ שֻׁתָּפוּת הַגּוּף. שֶׁאָבִיו מַזְרִיעַ לֹבֶן שֶׁל הָעֵינַיִם וְשֶׁל הָעֲצָמוֹת וְשֶׁל הַגִּידִים וְהַמֹּחַ, וְהָאִשָּׁה שָׁחֹר שֶׁבָּעֵינַיִם וְשֵׂעָר וּבָשָׂר וְעוֹר. וְגַם כָּךְ שָׁמַיִם וָאָרֶץ וְכָל חֵילֵיהֶם הִשְׁתַּתְּפוּ בִיצִירָתוֹ: מַלְאָכִים, מֵהֶם יֵצֶר הַטּוֹב וְיֵצֶר הָרָע לִהְיוֹת מְצֻיָּר מִשְּׁנֵיהֶם. שֶׁמֶשׁ וּלְבָנָה לְהָאִיר לוֹ בַּיּוֹם וּבַלַּיְלָה. חַיּוֹת וּבְהֵמוֹת וְעוֹפוֹת וְדָגִים לְהִתְפַּרְנֵס מֵהֶם, וְכָל עֵצִים וְזַרְעֵי הָאָרֶץ לְהִתְפַּרְנֵס מֵהֶם.</p>\n<p>מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? עָקַר אֶת אָבִיו וְאִמּוֹ מִגַּן עֵדֶן וֶהֱבִיאָם עִמּוֹ, לִהְיוֹת עִמּוֹ בְּחֶדְוַת בְּנוֹ, וְאֵין חֶדְוָה כְּחֶדְוַת הַגְּאֻלָּה, שֶׁכָּתוּב בָּהּ (דברי הימים א טז) יִשְׂמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ וְיֹאמְרוּ בַגּוֹיִם ה' מָלָךְ. אָז יְרַנְּנוּ עֲצֵי הַיָּעַר מִלִּפְנֵי ה' כִּי בָא לִשְׁפּוֹט אֶת הָאָרֶץ.</p>"],[9522012463,"<p>חָזַר אוֹתוֹ צֵל שֶׁל קֹדֶם וְהָלַךְ לְתוֹךְ הַבַּיִת כְּמוֹ דְמוּת אָדָם. נָפַל עַל פָּנָיו רַבִּי אַבָּא. אָמַר רַבִּי יוֹסֵי, נִזְכַּרְתִּי שֶׁבְּמָקוֹם זֶה רָאִיתִי אֶת רַבִּי פִּנְחָס בֶּן יָאִיר, יוֹם אֶחָד הָיָה עוֹמֵד בְּמָקוֹם זֶה וְהָיָה אוֹמֵר כָּךְ: פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן, בְּאוֹת י' קְטַנָּה.</p>\n<p>מִשּׁוּם שֶׁשְּׁנֵי א\"ב רְשׁוּמִים - אַלְפָא בֵּיתָא שֶׁל אוֹתִיּוֹת גְּדוֹלוֹת, וְאַלְפָא בֵּיתָא שֶׁל אוֹתִיּוֹת קְטַנּוֹת. אוֹתִיּוֹת גְּדוֹלוֹת הֵן בָּעוֹלָם הַבָּא, וְאוֹתִיּוֹת קְטַנּוֹת הֵן בָּעוֹלָם הַתַּחְתּוֹן. י' קְטַנָּה, אוֹת בְּרִית הַקָּדוֹשׁ. כֵּיוָן שֶׁפִּנְחָס קִנֵּא עַל בְּרִית זוֹ, נִתּוֹסְפָה לוֹ י' קְטַנָּה, סוֹד בְּרִית זוֹ.</p>\n<p>בְּאוֹתָהּ שָׁעָה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מָה אֶעֱשֶׂה עִם מֹשֶׁה? בְּרִית זוֹ מִמֹּשֶׁה הָיְתָה, וְכַלָּתוֹ הָיְתָה, גְּנַאי הוּא לָתֵת אוֹתָהּ לְאַחֵר בְּלִי דַעַת וּרְצוֹן מֹשֶׁה. לֹא נָאֶה זֶה. הִתְחִיל הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר לְמֹשֶׁה: מֹשֶׁה, פִּנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן. אָמַר לוֹ מֹשֶׁה: רִבּוֹנוֹ שֶׁל עוֹלָם, מַהוּ? אָמַר לוֹ, אַתָּה הוּא שֶׁמָּסַרְתָּ נַפְשְׁךְ עַל יִשְׂרָאֵל שֶׁלֹּא יֹאבְדוּ מִן הָעוֹלָם בְּכַמָּה פְעָמִים, וְהוּא הֵשִׁיב אֶת חֲמָתִי מֵעַל בְּנֵי יִשְׂרָאֵל וְגוֹ'. אָמַר מֹשֶׁה: מָה אַתָּה רוֹצֶה מִמֶּנִּי? הֲרֵי הַכֹּל שֶׁלְּךְ!</p>\n<p>אָמַר לוֹ: הֲרֵי הַכֹּל שֶׁלְּךְ הִיא, אֱמֹר לוֹ שֶׁתִּשְׁרֶה בְתוֹכוֹ. אָמַר מֹשֶׁה: הֲרֵי בְּלֵב שָׁלֵם תִּהְיֶה אֵלָיו. אָמַר לוֹ: אֱמֹר אַתָּה בְּפִיךְ וְהָרֵם קוֹלְךְ, שֶׁאַתָּה מָסַרְתָּ אוֹתָהּ בְּרָצוֹן וּבְלֵב שָׁלֵם. זֶהוּ שֶׁכָּתוּב לָכֵן אֱמֹר. אַתָּה אֱמֹר בְּרָצוֹן: הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. שֶׁאִלּוּ הַקָּדוֹשׁ בָּרוּךְ הוּא, הָיָה לוֹ לוֹמַר: לָכֵן אֱמֹר לוֹ הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. אֲבָל לֹא כָתוּב אֶלָּא לָכֵן אֱמֹר. וְאִם תֹּאמַר שֶׁהָעָבְרָה מִמֹּשֶׁה - לֹא. אֶלָּא כְּנֵר זֶה שֶׁמַּדְלִיקִים מִמֶּנּוּ - זֶה נוֹתֵן וּמְהַנֶּה, וְזֶה לֹא נִגְרָע מִמֶּנּוּ.</p>\n<p>בָּא אוֹתוֹ הַצֵּל, וְיָשַׁב, וּנְשָׁקוֹ. שָׁמְעוּ קוֹל אֶחָד שֶׁהָיָה אוֹמֵר: פַּנּוּ מָקוֹם, פַּנּוּ מָקוֹם לְרַבִּי פִּנְחָס בֶּן יָאִיר, שֶׁהוּא אִתְּכֶם. שֶׁשָּׁנִינוּ, שֶׁכָּל מָקוֹם שֶׁצַּדִּיק חִדֵּשׁ בּוֹ דִּבְרֵי תוֹרָה, כְּשֶׁהוּא בְּאוֹתוֹ הָעוֹלָם פּוֹקֵד אֶת אוֹתוֹ מָקוֹם וּבָא אֵלָיו, וְכָל שֶׁכֵּן כְּשֶׁשְּׁרוּיִים בּוֹ צַדִּיקִים אֲחֵרִים לְחַדֵּשׁ בְּאוֹתוֹ מָקוֹם שֶׁאוֹמְרִים דִּבְרֵי תוֹרָה, כְּמוֹ זֶה שֶׁהָיָה בָּא רַבִּי פִּנְחָס בֶּן יָאִיר לִפְקֹד אֶת מְקוֹמוֹ וּמָצָא צַדִּיקִים אֵלּוּ מְחַדְּשִׁים דִּבְרֵי תוֹרָה, וְהִתְחַדֵּשׁ כְּמִקֹּדֶם אוֹתוֹ דָּבָר שֶׁל רַבִּי פִּנְחָס בֶּן יָאִיר לְפָנָיו.</p>\n<p>אָמַר רַבִּי אַבָּא, נָאֶה הַדָּבָר שֶׁל רַבִּי פִּנְחָס בֶּן יָאִיר, שֶׁהֲרֵי לֹא כָתוּב לָכֵן הִנְנִי נוֹתֵן, אֶלָּא לָכֵן אֱמֹר הִנְנִי נֹתֵן לוֹ. וְכִי דָבָר זֶה הָיָה גָנוּז מֵחָסִיד זֶה תַּחַת יָדְךְ וְלֹא הָיִיתָ אוֹמֵר?! אַשְׁרֵי חֶלְקֵנוּ שֶׁזָּכִינוּ לִהְיוֹת בַּסִּיּוּעַ שֶׁל הַצֵּל הַקָּדוֹשׁ כָּאן.</p>"],[9522012464,"<p>גַּם הוּא פָּתַח וְאָמַר מִשְּׁמוֹ שֶׁל רַבִּי פִּנְחָס, (קהלת ט) כֹּל אֲשֶׁר תִּמְצָא יָדְךְ לַעֲשׂוֹת בְּכֹחֲךְ עֲשֵׂה וְגוֹ' - כַּמָּה נָאֶה לוֹ לָאָדָם בְּעוֹד שֶׁהַנֵּר דּוֹלֵק וְשָׁרוּי עַל רֹאשׁוֹ לְהִשְׁתַּדֵּל וְלַעֲשׂוֹת רְצוֹן רִבּוֹנוֹ, מִשּׁוּם שֶׁאוֹתוֹ הַנֵּר הוּא כֹּ\"חַ שֶׁשָּׁרוּי עָלָיו, וְלָכֵן כָּתוּב (במדבר יד) יִגְדַּל נָא כֹּחַ יְיָ. כֹּחַ יְיָ, זֶהוּ כֹּחַ שֶׁשּׁוֹרֶה עַל רֹאשׁ הַצַּדִּיקִים וְכָל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בִּרְצוֹן רִבּוֹנָם. וְעַל זֶה שָׁנִינוּ, כָּל הָעוֹנֶה אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ בְּכָל כֹּחוֹ. (זהו כחו)</p>\n<p>וַדַּאי צָרִיךְ לְעוֹרֵר כָּל אֵיבָרָיו בְּכֹחַ חָזָק, מִשּׁוּם שֶׁבְּהִתְעוֹרְרוּת חֲזָקָה שֶׁהִתְחַזֵּק, הִתְעוֹרֵר אוֹתוֹ כֹּחַ קָדוֹשׁ עֶלְיוֹן וְעָלָה לְתוֹךְ הַקֹּדֶשׁ, וְנִשְׁבַּר כֹּחַ וְחֹזֶק הַצַּד הָאַחֵר. וְלָכֵן בְּכֹחֲךְ, שֶׁצָּרִיךְ לַעֲשׂוֹת רְצוֹן רִבּוֹנְךְ.</p>\n<p>כִּי אֵין מַעֲשֶׂה וְחֶשְׁבּוֹן וְגוֹ', מִשּׁוּם שֶׁבְּאוֹתוֹ כֹּחַ יֵשׁ מַעֲשֵׂה הִשְׁתַּדְּלוּת לְהִשְׁתַּדֵּל בָּעוֹלָם הַזֶּה שֶׁנִּקְרָא מַעֲשֶׂה, עוֹלַם הַמַּעֲשֶׂה, לְהַשְׁלִים סוֹף הַמַּחֲשָׁבָה. וְחֶשְׁבּוֹן - זֶהוּ עוֹלָם שֶׁתָּלוּי בַּדִּבּוּר, שֶׁהֲרֵי הַחֶשְׁבּוֹן בַּדִּבּוּר תָּלוּי. וְלָכֵן כָּל הַגִּימַטְרִיָּאוֹת וּתְקוּפוֹת הָעִבּוּרִים שֶׁל הָעוֹלָם הֵם בַּלְּבָנָה. וְדַעַת - זֶהוּ סוֹד שִׁשָּׁה צְדָדִים שֶׁתְּלוּיִים בַּמַּחֲשָׁבָה, וְנִקְרָאִים עוֹלָם שֶׁל אוֹתָהּ מַחֲשָׁבָה. וְחָכְמָה - שֶׁהַכֹּל תָּלוּי מִמֶּנָּה.</p>\n<p>וְכָל אֵלּוּ כְּלוּלִים בְּאוֹתוֹ כֹּחַ, מַה שֶּׁאֵין כֵּן בְּצַד הַשְּׁאוֹל, דַּרְגַּת הַגֵּיהִנֹּם. שֶׁהֲרֵי כָּל אָדָם שֶׁלֹּא מִשְׁתַּדֵּל בְּכֹ\"חַ זֶה בָּעוֹלָם הַזֶּה לְהִכָּנֵס בּוֹ בְּמַעֲשֶׂה וְחֶשְׁבּוֹן וְדַעַת וְחָכְמָה, סוֹפוֹ לְהִכָּנֵס בַּשְּׁאוֹל, שֶׁאֵין בּוֹ מַעֲשֶׂה וְחֶשְׁבּוֹן וְדַעַת וְחָכְמָה. שֶׁהֲרֵי הַצַּד הָאַחֵר הוּא דֶּרֶךְ שְׁאוֹל, שֶׁכָּתוּב (משלי ז) דַּרְכֵי שְׁאוֹל בֵּיתָהּ. מִי שֶׁיִּתְרַפֶּה מִכֹּ\"חַ הַקָּדוֹשׁ הַזֶּה, מִתְחַזֵּק בּוֹ צַד הָאַחֵר, שֶׁשְּׁאוֹל בֵּיתָהּ.</p>\n<p>אֲשֶׁר אַתָּה הֹלֵךְ שָׁמָּה. וְכִי כָל בְּנֵי הָעוֹלָם הוֹלְכִים לַשְּׁאוֹל? כֵּן, אֲבָל עוֹלִים מִיָּד, שֶׁכָּתוּב (שמואל א ב) מוֹרִיד שְׁאוֹל וַיָּעַל. פְּרָט לְאוֹתָם רְשָׁעִים שֶׁלֹּא הִרְהֲרוּ תְשׁוּבָה לְעוֹלָמִים, שֶׁיּוֹרְדִים וְלֹא עוֹלִים. וַאֲפִלּוּ צַדִּיקִים גְּמוּרִים יוֹרְדִים לְשָׁם. לָמָּה יוֹרְדִים? מִשּׁוּם שֶׁלּוֹקְחִים כַּמָּה רְשָׁעִים מִשָּׁם, וּמַעֲלִים אוֹתָם לְמַעְלָה. (ושם גורמים להם להרהר בתשובה) וּמִי הֵם? אוֹתָם שֶׁהִרְהֲרוּ תְשׁוּבָה בָּעוֹלָם הַזֶּה וְלֹא יָכְלוּ, וְהִסְתַּלְּקוּ מֵהָעוֹלָם. וְצַדִּיקִים יוֹרְדִים בִּגְלַל הָרְשָׁעִים לְתוֹךְ הַשְּׁאוֹל, וְלוֹקְחִים אוֹתָם, וּמַעֲלִים אוֹתָם מִשָּׁם.</p>"],[9522012465,"<p>אָמַר רַבִּי יוֹסֵי, כָּתוּב (קהלת ז) אַחַת לְאַחַת לִמְצֹא חֶשְׁבּוֹן. חֶשְׁבּוֹן שֶׁל גִּימַטְרִיָּאוֹת שֶׁעוֹמְדִים בַּלְּבָנָה, בְּאֵיזוֹ דַרְגָּה שֶׁלָּהּ הֵם? לֹא הֵשִׁיב לוֹ. אָמַר, שָׁמַעְתִּי וְלֹא נִזְכַּרְתִּי בַּדָּבָר. קָם אוֹתוֹ הַצֵּל וְהִכָּה בְעֵינָיו שֶׁל רַבִּי אַבָּא. נָפַל עַל פָּנָיו מִתּוֹךְ פַּחַד. עַד שֶׁהָיָה נוֹפֵל עַל פָּנָיו, נָפַל פָּסוּק בְּפִיו, שֶׁכָּתוּב (שיר השירים ז) עֵינַיִךְ בְּרֵכוֹת בְּחֶשְׁבּוֹן עַל שַׁעַר בַּת רַבִּים. וְאֵלּוּ הָעֵינַיִם שֶׁלָּהּ: פַּרְפְּרָאוֹת לְתוֹךְ חָכְמָה עֶלְיוֹנָה שֶׁנִּמְשְׁכָה מִלְמַעְלָה, וּמִתּוֹךְ חֶשְׁבּוֹן וּתְקוּפוֹת וְעִבּוּרִים מִתְמַלְּאִים, וְנַעֲשׂוּ בְרֵכוֹת, שֶׁיָּצְאוּ מֵימָיו לְכָל הַצְּדָדִים, (אותן עינים) עַד שֶׁנִּפְקְדוּ לְכָל חֶשְׁבּוֹן וְעִבּוּרֵי הַלְּבָנָה בִּלְבַד (שבחוץ) וְכוֹכָבִים וּמַזָּלוֹת לַעֲשׂוֹת חֶשְׁבּוֹן, וְזֶהוּ שַׁעַר בַּת רַבִּים, זוֹהִי הַלְּבָנָה שֶׁבַּחוּץ.</p>"],[9522012466,"<p>אָמַר רַבִּי אַבָּא לְרַבִּי יוֹסֵי, אוֹתָהּ מַרְגָּלִית קְדוֹשָׁה שֶׁהָיְתָה תַּחַת יָדְךְ, מִתּוֹךְ סִיּוּעַ שֶׁל הֶחָסִיד הַקָּדוֹשׁ שֶׁהוּא אֶצְלֵנוּ, כַּמָּה יָפֶה הוּא, וְחָזַרְנוּ בוֹ. שֶׁהֲרֵי וַדַּאי לֹא צָרִיךְ לְהוֹצִיא אִשָּׁה לְהַשְׁרוֹת בְּמָקוֹם אַחֵר, עַד שֶׁבַּעְלָהּ יְצַוֶּה וְיִתֵּן לָהּ רְשׁוּת לָלֶכֶת, וּמוֹדִיעִים לְבַעְלָהּ בַּהַתְחָלָה, וּמְפַיֵּס אוֹתוֹ שֶׁהוּא יְצַוֶּה אוֹתָהּ וְיִתֵּן לָהּ רְשׁוּת לָלֶכֶת לְאוֹתוֹ מָקוֹם. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא פִּיֵּס אֶת מֹשֶׁה, וְעַד שֶׁנָּתַן לוֹ רְשׁוּת וְאָמַר לוֹ: אֱמֹר אַתָּה, הִנְנִי נֹתֵן לוֹ אֶת בְּרִית שָׁלוֹם, לִשְׁרוֹת בְּתוֹכוֹ. וְעַד שֶׁנָּתַן לָהּ רְשׁוּת לָלֶכֶת לְשָׁם, לֹא הָלְכָה.</p>\n<p>מִנַּיִן לָנוּ? מִצַּדִּיקוֹ שֶׁל עוֹלָם, שֶׁנָּתַן לָהּ רְשׁוּת לִשְׁרוֹת בְּתוֹךְ צַדִּיקֵי הָעוֹלָם הַזֶּה. וְיָשְׁבָה עִמָּם כְּמוֹ כַלָּה בְּתוֹךְ הַקִּשּׁוּטִים שֶׁלָּהּ. וְצַדִּיק הָעוֹלָם רוֹאֶה וְשָׂמֵחַ בָּזֶה. אֲבָל בֵּין זְרוֹעוֹת בַּעְלָהּ שׁוֹכֶבֶת, וְחוֹזֶרֶת לִהְיוֹת אִתָּם, וְשָׁבָה לְבַעְלָהּ, כְּמוֹ שֶׁנֶּאֱמַר (אסתר ב) בָּעֶרֶב הִיא בָאָה וּבַבֹּקֶר הִיא שָׁבָה. בָּעֶרֶב הִיא בָאָה לְבַעְלָהּ, וּבַבֹּקֶר הִיא שָׁבָה לְצַדִּיקֵי הָעוֹלָם, וְהַכֹּל בִּרְשׁוּת בַּעְלָהּ. (זהו שכתוב (תהלים לז) וצדיק חונן ונותן).</p>\n<p>וּמֹשֶׁה כָּךְ אָמַר, הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי. כְּמוֹ שֶׁצַּדִּיק שֶׁלְּמַעְלָה נוֹתֵן, גַּם אֲנִי הִנְנִי נוֹתֵן, מַתָּנָה לְהַחֲזִיר מַתָּנָה הִיא, וּבִשְׁבִיל בְּרִית זוֹ הִרְוִיחַ כְּהֻנָּה עֶלְיוֹנָה. וְאִם לֹא תִהְיֶה אִתּוֹ, לֹא יִתְקַשֵּׁר פִּנְחָס בְּדַרְגַּת כְּהֻנָּה עֶלְיוֹנָה, שֶׁהֲרֵי בְּרִית דְּבֵקָה תָּמִיד בְּיָמִין עֶלְיוֹן. וְיָמִין עֶלְיוֹן זֶה עָתִיד לִבְנוֹת בֵּית מִקְדָּשׁ, שֶׁהוּא בְּרִית.</p>"],[9522012467,"<p>אָמַר רַבִּי אַבָּא, נִזְכַּרְתִּי בְּדָבָר אֶחָד שֶׁשָּׁמַעְתִּי מֵהַמְּנוֹרָה הַקְּדוֹשָׁה, שֶׁשָּׁמַע מִשְּׁמוֹ שֶׁל רַבִּי אֱלִיעֶזֶר. יוֹם אֶחָד בָּא לְפָנָיו גּוֹי אֶחָד וְאָמַר לוֹ: זָקֵן זָקֵן, שָׁלֹשׁ בְּעָיוֹת אֲנִי רוֹצֶה לִתְבֹּעַ מִמְּךְ. אַחַת, שֶׁאַתֶּם אוֹמְריִם שֶׁיִּבָּנֶה לָכֶם בֵּית מִקְדָּשׁ אַחֵר, וַהֲרֵי לֹא הָיוּ לְהִבָּנוֹת אֶלָּא רַק פַּעֲמַיִם - בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי. בַּיִת שְׁלִישִׁי (ובית רביעי) לֹא תִמְצָא בַּתּוֹרָה, וַהֲרֵי מַה שֶּׁהָיָה לוֹ לְהִבָּנוֹת כְּבָר נִבְנוּ, וּלְעוֹלָם אֵין בּוֹ יוֹתֵר, שֶׁהֲרֵי שְׁנֵי בָּתֵּי יִשְׂרָאֵל קָרָא לָהֶם הַפָּסוּק, וְכָתוּב (חגי ב) גָּדוֹל יִהְיֶה כְּבוֹד הַבַּיִת הַזֶּה הָאַחֲרוֹן מִן הָרִאשׁוֹן.</p>\n<p>וְעוֹד, שֶׁאַתֶּם אוֹמְרִים שֶׁאַתֶּם קְרוֹבִים לַמֶּלֶךְ הָעֶלְיוֹן יוֹתֵר מִכָּל שְׁאָר הָעַמִּים. מִי שֶׁקָּרוֹב לַמֶּלֶךְ הוּא שָׂמֵחַ (יותר) תָּמִיד, בְּלִי צַעַר, בְּלִי פַחַד, בְּלִי דחַק, וַהֲרֵי אַתֶּם בְּצַעַר וּבְדחַק וּבְיָגוֹן תָּמִיד יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם, וְלָנוּ לֹא הִתְקָרֵב צַעַר וְדחַק וְיָגוֹן כְּלָל. אָנוּ קְרוֹבִים לַמֶּלֶךְ הָעֶלְיוֹן, וְאַתֶּם רְחוֹקִים מִמֶּנּוּ, וְלָכֵן יֵשׁ לָכֶם צַעַר וְדחַק, אֵבֶל וְיָגוֹן, מַה שֶּׁאֵין לָנוּ.</p>\n<p>וְעוֹד, שֶׁאַתֶּם לֹא אוֹכְלִים נְבֵלוֹת וּטְרֵפוֹת כְּדֵי שֶׁתִּהְיוּ בְרִיאִים וְגוּפְכֶם יִהְיֶה בִּבְרִיאוּת. אָנוּ אוֹכְלִים כָּל מַה שֶּׁרוֹצִים, וְאָנוּ חֲזָקִים בְּכֹחַ בִּבְרִיאוּת, וְכָל אֵיבָרֵינוּ בְּעָמְדָם. וְאַתֶּם שֶׁלֹּא אוֹכְלִים, חַלָּשִׁים כֻּלְּכֶם בֶּחֳלָאִים רָעִים וּבְשֶׁבֶר יוֹתֵר מִכָּל שְׁאָר הָעַמִּים. עַם שֶׁשּׂוֹנֵא אֶתְכֶם אֱלֹהֵיכֶם בַּכֹּל. זָקֵן זָקֵן, אַל תֹּאמַר לִי דָבָר, שֶׁלֹּא אֶשְׁמַע אוֹתְךְ וְלֹא אֲקַבֵּל מִמְּךְ. הֵרִים רַבִּי אֶלְעָזָר עֵינָיו וְהִשְׁגִּיחַ בּוֹ, וְנַעֲשָׂה גַל שֶׁל עֲצָמוֹת.</p>\n<p>כֵּיוָן שֶׁנָּח רָגְזוֹ, הֶחֱזִיר רֹאשׁוֹ וּבָכָה, וְאָמַר, (תהלים ח) ה' אֲדנֵינוּ מָה אַדִּיר שִׁמְךְ בְּכָל הָאָרֶץ. כַּמָּה חָזָק כֹּחַ הַשֵּׁם הַקָּדוֹשׁ, חָזָק בְּכָל הָאָרֶץ, וְכַמָּה חֲבִיבִים דִּבְרֵי הַתּוֹרָה, שֶׁאֵין לְךְ דָּבָר קָטָן שֶׁלֹּא תִמְצָא בַתּוֹרָה, וְאֵין לְךְ דָּבָר קָטָן שֶׁבָּא בַתּוֹרָה שֶׁלֹּא יָצָא מִפִּי הַקָּדוֹשׁ בָּרוּךְ הוּא. דְּבָרִים אֵלּוּ שֶׁשָּׁאַל אוֹתוֹ רָשָׁע, אֲנִי שָׁאַלְתִּי יוֹם אֶחָד אֶת אֵלִיָּהוּ, וְאָמַר שֶׁהֲרֵי בִּישִׁיבַת הָרָקִיעַ הִסְתַּדְּרוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְכָךְ זֶה:</p>\n<p>שֶׁכְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹתָם בָּאָרֶץ כְּמַלְאָכִים קְדוֹשִׁים שֶׁל מַעְלָה, וְרָצָה לִבְנוֹת לָהֶם בַּיִת קָדוֹשׁ וּלְהוֹרִידוֹ מִתּוֹךְ שְׁמֵי הָרְקִיעִים וְלִנְטֹעַ אֶת יִשְׂרָאֵל, נְצִיב קָדוֹשׁ, כְּמוֹ הַדְּמוּת שֶׁלְּמַעְלָה. זֶהוּ שֶׁכָּתוּב (שמות טו) תְּבִאֵמוֹ וְתִטָּעֵמוֹ בְּהַר נַחֲלָתְךְ. בְּאֵיזֶה מָקוֹם. בְּמָכוֹן לְשִׁבְתְּךְ פָּעַלְתָּ ה'. בְּאוֹתוֹ שֶׁפָּעַלְתָּ אַתָּה ה', וְלֹא אַחֵר. מָכוֹן לְשִׁבְתְּךְ פָּעַלְתָּ ה' - זֶה בַּיִת רִאשׁוֹן. מִקְּדָשׁ ה' כּוֹנֲנוּ יָדֶיךְ - זֶה בַּיִת שֵׁנִי. וּשְׁנֵיהֶם אֻמָּנוּת הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם.</p>\n<p>וּמִשֶּׁהִרְגִּיזוּ לְפָנָיו בַּמִּדְבָּר - מֵתוּ, וְהִכְנִיס הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בְּנֵיהֶם לָאָרֶץ, (למדו מעשיהם) וְהַבַּיִת נִבְנָה עַל יְדֵי אָדָם, וְלָכֵן לֹא עָמַד. וּשְׁלֹמֹה הָיָה יוֹדֵעַ שֶׁמִשּׁוּם שֶׁמַּעֲשֶׂה זֶה שֶׁל אָדָם לֹא יַעֲמֹד, וְעַל זֶה אָמַר, (תהלים קכז) אִם ה' לֹא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ, שֶׁהֲרֵי אֵין לוֹ בּוֹ עֲמִידָה. בִּימֵי עֶזְרָא גָּרַם הַחֵטְא, וְהִצְטָרְכוּ הֵם לִבְנוֹת, וְלֹא הָיְתָה בּוֹ עֲמִידָה. וְעַד עַכְשָׁו בִּנְיַן הָרִאשׁוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הָיָה בָּעוֹלָם, וְלֶעָתִיד לָבא כָּתוּב (שם קמז) בּוֹנֵה יְרוּשָׁלם ה'. הוּא וְלֹא אַחֵר. וּלְבִנְיָן זֶה אָנוּ מְחַכִּים, וְלֹא בִּנְיַן אָדָם, שֶׁאֵין לוֹ עֲמִידָה כְּלָל.</p>\n<p>בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי יוֹרִיד אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא כְּאֶחָד מִלְמַעְלָה. בַּיִת רִאשׁוֹן בְּכִסּוּי, וּבַיִת שֵׁנִי בְּגִלּוּי. אוֹתוֹ בַּיִת יִהְיֶה בְגִלּוּי, שֶׁנִּקְרָא בַּיִת שֵׁנִי, שֶׁיֵּרָאֶה לְכָל הָעוֹלָם אֻמָּנוּת הַקָּדוֹשׁ בָּרוּךְ הוּא, חֶדְוָה שְׁלֵמָה וּרְצוֹן הַלֵּב בְּכָל עֲמִידָה.</p>\n<p>אוֹתוֹ בַּיִת רִאשׁוֹן בְּכִסּוּי עָלָה לְמַעְלָה, עַל גַּב אוֹתוֹ שֶׁבְּגִלּוּי. וְכָל הָעוֹלָם יִרְאוּ עַנְנֵי כָבוֹד שֶׁסּוֹבְבִים עַל גַּב אוֹתוֹ שֶׁבְּגִלּוּי. וּבְתוֹךְ אוֹתָם עֲנָנִים יִהְיֶה בַּיִת רִאשׁוֹן בְּמַעֲשֶׂה טָמִיר שֶׁעוֹלֶה עַד רוּם כְּבוֹד הַשָּׁמַיִם, וּלְבִנְיָן זֶה אָנוּ מְחַכִּים.</p>\n<p>וְעַד עַכְשָׁו לֹא הָיָה בָעוֹלָם, שֶׁאֲפִלּוּ עִיר שֶׁל יְרוּשָׁלַיִם לֹא תִהְיֶה אֻמָּנוּת אָדָם, שֶׁהֲרֵי כָּתוּב (זכריה ב) וַאֲנִי אֶהְיֶה לָּהּ נְאֻם ה' חוֹמַת אֵשׁ סָבִיב וְגוֹ'. אִם לְעִיר כָּתוּב כָּךְ - כָּל שֶׁכֵּן הַבַּיִת, שֶׁהוּא דִּיּוּר שֶׁלּוֹ. וּמַעֲשֶׂה זֶה הֲרֵי רָאוּי לִהְיוֹת בָּרֹאשׁ כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, וְהִסְתַּלֵּק עַד לְסוֹף הַיָּמִים בַּגְּאֻלָּה הָאַחֲרוֹנָה.</p>"],[9522012468,"<p>שְׁאֵלָה אַחֶרֶת, שֶׁוַּדַּאי אָנוּ קְרוֹבִים לַמֶּלֶךְ הָעֶלְיוֹן יוֹתֵר מִכָּל שְׁאָר הָעַמִּים - וַדַּאי כָּךְ זֶה, שֶׁיִּשְׂרָאֵל עָשָׂה אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לֵב כָּל הָעוֹלָם. וְכָךְ הֵם יִשְׂרָאֵל בֵּין שְׁאָר הָעַמִּים, כְּמוֹ לֵב בֵּין הָאֵיבָרִים. כְּמוֹ שֶׁהָאֵיבָרִים לֹא יְכוֹלִים לַעֲמֹד בָּעוֹלָם אֲפִלּוּ רֶגַע אֶחָד בְּלִי לֵב, כָּךְ הָעַמִּים כֻּלָּם לֹא יְכוֹלִים לַעֲמֹד בָּעוֹלָם בְּלִי יִשְׂרָאֵל. וְכָךְ גַּם יְרוּשָׁלַיִם בְּתוֹךְ שְׁאָר הָאֲרָצוֹת כְּמוֹ לֵב בְּתוֹךְ הָאֵיבָרִים, וְעַל כָּךְ הִיא בְּאֶמְצַע כָּל הָעוֹלָם, כְּמוֹ לֵב בְּתוֹךְ הָאֵיבָרִים.</p>\n<p>וְיִשְׂרָאֵל מִתְנַהֲגִים בְּתוֹךְ שְׁאָר הָעַמִּים כְּמוֹ הַלֵּב בְּתוֹךְ הָאֵיבָרִים. הַלֵּב הוּא רַךְ וְחַלָּשׁ, וְהוּא קִיּוּם כָּל הָאֵיבָרִים. לֹא יוֹדֵעַ מִצַּעַר וְצָרָה וְיָגוֹן כְּלָל, רַק הַלֵּב, שֶׁבּוֹ הַקִּיּוּם, שֶׁבּוֹ הַשֵּׂכֶל. שְׁאָר הָאֵיבָרִים לֹא הִתְקָרֵב בָּהֶם כְּלָל, שֶׁהֲרֵי אֵין בָּהֶם קִיּוּם וְלֹא יוֹדְעִים דָּבָר. כָּל שְׁאָר הָאֵיבָרִים לֹא קְרוֹבִים לַמֶּלֶךְ, שֶׁהוּא חָכְמָה וְשֵׂכֶל, שֶׁשָּׁרוּי בַּמֹּחַ, אֶלָּא רַק הַלֵּב. וּשְׁאָר הָאֵיבָרִים רְחוֹקִים מִמֶּנּוּ וְלֹא יוֹדְעִים כְּלָל. כָּךְ יִשְׂרָאֵל קְרוֹבִים לַמֶּלֶךְ הַקָּדוֹשׁ, וּשְׁאָר הָעַמִּים רְחוֹקִים מִמֶּנּוּ.</p>"],[9522012469,"<p>שְׁאֵלָה אַחֶרֶת, שֶׁיִּשְׂרָאֵל לֹא אוֹכְלִים נְבֵלוֹת וּטְרֵפוֹת וְטִנּוּף וְלִכְלוּךְ וּשְׁקָצִים וּרְמָשִׂים כִּשְׁאָר הָעַמִּים - כָּךְ הוּא, שֶׁהֲרֵי הַלֵּב הוּא רַךְ וְחַלָּשׁ, וּמֶלֶךְ וַעֲמִידַת כָּל שְׁאָר הָאֵיבָרִים. לֹא לוֹקֵחַ לִמְזוֹנוֹ, רַק בֵּרוּר וְצַחוּת כָּל הַדָּם, וּמְזוֹנוֹ נָקִי וּבָרוּר, וְהוּא רַךְ וְחַלָּשׁ מֵהַכֹּל, וּשְׁאָר הַפְּסֹלֶת מַנִּיחַ לְכָל הָאֵיבָרִים, וְכָל שְׁאָר הָאֵיבָרִים לֹא מַשְׁגִּיחִים בָּזֶה, אֶלָּא כָּל פְּסֹלֶת וְרַע שֶׁל הַכֹּל לוֹקְחִים, וְהֵם בְּחֹזֶק כְּמוֹ שֶׁרָאוּי לָהֶם.</p>\n<p>וְעַל זֶה בְּכָל שְׁאָר הָאֵיבָרִים יֵשׁ אֲבַעְבּוּעוֹת, שְׂאֵת אוֹ סַפַּחַת, סְגִירוּת הַצָּרַעַת. לַלֵּב אֵין כְּלוּם מִכָּל אֵלֶּה, אֶלָּא הוּא נָקִי וּבָרוּר מֵהַכֹּל, אֵין בּוֹ מוּם כְּלָל. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לָקַח אֶת יִשְׂרָאֵל, שֶׁהוּא נָקִי וּבָרוּר שֶׁאֵין בּוֹ מוּם, וְעָלָיו כָּתוּב (שיר השירים ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. בָּא רַבִּי יוֹסֵי, נָשַׁק יָדוֹ וְאָמַר, אִלּוּ לֹא בָאתִי לָעוֹלָם רַק כְּדֵי לִשְׁמֹעַ אֶת זֶה - דַּי לִי.</p>"],[9522012470,"<p>וְשֵׁם אִישׁ יִשְׂרָאֵל הַמֻּכֶּה וְגוֹ'. אָמַר רַבִּי יִצְחָק, פָּסוּק זֶה הָיָה צָרִיךְ לְהִכָּתֵב: וְשֵׁם אִישׁ יִשְׂרָאֵל אֲשֶׁר הִכָּה פִּנְחָס, וְלֹא הַמֻּכֶּה אֲשֶׁר הֻכָּה. לֹא נֶאֱמַר אֶלָּא בְּדֶרֶךְ נִסְתָּר.</p>\n<p>אֶלָּא כָּךְ אָמַר רַבִּי אֶלְעָזָר (רבי שמעון), כֵּיוָן שֶׁהֶעֱלָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת פִּנְחָס לִכְהֻנָּה גְדוֹלָה, לֹא רָצָה לְהַזְכִּיר לְפִנְחָס אֶת הֶרֶג הָאָדָם, שֶׁהֲרֵי לֹא רָאוּי לְכֹהֵן גָּדוֹל. טֶרֶם הֶעֱלָהוּ לִכְהֻנָּה גְדוֹלָה הִזְכִּיר לוֹ, וְאָמַר, וַיַּרְא פִּינְחָס (וגו') וַיִּקַּח רֹמַח וְגוֹ', וַיִּדְקֹר אֶת שְׁנֵיהֶם וְגוֹ'. כֵּיוָן שֶׁהֶעֱלָהוּ לִכְהֻנָּה גְדוֹלָה, לֹא הִזְכִּיר שְׁמוֹ בַּהֶרֶג, שֶׁלֹּא רָאוּי לוֹ, וְחָס עָלָיו כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכֹּהֵן גָּדוֹל לֹא רָאוּי לְהַזְכִּיר בְּהֶרֶג. וְשֵׁם הָאִשָּׁה הַמֻּכָּה, גַּם כָּךְ.</p>"],[9522012471,"<p>רַבִּי שִׁמְעוֹן הָיָה הוֹלֵךְ מִקַּפּוּטְקִיָּא לְלוֹד, וְרַבִּי יְהוּדָה הָלַךְ עִמּוֹ. עַד שֶׁהָיוּ הוֹלְכִים, פָּגַע בָּהֶם רַבִּי פִּנְחָס בֶּן יָאִיר, וּשְׁנֵי אֲנָשִׁים מְחַמְּרִים אַחֲרָיו. עָמַד חֲמוֹרוֹ שֶׁל רַבִּי פִּנְחָס. טָעֲנוּ אוֹתוֹ, וְלֹא הָלַךְ. אָמַר רַבִּי פִּנְחָס, הַשְׁאִירוּ אוֹתוֹ, שֶׁהֲרֵי רֵיחַ שֶׁל פָּנִים חֲדָשׁוֹת הֵרִיחַ, אוֹ שֶׁנֵּס יֵעָשֶׂה לָנוּ כָּאן. עַד שֶׁהֵם שָׁם, יָצָא רַבִּי שִׁמְעוֹן מֵאַחֲרֵי סֶלַע אֶחָד, נָטַל חֲמוֹר וְהָלַךְ. אָמַר רַבִּי פִּנְחָס, וְלֹא אָמַרְתִּי לָכֶם שֶׁהֲרֵי רֵיחַ שֶׁל פָּנִים חֲדָשׁוֹת הֵרִיחַ?!</p>\n<p>יָרַד וְגִפֵּף אוֹתוֹ רַבִּי פִּנְחָס וּבָכָה. אָמַר לוֹ, רָאִיתִי בַחֲלוֹמִי שֶׁבָּאָה שְׁכִינָה אֵלַי וְנָתְנָה לִי אוֹצָרוֹת גְּדוֹלִים, וְשָׂמַחְתִּי בָהּ. וְעַכְשָׁו כְּפִי שֶׁרָאִיתִי. אָמַר רַבִּי שִׁמְעוֹן, מִקּוֹל פַּרְסוֹת חֲמוֹרְךְ יָדַעְתִּי שֶׁזֶּה אַתָּה. כָּעֵת חֶדְוָה שְׁלֵמָה. אָמַר רַבִּי פִּנְחָס, נֵשֵׁב בְּמָקוֹם אֶחָד, שֶׁדִּבְרֵי הַתּוֹרָה צְרִיכִים צַחוּת. מָצְאוּ מַעְיַן מַיִם וְעֵץ, וְיָשְׁבוּ.</p>\n<p>אָמַר רַבִּי פִּנְחָס, מִסְתַּכֵּל הָיִיתִי שֶׁזֶּה לִתְחִיַּת הַמֵּתִים בְּדֶרֶךְ אַחֵר יַעֲשֶׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמַה שֶּׁהָיָה בְּעֵת רִאשׁוֹן, יִהְיֶה אָז אַחֲרוֹן. מִנַּיִן לָנוּ? מֵאוֹתָן עֲצָמוֹת, אוֹתָן עֲצָמוֹת שֶׁהֶחֱיָה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יְדֵי יְחֶזְקֵאל, שֶׁכָּתוּב (יחזקאל לז) וַתִּקְרְבוּ הָעֲצָמוֹת עֶצֶם אֶל עַצְמוֹ - בַּהַתְחָלָה, וְאַחַר כָּךְ כָּתוּב, וְרָאִיתִי וְהִנֵּה עֲלֵיהֶם גִּידִים וּבָשָׂר עָלָה וְגוֹ'. וַיִּקְרַם עֲלֵיהֶם עוֹר מִלְמָעְלָה וְרוּחַ אֵין בָּהֶם - שֶׁהֲרֵי מַה שֶּׁהִפְשִׁיט בַּתְּחִלָּה, יִהְיֶה אַחֲרוֹן. בַּתְּחִלָּה (הפשיט מרוח, ואחר כך) עוֹר, וְאַחַר כָּךְ בָּשָׂר. בַּתְּחִלָּה הִפְשִׁיט מֵרוּחַ, וְאַחַר כָּךְ עוֹר, וְאַחַר כָּךְ בָּשָׂר, וְאַחַר כָּךְ עֲצָמוֹת.</p>"],[9522012472,"<p>אָמַר רַבִּי שִׁמְעוֹן, בָּזֶה הִתְקַשּׁוּ הָאַחֲרוֹנִים, אֲבָל עֲצָמוֹת אֵלֶּה שֶׁהֶחֱיָה הַקָּדוֹשׁ בָּרוּךְ הוּא, נִסִּים וְאוֹתוֹת מְשֻׁנִּים עָשָׂה בָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא. בֹּא וּרְאֵה מַה כָּתוּב, (איוב י) זְכָר נָא כִּי כַחֹמֶר עֲשִׂיתָנִי וְאֶל עָפָר תְּשִׁיבֵנִי. מַה כָּתוּב אַחֲרָיו? הֲלֹא כֶחָלָב תַּתִּיכֵנִי וְכַגְּבִינָה תַּקְפִּיאֵנִי. עוֹר וּבָשָׂר תַּלְבִּישֵׁנִי וּבַעֲצָמוֹת וְגִידִים תְּשּכְכֵנִי. עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא, לְאַחַר שֶׁיִּבְלֶה הָאָדָם בֶּעָפָר וְיַגִּיעַ זְמַן שֶׁל תְּחִיַּת הַמֵּתִים, שֶׁאוֹתָהּ עֶצֶם שֶׁתִּשָּׁאֵר, לַעֲשׂוֹת אוֹתָהּ כְּמוֹ עִסָּה זוֹ, וּכְמוֹ גְּבִינָה שֶׁל חָלָב וּנְבִיעַת הֶחָלָב, שֶׁאוֹתָהּ נְבִיעָה נְקִיָּה וּמְצֻחְצַחַת בְּצַחוּת אוֹתָהּ עֶצֶם. תִּתְעָרֵב אוֹתָהּ הָעֶצֶם וְתִמָּחֶה כְּמוֹ חָלָב, וְאַחַר כָּךְ יַקְפִּיא אוֹתָהּ, וְתִצְטַיֵּר בְּצִיּוּר כְּמוֹ גְּבִינָה בְּקִפָּאוֹן, וְאַחַר כָּךְ יִמָּשֵׁךְ עָלֶיהָ עוֹר וּבָשָׂר וַעֲצָמוֹת וְגִידִים.</p>\n<p>זֶהוּ שֶׁכָּתוּב הֲלֹא כֶחָלָב תַּתִּיכֵנִי וְכַגְּבִינָה תַּקְפִּיאֵנִי. הִתַּכְתַּנִי לֹא כָתוּב, אֶלָּא תַּתִּיכֵנִי. הִקְפִּיתַנִי לֹא כָתוּב, אֶלָּא תַּקְפִּיאֵנִי. הִלְבַּשְׁתַּנִי לֹא כָתוּב, אֶלָּא תַּלְבִּישֵׁנִי. סוֹכַכְתַּנִי לֹא כָתוּב, אֶלָּא תְּסוֹכְכֵנִי. כֻּלָּם מַשְׁמָע שֶׁלְּאַחַר זְמַן.</p>\n<p>וְאַחַר כָּךְ מַה כָּתוּב? חַיִּים וָחֶסֶד עָשִׂיתָ עִמָּדִי - זוֹ רוּחַ הַחַיִּים. (ואם תאמר), הֲרֵי כָּתוּב עָשִׂיתָ עִמָּדִי, וְלֹא כָתוּב תַּעֲשֶׂה! אֶלָּא כָּךְ אָמַר, חַיִּים וָחֶסֶד עָשִׂיתָ עִמָּדִי. בְּאוֹתוֹ עוֹלָם זָרַקְתָּ בִּי רוּחַ חַיִּים, אֲבָל וּפְקֻדָּתְךְ - שֶׁמַּלְכַּת הַמֶּלֶךְ - שָׁמְרָה רוּחִי, הִיא שָׁמְרָה אֶת רוּחִי בְּאוֹתוֹ עוֹלָם. מַה זֶּה וּפְקֻדָּתְךְ? שֶׁאַתָּה עָתִיד לִפְקֹד אוֹתָהּ בַּתְּחִלָּה.</p>\n<p>(שמרה רוחי) וְסוֹד דָּבָר זֶה - כָּל נַפְשׁוֹת הַצַּדִּיקִים גְּנוּזוֹת וּטְמִירוֹת תַּחַת כִּסֵּא הַמֶּלֶךְ, וְהִיא שׁוֹמֶרֶת אוֹתָם לַהֲשִׁיבָן לִמְקוֹמוֹתֵיהֶן. זֶהוּ שֶׁכָּתוּב וּפְקֻדָּתְךְ שָׁמְרָה רוּחִי. מַה זֶּה וּפְקֻדָּתְךְ? כְּמוֹ שֶׁנֶּאֱמַר (תהלים קט) פְּקֻדָּתוֹ יִקַּח אַחֵר. פְּקֻדָּתְךְ - זוֹהִי מַלְכַּת הַמֶּלֶךְ, שֶׁכָּל הָרוּחוֹת הֵם פִּקְדוֹנוֹת בְּיָדֶיהָ. זֶהוּ שֶׁכָּתוּב (שם לא) בְּיָדְךְ אַפְקִיד רוּחִי וְגוֹ', וְהִיא שׁוֹמֶרֶת אוֹתָם, בִּגְלַל זֶה שָׁמְרָה רוּחִי, וְהִיא שׁוֹמֶרֶת אוֹתָהּ.</p>\n<p>כְּמוֹ זֶה אָמַר דָּוִד, (שם פו) שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי. שָׁמְרָה - זוֹ מַלְכַּת הַמֶּלֶךְ, שֶׁהִיא שָׁמְרָה נַפְשִׁי, בִּגְלַל כִּי חָסִיד אָנִי. וּבְכָל מָקוֹם שֶׁכָּתוּב סְתָם - זוֹ הַמַּלְכָּה, כְּמוֹ שֶׁנֶּאֱמַר וַיִּקְרָא אֶל מֹשֶׁה, (שמות טו) וַיֹּאמֶר אִם שָׁמֹעַ תִּשְׁמַע בְּקוֹל ה' אֱלֹהֶיךְ.</p>\n<p>בָּכָה רַבִּי פִּנְחָס וְאָמַר, וְלֹא אָמַרְתִּי לְךְ שֶׁהַשְּׁכִינָה נָתְנָה לִי אוֹצָרוֹת וּמַתָּנוֹת?! אַשְׁרֵי חֶלְקִי שֶׁזָּכִיתִי לִרְאוֹתְךְ וְשָׁמַעְתִּי אֶת זֶה. אָמַר לוֹ, בְּאוֹתוֹ זְמַן מֵילָא אוֹתָהּ עֶצֶם, מַה יַּעֲשֶׂה מִשְּׁאָר הָעֲצָמוֹת שֶׁיִּמָּצְאוּ? אָמַר לוֹ, כֻּלָּן יִכָּלְלוּ בְּאוֹתָהּ נְבִיעָה שֶׁל עֶצֶם זוֹ, וְיִכָּלְלוּ יַחַד אִתָּהּ, וְהַכֹּל יֵעָשֶׂה עִסָּה אַחַת, וְשָׁם יִצְטַיֵּר צִיּוּר, כְּמוֹ שֶׁנֶּאֱמַר. זֶהוּ שֶׁכָּתוּב (ישעיה נח) וְעַצְמֹתֶיךְ יַחֲלִיץ. מַה זֶּה יַחֲלִיץ? כְּמוֹ שֶׁנֶּאֱמַר (הושע ה) חָלַץ מֵהֶם. כֻּלָּם יָעָבְרוּ מִקִּיּוּמָם וְיִכָּלְלוּ בָעֶצֶם הַזֹּאת לִהְיוֹת עִסָּה אַחַת, וְאָז (ישעיה שם) וְהָיִיתָ כְּגַן רָוֶה וּכְמוֹצָא מַיִם וְגוֹ'. (אמר הרועה הנאמן)</p>\n<p>אָמַר רוֹעֶה הַנֶּאֱמָן, אוֹי לָהֶם לִבְנֵי אָדָם שֶׁהֵם אֲטוּמֵי לֵב, סְתוּמֵי עֵינַיִם, שֶׁלֹּא יוֹדְעִים שֶׁכְּשֶׁבָּא הַלַּיְלָה שַׁעֲרֵי הַגֵּיהִנֹּם נִפְתָּחִים, שֶׁהִיא מָרָה. וַעֲשָׁנִים שֶׁלָּהּ שֶׁמִּתְפַּשְּׁטִים עוֹלִים עַד לַמֹּחַ. וְכַמָּה חֵילוֹת יֵצֶר הָרָע מִתְפַּשְּׁטִים בְּכָל אֵיבְרֵי הַגּוּף, וְשַׁעֲרֵי גַּן עֵדֶן, שֶׁהוּא עֵינֵי הַלֵּב, נִסְתָּמִים וְלֹא נִפְתָּחִים. שֶׁכָּל אוֹרוֹת הָעֵינַיִם יוֹצְאִים מֵהַלֵּב.</p>"],[9522012473,"<p>וְשַׁעָרֵי הַלֵּב, אוֹתָם עֵינַיִם נִסְתָּמוֹת, מִשּׁוּם שֶׁלֹּא מִסְתַּכְּלוֹת בַּמַּזִּיקִים הַלָּלוּ, שֶׁהֵם לִילִית, וְלֹא שׁוֹלְטִים בְּאוֹרוֹת הַלֵּב, שֶׁהֵם מַלְאָכִים שֶׁמִּתְפַּשְּׁטִים בְּכָל הָאֵיבָרִים כְּעַנְפֵי הָעֵץ לְכָל צַד. בְּאוֹתוֹ זְמַן הֵם כֻּלָּם אוֹרוֹת נִסְתָּרִים בַּלֵּב, וּמִתְכַּנְּסִים אֵלָיו כְּמוֹ יוֹנִים לַאֲרֻבּוֹתֵיהֶם, כְּמוֹ נֹחַ וְאִשְׁתּוֹ וְכָל מִין וּמִין שֶׁנִּכְנְסוּ עִמּוֹ לַתֵּבָה.</p>\n<p>וּמַזִּיקִים שֶׁמִּתְגַּבְּרִים עַל כָּל אֵיבְרֵי הַגּוּף, כְּמוֹ מֵי הַמַּבּוּל שֶׁגָּבְרוּ עָלָיו ט\"ו אַמָּה, מִשּׁוּם שֶׁחָטָא בְּיָ\"הּ, וְהִסְתַּלֵּק יָ\"הּ מֵהַגּוּף וְנִשְׁאַר אִלֵּ\"ם, בְּלִי רְאִיָּה וּשְׁמִיעָה וְרֵיחַ וְדִבּוּר. וְסוֹד הַדָּבָר - (תהלים לט) נֶאֱלַמְתִּי דוּמִיָּה (החשיתי מטוב וכאבי נעכר). דּוּמִיָּ\"ה - דּוֹ\"ם יָ\"הּ. כְּאוֹתוֹ זְמַן, חֲמֵשׁ עֶשְׂרֵה אַמָּה גָּבְרוּ הַמַּזִּיקִים עַל הַגּוּף, וְהֵם כְּמוֹ תֶּלֶם לַעֲרוּגָה.</p>\n<p>וּכְמוֹ שֶׁנֹּחַ שָׁלַח אֶת הַיּוֹנָה בִּשְׁלִיחוּתוֹ, גַּם כָּךְ שָׁלַח נְשָׁמָה בָּאָדָם, רוּחוֹ בִּשְׁלִיחוּתוֹ, וְלָכֵן צָרִיךְ אָדָם לְהַפְקִיד אוֹתָהּ בַּמַּלְכָּה. זֶהוּ שֶׁכָּתוּב (תהלים לא) בְּיָדְךְ אַפְקִיד רוּחִי. וְאִם הִיא אֲסוּרָה בַּחֲטָאֵי הַגּוּף וּבִידֵי חֵילוֹת יֵצֶר הָרָע, מַה כָּתוּב? בְּיָדְךְ אַפְקִיד רוּחִי פָּדִיתָה אוֹתִי ה' אֵל אֱמֶת.</p>\n<p>וְעוֹד, בִּזְמַן שֶׁהִיא חַיֶּבֶת, מַה כָּתוּב בְּרוּחוֹ? (משלי יא) יָד לְיָד לֹא יִנָּקֶה רָע. שֶׁהוֹלֵךְ מִיָּד לְיָד בְּמַחֲנוֹת הַיֵּצֶר הָרָע שֶׁשּׁוֹרִים עָלָיו בַּחֲטָאָיו, וְזוֹרְקִים אוֹתוֹ מִמָּקוֹם לְמָקוֹם. וְזֶהוּ שֶׁמַּרְאֶה עַצְמוֹ בִּמְדִינָה אַחֶרֶת אוֹ בְּמַלְכוּת אַחֶרֶת, וְלִפְעָמִים בָּאַשְׁפָּה, כְּפִי עֲונוֹתָיו. וְאִם הוּא צַדִּיק, כָּל מַחֲנוֹת הַיֵּצֶר הַטּוֹב כֻּלָּם, וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת לְקַבֵּל רוּחַ, וּמַעֲלִים אוֹתוֹ לְמַעֲלוֹת, לִמְקוֹם חַיּוֹת הַכִּסֵּא, וְשָׁם רוֹאֶה כַּמָּה חֶזְיוֹנוֹת, דִּמְיוֹנוֹת וּמַרְאוֹת נְבוּאָה. וּמִשּׁוּם זֶה פֵּרְשׁוּהָ רַבּוֹתֵינוּ שֶׁחֲלוֹם אֶחָד מִשִּׁשִּׁים שֶׁל נְבוּאָה. וְעוֹד, (תהלים פו) שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי - אַף עַל גַּב שֶׁפֵּרְשׁוּהָ בַּגְּמָרָא, וְלֹא חָסִיד אָנִי, שֶׁכָּל מַלְכֵי מִזְרָח וּמַעֲרָב יְשֵׁנִים עַד אַרְבַּע שָׁעוֹת, וַאֲנִי (שם קיט) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ. וְלֹא עוֹד, אֶלָּא שֶׁכָּל מַלְכֵי מִזְרָח וּמַעֲרָב וְכוּ', וַאֲנִי יָדַי מְלֻכְלָכוֹת בְּדַם שָׁפִיר וְשִׁלְיָה כְּדֵי לְטַהֵר אִשָּׁה לְבַעְלָהּ. מִיָּד נִזְדַּמְּנָה לוֹ צְפַרְדֵּעַ אַחַת וְאָמְרָה לוֹ, לָמָּה אַתָּה מְשַׁבֵּחַ עַצְמְךְ לוֹמַר חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ? וַאֲנִי כָּל לַיְלָה לֹא יְשֵׁנָה לְשַׁבֵּחַ לוֹ וּלְנַגֵּן לְפָנָיו! אָמַר דָּוִד, אוֹי לַמְמֻנֶּה שֶׁל אוֹתָהּ צְפַרְדֵּעַ שֶׁלֹּא יוֹדֵעַ מַה שֶּׁאֲנִי אוֹמֵר, שֶׁלֹּא אָמַרְתִּי כִּי חָסִיד אָנִי.</p>\n<p>אֶלָּא מִשּׁוּם שֶׁפֵּרְשׁוּהוּ חֲכָמִים, וְלֹא עַם הָאָרֶץ הָאָרֶץ חָסִיד, שֶׁהַתּוֹרָה נִתְּנָה מִימִין הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא חֶסֶד. וּמִשּׁוּם זֶה מִי שֶׁמִּתְעַסֵּק בַּתּוֹרָה נִקְרָא חָסִיד. בִּגְלַל זֶה אָמַרְתִּי לְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁמְרָה נַפְשִׁי, וְלֹא תָדוּן אוֹתָהּ כְּמַעֲשֵׂה אֵלּוּ עַמֵּי הָאֲרָצוֹת שֶׁנֶּאֱמַר בָּהֶם וְלֹא עַם הָאָרֶץ חָסִיד. וְאִם תֹּאמַר, כַּמָּה עַמֵּי הָאֲרָצוֹת הֵם שֶׁעָשׂוּ חֶסֶד - אֶלָּא כָּךְ פֵּרְשׁוּהוּ: אֵיזֶהוּ חָסִיד? זֶה הַמִּתְחַסֵּד עִם קוֹנוֹ. כְּמוֹ דָּוִד שֶׁהָיָה מְחַבֵּר. וּמֶה הָיָה מְחַבֵּר? תּוֹרָה שֶׁל לְמַעְלָה הָיָה מְחַבֵּר עִם הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם זֶה, שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי.</p>"],[9522012474,"<p>וּכְשֶׁאָדָם מֵת, מַה כָּתוּב בַּנֶּפֶשׁ הַזּוֹ? (משלי ו) בְּהִתְהַלֶּכְךְ תַּנְחֶה אֹתָךְ בְּשָׁכְבְּךְ תִּשְׁמֹר עָלֶיךְ, וַהֲקִיצוֹתָ - לִתְחִיַּת הַמֵּתִים - הִיא תְשִׂיחֶךְ. זֶה לִתְחִיַּת הַמֵּתִים יָפֶה, שֶׁיַּעֲמִיד אֶת הָאָדָם, אֲבָל לִשְׂכַר הַנְּשָׁמָה בָּעוֹלָם הַבָּא מַה יִּהְיֶה?</p>\n<p>אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא מַלְבִּישׁ אוֹתָהּ כְּמוֹ בַּתְּחִלָּה בְּעַנְנֵי כָבוֹד. כְּמוֹ בַּתְּחִלָּה תִּכָּנֵס בְּמַרְאָה, שֶׁהוּא כְּמוֹ הַגּוּף, כְּלוּלָה בְּרמ\"ח אֵיבָרִים. גַּם כָּךְ תִּכָּנֵס בַּמַּרְאָה כְּלוּלָה בְּמָאתַיִם אַרְבָּעִים וּשְׁמוֹנֶה מִצְווֹת, וּבְמָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אוֹרוֹת שֶׁנִּפְרָדִים מֵאוֹתָהּ מַרְאָה, שֶׁנֶּאֱמַר בָּהּ (במדבר יב) וַיֹּאמֶר אִם יִהְיֶה נְבִיאֲכֶם ה' בַּמַּרְאָה אֵלָיו אֶתְוַדָּע. וּבִלְבוּשֵׁי עַנְנֵי כָבוֹד - (בראשית ט) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם, זוֹ אַסְפַּקְלַרְיָה הַמְּאִירָה. (במדבר יב) בַּחֲלוֹם אֲדַבֵּר בּוֹ - זוֹ אַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה, כְּלוּלָה מִשְּׁלֹשׁ מֵאוֹת שִׁשִּׁים וַחֲמִשָּׁה אוֹרוֹת, כְּחֶשְׁבּוֹן יְשֵׁנָה, וְהַיְנוּ (שיר השירים ה) אֲנִי יְשֵׁנָה. אֶחָד בָּעוֹלָם הַזֶּה וְאֶחָד בָּעוֹלָם הַבָּא. וְהֵם בְּמַעֲשֵׂה יָדָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְסוֹד שֶׁלָּהֶם - (שמות ג) זֶה שְּׁמִי לְעֹלָם. יָ\"הּ עִם שְׁמִי - שְׁלֹשׁ מֵאוֹת וַחֲמִשָּׁה וְשִׁשִּׁים. ו\"ה עִם זִכְרִי - מָאתַיִם וּשְׁמוֹנָה וְאַרְבָּעִים. וְכָרוֹזִים יוֹרְדִים וְעוֹלִים לְפָנָיו: תְּנוּ כָבוֹד (לדמות) לִכְבוֹד הַמֶּלֶךְ.</p>\n<p>וְהַיְנוּ (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ. וְהוּא שֶׁעָשָׂה אוֹתוֹ בִּשְׁתֵּי דְמֻיּוֹת, בִּשְׁנֵי גַנִּים (פנים), שֶׁנֶּאֱמַר עֲלֵיהֶם (שיר השירים ה) הַיּוֹשֶׁבֶת בַּגַּנִּים. הִיא עִלַּת עַל הַכֹּל, שֶׁנֶּאֱמַר עָלֶיהָ (דברים ד) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה. וְעַל שְׁאָר הַדְּמֻיּוֹת כָּתוּב, תְּמוּנַת כָּל וְגוֹ'. (במדבר יב) וּתְמוּנַת ה' יַבִּיט. וְתרי\"ג מַלְאָכִים מַעֲלִים אֶת הַנְּשָׁמָה בִּדְמֻיּוֹת אֵלּוּ, כֻּלָּם וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת, לְקַיֵּם אֶת הַפָּסוּק שֶׁכָּתוּב בָּהֶם (שמות יט) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים וָאָבִא אֶתְכֶם אֵלָי.</p>\n<p>כְּמוֹ שֶׁיָּצְאוּ מִמִּצְרַיִם וְהָלְכוּ בְּעַנְנֵי כָבוֹד, וּבְכָל אוֹתוֹ כָּבוֹד כְּמוֹ זֶה תִּהְיֶה יְצִיאַת הַנְּשָׁמָה מִגּוּף שֶׁל טִפָּה סְרוּחָה לָלֶכֶת לִשְׁנֵי גַנִּים, שֶׁנִּבְרְאוּ שָׁמַיִם וָאָרֶץ שֶׁלָּהֶם בְּשֵׁם ה', וּבִגְלָלוֹ נֶאֱמַר (תהלים צו) יִשְׂמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ. בְּאוֹתוֹ זְמַן יִתְקַיֵּם בָּאָדָם (ישעיה ל) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךְ, לְגַבֶּיךְ, (שם ו) בִּשְׁתַּיִם יְכַסֶּה פָּנָיו, אֶלָּא - וְהָיוּ עֵינֶיךְ רֹאוֹת אֶת מוֹרֶיךְ. וּמִצַּד הַמַּרְאוֹת הַלָּלוּ זָכָה מֹשֶׁה רַבֵּנוּ עָלָיו הַשָּׁלוֹם, רַבָּן שֶׁל נְבִיאִים וַחֲכָמִים. אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, אַתָּה הוּא שֶׁזָּכִיתָ בְּחַיֶּיךְ לְמַה שֶּׁיִּזְכּוּ צַדִּיקִים אַחַר חַיֵּיהֶם, אַשְׁרֵי חֶלְקְךְ!</p>"],[9522012475,"<p>דָּבָר אַחֵר, שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי - לָמָּה? כְּדֵי שֶׁאֶתְחַסֵּד עִם אֲנִ\"י, שֶׁנֶּאֱמַר בּוֹ אֲנִ\"י וָה\"וּ. אוֹי לוֹ לְמִי שֶׁמַּפְרִיד אֲנִי מֵהוּא, שֶׁנֶּאֱמַר (תהלים ק) הוּא עָשָׂנוּ וְלֹא אֲנַחְנוּ. שֶׁהַכֹּל אֶחָד בְּלִי פֵרוּד. זֶהוּ שֶׁכָּתוּב (דברים לב) רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא (וגו'), אֲנִי אָמִית וַאֲחַיֶּה מָחַצְתִּי וַאֲנִי אֶרְפָּא וְאֵין מִיָּדִי מַצִּיל. אֲנִי יְהֹוָ\"ה, אֲנִי הוּא וְלֹא אַחֵר. וְזֶה אֲנִי מִן אֲדנָ\"י. ה' - עַמּוּד הָאֶמְצָעִי.</p>\n<p>וּמִשּׁוּם שֶׁיְהֹוָ\"ה הוּא לְיָמִין, שֶׁהוּא חֶסֶד, אָמַר, שָׁמְרָה נַפְשִׁי שֶׁאֶתְחַסֵּד בְּךְ עִם אָנִ\"י, וְהוּא אֲדֹנָ\"י לִגְבוּרָה. וּבְתִפְאֶרֶת מִתְחַבְּרִים שְׁנֵי שֵׁמוֹת - יאהדונה\"י. וְסוֹד הַדָּבָר בְּחֶסֶד וּבִגְבוּרָה (יחזקאל א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת מִלְמָעְלָה. וּבְתִפְאֶרֶת שֶׁנִּקְרָא (שמות טו) ה' אִישׁ מִלְחָמָה, מַה כָּתוּב? (יחזקאל א) שְׁתַּיִם חֹבְרוֹת אִישׁ, שְׁנֵי שֵׁמוֹת מִתְחַבְּרִים בּוֹ כְּאֶחָד. וּשְׁתַּיִם מְכַסּוֹת אֵת גְּוִיּתֵיהֶנָה. תִּפְאֶרֶת נִקְרָא גּוּף, (דניאל י) וּגְוִיָּתוֹ כְתַרְשִׁישׁ, יאההויה\"ה.</p>"],[9522012476,"<p>הוֹשַׁע עַבְדְּךְ אַתָּה אֱלֹהַי. שַׂמֵּחַ נֶפֶשׁ עַבְדֶּךְ. תְּנָה עֻזְּךְ לְעַבְדֶּךְ (תהלים פו). שָׁלֹשׁ פְּעָמִים נַעֲשָׂה דָוִד עֶבֶד בַּתְּהִלָּה הַזּוֹ, כְּנֶגֶד שָׁלֹשׁ פְּעָמִים שֶׁהֶעֱמִידוּ בַּעֲלֵי הַמִּשְׁנָה שֶׁצָּרִיךְ אָדָם לִהְיוֹת עֶבֶד בַּתְּפִלָּה: בַּבְּרָכוֹת הָרִאשׁוֹנוֹת, כְּמוֹ עֶבֶד שֶׁמְּסַדֵּר שִׁבְחוֹ לִפְנֵי רַבּוֹ. בָּאֶמְצָעִיּוֹת, כְּמוֹ עֶבֶד שֶׁמְּבַקֵּשׁ פְּרָס מֵרַבּוֹ. וּבָאַחֲרוֹנוֹת, כְּמוֹ עֶבֶד שֶׁמּוֹדֶה לִפְנֵי רַבּוֹ בַּפְּרָס שֶׁקִּבֵּל מִמֶּנּוּ וְהוֹלֵךְ לוֹ.</p>\n<p>וְשָׁלֹש פְּעָמִים שֶׁעֶבֶד צָרִיךְ לַעֲשׂוֹת מִצַּד הָעֲבוֹדָה, שֶׁפֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה שֶׁאֵין עֲבוֹדָה אֶלָּא תְּפִלָּה, וּשְׁלֹשָׁה אָבוֹת נִקְרְאוּ עֲבָדִים מִצִּדָּהּ, עַל שֵׁם הַשְּׁכִינָה, שֶׁהִיא עֲבוֹדַת ה'. וְגַם כָּךְ מֹשֶׁה עֶבֶד ה'. וְלָכֵן (ויקרא כה) כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים. אֲבָל לְגַבֵּי אֲחֵרִים - כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים הֵם, מִצַּד הַמַּלְכוּת. וְהִיא לָמָּה נִקְרֵאת עֲבוֹדָה? כְּדֶרֶךְ אִשָּׁה לַעֲבֹד לְבַעְלָהּ, וְדֶרֶךְ בָּנִים לַעֲבֹד אֶת אֲבִיהֶם.</p>"],[9522012477,"<p>וְדָוִד נַעֲשָׂה עָנִי, חָסִיד וְעֶבֶד. זֶהוּ שֶׁכָּתוּב, (תהלים פו) תְּפִלָּה לְדָוִד הַטֵּה אֲדנָי אָזְנְךְ עֲנֵנִי כִּי עָנִי וְאֶבְיוֹן אָנִי. שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי. הוֹשַׁע עַבְדְּךְ אַתָּה אֱלֹהַי הַבּוֹטֵחַ אֵלֶיךְ. נַעֲשָׂה עָנִי לְשַׁעַר הַמֶּלֶךְ, שֶׁנֶּאֱמַר בָּהּ (שם נא) אֲדֹנָי שְׂפָתַי תִּפְתָּח. אֲדנָ\"י הֵיכָ\"ל, נַעֲשָׂה עָנִי לְשַׁעַר הַמֶּלֶךְ. וּמַה כָּתוּב? הַטֵּה אֲדנָי אָזְנְךְ עֲנֵנִי, וְזוֹהִי שְׁכִינָה תַחְתּוֹנָה, שֶׁהִיא אֹזֶן לְקַבֵּל תְּפִלּוֹת וְלִשְׁמֹעַ אוֹתָן, כְּמוֹ שֶׁכָּתוּב (שם כב) כִּי לֹא בָזָה וְלֹא שִׁקַּץ עֱנוּת עָנִי וְלֹא הִסְתִּיר פָּנָיו מִמֶּנּוּ וּבְשַׁוְּעוֹ אֵלָיו שָׁמֵעַ.</p>\n<p>שֶׁהוּא נַעֲשָׂה עָנִי וָדַל מִצַּד אוֹת ד' מִן אֶחָד, לִשְׁאֹל מִן א\"ח, שֶׁהוּא עַמּוּד הָאֶמְצָעִי, לְקַיֵּם בּוֹ (שם קטז) דַּלּוֹתִי וְלִי יְהוֹשִׁיעַ, שֶׁלֹּא יָמוּת מָשִׁיחַ בֶּן אֶפְרַיִם. וְשָׁאַל מִמֶּנּוּ בְּאוֹתוֹ הַשַּׁעַר בִּשְׁבִיל יִשְׂרָאֵל הָעֲנִיִּים, לְקַיֵּם בָּהֶם (שמואל ב כב) וְאֶת עַם עָנִי תּוֹשִׁיעַ.</p>\n<p>וְאַחַר כָּךְ שָׁאַל בִּשְׁבִיל הַכֹּהֲנִים, שֶׁתַּחֲזֹר עֲבוֹדָה לִמְקוֹמָהּ, וְנַעֲשָׂה עֶבֶד. לְאַחַר שֶׁנָּתַן לָהֶם תּוֹרָה מִצַּד הַחֶסֶד, לַעֲשׂוֹת גְּמוּל עִם דָּלֶ\"ת מֵהַתּוֹרָה, וְלָכֵן נַעֲשָׂה חָסִיד. כָּךְ הִגִּיעַ לְשָׁלֹשׁ סְפִירוֹת הָעֶלְיוֹנוֹת. פָּתַח וְאָמַר, (שם קלא) ה' לֹא גָבַהּ לִבִּי וְלֹא רָמוּ עֵינַי וְלֹא הִלַּכְתִּי בִּגְדלוֹת וּבְנִפְלָאוֹת מִמֶּנִּי.</p>\n<p>שְׁלֹמֹה אָמַר, הֲרֵי בִּינָה הִיא שֶׁל מֹשֶׁה, אֶשְׁאַל בְּחָכְמָה עֶלְיוֹנָה, שֶׁהִיא מֵעַל דַּרְגָּתוֹ. מַה כָּתוּב? (קהלת ז) אָמַרְתִּי אֶחְכָּמָה וְהִיא רְחוֹקָה מִמֶּנִּי. וַהֲרֵי כָּתוּב (מלכים א ה) וַה' נָתַן חָכְמָה לִשְׁלֹמֹה! חָכְמָה קְטַנָּה. וְרָצָה לְהַעֲלוֹתָהּ מִלְּמַטָּה לְמַעְלָה שֶׁהִתְרַחֲקָה מִמֶּנּוּ, מִשּׁוּם שֶׁאֲפִלּוּ לַבִּינָה אֵין אָדָם בָּעוֹלָם יָכוֹל לַעֲלוֹת פְּרָט לְמֹשֶׁה, כָּל שֶׁכֵּן לְמַעְלָה מִמֶּנָּה, שֶׁהִיא חָכְמָה עֶלְיוֹנָה, שֶׁמִּצִּדָּהּ חָכָם עָדִיף מִנָּבִיא. וְאַף עַל גַּב שֶׁפֵּרְשׁוּהָ בְּדֶרֶךְ דְּרָשׁ עַל פָּרָה אֲדֻמָּה, שִׁבְעִים פָּנִים לַתּוֹרָה.</p>"],[9522012478,"<p>רַבִּי אֶלְעָזָר, קוּם לְחַדֵּשׁ דְּבָרִים לִפְנֵי הַשְּׁכִינָה, שֶׁתִּהְיֶה עֵזֶר לְאָבִיךְ, שֶׁהַשֵּׁם גּוֹרֵם - עֵזֶר אֵל. אֵל מִיָּמִין, עֵזֶר מִשְּׂמֹאל. זֶהוּ שֶׁכָּתוּב (בראשת ב) אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ. בַּמֶּה? בְּזֶרַע יָפֶה, שֶׁהוּא הֵפֶךְ עֵזֶר. וְיָקוּם רַבִּי יוֹסֵי עִמְּךְ, שֶׁהוּא כִּסֵּא שָׁלֵם לְרִבּוֹנוֹ, שֶׁכָּךְ עוֹלֶה יוֹסֵי לְחֶשְׁבּוֹן כִּסֵּ\"א, אֱלֹהִים בְּחֶשְׁבּוֹן.</p>\n<p>וְיָקוּם עִמּוֹ רַבִּי יְהוּדָה, שֶׁבּוֹ הוֹ\"ד, וּבוֹ יָ\"הּ, וּבוֹ יְהֹוָ\"ה ד', אַרְבַּע חַיּוֹת. וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת, כֻּלָּם לְקַבֵּל אוֹתוֹ. וּמִמֶּנּוּ דָּוִד, שֶׁהוֹדָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא, דַּרְגָּה בְּהוֹדָאוֹת, שֶׁהוּא מִצַּד הוֹד. וְיָקוּם עִמּוֹ רַבִּי אֶלְעַאי, בְּגִימַטְרִיָּא יַבּ\"ק, בָּקִי בַּהֲלָכָה.</p>\n<p>וְיָקוּם עִמּוֹ רַבִּי יוּדַאי, שֶׁחֶשְׁבּוֹנוֹ אֵ\"ל. כְּמוֹ מִיכָאֵל, מַלְאָכִים רְשׁוּמִים בְּאֵל, כְּמוֹ (שם לא) יֵשׁ לְאֵל יָדִי. וְסוֹד שֶׁל אֵל - א' דְּמוּת אָדָם, ל' שָׁלֹשׁ חַיּוֹת, שֶׁהֵם אַרְבַּע פָּנִים לְכָל אֶחָד, שֶׁרְמוּזִים (בה) בְּה' בְּחֶשְׁבּוֹן ל', שָׁלֹשׁ יוֹדִי\"ן (עולות ל'). וְהֵם בְּרָאשֵׁי שָׁלֹשׁ אַזְכָּרוֹת, שֶׁהֵם ה' מֶלֶךְ, ה' מָלָךְ, ה' יִמְלֹךְ לְעֹלָם וָעֶד. וְיָקוּם עִמָּם רַבִּי אַבָּא, שֶׁהוּא חֶשְׁבּוֹנוֹ ד', אַרְבַּע חַיּוֹת.</p>\n<p>רַבִּי שִׁמְעוֹן הוּא כְּאִילָן, וְרַבִּי אֶלְעָזָר בְּנוֹ וַחֲבֵרָיו, שֶׁהֵם הַחֲמִשָּׁה שֶׁהִזְכַּרְנוּ, כַּעֲנָפִים גְּדוֹלִים שֶׁל הָאִילָן שֶׁדּוֹמִים לִזְרוֹעוֹת וְשׁוֹקַיִם.</p>"],[9522012479,"<p>קוּם רַבִּי שִׁמְעוֹן וְיִתְחַדְּשׁוּ דְבָרִים מִפִּיךְ בְּפָסוּק זֶה שֶׁמִּקֹּדֶם. לַמְנַצֵּחַ - שָׁם נֵצַח, נִגּוּן צַח. וּבוֹ נִקְרָא ה' בַּעַל נִצְחוֹן קְרָבוֹת לְאֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁל הָעוֹלָם, וְרַחֲמִים וְדִין לְיִשְׂרָאֵל. וְסוֹד הַדָּבָר - (משלי יא) וּבַאֲבֹד רְשָׁעִים רִנָּה. מ\"ל - שִׁבְעִים שֵׁמוֹת יֵשׁ לוֹ, וְעִם נֵצַח וְהוֹד ע\"ב, כְּחֶשְׁבּוֹן חֶסֶ\"ד, וְסוֹד הַדָּבָר - (תהלים טז) נְעִמוֹת בִּימִינְךְ נֶצַח.</p>\n<p>הוֹד - בּוֹ הוֹדוּ לַה'. צַדִּיק - בּוֹ (תהלים לג) רַנְּנוּ צַדִּיקִים בַּה', וּבוֹ (ירמיה לא) רָנּוּ לְיַעֲקֹב שִׂמְחָה. תִּפְאֶרֶת - בּוֹ (תהלים קנ) הַלְלוּ אֵל. הַלְלוּיָהּ, הַלְלוּ יָהּ, שֶׁשָּׁם יְהֹוָ\"ה. בְּנִגּוּן וּבְזֶמֶר - חֶסֶד וּגְבוּרָה. בְּשִׁיר וּבִבְרָכָה - חָכְמָה וּבִינָה. בְּאַשְׁרֵי - כֶּתֶר. בִּתְהִלָּה - מַלְכוּת.</p>\n<p>מִזְמוֹר - בּוֹ רָ\"ז וּבוֹ מוּ\"ם. מִצַּד הַזֶּמֶר שֶׁל תּוֹרָה וְזֶמֶר שֶׁל תְּפִלָּה. זֶמֶר מִצַּד אַחֵר הוּא מוּ\"ם זָ\"ר. זֶמֶר בַּבַּיִת - חֶרֶב בַּבַּיִת. נִדָּה שִׁפְחָה בַּת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת זוֹנָה. וְזֶה אוֹתִיּוֹת מִזְמוֹ\"ר. נִגּוּ\"ן - שָׁם גַּ\"ן. כָּךְ יְפִי הַנִּגּוּן, בּוֹ הַלֵּל, כְּמוֹ (שמות יב) לֵיל שִׁמֻּרִים הוּא לַה' לְהוֹצִיאָם מֵאֶרֶץ מִצְרָיִם. אַשְׁרֵי שֶׁבּוֹ שָׁרוּי הָעוֹלָם מְשַׁבְּחִים. (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ. בִּבְרָכָה - (שם לד) אֲבָרְכָה אֶת ה' בְּכָל עֵת. בִּתְהִלָּה - תָּמִיד תְּהִלָּתוֹ בְּפִי.</p>\n<p>עֵל שׁוּשַׁן עֵדוּת (שם ס) - זֶה הוֹד, שֶׁהוּא שׁוֹשַׁן, אָדם שׁוֹלֵט עַל לָבָן, שֶׁהַנֵּצַח שׁוֹלֵט הוּא לָבָן עַל אָדם. מַה זֶּה עֵדוּת? זֶה צַדִּיק. הוּא בְּרִית, שֶׁהוּא אוֹחֵז אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. זֶהוּ שֶׁכָּתוּב (דברים ד) הַעִידתִי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. מַה זֶּה מִכְתָּם? מָ\"ךְ תָּ\"ם. מָךְ הוּא צַדִּיק, תָּם עַמּוּד הָאֶמְצָעִי, דַּרְגַּת יַעֲקֹב, (בראשית כה) אִישׁ תָּם. גּוּף וּבְרִית נֶחְשָׁבִים לְאֶחָד. לְלַמֵּד - חֶסֶד וּגְבוּרָה, שֶׁמִּשָּׁם נִתְּנָה תוֹרָה לִלְמֹד וּלְלַמֵּד.</p>\n<p>אָמַר לוֹ, יָפֶה אָמַרְתָּ, אֲבָל (תהלים יב) לַמְנַצֵּחַ עַל הַשְּׁמִינִית, שֶׁלֹּא תָזוּז נֵצַח מֵהוֹד, שֶׁהִיא סְפִירָה שְׁמִינִית, אָמַר לַמְנַצֵּחַ עַל הַשְּׁמִינִית. אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, אִם כָּךְ, בִּינָה דַּרְגָּתְךְ, וְלָמָּה פֵּרְשׁוּהָ וְנִתַּן הַהוֹד לְמֹשֶׁה, שֶׁנֶּאֱמַר (במדבר כז) וְנָתַתָּה מֵהוֹדְךְ עָלָיו?</p>\n<p>אָמַר לוֹ, יָפֶה שָׁאַלְתָּ. ה' עוֹלָה בָּאוֹת י', חָמֵשׁ פְּעָמִים עֶשֶׂר, לַחֲמִשִּׁים שַׁעֲרֵי בִינָה. וְהִתְפַּשְּׁטוּתָם מֵחֶסֶד וְעַד הוֹד הֵן חָמֵשׁ, עֶשֶׂר בְּכָל סְפִירָה, הֵם חֲמִשִּׁים. וּמִשּׁוּם זֶה מִבִּינָה עַד הוֹד, הַכֹּל הִתְפַּשְּׁטוּת אַחַת. אַחַר כָּךְ בָּא צַדִּיק, וְלָקַח כָּל הַחֲמִשִּׁים שְׁעָרִים לְבַדּוֹ, לִהְיוֹת שָׁקוּל לְכָל הֶחָמֵשׁ, וְנִקְרָא כֹּל, שֶׁנּוֹטֵל כָּל חֲמִשִּׁים שְׁעָרִים. וְגַם כָּךְ כַּלָּה לָקְחָה אֶת כֻּלָּם. אָמַר, כָּעֵת הִתְיַשֵּׁב דָּבָר זֶה עַל בֻּרְיוֹ.</p>\n<p>וְעוֹד לַמְנַצֵּחַ - שָׁם מ\"ל עִם נֵצַח. וְזֶה מ\"ל מֵחַשְׁמַ\"ל. מִן ח\"ש - הוֹד וְנֵצַח, הֵם כְּנֶגֶד שְׁתֵּי הַשְּׂפָתַיִם. וְלָכֵן נִקְרְאוּ שְׂפָתַיִם, חַיּוֹת אֵשׁ מְדַבְּרוֹת. וּבַחֲגִיגָה, עַד הֵיכָן מַעֲשֵׂה מֶרְכָּבָה? וּפֵרְשׁוּהָ מִן וָאֵרֶא, עַד חַשְׁמַל. שֶׁמִּצַּד הַגְּבוּרָה נִקְרְאוּ חַיּוֹת אֵשׁ. וְנָהָר שֶׁיּוֹצֵא מֵהַזֵּעָה שֶׁלָּהֶם - יְסוֹד. כָּל שְׁלֹשֶׁת אֵלֶּה מֶרְכָּבָה לְתִפְאֶרֶת, אָדָם.</p>\n<p>מַעָשֵׂה מֶרְכָּבָה זוֹ מַלְכוּת. וּבִשְׁלֹשֶׁת אֵלּוּ, הוּא חָכְמָה וּבִינָה וָדַעַת. וְלָכֵן פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה שֶׁאֵין דּוֹרְשִׁים בְּמַעֲשֵׂה מֶרְכָּבָה בְּיָחִיד, אֶלָּא אִם כֵּן הוּא חָכָם וּמֵבִין מִדַּעְתּוֹ.</p>"],[9522012480,"<p>וְיִשִׁ מֶרְכָּבָה לְמַטָּה מִזְּעֵיר אַנְפִּין, שֶׁהוּא מְטַטְרוֹ\"ן, אָדָם הַקָּטָן. שֶׁבְּמֶרְכַּבְתּוֹ, שֶׁהִיא פַּרְדֵּס, זוֹרְמִים בִּמְהִירוּת מַיִם שֶׁל הַתּוֹרָה שֶׁיּוֹצְאִים מִתּוֹךְ פַּרְדֵּס שֶׁלּוֹ לְשָׁלֹשׁ מֵאַרְבַּע, שֶׁנֶּאֱמַר עֲלֵיהֶם אַרְבָּעָה נִכְנְסוּ לַפַּרְדֵּס, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>שֶׁהוּא צִפּוֹר שֶׁרָאָה רַבָּה בַּר בַּר חַנָּה לְחוֹף יָם הַתּוֹרָה, שֶׁהַיָּם הִגִּיעַ עַד קַרְסֻלָּיו, וְרֹאשׁוֹ הִגִּיעַ עַד קְצֵה הַשָּׁמַיִם, וְלֹא נִכְשְׁלוּ בוֹ שְׁלֹשָׁה מִשּׁוּם שֶׁהַמַּיִם שֶׁלּוֹ רַבִּים, אֶלָּא מִשּׁוּם זִרְמַת הַמַּיִם, וּפֵרְשׁוּהָ.</p>\n<p>אבג כּוֹלֵל אוֹתָם שֶׁעוֹלִים לְשֵׁשׁ, כְּנֶגֶד אוֹתִיּוֹת מְטַטְרוֹ\"ן. רְבִיעִי ד', (מלכים א יט) קוֹל דְּמָמָה דַקָּה, שֶׁשָּׁם בָּא הַמֶּלֶךְ, וְהוּא אָדָם לָשֶׁבֶת עַל הַכִּסֵּא.</p>\n<p>א י\"י - מַיִם עֶלְיוֹנִים וּמַיִם תַּחְתּוֹנִים, שֶׁאֵין בֵּינֵיהֶם אֶלָּא כִּמְלֹא נִימָה, שֶׁהוּא ו' נָטוּי בֵּינֵיהֶם בָּרָקִיעַ שֶׁהוּא מַבְדִּיל בֵּין מַיִם לָמָיִם, שֶׁתְּהֵא הַבְדָּלָה בֵּין נְקֵבָה לְזָכָר. לָכֵן, (בראשית א) וִיהִי מַבְדִּיל. וְסוֹד הַדָּבָר - יאהדונה\"י. מַיִם עֶלְיוֹנִים זְכָרִים - י' עֶלְיוֹנָה. מַיִם תַּחְתּוֹנִים נְקֵבוֹת - י' תַּחְתּוֹנָה. שֵׁשׁ אוֹתִיּוֹת בֵּינֵיהֶם, כְּחֶשְׁבּוֹן ו', זֶה מְטַטְרוֹן, שֶׁהוּא בֵּין א.</p>\n<p>וְעוֹד, יוֹד נְקֻדָּה. ו' גַלְגַּל. וְאֵין תְּנוּעָה בַגַּלְגַּל בְּשִׁשָּׁה צְדָדִים כְּחֶשְׁבּוֹן ו', אֶלָּא בְּאוֹתָהּ נְקֻדָּה. וְאוֹתָהּ נְקֻדָּה הִיא יִחוּד הַכֹּל, וּמְעִידָה עַל אוֹתוֹ יָחִיד שֶׁאֵין לוֹ שֵׁנִי, שֶׁפֵּרְשׁוּ עָלֶיהָ רַבּוֹתֵינוּ שֶׁצָּרִיךְ לְיַחֵד אוֹתָהּ כְּדֵי שֶׁתַּמְלִיכֵהוּ עַל הַשָּׁמַיִם וְעַל הָאָרֶץ, וְעַל אַרְבַּע רוּחוֹת הָעוֹלָם. ב' - שָׁמַיִם וָאָרֶץ. ג' - עַמּוּד שֶׁסּוֹבֵל אוֹתָם. ד' - אַרְבַּע חַיּוֹת. ה'- הַכִּסֵּא. ו' - שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. וְעוֹד, א ב ג ד ה ו ז ח ט - אָדָם. י' יִחוּד שֶׁלּוֹ, מַלְכוּת, עֲשִׂירִי שֶׁל אָדָם. תֵּשַׁע הוּא כְּנֶגֶד תֵּשַׁע אוֹתִיּוֹת. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁיּוֹדְעִים סוֹד רִבּוֹנָם.</p>"],[9522012481,"<p>דָּבָר אַחֵר צַו אֶת בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵהֶם אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי רֵיחַ נִחוֹחִי - רַבִּי יְהוּדָה אָמַר, בַּקָּרְבָּן יֵשׁ עָשָׁן, וְיֵשׁ רֵיחַ, וְיֵשׁ רֵיחַ נִיחֹחַ. עָשָׁן הוּא מִצַּד הַדִּין, זֶהוּ שֶׁכָּתוּב (דברים כט) כִּי אָז יֶעְשַׁן אַף ה'. (תהלים יח) עָלָה עָשָׁן בְּאַפּוֹ וְאֵשׁ מִפִּיו תֹּאכֵל. רֵיחַ נִיחֹחִי, רַחֲמִים. (שיר השירים ז) וְרֵיחַ אַפֵּךְ כַּתַּפּוּחִים.</p>\n<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, וַהֲרֵי שְׁנֵיהֶם - עָשָׁן וְרֵיחַ - הֵם בָּאַף, וְהַפְּסוּקִים מְעִידִים. אֶחָד, עָלָה עָשָׁן בְּאַפּוֹ. וְהַשֵּׁנִי, וְרֵיחַ אַפֵּךְ כַּתַּפּוּחִים. וְלָמָּה נִקְרָא אֶחָד עָשָׁן דִּין, וְהַשֵּׁנִי רַחֲמִים? אֶלָּא, בַּחֹטֶם יֵשׁ שְׁנֵי חַלּוֹנוֹת, וְנֶאֱמַר בַּשְּׂמֹאל, עָלָה עָשָׁן בְּאַפּוֹ. מֶה עָלָה? אֶלָּא מֵהַלֵּב שֶׁהוּא בִּשְׂמֹאל, כְּנֶגֶד גִּבּוֹר. מִיָּמִין יוֹרֶדֶת אֵלָיו רוּחַ לְקָרְרוֹ וּלְשַׁכֵּךְ רָגְזוֹ, מִצַּד הַחֶסֶד, שֶׁשָּׁם הַמֹּחַ. חָכְמָה לְיָמִין - הָרוֹצֶה לְהַחְכִּים יַדְרִים. בִּינָה בַּלֵּב, כְּלַפֵּי שְׂמֹאל - הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין. וְלָכֵן עָלָה עָשָׁן בְּאַפּוֹ, מִבִּינָה לְחָכְמָה, שֶׁהִיא לְיָמִין, וּמְקַבְּלוֹ בְחֶדְוָה, בְּנִגּוּן הַלְוִיִּם.</p>\n<p>וְעָשָׁן זֶה לֹא עוֹלֶה, אֶלָּא עַל יְדֵי אֵשׁ שֶׁדּוֹלֵק בָּעֵצִים, שֶׁהֵם אֵיבָרִים מְלֵאִים מִצְווֹת, עֲצֵי עוֹלָה. בַּעֲלֵי תוֹרָה, תּוֹרָה שֶׁהִיא נִדְלֶקֶת בָּהֶם, אֵשׁ בְּחֹזֶק הַגְּבוּרָה, וְעָלָה עָשָׁן בָּהֶם. בַּבִּינָה עֲשַׁן הַמַּעֲרָכָה.</p>\n<p>וּמִשֶּׁעוֹלֶה לָאַף, נִקְרָא קְטֹרֶת, זֶהוּ שֶׁכָּתוּב (דברים לג) יָשִׂימוּ קְטוֹרָה בְּאַפֶּךְ. וְאֵין הַמְבַטֵּל מָוֶת בָּעוֹלָם כְּמוֹ קְטֹרֶת, שֶׁהִיא קִשּׁוּר הַדִּין בְּרַחֲמִים עִם רֵיחַ נִיחוֹחַ בָּאַף. תַּרְגּוּם שֶׁל קֶשֶׁר - קְטִירוּ. אָמַר רַבִּי יְהוּדָה, אַשְׁרֵי חֶלְקֵנוּ שֶׁהִרְוַחְנוּ דְבָרִים נִסְתָּרִים בַּגָּלוּי. עוֹד אָמַר מְנוֹרָה הַקְּדוֹשָׁה, שֶׁאַחַר הַתְּפִלָּה, שֶׁהִיא כְּמוֹ קָרְבָּן, מִי שֶׁיֹּאמַר פִּטּוּם הַקְּטֹרֶת אַחַר תְּהִלָּה לְדָוִד, מְבַטֵּל מָוֶת מִן הַבַּיִת.</p>"],[9522012482,"<p>אָמַר רוֹעֶה הַנֶּאֱמָן, כָּעֵת צָרִיךְ לָדַעַת אֵיךְ הִתְקִינוּ תְפִלּוֹת כְּנֶגֶד קָרְבָּנוֹת. אֶלָּא שָׁלֹשׁ תְּפִלּוֹת, כְּנֶגֶד אֶת הַכֶּבֶשׂ הָאֶחָד תַּעֲשֶׂה בַבֹּקֶר - זוֹ תְּפִלַּת שַׁחֲרִית, שֶׁנֶּאֱמַר בָּהּ (בראשית יט) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר אֶל הַמָּקוֹם אֲשֶׁר עָמַד שָׁם אֶת פְּנֵי ה'. וּפֵרְשׁוּהָ רַבּוֹתֵינוּ, שֶׁאֵין עֲמִידָה אֶלָּא תְּפִלָּה. וְאֶת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם - כְּנֶגֶד תְּפִלַּת מִנְחָה שֶׁתִּקֵּן אוֹתָהּ יִצְחָק. זֶהוּ שֶׁכָּתוּב (שם כד) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה לִפְנוֹת עָרֶב, וְאֵין שִׂיחָה אֶלָּא תְּפִלָּה. תְּפִלַּת עַרְבִית כְּנֶגֶד אֵמוּרִים וּפְדָרִים שֶׁמִּתְאַכְּלִים כָּל הַלַּיְלָה, זֶהוּ שֶׁכָּתוּב (שם כח) וַיִּפְגַּע בַּמָּקוֹם וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ, וְאֵין פְּגִיעָה אֶלָּא תְּפִלָּה.</p>\n<p>בֵּין כָּךְ שֶׁאָנוּ בְמָקוֹם זֶה, לָמָּה כָּתוּב וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וַיָּשֶׂם מְרַאֲשּתָיו וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא? וְכִי לֹא הָיוּ לוֹ כָּרִים וּכְסָתוֹת לִשְׁכַּב? אֶלָּא הוֹאִיל וּבָא חָתָן לַכַּלָּה, אַף עַל פִּי שֶׁלֹּא הָיָה דַרְכּוֹ לִשְׁכַּב אֶלָּא בְּכָרִים וּכְסָתוֹת, וְהִיא נָתְנָה לוֹ אֲבָנִים לִשְׁכַּב - יְקַבֵּל הַכֹּל בִּרְצוֹן הַלֵּב, וַהֲרֵי נִתְבָּאֵר. וְגַם כָּךְ נֶאֱמַר בַּחִבּוּר הָרִאשׁוֹן. מַהוּ שֶׁכָּתוּב (שם לב) וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם? אָמַר רַבִּי שִׁמְעוֹן, שֵׁב וֶאֱמֹר הַפָּסוּק. אָמַר רוֹעֶה הַנֶּאֱמָן,</p>\n<p>אָמַר רַבִּי פִּנְחָס, הָיִיתִי מִסְתַּכֵּל, הַשְּׁמִירָה הִיא וַדַּאי בַּלֵּב, (שראה בלב) (והלבדגמתהלבהעליון) וְלָכֵן שָׁמוֹר בַּלֵּב וְלֹא בְמָקוֹם אַחֵר. זְכִירָה בְּזָכָר, בַּמֹּחַ, שֶׁרוֹכֵב וְשׁוֹלֵט עַל הַלֵּב. וְאֵין זְכִירָה אֶלָּא בַּמֹּחַ. וְעַל זֶה זָכוֹר לְזָכָר, וְשָׁמוֹר לִנְקֵבָה. הַמֹּחַ שֶׁהוּא זָכָר, רוֹכֵב וְשׁוֹלֵט עַל הַלֵּב. הַלֵּב שׁוֹלֵט וְרוֹכֵב עַל הַכָּבֵד. הַכָּבֵד, סָמָאֵל וְנָחָשׁ זֶה בָּזֶה, וְהוּא אֶחָד. (והם זכר ונקבה) יוֹתֶרֶת הַכָּבֵד וְכָבֵד. וְלָכֵן בַּקָּרְבָּן, יוֹתֶרֶת הַכָּבֵד זֶה נָחָשׁ. כָּבֵד מַאֲכַל זָכָר, סוֹד שֶׁל סָמָאֵ\"ל.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי כָּךְ זֶה, וְיָפֶה הוּא. וּבֵרוּר הַדָּבָר וְסוֹד וְנִסְתְּרוֹת הַקָּרְבָּן כָּךְ הוּא. כָּבֵד לוֹקֵחַ בַּהַתְחָלָה, הוּא וְהַיּוֹתֶרֶת שֶׁלּוֹ, (ואחר כך היותרת שלו) סָמָאֵל וּבַת זוּגוֹ. (ואחר כך כל וכו' שאותם חילות) וְכָל אוֹתָם עוֹרְקֵי הַכָּבֵד חֲיָלוֹת וּמַחֲנוֹת שֶׁלָּהֶם, וְלוֹקְחִים אֶת שֶׁלָּהֶם, שֶׁאוֹכְלִים חֲלָבִים וְשַׁמְנוּנֵי הַקָּרְבָּן. זֶהוּ שֶׁכָּתוּב וְאֶת הַחֵלֶב אֲשֶׁר עֲלֵיהֶם. וְאָז נִקְרָב הַכֹּל לַלֵּב.</p>\n<p>וְהַלֵּב לֹא לוֹקֵחַ מֵהַכֹּל, אֶלָּא וִדּוּי שֶׁנַּעֲשָׂה בּוֹ וְעוֹלֶה בְּאוֹתוֹ עָשָׁן וּתְפִלָּה שֶׁנַּעֲשָׂה עָלָיו הַקָּרְבָּן. הַלֵּב מַקְרִיב לַמֹּחַ, רָצוֹן שֶׁל הַיִּחוּד שֶׁהַכֹּהֵן בּוֹ וְחֶדְוַת הַלְוִיִּם. הַמֹּחַ הַזֶּה אוֹר שֶׁבָּא מִמֹּחַ עֶלְיוֹן. הַמֹּחַ מַקְרִיב לַטָּמִיר מֵהַכֹּל, שֶׁלֹּא נוֹדָע כְּלָל, (אליו, מכלל שלא נפרע כלל) וְהַכֹּל נִקְשָׁר זֶה בָּזֶה, וְהַמֹּחַ מַקִרִיב נַחַת רוּחַ שֶׁל הַכֹּל.</p>\n<p>עוֹרְקֵֹי הַכָּבֵד, אֵלּוּ אִשִּׁים וְכָל אוֹתָם חֵילוֹתֵיהֶם. כָּבֵד, כְּמוֹ שֶׁנֶּאֱמַר. יוֹתֶרֶת נְקֵבָה, נְקֵבָה שֶׁלּוֹ. לָמָּה יוֹתֶרֶת? שֶׁלֹּא מִתְחַבֶּרֶת בְּזָכָר, אֶלָּא רַק כְּשֶׁנִּשְׁאֶרֶת לָהּ שָׁעָה לְאַחַר שֶׁעָשְׂתָה נִאוּפֶיהָ וְעָזְבָה אוֹתוֹ. עוֹד יוֹתֶרֶת נְקֵבָה - שֶׁכְּשֶׁרוֹצָה לְהִתְחַבֵּר בְּאָדָם, נַעֲשֵׂית אֵלָיו שִׁירַיִם, שֶׁלֹּא נֶחְשֶׁבֶת כְּלָל. לְאַחַר מִכֵּן מִתְקָרֶבֶת לְאַט לְאַט אֵלָיו, עַד שֶׁנַּעֲשֵׂית אֵלָיו חִבּוּר אֶחָד. וּמֵעוֹרְקֵי הַכָּבֵד הַלָּלוּ מִתְפַּשְּׁטִים אֲחֵרִים קְטַנִּים לְכַמָּה מִינִים, וְהַכֹּל לוֹקְחִים אֵמוּרִים וּפְדָרִים, וְכֻלָּם כְּלוּלִים בַּכָּבֵד.</p>\n<p>הַלֵּב שֶׁהוּא עִקָּר בִּקְדֻשָּׁה, לוֹקֵחַ וּמַקְרִיב לַמֹּחַ, כְּמוֹ שֶׁנֶּאֱמַר. הַלֵּב שָׁרוּי עַל שְׁתֵּי כְלָיוֹת, וְהֵם שְׁנֵי כְרוּבִים, נוֹתְנִים עֵצָה, וְהֵם רְחוֹקִים קְרוֹבִים, יָמִין וּשְׂמֹאל, וְכֻלָּם נוֹטְלִים וְאוֹכְלִים כָּל אֶחָד כָּרָאוּי, עַד שֶׁהַכֹּל נִקְשָׁר כְּאֶחָד.</p>\n<p>זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה. זֶה נִקְרָב לַלֵּב, רוּחַ נִשְׁבָּרָה, וִדּוּי וּתְפִלָּה. שֶׁהֲרֵי וַדַּאי (קהלת יב) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. וְהַכָּבֵד מַקְרִיב אוֹתוֹ לְגַבֵּי הַלֵּב, שֶׁהוּא סָנֵגוֹר עָלָיו, וְהַכֹּל קִשּׁוּר אֶחָד בַּקָּרְבָּן.</p>\n<p>מֵהַכָּבֵד יוֹצְאִים כָּל הֶחֳלָאִים וְכָל הַמַּכּוֹת לְכָל אֵיבְרֵי הַגּוּף, וּבוֹ שְׁרוּיִים. הַלֵּב הוּא זַךְ מֵהַכֹּל, וּמִמֶּנּוּ יוֹצֵא כָּל טוּב, וְכָל בְּרִיאוּת הָאֵיבָרִים כֻּלָּם, וְכָל חֹזֶק, וְכָל חֶדְוָה, וְכָל הַשְּׁלֵמוּת שֶׁצְּרִיכִים לְכָל הָאֵיבָרִים.</p>"],[9522012483,"<p>אֵין קָרְבָּנוֹת אֶלָּא לְהַרְחִיק צְדָדִים טְמֵאִים וּלְקָרֵב דַּרְגוֹת קְדוֹשׁוֹת. וְנֶאֱמַר בַּחִבּוּר הָרִאשׁוֹן שֶׁלָּהֶם: (עורקי הכבד אלו אשים וכל אותם חילות, ונתבאר) עוֹרְקֵי הַכָּבֵד, יֵשׁ מֵהֶם גְּדוֹלִים, יֵשׁ מֵהֶם גְּדוֹלִים וּקְטַנִּים, וּמִתְפַּשְּׁטִים מֵהֶם לְכַמָּה צְדָדִים. וְאֵלּוּ לוֹקְחִים אֵיבָרִים וְאֵמוּרִים וּפְדָרִים שֶׁמִּתְאַכְּלִים כָּל הַלַּיְלָה, שֶׁהֲרֵי קָרְבָּן כֻּלּוֹ לַה'.</p>\n<p>אָמַר מְנוֹרָה הַקְּדוֹשָׁה, רוֹעֶה הַנֶּאֱמָן, הֲלֹא אָמַרְתָּ לְעֵיל שֶׁקָּרְבָּנוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינָם אֶלָּא לְקָרֵב י' לְה', ו' לְה'. אֶלָּא שֶׁאַף עַל גַּב שֶׁכָּל הַקָּרְבָּנוֹת יֵשׁ לְהַקְרִיב לְפָנָיו, הוּא מְחַלֵּק לְכָל הַמַּחֲנוֹת מַאַכְלֵי הַקָּרְבָּנוֹת, לְכָל אֶחָד כָּרָאוּי לוֹ. לַשִּׂכְלִיִּים מְזוֹנוֹת הַתּוֹרָה, וּמִשְׁתֵּה הַיַּיִן וּמַיִם שֶׁל הַתּוֹרָה. לַטִּבְעִיִּים, שֶׁהֵם שֵׁדִים, שֶׁהֵם כִּבְנֵי אָדָם, נוֹתֵן לָהֶם מַאֲכָלִים טִבְעִיִּים אֵלּוּ, שֶׁיּוֹרֵד אֵשׁ שֶׁלָּהֶם לֶאֱכֹל אוֹתָם.</p>\n<p>כְּמוֹ שֶׁפֵּרְשׁוּהָ רַבּוֹתֵינוּ, אִם זָכוּ - הָיָה יוֹרֵד כְּאַרְיֵה שֶׁל אֵשׁ לֶאֱכֹל הַקָּרְבָּנוֹת, וְאִם לֹא - הָיָה יוֹרֵד שָׁם כְּמִין כֶּלֶב שֶׁל אֵשׁ. וְגַם כָּךְ כְּשֶׁמֵּת אָדָם, אִם זוֹכֶה - יוֹרֵד בִּדְמוּת אַרְיֵה לְקַבֵּל אֶת הַנֶּפֶשׁ, וְאִם לֹא - כִּדְמוּת כֶּלֶב, שֶׁאָמַר עָלָיו דָּוִד, (תהלים כב) הַצִּילָה מֵחֶרֶב נַפְשִׁי מִיַּד כֶּלֶב יְחִידָתִי.</p>\n<p>וּכְדֵי לְהַצִּיל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת גּוּפֵיהֶם שֶׁל יִשְׂרָאֵל מֵהֶם וְאֶת נַפְשׁוֹתָם, מִנָּה לְהַקְרִיב קָרְבָּנוֹת שֶׁל בְּהֵמוֹת וְגוּפִים בִּמְקוֹמָם, לְקַיֵּם (משלי כה) אִם רָעֵב שֹׂנַאֲךְ הַאֲכִילֵהוּ לָחֶם וְאִם צָמֵא הַשְׁקֵהוּ מָיִם. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא לוֹקֵחַ כִּי אִם אֶת רְצוֹן הַלֵּב וְשִׁבְרוֹנוֹ (שהוא ישראל). זֶהוּ שֶׁכָּתוּב (תהלים נא) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה. כְּמוֹ כְּלֵי חֶרֶס שֶׁנֶּאֱמַר בָּהֶם נִשְׁבָּרוּ נִטְהָרוּ.</p>\n<p>כֹּהֵן מֹחַ. לֵוִי לֵב. יִשְׂרָאֵל גּוּף. וְנֶאֱמַר בָּהֶם, כֹּהֲנִים בַּעֲבוֹדָתָם וּלְוִיִּם בְּדוּכָנָם וְיִשְׂרָאֵל בְּמַעֲמָדָם. וְאִם צָרִיךְ לְהַקְרִיב כָּבֵד לַלֵּב, חֶלְבּוֹ שֶׁל אוֹתָם טְמֵאִים, הוּא לֹא לוֹקֵחַ. אֶלָּא שַׁמְנוּנוֹ שֶׁל חֵלֶב טָהוֹר. כְּמוֹ שֶׁיֵּשׁ בַּגּוּף חֵלֶב טָהוֹר וְחֵלֶב טָמֵא, דָּם צָלוּל בְּלִי פְסֹלֶת וְדָם עָכוּר בִּפְסֹלֶת. וְעוֹרְקֵי הַלֵּב חֲיָלוֹת קְדוֹשִׁים, וְעוֹרְקֵי הַכָּבֵד חֲיָלוֹת טְמֵאִים. גַּם כָּךְ הֵם מַחֲנוֹת הַיֵּצֶר הָרָע וּמַחֲנוֹת הַיֵּצֶר הַטּוֹב. אֵלּוּ מְמֻנִּים עַל עוֹרְקֵי הַלֵּב, וְאֵלּוּ מְמֻנִּים עַל עוֹרְקֵי הַכָּבֵד. גַּם כָּךְ שְׁתֵּי אֻמּוֹת, יִשְׂרָאֵל וְאֻמּוֹת הָעוֹלָם עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת.</p>\n<p>אָמַר לוֹ רוֹעֶה הַנֶּאֱמָן, יָפֶה אָמַרְתָּ בַּכֹּל, אֲבָל אֲפִלּוּ יִשְׂרָאֵל לֹא כֻּלָּם שָׁוִים, שֶׁיֵּשׁ בָּהֶם בְּנֵי מַלְכוּת מִצַּד מַלְכוּת הַקְּדוֹשָׁה, כְּלוּלָה מֵעֶשֶׂר סְפִירוֹת וּמִכָּל הֲוָיוֹת וְכִנּוּיִים. וְיֵשׁ מֵהֶם עֲבָדִים מִצַּד שֶׁל עֶבֶד, שֶׁהוּא (בראשית כד) עַבְדּוֹ זְקַן בֵּיתוֹ. וְיֵשׁ מֵהֶם כַּבְּהֵמוֹת, וְנֶאֱמַר בָּהֶם (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם. וְאוֹתָם שֶׁדּוֹמִים לְצֹאן, הַקָּדוֹשׁ בָּרוּךְ הוּא צִוָּה לְהַקְרִיב בְּהֵמוֹת בִּמְקוֹמָם לְכַפֵּר עֲלֵיהֶם. וְאוֹתָם שֶׁדּוֹמִים לְמַלְאָכִים, קָרְבָּנוֹת שֶׁלָּהֶם הֵם מַעֲשִׂים טוֹבִים שֶׁמְּמֻנִּים עֲלֵיהֶם מַלְאָכִים שֶׁמַּקְרִיבִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא בִּמְקוֹמָם.</p>\n<p>וְאוֹתָם שֶׁהָיוּ בָּנִים לַה', זֶהוּ שֶׁכָּתוּב (דברים י) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם, בַּחֲטָאֵיהֶם מִתְפָּרְדוֹת הָאוֹתִיּוֹת, וְהַתִּקּוּן (שלהם הוא התורה) הוּא שֶׁתִּהְיֶה תוֹרָה, שֶׁהוּא שֵׁם יְהֹוָ\"ה, לְקָרֵב אֶת הָאוֹתִיּוֹת, י' בְּה', ו' בְּה', בְּקָרְבְּנוֹתֵיהֶם.</p>\n<p>הֲרֵי בְּכָל הַקָּרְבָּנוֹת - בֵּין שֶׁל בְּהֵמוֹת, בֵּין שֶׁל מַלְאָכִים שֶׁמְּמֻנִּים עַל מִצְווֹת, בֵּין בְּמַלְכוּת, בֵּין בִּשְׁמוֹ - הַכֹּל צָרִיךְ לְהַקְרִיב לַקָּדוֹשׁ-בָּרוּךְ-הוּא (שתורתו) בְּאוֹתִיּוֹת קְדוֹשׁוֹת, וְהוּא רוֹכֵב בְּאַרְבַּע חַיּוֹת שֶׁל הַמַּלְאָכִים, וְהוּא רוֹכֵב בְּאַרְבָּעָה יְסוֹדוֹת, שֶׁמֵּהֶם נִבְרְאוּ אַרְבַּע חַיּוֹת טִבְעִיּוֹת. וְהוּא הוּא שֶׁמְּקָרֵב מַיִם לְאֵשׁ, וְרוּחַ לְעָפָר. זֶהוּ שֶׁכָּתוּב (איוב כח) עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. וְגַם כָּךְ הוּא מְקָרֵב אֶת מִיכָאֵל, שֶׁהוּא מַיִם שִׂכְלִיִּים, עִם גַּבְרִיאֵל, שֶׁהוּא אֵשׁ שִׂכְלִי. וְהוּא מְקָרֵב אֶת אוּרִיאֵל, שֶׁהוּא אֲוִיר, שֶׁהַיְנוּ רוּחַ שִׂכְלִי, עִם רְפָאֵל, שֶׁהוּא אֵפֶר, שֶׁהַיְנוּ עָפָר שִׂכְלִית. שֶׁמִּיָּד שֶׁמִּסְתַּלֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא מִבֵּינֵיהֶם, אֵין בָּהֶם כֹּחַ.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב בְּכָל הַקָּרְבָּנוֹת לַיהֹוָ\"ה, וְאֵיךְ אָמַרְנוּ שֶׁיֵּשׁ פֵּרוּד בָּאוֹתִיּוֹת? אֶלָּא זֶה נֶאֱמַר בַּדְּרָגוֹת שֶׁנִּבְרְאוּ וְנִקְרְאוּ בִשְׁמוֹ, וְלֹא שֶׁהֵם הוּא מַמָּשׁ. זֶהוּ שֶׁכָּתוּב (ישעיה מג) כֹּל הַנִּקְרָא בִשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו יְצַרְתִּיו אַף עֲשִׂיתִיו. שֶׁיֵּשׁ אוֹתִיּוֹת שֶׁל יְהֹוָ\"ה בָּאֲצִילוּת, שֶׁאֵין בָּהֶן פֵּרוּד וְהַפְסָקָה, שֶׁהֵן כְּמוֹ מַבּוּעִין אֲלֵיהֶם שֶׁמַּשְׁקִים אֶת הָאִילָנוֹת. וּמִשּׁוּם אֵלֶּה שֶׁנִּבְרְאוּ מִתְדַּמִּים י' לָרֹאשׁ, ו' לַגּוּף, ה' ה' לְעֶשֶׂר אֶצְבָּעוֹת.</p>\n<p>אֲבָל עִלַּת הָעִלּוֹת עַל הַכֹּל, שֶׁנִּקְרָא יְהֹוָ\"ה, נֶאֱמַר בּוֹ (שם מ) וְאֶל מִי תְדַמְּיוּנִי וְאֶשְׁוֶה יֹאמַר קָדוֹשׁ. (שם) וְאֶל מִי תְּדַמְּיוּן אֵל וּמַה דְּמוּת תַּעַרְכוּ לוֹ. (מלאכי ג) אֲנִי ה' לֹא שָׁנִיתִי. לָא מַגִּיעַ אֵלָיו חֲטָאִים לְהַפְרִיד אוֹתִיּוֹתָיו - י' מֵה', ו' מֵה'. שֶׁאֵין בָּהֶם פֵּרוּד. וְעָלָיו נֶאֱמַר (תהלים ה) לֹא יְגֻרְךְ רָע. הוּא שׁוֹלֵט עַל הַכֹּל, וְאֵין מִי שֶׁשּׁוֹלֵט בּוֹ. הוּא תּוֹפֵס אֶת הַכֹּל, וְאֵין מִי שֶׁתּוֹפֵס בּוֹ. וְהוּא לֹא נִקְרָא יְהֹוָ\"ה, וּבְכָל הַשֵּׁמוֹת, אֶלָּא בְּהִתְפַּשְּׁטוּת אוֹרוֹ עֲלֵיהֶם. וּכְשֶׁמִּסְתַּלֵּק מֵהֶם, אֵין לוֹ מֵעַצְמוֹ שֵׁם כְּלָל מֵהֶם. עָמֹק עָמֹק מִי יִמְצָאֶנּוּ.</p>\n<p>אֵין אוֹר יָכוֹל לְהִסְתַּכֵּל בּוֹ, שֶׁלֹּא נֶחְשָׁךְ. אֲפִלּוּ כֶּתֶר עֶלְיוֹן, שֶׁאוֹרוֹ חָזָק עַל כָּל הַדְּרָגוֹת וְעַל כָּל חֵילוֹת הַשָּׁמַיִם, עֶלְיוֹנִים וְתַחְתּוֹנִים, נֶאֱמַר עָלָיו (שם יח) יָשֶׁת חֹשֶׁךְ סִתְרוֹ. וְעַל חָכְמָה וּבִינָה - (שם צג) עָנָן וַעֲרָפֶל סְבִיבָיו. כָּל שֶׁכֵּן שְׁאָר הַסְּפִירוֹת, כָּל שֶׁכֵּן הַחַיּוֹת, כָּל שֶׁכֵּן יְסוֹדוֹת, שֶׁהֵם מֵתִים. הוּא סוֹבֵב עַל כָּל הָעוֹלָמוֹת, וְאֵין סוֹבֵב אוֹתָם לְכָל צַד, לְמַעְלָה וּלְמַטָּה וּלְאַרְבָּעָה צְדָדִים, פְּרָט לוֹ. וְאֵין מִי שֶׁיּוֹצֵא מֵרְשׁוּתוֹ הַחוּצָה. הוּא מְמַלֵּא כָּל הָעוֹלָמוֹת, וְאֵין (אלוה וכו' להם חוץ ממנו) אַחֵר שֶׁמְּמַלֵּא אוֹתָם.</p>\n<p>הוּא מְחַיֶּה אוֹתָם, וְאֵין אֱלוֹהַּ אַחֵר עָלָיו לָתֵת לוֹ חַיִּים. זֶהוּ שֶׁכָּתוּב (נחמיה ט) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם. וּבִגְלָלוֹ אָמַר דָּנִיֵּאל, (דניאל ד) וְכָל דַּיָּרֵי הָאָרֶץ כְּאֵינָם חֲשׁוּבִים, וְכִרְצוֹנוֹ עוֹשֶׂה בְּחֵיל הַשָּׁמַיִם. הוּא מְקַשֵּׁר וּמְיַחֵד מִין לְמִינוֹ, לְמַעְלָה וּלְמַטָּה, וְאֵין קִרְבָה לָהֶם בְּאַרְבָּעָה יְסוֹדוֹת, רַק הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁהוּא בֵּינֵיהֶם.</p>\n<p>מִיָּד שֶׁחָטְאוּ, אֵלּוּ שֶׁנִּקְרְאוּ בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם, הִסְתַּלֵּק מִן הָאוֹתִיּוֹת, וְנִשְׁאֲרוּ בְפֵרוּד. וּמַה תִּקּוּנוֹ? לְקָרֵב אוֹתִיּוֹת בַּקָּדוֹשׁ- בָּרוּךְ-הוּא - י' בְּה', ו' בְּה'. גַּם כָּךְ הֵם עֲבָדִים שֶׁלּוֹ מִצַּד הַחַיּוֹת, בַּחֲטָאֵיהֶם גָּרְמוּ לוֹ לְהִסְתַּלֵּק מֵהֶם. מַה תַּקָּנָתָם? לְהוֹרִיד אֶת הַקָּדוֹשׁ בָּרוּךָ הוּא עֲלֵיהֶם לְקָרֵב אוֹתָם. גַּם כָּךָ אֵלּוִּ שֶׁהָיוּ מֵאַרְבָּעָה יְסוֹדוֹת, שֶׁהֵם צאנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךָ הוּא, שֶׁגָּרְמוּ לְסַלֵּק אֶת הַקָּדוֹשׁ בָּרוּךָ הוּא מֵהֶם, מָה הַתַּקָּנָה? לְקָרְבָם לַקָּדוֹשׁ-בָּרוּךָ- הוּא.</p>\n<p>וְלָכֵ בְּכֻלָּם צִוָּה: קָרְבָּן לַה', אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי. גַּם, אֶת הַכֶּבֶשׂ אֶחָד תַּעֲשֶׂה בַּבֹּקֶר וְאֶת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֶּין הָעַרְבָּיִם. וְכָתוּב (ולקחת) שְׁתֵּי תרִים אוֹ שְׁנֵי בְנֵי יוֹנָה. כָּל מִין הוֹלֵךָ לְמִינוֹ. וְהַקָּדוֹשׁ בָּרוּךָ הוּא מְקָרֵב הַכֹּל בְּמָקוֹם זֶה, הוּא עִלַּת הַכֹּל, שֶׁאֵין אֱלוֹהַּ פְּרָט לוֹ, וְאֵין מִי שֶׁיָּכוֹל לְקָרֵב חֲיָלוֹת פְּרָט לוֹ.</p>\n<p>אֲבָל חֵילוֹת אֻמּוֹת עוֹבְדֵי עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, הֵם מִצַּד הַפֵּרוּד. אוֹי לְמִי שֶׁגּוֹרֵם בַּחֲטָאָיו לְהַעֲלוֹת אוֹתִיּוֹת וְחַיּוֹת וִיסוֹדוֹת, שֶׁמִּיָּד מִסְתַּלֵּק הַקָּדוֹשׁ בָּרוּךָ הוּא מִיִּשְׂרָאֵל, וְיִכָּנְסוּ בֵינֵיהֶם אֻמּוֹת עוֹבְדֵי עֲבוֹדַת כוֹכָבִים וּמַזָּלוֹת, שֶׁאֵין לָהֶם קִרְבָה לַקָּדוֹשׁ-בָּרוּךָ- הוּא, שֶׁאֵין קָרְבָּנוֹת בְּחוּץ לָאָרֶץ. וְלָכֵן פֵּרְשׁוּהָ רַבּוֹתֵינוּ, הַדָּר בְּחוּצָה לָאָרֶץ דּוֹמֶה כְּמִי שֶׁאֵין לוֹ אֱלוֹהַּ. בְּאוֹתוֹ זְמַן שֶׁאָמַר דְּבָרִים הַלָּלוּ, יָרְדוּ כָּל הָאוֹתִיּוֹת הַקְּדוֹשׁוֹת וְחַיּוֹת קְדוֹשׁוֹת וְאַרְבָּעָה יְסוֹדוֹת אֵלָיו, וּבֵרְכוּ אוֹתוֹ וְאָמְרוּ: עַל יָדְךְ, רוֹעֶה הַנֶּאֱמָן, יָרַד עָלֵינוּ הַקָּדוֹשׁ בָּרוּךָ הוּא, וּמִתְקָרְבִים מִין לְמִינוֹ. בָּרוּךָ אַתָּה לַקָּדוֹשׁ-בָּרוּךָ-הוּא בְּאַרְבָּעָה יְסוֹדוֹת. כָּעֵת הִתְבָּרֵר הַכֹּל עַל בֻּרְיוֹ.</p>"],[9522012484,"<p>פָּתַח וְאָמַר, (תהלים לז) בְּטַח בַּה' וַעֲשֵׂה טוֹב שְׁכָן אֶרֶץ וּרְעֵה אֱמוּנָה. בְּטַח בַּה', כָּרָאוּי. וַעֲשֵׂה טוֹב, תִּקּוּן שֶׁל בְּרִית הַקֹּדֶשׁ, שֶׁתְּתַקֵּן אוֹתָהּ וְתִשְׁמר אוֹתָהּ כָּרָאוּי. וְאִם תַּעֲשֶׂה אֶת זֶה, אַתָּה תִהְיֶה כָאן בָּאָרֶץ, וְאוֹתָהּ הָאֱמוּנָה שֶׁלְּמַעְלָה תִּזּוֹן מִמְּךְ וְתִתְפַּרְנֵס מִמְּךְ.</p>\n<p>וְעוֹד, (מתקּן אותו ושומר עָלָיו. שכָן ארץ ארץ קדושָה עליונָה, ארץ החיּים, שהָאָרץ ההיא תּשרה בּטוב ההוּא. וּרעה אמוּנָה אותָהּ הָאמוּנָה שלּמעלָה תּהיה נזּונית וּמתפּרנסת ממנּוּ על יָדךְ. ואם תּעשה זה) תתענג על ה' ויתן לך משאלת לבך - כל זה מתתקן בתקון הברית. כיון שהתקנה הברית, התתקן הכל. פנחס, משום שקנא על ברית זו, זכה לכל. ולא עוד, אלא שהגן על כל ישראל, ובו התקים והתענג על ה'. שהרי עלה והתקשר למעלה (והאיר) באור הראשון שברא הקדוש ברוך הוא וגנז אותו. באותו אור שנהנה ממנו אברהם, ואהרן הכהן נקשר בו.</p>\n<p>אַחַר שֶׁעָלָה לִכְהֻנָּה גְדוֹלָה, לֹא הִזְכִּיר לוֹ הֶרֶג זִמְרִי, וְלֹא רָאוּי, בִּשְׁבִיל שֶׁלֹּא יֹאחַז כְּלָל בַּעֲנָפָיו שֶׁל הַצַּד הָאַחֵר, וְלֹא רָאוּי לְהַזְכִּיר עָלָיו. שֶׁכָּל מִי שֶׁהוֹרֵג, עֲנָפִים שֶׁל צַד הָאַחֵר יֵשׁ בּוֹ. וּפִנְחָס הֲרֵי נֶאֱחַז בַּיָּמִין, וְאֵין לוֹ חֵלֶק בַּצַּד הָאַחֵר כְּלָל, וְלָכֵן לֹא נִזְכַּר כָּאן. מַה שֶּׁנִּרְאֶה שֶׁבַח - גְּנַאי הוּא לוֹ, וּנְחִיתוּת מִמַּעְלָה עֶלְיוֹנָה שֶׁנֶּאֱחַז בָּהּ. וְלָכֵן כָּתוּב הַמֻּכֶּה אֲשֶׁר הֻכָּה סְתָם, וְשֵׁם הָאִשָּׁה הַמֻּכָּה, וְלֹא נִזְכַּר עַל יְדֵי מִי.</p>\n<p>אָמַר רַבִּי פִּנְחָס, אַשְׁרֵי הַדּוֹר שֶׁשּׁוֹמְעִים דִּבְרֵי הַתּוֹרָה שֶׁלְּךְ, וְאַשְׁרֵי חֶלְקִי שֶׁזָּכִיתִי לְכָךְ. אָמַר רַבִּי שִׁמְעוֹן, אַשְׁרֵי הַדּוֹר שֶׁאַתָּה וַחֲסִידוּת שֶׁלְּךְ נִמְצָא בְתוֹכוֹ. עַד שֶׁהָיוּ יוֹשְׁבִים וּמְפַיְּסִים זֶה אֶת זֶה, בָּא רַבִּי אֶלְעָזָר בֶּן רַבִּי שִׁמְעוֹן וּמָצָא אוֹתָם שָׁם. אָמַר רַבִּי פִּנְחָס, וַדַּאי שֶׁכָּתוּב (בראשית לב) וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם מַחֲנֵה אֱלֹהִים זֶה. אָמַר לוֹ רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּנִי, שֵׁב בְּנִי וֶאֱמֹר הַפָּסוּק. יָשַׁב רַבִּי אֶלְעָזָר.</p>"],[9522012485,"<p>פָּתַח וְאָמַר, (שם) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים. מַה זֶּה וַיִּפְגְּעוּ בוֹ? אֶלָּא יֵשׁ פְּגִיעָה לְטוֹב וְיֵשׁ פְּגִיעָה לְרַע וְיֵשׁ פְּגִיעָה לִתְפִלָּה. אֶלָּא בְּשָׁעָה שֶׁהָיָה הוֹלֵךְ לְחָרָן מַה כָּתוּב? (שם כח) וַיִּפְגַּע בַּמָּקוֹם. תְּפִלַּת עַרְבִית הָיָה מִתְפַּלֵּל בְּאוֹתוֹ מָקוֹם, כְּמוֹ שֶׁנֶּאֱמַר (שמותלג) הִנֵּה מָקוֹם אִתִּי. וּתְפִלַּת עַרְבִית בְּאוֹתוֹ מָקוֹם נִרְאֲתָה.</p>\n<p>עוֹד וַיִּפְגַּע בַּמָּקוֹם - דִּבְרֵי פִיּוּסִים הֵם. שֶׁבָּא הַשֶּׁמֶשׁ הַקָּדוֹשׁ אֶל הַלְּבָנָה, בַּעְלָהּ אֶל אִשְׁתּוֹ. מִכָּאן שֶׁלֹּא רָאוּי לַבַּעַל לָבא לָאִשָּׁה אִם לֹא הָיָה בְדִבְרֵי פִיּוּסִים לְפַיְּסָהּ, שֶׁכָּתוּב וַיִּפְגַּע בַּמָּקוֹם, וְאַחַר כָּךְ וַיָּלֶן שָׁם. כְּשֶׁהָיָה בָּא יַעֲקֹב מֵחָרָן, מַה כָּתוּב? וַיִּפְגְּעוּ בוֹ. שָׁלְחָה הִיא לְפַיֵּס אוֹתוֹ לָבא אֵלֶיהָ.</p>\n<p>וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם. מַהוּ כַּאֲשֶׁר רָאָם? אֵלּוּ מַלְאֲכֵי הַיּוֹם. וּמַלְאֲכֵי הַלַּיְלָה הָיוּ, וְנִתְכַּסּוּ מִמֶּנּוּ, וְאַחַר כָּךְ נִתְגַּלּוּ לוֹ. וְלָכֵן כַּאֲשֶׁר רָאָם, כָּתוּב מַחֲנֵה אֱלֹהִים זֶה. מִכָּאן שֶׁהָיוּ אֵלּוּ שֶׁל הַיּוֹם, וְאֵלּוּ שֶׁל הַלַּיְלָה. בְּאֵלּוּ שֶׁל הַלַּיְלָה כָּתוּב מַחֲנֵה אֱלֹהִים, וּבְאֵלּוּ שֶׁל הַיּוֹם כָּתוּב בָּהֶם זֶה. וְלָכֵן וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם, שְׁתֵּי מַחֲנוֹת. וְעַכְשָׁו מַחֲנוֹת קְדוֹשִׁים רָאִיתִי כָּאן. אַשְׁרֵי הַדֶּרֶךְ שֶׁבָּאתִי לְכָאן.</p>"],[9522012486,"<p>אֶלָּא פְּגִיעָה הִיא פִּיּוּס. שֶׁכְּשֶׁיָּבֹא הֶחָתָן לַכַּלָּה, אֵין דֶּרֶךְ לֶחָתָן לְהִתְיַחֵד עִם הַכַּלָּה אֶלָּא בְּפִיּוּס, וְאַחַר כָּךְ יַעֲשֶׂה עִמָּהּ לִינָה. וְהַיְנוּ כִּי בָא הַשֶּׁמֶשׁ.</p>\n<p>אָמַר רוֹעֶה הַנֶּאֱמָן, אִם כָּךְ, מַהוּ כִּי בָא הַשֶּׁמֶשׁ, שֶׁהֲרֵי דֶּרֶךְ דְּרָשׁ פֵּרְשׁוּהָ לְשׁוֹן כִּבּוּי, וְהַיְנוּ כִּי בָא הַשֶּׁמֶשׁ? אֶלָּא מִכָּאן לָמַדְנוּ, מִי שֶׁמִּתְיַחֵד עִם אִשְׁתּוֹ צָרִיךְ בַּלַּיְלָה לְכַבּוֹת אֶת הַנֵּר, וּבַיּוֹם אֵין דֶּרֶךְ רַבּוֹתֵינוּ לְשַׁמֵּשׁ מִטָּתָם, רַק בַּלַּיְלָה, דֶּרֶךְ צִנְעָה. וְלָכֵן מָתַי נַעֲשָׂה לִינָה? כִּי בָא הַשֶּׁמֶשׁ, שֶׁהִתְפַּנָּה הַשֶּׁמֶשׁ מֵהָעוֹלָם.</p>\n<p>וְלָכֵן גַּם כֵּן צָרִיךְ לְהִתְכַּסּוֹת מֵהַשֶּׁמֶשׁ, וְכָךְ צָרִיךְ לְהִתְכַּסּוֹת מֵאֵלּוּ הַמַּלְאָכִים, שֶׁהֵם מִיֵּצֶר הַטּוֹב מִיָּמִין בְּכַמָּה מַחֲנוֹת, וּמִיֵּצֶר הָרָע שֶׁהוֹלֵךְ לִשְׂמֹאל בְּכַמָּה מַחֲנוֹת. וְלָכֵן אַחַר שֶׁבָּא הַבֹּקֶר אָמַר כַּאֲשֶׁר רָאָם. וּמִצַּד יַעֲקֹב שֶׁהָיָה אִישׁ תָּם, לֹא הָיָה עִמּוֹ, רַק חֵילוֹת הַמֶּלֶךְ וְהַמַּלְכָּה, וְלָכֵן וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם. אוֹתָם מַלְאֲכֵי הַיּוֹם כָּתוּב, כַּאֲשֶׁר רָאָם מַחֲנֵה אֱלֹהִים זֶה. וּכְשֶׁבָּאוּ מַלְאֲכֵי הַלַּיְלָה, שֶׁהִתְכַּנְּסוּ אִתּוֹ לִשְׁמֹר אוֹתוֹ, אָמַר וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם.</p>\n<p>מִשּׁוּם שֶׁהַתְּפִלָּה הִיא כַּלָּה, זֶהוּ שֶׁכָּתוּב (שיר השירים ד) אִתִּי מִלְּבָנוֹן כַּלָּה אִתִּי וְגוֹ'. נִקְרָא כָּאן \"אִתִּי\", וּבַתּוֹרָה שֶׁבִּכְתָב נֶאֱמַר עָלֶיהָ, (שמות לג) הִנֵּה מָקוֹם אִתִּי. וּמִשּׁוּם שֶׁהִיא נִקְרְאָה מָקוֹם בָּעוֹלָם הַזֶּה, נֶאֱמַר בָּהּ וַיִּפְגַּע בַּמָּקוֹם וַיָּלֶן שָׁם.</p>\n<p>וְלָכֵן הִיא אָמְרָה, (ירמיה ט) מִי יִתְּנֵנִי בַמִּדְבָּר מְלוֹן אוֹרְחִים. שֶׁהָיְתָה רְשׁוּת בִּפְנֵי עַצְמָהּ, וְלֹא עִם אוֹתָם שֶׁקּוֹבְעִים אוֹתָהּ חוֹבָה עִמָּם, בְּלִי הֶחָתָן שֶׁלָּהּ. וּבְכָל שָׁעָה שֶׁאָדָם מִתְפַּלֵּל, הַקָּדוֹשׁ בָּרוּךְ הוּא מַקְדִּים וְשׁוֹמֵר אוֹתוֹ. וְסוֹד הַדָּבָר - (בראשית כד) וְהָאִישׁ מִשְׁתָּאֵה לָהּ. וְאֵין אִישׁ אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא, זֶהוּ שֶׁכָּתוּב (שמות טו) ה' אִישׁ מִלְחָמָה. (בראשיתכד) וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר וְהִנֵּה רִבְקָה יצֵאת, כְּמוֹ (זכריה ט) וְיָצָא כַּבָּרָק חִצּוֹ.</p>\n<p>וְאִם תֹּאמְרוּ שֶׁהֲרֵי פֵּרְשׁוּהָ רַבּוֹתֵינוּ, לַעֲשָׂרָה מַקְדִּימָה הַשְּׁכִינָה וּבָאָה, לְאֶחָד עַד שֶׁיּוֹשֵׁב. לַעֲשָׂרָה שֶׁהִיא י' קָדְמָה ה'. לְאֶחָד שֶׁהוּא ו', עַד שֶׁיּוֹשֵׁב לֹא בָאָה אֵלָיו ה' שֵׁנִית. וְסוֹד הַדָּבָר - שֶׁבְּמָקוֹם שֶׁאֵין שָׁם יָ\"הּ, לֹא בָאָה שָׁם ה'. וּמִי שֶׁרוֹצֶה לְיַחֵד אוֹתִיּוֹת, צָרִיךְ בִּתְחִנָּה וּבְתַחֲנוּנִים. וְלָכֵן (דברים ג) וָאֶתְחַנַּן אֶל ה', בַּאדֹנָ\"י לַשְּׁכִינָה בְּתַחֲנוּנִים, וְלַקָּדוֹשׁ-בָּרוּךְ-הוּא בְּרַחֲמִים. עַד כָּאן.</p>"],[9522012487,"<p>אֶת הַכֶּבֶשׂ הָאֶחָד תַּעֲשֶׂה בַבֹּקֶר וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם. שֶׁהוּא סוֹד שֶׁל סִתְרֵי הָרַחֲמָן, שֶׁבֵּאֲרוּ עֲלֵיהֶם רַבּוֹתֵינוּ, גַּבֵּי סִתְרֵי הָרַחֲמָן לָמָּה לָךְ? אֶלָּא דְּבָרִים שֶׁיִּהְיוּ תַּחַת סִתְרֵי הָעוֹלָם, יִהְיוּ מְכֻסִּים תַּחַת לְבוּשְׁךְ. מַה לְּבוּשׁ מְכַסֶּה עַל הַגּוּף, גַּם כָּךְ צָרִיךְ לְכַסּוֹת סוֹדוֹת הַתּוֹרָה. כָּל שֶׁכֵּן סוֹדוֹת הַקָּרְבָּנוֹת, שֶׁהֵם כְּמוֹ קִרְבַת אִשָּׁה לְבַעְלָהּ.</p>\n<p>וּמַה קִּרְבָתָם צְרִיכָה בִּמְכֻסֶּה, גַּם כָּךְ צָרִיךְ קָרְבָּן לְכַסּוֹת אוֹתָם מִבְּנֵי עֲרָיוֹת רְשָׁעִים חֲצוּפִים, שֶׁעֵין לָהֶם לֹא בּשֶׁת פָּנִים וְלֹא עֲנָוָה. וְכַמָּה מִינֵי מַמְזֵרִים הֵם: בְּנֵי עֲרָיוֹת, בְּנֵי נִדָּה, שֶׁנָּד ה' מִמֶּנָּה וְנִמְצֵאת בִּמְקוֹמָהּ, שִׁפְחָה בַּת אֵל נֵכָר זוֹנָה. וְזֶהוּ סוֹד (משלי ל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ וְגוֹ', תַּחַת עֶבֶד כִּי יִמְלוֹךְ וְנָבָל כִּי יִשְׂבַּע לָחֶם וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ. שֶׁנָּדָה ה' מִמְּקוֹמָהּ, שֶׁהִיא הַמַּלְכָּה, יֵצֶר הַטּוֹב, וְנִכְנְסָה בִמְקוֹמָהּ שִׁפְחָה, יֵצֶר הָרָע.</p>\n<p>וְסוֹד הַדָּבָר - (ויקרא יד) כְּנֶגַע נִרְאָה לִי בַּבָּיִת, הַיְנוּ דָּם טָמֵא שֶׁל נִדָּה. וּמַה שָּׁם (שם יג) וְהִסְגִּירוֹ הַכֹּהֵן שִׁבְעַת יָמִים - אַף כָּךְ (שם טו) שִׁבְעַת יָמִים תִּהְיֶה בְנִדָּתָהּ. אַשְׁרֵי אוֹתָם אֵיבָרִים שֶׁמִּתְקַדְּשִׁים בִּשְׁעַת תַּשְׁמִישׁ, שֶׁהֵם עֲצֵי הָעוֹלָה שֶׁאוֹחֲזִים בָּהֶם אִשִּׁים קְדוֹשׁוֹת, שֵׁם יְהֹוָ\"ה שֶׁאָחוּז בָּאִשִּׁים שֶׁלָּהֶם, וְלָכֵן (ישעיה כד) בָּאוּרִים כַּבְּדוּ ה'. עַל זֶה נִסְתְּרוֹת ה', הַיְנוּ אֶת הַכֶּבֶשׂ הָאֶחָד תַּעֲשֶׂה בַבֹּקֶר וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם.</p>\n<p>שְׁלֵמוּת הַכָּתוּב - וַעֲשִׂירִית הָאֵיפָה סֹלֶת. אַשְׁרֵי מִי שֶׁמַּשְׁפִּיעַ מִמֹּחוֹ טִפָּה סֹלֶת נְקִיָּה בְּלִי פְסֹלֶת. וְהִיא רְמוּזָה בָּאוֹת י' שֶׁל אֲדנָ\"י, כְּלוּלָה בְּעֶשֶׂר סְפִירוֹת, שֶׁהִיא בְּלוּלָה בְּשֶׁמֶן כָּתִית רְבִיעִית הַהִין. וְהִיא בְּלוּלָה בַּמִּקְרָא, בַּמִּשְׁנָה, בַּתַּלְמוּד, בַּקַּבָּלָה.</p>"]]});
